/**
 * Rootz V6 Dashboard - Storage Integration
 *
 * Initializes StorageGateway as the single entry point for all storage.
 * Uses browser-based storage (IndexedDB + localStorage).
 */

import {
  StorageGateway,
  createStorageGateway,
  openRootzDatabase,
  createBrowserKeyStorage,
  MessageProcessor,
  SyncService,
  ChainReader,
  IdentityManager,
  type RootzDatabase,
  type KeyStorage,
  type StorageEventType,
  type StorageEventListener,
  type StoredSecret,
  type StoredInvite,
} from '@rootz/integration';

// Storage instances (singleton)
let gateway: StorageGateway | null = null;
let database: RootzDatabase | null = null;
let keyStorage: KeyStorage | null = null;
let processor: MessageProcessor | null = null;
let syncService: SyncService | null = null;
let storedConfig: StorageConfig | null = null;  // Store config for later use

export interface StorageConfig {
  chainId: number;
  chainName: string;
  walletAddress: string;
  chainReader?: ChainReader;
  /**
   * Optional: Identity contract addresses where this wallet is a rivet.
   * Used for multi-device access - sync will find secrets owned by these Identities.
   */
  identityContracts?: string[];
  /**
   * Optional: Factory contract address.
   * Required for discovering secrets owned by Identity contracts.
   */
  factoryAddress?: string;
  /**
   * Optional: Identity factory contract address.
   * Required for auto-discovering Identity contracts.
   */
  identityFactoryAddress?: string;
  /**
   * Optional: Signer for Identity discovery.
   * Required if discoverIdentity is true and no identityContracts provided.
   */
  signer?: unknown;
  /**
   * Auto-discover Identity contracts if none provided.
   * Default: true (if signer and identityFactoryAddress are available)
   */
  discoverIdentity?: boolean;
}

/**
 * Initialize storage gateway for the dashboard.
 *
 * IMPORTANT: This function auto-discovers Identity contracts BEFORE creating the
 * SyncService, ensuring that `isOwner=true` is correctly set for Identity-owned
 * secrets on all devices (not just the creator device).
 */
export async function initStorage(config: StorageConfig): Promise<StorageGateway> {
  if (gateway) {
    console.log('[Storage] Already initialized, returning existing gateway');
    return gateway;
  }

  console.log(`[Storage] Initializing for chain ${config.chainId}, wallet ${config.walletAddress.slice(0, 10)}...`);

  // Step 1: Resolve Identity contracts BEFORE anything else
  // This ensures SyncService queries Identity-owned secrets correctly on first sync
  // IMPORTANT: Get ALL identities, not just one - fat packages could be on any of them!
  let identityContracts = config.identityContracts || [];
  console.log(`[Storage] Identity resolution starting...`);
  console.log(`[Storage] Config identityContracts: ${identityContracts.length}`);

  // Check localStorage for ALL identities (not just one)
  if (identityContracts.length === 0) {
    // Get ALL identities the wallet is associated with
    const allStoredIdentities = getAllIdentityContracts(config.walletAddress);
    console.log(`[Storage] Found ${allStoredIdentities.length} stored Identity contract(s) in localStorage`);
    if (allStoredIdentities.length > 0) {
      identityContracts = allStoredIdentities;
      allStoredIdentities.forEach((id, i) => console.log(`  [${i}] ${id}`));
    } else {
      // Fallback to single identity check (legacy)
      const stored = getStoredIdentityContract(config.walletAddress);
      if (stored) {
        identityContracts = [stored];
        console.log(`[Storage] Found single stored Identity: ${stored}`);
      }
    }
  }

  // Auto-discover if enabled and no Identity found yet
  const shouldDiscover = config.discoverIdentity !== false &&
                         identityContracts.length === 0 &&
                         config.signer &&
                         config.identityFactoryAddress;

  if (shouldDiscover) {
    try {
      console.log('[Storage] Auto-discovering Identity contract...');
      const identityManager = new IdentityManager({
        signer: config.signer as any,
        chainId: config.chainId,
        factoryAddress: config.identityFactoryAddress,
      });
      const identityInfo = await identityManager.discoverAndLoadIdentity();
      if (identityInfo) {
        console.log(`[Storage] 🆔 Discovered Identity: ${identityInfo.address}`);
        // Save to localStorage for future sessions
        localStorage.setItem(`identity_${config.walletAddress.toLowerCase()}`, identityInfo.address);
        identityContracts = [identityInfo.address];
      }
    } catch (e) {
      // Identity discovery is optional - don't fail storage init
      console.log('[Storage] No Identity found (normal for new wallets)');
    }
  }

  console.log(`[Storage] Final Identity contracts for sync: ${identityContracts.length}`);
  identityContracts.forEach((id, i) => console.log(`  [${i}] ${id}`));

  // Step 2: Open IndexedDB database
  database = await openRootzDatabase(config.chainId);
  console.log('[Storage] IndexedDB opened');

  // Step 3: Create localStorage-based key storage
  keyStorage = createBrowserKeyStorage();
  console.log('[Storage] KeyStorage initialized');

  // Step 4: Create the gateway (single entry point for storage)
  gateway = createStorageGateway({
    database,
    keyStorage,
    chainId: config.chainId,
    walletAddress: config.walletAddress,
    batchSize: 10,
    batchDelayMs: 100,
    cacheEnabled: true,
    cacheTtlMs: 60000,
  });

  console.log('[Storage] Gateway created');

  // Store config for later use (e.g., fetchMissingChainDataForSharedSecrets)
  storedConfig = config;

  // Step 5: Initialize MessageProcessor for handling chain messages
  processor = new MessageProcessor({
    database,
    keyStorage,
    chainId: config.chainId,
    walletAddress: config.walletAddress,
    identityContracts: identityContracts.length > 0 ? identityContracts : undefined,
  });
  console.log(`[Storage] MessageProcessor initialized${identityContracts.length > 0 ? ` with ${identityContracts.length} Identity contract(s)` : ''}`);

  // Step 6: Initialize SyncService with resolved Identity contracts
  if (config.chainReader) {
    syncService = new SyncService({
      reader: config.chainReader,
      processor,
      database,
      chainId: config.chainId,
      chainName: config.chainName,
      walletAddress: config.walletAddress,
      identityContracts: identityContracts.length > 0 ? identityContracts : undefined,
      factoryAddress: config.factoryAddress,
      onProgress: (progress) => {
        console.log(`[Sync] ${progress.status}: ${progress.messagesProcessed}/${progress.messagesFound} messages`);
      },
      onError: (error, message) => {
        console.error(`[Sync] Error processing ${message?.txHash || 'unknown'}:`, error);
      },
    });
    if (identityContracts.length > 0) {
      console.log(`[Storage] 🆔 SyncService initialized with ${identityContracts.length} Identity contract(s)`);
      if (config.factoryAddress) {
        console.log(`[Storage] Factory address set for Identity sync: ${config.factoryAddress.slice(0, 12)}...`);
      } else {
        console.warn('[Storage] No factory address - Identity-owned secrets will not be discovered');
      }
    } else {
      console.log('[Storage] SyncService initialized (no Identity contracts)');
    }
  }

  return gateway;
}

/**
 * Get the storage gateway instance
 */
export function getStorage(): StorageGateway | null {
  return gateway;
}

/**
 * Get the sync service instance
 */
export function getSyncService(): SyncService | null {
  return syncService;
}

/**
 * Update the Identity contracts for sync and message processing.
 * Call this when the user adds or removes Identity associations.
 */
export function setIdentityContracts(contracts: string[]): void {
  if (processor) {
    processor.setIdentityContracts(contracts);
  }
  if (syncService) {
    syncService.setIdentityContracts(contracts);
  }
}

/**
 * Get the active (currently selected) Identity contract for a wallet.
 * Falls back to first identity if no active selection.
 */
export function getStoredIdentityContract(walletAddress: string): string | null {
  try {
    // First check for explicitly selected active identity
    const activeIdentity = localStorage.getItem(`operating_identity_${walletAddress.toLowerCase()}`);
    if (activeIdentity) {
      return activeIdentity;
    }
    // Fall back to legacy single-identity key
    const legacyIdentity = localStorage.getItem(`identity_${walletAddress.toLowerCase()}`);
    if (legacyIdentity) {
      return legacyIdentity;
    }
    // Fall back to first in multi-identity list
    const allIdentities = getAllIdentityContracts(walletAddress);
    return allIdentities.length > 0 ? allIdentities[0] : null;
  } catch {
    return null;
  }
}

/**
 * Get all Identity contracts associated with a wallet.
 * Merges legacy single-identity storage with new multi-identity array.
 */
export function getIdentityContractsForWallet(walletAddress: string): string[] {
  return getAllIdentityContracts(walletAddress);
}

/**
 * Get all Identity contracts for a wallet from localStorage.
 * Returns an array of unique identity contract addresses.
 */
export function getAllIdentityContracts(walletAddress: string): string[] {
  try {
    const addr = walletAddress.toLowerCase();
    const identities = new Set<string>();

    // Check multi-identity storage (new format)
    const multiIdentityJson = localStorage.getItem(`identities_${addr}`);
    if (multiIdentityJson) {
      try {
        const parsed = JSON.parse(multiIdentityJson);
        if (Array.isArray(parsed)) {
          parsed.forEach((id: string) => identities.add(id.toLowerCase()));
        }
      } catch {
        // Invalid JSON, ignore
      }
    }

    // Check legacy single-identity storage (for backwards compatibility)
    const legacyIdentity = localStorage.getItem(`identity_${addr}`);
    if (legacyIdentity) {
      identities.add(legacyIdentity.toLowerCase());
    }

    // Check active identity (might be different from stored)
    const activeIdentity = localStorage.getItem(`operating_identity_${addr}`);
    if (activeIdentity) {
      identities.add(activeIdentity.toLowerCase());
    }

    return Array.from(identities);
  } catch {
    return [];
  }
}

/**
 * Add an Identity contract to the wallet's list.
 * Updates both the multi-identity list and the sync service.
 */
export function addIdentityContract(walletAddress: string, identityAddress: string): void {
  const addr = walletAddress.toLowerCase();
  const identityAddr = identityAddress.toLowerCase();

  // Get existing identities
  const identities = new Set(getAllIdentityContracts(addr));
  identities.add(identityAddr);

  // Save to multi-identity storage
  localStorage.setItem(`identities_${addr}`, JSON.stringify(Array.from(identities)));

  // Also update legacy key for backwards compatibility
  if (!localStorage.getItem(`identity_${addr}`)) {
    localStorage.setItem(`identity_${addr}`, identityAddress);
  }

  // Update sync service
  setIdentityContracts(Array.from(identities));

  console.log(`[Storage] Added Identity ${identityAddr.slice(0, 12)}... (total: ${identities.size})`);
}

/**
 * Set the active Identity contract for a wallet.
 * This is the Identity that will be used for operations.
 */
export function setActiveIdentity(walletAddress: string, identityAddress: string | null): void {
  const addr = walletAddress.toLowerCase();

  if (identityAddress) {
    localStorage.setItem(`operating_identity_${addr}`, identityAddress.toLowerCase());
    console.log(`[Storage] Active Identity set: ${identityAddress.slice(0, 12)}...`);
  } else {
    localStorage.removeItem(`operating_identity_${addr}`);
    console.log(`[Storage] Active Identity cleared`);
  }
}

/**
 * Get the active Identity contract address (if any).
 */
export function getActiveIdentity(walletAddress: string): string | null {
  return localStorage.getItem(`operating_identity_${walletAddress.toLowerCase()}`);
}

/**
 * Remove an Identity contract from a wallet's list.
 */
export function removeIdentityContract(walletAddress: string, identityAddress: string): void {
  const addr = walletAddress.toLowerCase();
  const identityAddr = identityAddress.toLowerCase();

  // Get existing identities and remove this one
  const identities = new Set(getAllIdentityContracts(addr));
  identities.delete(identityAddr);

  // Save updated list
  localStorage.setItem(`identities_${addr}`, JSON.stringify(Array.from(identities)));

  // If this was the active identity, clear it
  const active = getActiveIdentity(addr);
  if (active?.toLowerCase() === identityAddr) {
    const remaining = Array.from(identities);
    if (remaining.length > 0) {
      setActiveIdentity(addr, remaining[0]);
    } else {
      setActiveIdentity(addr, null);
    }
  }

  // If this was the legacy identity, update it
  const legacyIdentity = localStorage.getItem(`identity_${addr}`);
  if (legacyIdentity?.toLowerCase() === identityAddr) {
    const remaining = Array.from(identities);
    if (remaining.length > 0) {
      localStorage.setItem(`identity_${addr}`, remaining[0]);
    } else {
      localStorage.removeItem(`identity_${addr}`);
    }
  }

  // Update sync service
  setIdentityContracts(Array.from(identities));

  console.log(`[Storage] Removed Identity ${identityAddr.slice(0, 12)}... (remaining: ${identities.size})`);
}

/**
 * Subscribe to storage events
 */
export function onStorageEvent(type: StorageEventType, listener: StorageEventListener): () => void {
  if (!gateway) {
    console.warn('[Storage] Not initialized, cannot subscribe to events');
    return () => {};
  }
  return gateway.on(type, listener);
}

/**
 * Sync from blockchain to storage.
 * Uses fullSync which includes both wallet messages AND V5 owned secrets.
 */
export async function syncFromChain(fromBlock?: number): Promise<{
  success: boolean;
  messagesProcessed: number;
  secretsFound: number;
  errors: number;
}> {
  if (!syncService) {
    console.warn('[Storage] SyncService not initialized');
    return { success: false, messagesProcessed: 0, secretsFound: 0, errors: 0 };
  }

  console.log('[Storage] Starting full sync from chain (messages + V5 secrets)...');

  // Use fullSync which combines message sync with V5 secret discovery
  const result = await syncService.fullSync(fromBlock);
  console.log(`[Storage] Sync complete: ${result.messagesProcessed} messages, ${result.secretsFound} secrets, ${result.errors.length} errors`);

  return {
    success: result.errors.length === 0,
    messagesProcessed: result.messagesProcessed,
    secretsFound: result.secretsFound,
    errors: result.errors.length,
  };
}

/**
 * Get all secrets from storage
 */
export async function getAllSecrets(): Promise<StoredSecret[]> {
  if (!gateway) {
    console.warn('[Storage] Not initialized');
    return [];
  }

  const owned = await gateway.getOwnedSecrets();
  const shared = await gateway.getSharedSecrets();
  return [...owned, ...shared];
}

/**
 * Get owned secrets from storage
 */
export async function getOwnedSecrets(): Promise<StoredSecret[]> {
  if (!gateway) {
    console.log('[Storage] getOwnedSecrets: gateway is null');
    return [];
  }

  // Debug: try direct database query
  if (database) {
    const allSecrets = await database.secrets.getAll();
    console.log(`[Storage] Direct DB query: ${allSecrets.length} total secrets`);
    if (allSecrets.length > 0) {
      console.log('[Storage] First secret:', JSON.stringify(allSecrets[0], null, 2));
    }
  }

  const owned = await gateway.getOwnedSecrets();
  console.log(`[Storage] Gateway returned ${owned.length} owned secrets`);
  return owned;
}

/**
 * Get shared secrets from storage.
 * Merges secrets from the gateway with locally-stored shared secrets from team invites.
 */
export async function getSharedSecrets(): Promise<StoredSecret[]> {
  const fromGateway = gateway ? await gateway.getSharedSecrets() : [];

  // Also check localStorage for team-shared secrets
  const localShared: StoredSecret[] = [];
  try {
    const localData = localStorage.getItem('shared_secrets');
    if (localData) {
      const parsed = JSON.parse(localData);
      if (Array.isArray(parsed)) {
        localShared.push(...parsed);
      }
    }
  } catch (e) {
    console.warn('[Storage] Error reading local shared_secrets:', e);
  }

  // Merge and deduplicate by contract address
  const merged: StoredSecret[] = [...fromGateway];
  for (const local of localShared) {
    if (!merged.some(s => s.contractAddress.toLowerCase() === local.contractAddress.toLowerCase())) {
      merged.push(local as StoredSecret);
    }
  }

  return merged;
}

/**
 * Get a single secret by contract address
 */
export async function getSecret(contractAddress: string): Promise<StoredSecret | undefined> {
  if (!gateway) return undefined;
  return gateway.getSecret(contractAddress);
}

/**
 * Get storage stats for diagnostics
 */
export function getStorageStats(): {
  initialized: boolean;
  cacheSize: number;
  queueLength: number;
  listenerCount: number;
  syncServiceReady: boolean;
} {
  if (!gateway) {
    return {
      initialized: false,
      cacheSize: 0,
      queueLength: 0,
      listenerCount: 0,
      syncServiceReady: false,
    };
  }

  const stats = gateway.getStats();
  return {
    initialized: true,
    cacheSize: stats.cacheSize,
    queueLength: stats.queueLength,
    listenerCount: stats.listenerCount,
    syncServiceReady: syncService !== null,
  };
}

/**
 * Clear all storage (for testing/reset)
 */
export async function clearStorage(): Promise<void> {
  if (!gateway) {
    console.warn('[Storage] Not initialized, nothing to clear');
    return;
  }

  await gateway.clear();
  console.log('[Storage] All data cleared');
}

/**
 * Fetch chain data (ipfsHash, rawKeysData) for shared secrets that are missing it.
 * This is needed for direct-keys sharing where the processor creates a secret record
 * but doesn't have chain reading capability.
 *
 * @param chainReader - ChainReader instance to fetch KeyVault data
 * @returns Number of secrets updated
 */
export async function fetchMissingChainDataForSharedSecrets(
  chainReader: ChainReader
): Promise<number> {
  if (!gateway || !database) {
    console.warn('[Storage] Not initialized');
    return 0;
  }

  // Get shared secrets from IndexedDB
  const sharedSecrets = await gateway.getSharedSecrets();
  const secretsMissingData = sharedSecrets.filter(
    s => !s.ipfsHash && s.keyVaultBlock && s.keyVaultBlock > 0
  );

  if (secretsMissingData.length === 0) {
    console.log('[Storage] No shared secrets missing chain data');
    return 0;
  }

  console.log(`[Storage] Found ${secretsMissingData.length} shared secrets missing chain data`);
  let updatedCount = 0;

  // Get chain name from stored config
  const chainName = storedConfig?.chainName || 'polygon mainnet v6.2';

  for (const secret of secretsMissingData) {
    try {
      console.log(`[Storage] Fetching chain data for ${secret.contractAddress.slice(0, 12)}...`);

      // Fetch KeyVaultCreated events from the secret contract
      const keyVaults = await chainReader.getKeyVaultCreatedEvents(
        secret.contractAddress,
        chainName
      );

      if (keyVaults.length === 0) {
        console.log(`[Storage] No KeyVault found for ${secret.contractAddress.slice(0, 12)}...`);
        continue;
      }

      // Find the KeyVault at the expected block
      const kv = keyVaults.find(k => k.blockNumber === secret.keyVaultBlock) || keyVaults[0];

      // Extract encrypted keys data
      let ipfsHash = '';
      let ipfsIV = '';
      let rawKeysData = '';

      if (kv.encryptedKeysData) {
        rawKeysData = kv.encryptedKeysData;
        try {
          const keysObj = typeof kv.encryptedKeysData === 'string'
            ? JSON.parse(kv.encryptedKeysData)
            : kv.encryptedKeysData;

          // Extract IPFS hash - can be nested object or direct value
          const encIPFS = keysObj.encryptedIPFSHash;
          if (typeof encIPFS === 'object' && encIPFS !== null) {
            ipfsHash = encIPFS.encrypted || '';
            ipfsIV = encIPFS.iv || '';
          } else {
            ipfsHash = encIPFS || '';
            ipfsIV = keysObj.ipfsIV || '';
          }
        } catch (e) {
          console.warn(`[Storage] Could not parse encryptedKeysData:`, e);
        }
      }

      // Update the secret record in IndexedDB
      const existingSecret = await database.secrets.get(secret.contractAddress.toLowerCase());
      if (existingSecret) {
        existingSecret.ipfsHash = ipfsHash || existingSecret.ipfsHash;
        existingSecret.ipfsIV = ipfsIV || existingSecret.ipfsIV;
        existingSecret.rawKeysData = rawKeysData || existingSecret.rawKeysData;
        existingSecret.lastSyncedAt = Date.now();

        await database.secrets.put(existingSecret);
        updatedCount++;
        console.log(`[Storage] Updated ${secret.name || secret.contractAddress.slice(0, 12)} with chain data (ipfsHash=${!!ipfsHash})`);
      }
    } catch (error) {
      console.warn(`[Storage] Error fetching chain data for ${secret.contractAddress}:`, error);
    }
  }

  console.log(`[Storage] Updated ${updatedCount} shared secrets with chain data`);
  return updatedCount;
}

/**
 * Get invites for a specific secret contract.
 * Used to find encrypted keys from fat packages and team sharing.
 */
export async function getInvitesBySecret(contractAddress: string): Promise<StoredInvite[]> {
  if (!gateway) {
    console.warn('[Storage] Not initialized');
    return [];
  }
  return gateway.getInvitesBySecret(contractAddress);
}

/**
 * Close storage and cleanup
 */
export async function closeStorage(): Promise<void> {
  if (gateway) {
    await gateway.close();
    gateway = null;
  }

  if (syncService) {
    syncService.stopPolling();
    syncService = null;
  }

  console.log('[Storage] Closed');
}
