/**
 * @rootz/message-processor - RootzDatabase
 *
 * IndexedDB wrapper with chain-namespaced storage.
 * Implements unified schema from STORAGE_SCHEMA.md
 *
 * ## Stores (V2)
 *
 * | Store | Purpose | Primary Key |
 * |-------|---------|-------------|
 * | invites | Team sharing invitations | inviteId |
 * | secrets | Secret contract metadata | contractAddress |
 * | publicKeys | Cached ECDH public keys | address |
 * | syncState | Blockchain sync tracking | key |
 * | messages | Raw blockchain messages | txHash |
 * | notes | Decrypted content | noteId |
 * | pendingOperations | Queued write commands | operationId |
 */

import { openDB, IDBPDatabase, DBSchema } from 'idb';
import {
  RootzDatabase,
  StoredInvite,
  StoredSecret,
  StoredPublicKey,
  SyncState,
  StoredMessage,
  StoredNote,
  StoredKeyVault,
  PendingOperation,
  InviteStatus,
  PendingOperationStatus,
  PendingOperationType,
} from './types.js';

// ============================================================================
// Database Schema
// ============================================================================

interface RootzDBSchema extends DBSchema {
  invites: {
    key: string;
    value: StoredInvite;
    indexes: {
      'by-status': InviteStatus;
      'by-secret': string;
      'by-member': string;
      'by-owner': string;
      'by-direction': 'sent' | 'received';
      'by-updated': number;
    };
  };
  secrets: {
    key: string;
    value: StoredSecret;
    indexes: {
      'by-owner': string;
      'by-status': string;
      'by-accessed': number;
      'by-is-owner': number; // 1 or 0
      'by-owner-type': string; // V4: 'EOA' or 'IDENTITY'
    };
  };
  publicKeys: {
    key: string;
    value: StoredPublicKey;
    indexes: {
      'by-verified': number; // 1 or 0
      'by-used': number;
    };
  };
  syncState: {
    key: string;
    value: SyncState;
  };
  // V2 stores
  messages: {
    key: string;
    value: StoredMessage;
    indexes: {
      'by-type': string;
      'by-block': number;
      'by-processed': number; // 1 or 0
      'by-created': number;
    };
  };
  notes: {
    key: string;
    value: StoredNote;
    indexes: {
      'by-secret': string;
      'by-kvblock': string; // compound: secret_kvblock
      'by-dirty': number; // 1 or 0
      'by-accessed': number;
    };
  };
  // V3 stores
  keyVaults: {
    key: string;
    value: StoredKeyVault;
    indexes: {
      'by-secret': string;
      'by-primary': string; // compound: secret_isPrimary
    };
  };
  pendingOperations: {
    key: string;
    value: PendingOperation;
    indexes: {
      'by-status': PendingOperationStatus;
      'by-type': PendingOperationType;
      'by-created': number;
    };
  };
}

// ============================================================================
// Database Version
// ============================================================================

/**
 * Database version history:
 * V1: Initial stores (invites, secrets, publicKeys, syncState)
 * V2: Added messages, notes, pendingOperations stores
 * V3: Added keyVaults store
 * V4: Added ownerType index to secrets (for identity mode filtering)
 */
const DB_VERSION = 4;

function getDbName(chainId: number): string {
  return `rootz_v6_${chainId}`;
}

// ============================================================================
// Database Implementation
// ============================================================================

export async function openRootzDatabase(chainId: number): Promise<RootzDatabase> {
  const dbName = getDbName(chainId);

  const db = await openDB<RootzDBSchema>(dbName, DB_VERSION, {
    upgrade(db, oldVersion, _newVersion, transaction) {
      // V1 stores
      if (oldVersion < 1) {
        // Invites store
        const inviteStore = db.createObjectStore('invites', { keyPath: 'inviteId' });
        inviteStore.createIndex('by-status', 'status');
        inviteStore.createIndex('by-secret', 'secretContract');
        inviteStore.createIndex('by-member', 'memberAddress');
        inviteStore.createIndex('by-owner', 'ownerAddress');
        inviteStore.createIndex('by-direction', 'direction');
        inviteStore.createIndex('by-updated', 'updatedAt');

        // Secrets store
        const secretStore = db.createObjectStore('secrets', { keyPath: 'contractAddress' });
        secretStore.createIndex('by-owner', 'ownerAddress');
        secretStore.createIndex('by-status', 'status');
        secretStore.createIndex('by-accessed', 'lastAccessedAt');
        secretStore.createIndex('by-is-owner', 'isOwner');

        // Public keys store
        const keyStore = db.createObjectStore('publicKeys', { keyPath: 'address' });
        keyStore.createIndex('by-verified', 'verified');
        keyStore.createIndex('by-used', 'lastUsedAt');

        // Sync state store
        db.createObjectStore('syncState', { keyPath: 'key' });
      }

      // V2 stores
      if (oldVersion < 2) {
        // Messages store
        const messageStore = db.createObjectStore('messages', { keyPath: 'txHash' });
        messageStore.createIndex('by-type', 'type');
        messageStore.createIndex('by-block', 'blockNumber');
        messageStore.createIndex('by-processed', 'processed');
        messageStore.createIndex('by-created', 'createdAt');

        // Notes store
        const noteStore = db.createObjectStore('notes', { keyPath: 'noteId' });
        noteStore.createIndex('by-secret', 'secretContract');
        noteStore.createIndex('by-dirty', 'isDirty');
        noteStore.createIndex('by-accessed', 'accessedAt');

        // Pending operations store
        const opStore = db.createObjectStore('pendingOperations', { keyPath: 'operationId' });
        opStore.createIndex('by-status', 'status');
        opStore.createIndex('by-type', 'type');
        opStore.createIndex('by-created', 'createdAt');
      }

      // V3 stores
      if (oldVersion < 3) {
        // KeyVaults store
        const kvStore = db.createObjectStore('keyVaults', { keyPath: 'keyVaultId' });
        kvStore.createIndex('by-secret', 'secretContract');
      }

      // V4: Add ownerType index to secrets (for identity mode filtering)
      if (oldVersion < 4) {
        // Add index to existing secrets store
        // Note: Existing secrets will have ownerType=undefined, which defaults to 'EOA'
        const secretStore = transaction.objectStore('secrets');
        secretStore.createIndex('by-owner-type', 'ownerType');
      }
    },
  });

  return createDatabaseWrapper(db, chainId);
}

function createDatabaseWrapper(
  db: IDBPDatabase<RootzDBSchema>,
  chainId: number
): RootzDatabase {
  return {
    // ========================================================================
    // Invites
    // ========================================================================
    invites: {
      async get(inviteId: string) {
        return db.get('invites', inviteId);
      },

      async put(invite: StoredInvite) {
        invite.chainId = chainId;
        invite.updatedAt = Date.now();
        await db.put('invites', invite);
      },

      async getAll() {
        return db.getAll('invites');
      },

      async getByStatus(status: InviteStatus) {
        return db.getAllFromIndex('invites', 'by-status', status);
      },

      async getBySecret(contract: string) {
        return db.getAllFromIndex('invites', 'by-secret', contract.toLowerCase());
      },

      async getByMember(address: string) {
        return db.getAllFromIndex('invites', 'by-member', address.toLowerCase());
      },

      async getByOwner(address: string) {
        return db.getAllFromIndex('invites', 'by-owner', address.toLowerCase());
      },

      async getPending() {
        const all = await db.getAll('invites');
        return all.filter(
          (inv) =>
            inv.status !== 'complete' &&
            inv.status !== 'declined' &&
            inv.status !== 'expired'
        );
      },

      async delete(inviteId: string) {
        await db.delete('invites', inviteId);
      },
    },

    // ========================================================================
    // Secrets
    // ========================================================================
    secrets: {
      async get(contract: string) {
        return db.get('secrets', contract.toLowerCase());
      },

      async put(secret: StoredSecret) {
        console.log(`[Database] secrets.put called for ${secret.contractAddress}`);
        secret.chainId = chainId;
        secret.contractAddress = secret.contractAddress.toLowerCase();
        try {
          await db.put('secrets', secret);
          console.log(`[Database] secrets.put succeeded for ${secret.contractAddress}`);
        } catch (err) {
          console.error(`[Database] secrets.put FAILED for ${secret.contractAddress}:`, err);
          throw err;
        }
      },

      async getAll() {
        return db.getAll('secrets');
      },

      async getOwned() {
        const all = await db.getAll('secrets');
        console.log(`[Database] getOwned: found ${all.length} total secrets`);
        const owned = all.filter((s) => s.isOwner);
        console.log(`[Database] getOwned: ${owned.length} owned (isOwner=true)`);
        if (all.length > 0 && owned.length === 0) {
          console.log(`[Database] First secret isOwner:`, all[0]?.isOwner, all[0]?.ownerAddress);
        }
        return owned;
      },

      async getShared() {
        const all = await db.getAll('secrets');
        return all.filter((s) => !s.isOwner);
      },

      async getRecent(limit: number) {
        const all = await db.getAllFromIndex('secrets', 'by-accessed');
        return all.reverse().slice(0, limit);
      },

      async delete(contract: string) {
        await db.delete('secrets', contract.toLowerCase());
      },
    },

    // ========================================================================
    // Public Keys
    // ========================================================================
    publicKeys: {
      async get(address: string) {
        return db.get('publicKeys', address.toLowerCase());
      },

      async put(key: StoredPublicKey) {
        key.chainId = chainId;
        key.address = key.address.toLowerCase();
        key.updatedAt = Date.now();
        await db.put('publicKeys', key);
      },

      async getAll() {
        return db.getAll('publicKeys');
      },

      async delete(address: string) {
        await db.delete('publicKeys', address.toLowerCase());
      },
    },

    // ========================================================================
    // Sync State
    // ========================================================================
    syncState: {
      async get(key: string) {
        return db.get('syncState', key);
      },

      async put(state: SyncState) {
        state.chainId = chainId;
        await db.put('syncState', state);
      },
    },

    // ========================================================================
    // Messages (V2)
    // ========================================================================
    messages: {
      async get(txHash: string) {
        return db.get('messages', txHash.toLowerCase());
      },

      async put(message: StoredMessage) {
        message.chainId = chainId;
        message.txHash = message.txHash.toLowerCase();
        await db.put('messages', message);
      },

      async getAll() {
        return db.getAll('messages');
      },

      async getByType(type: string) {
        return db.getAllFromIndex('messages', 'by-type', type);
      },

      async getUnprocessed() {
        const all = await db.getAll('messages');
        return all.filter((m) => !m.processed);
      },

      async getByBlock(blockNumber: number) {
        return db.getAllFromIndex('messages', 'by-block', blockNumber);
      },

      async getRecent(limit: number) {
        const all = await db.getAllFromIndex('messages', 'by-created');
        return all.reverse().slice(0, limit);
      },

      async delete(txHash: string) {
        await db.delete('messages', txHash.toLowerCase());
      },
    },

    // ========================================================================
    // Notes (V2)
    // ========================================================================
    notes: {
      async get(noteId: string) {
        return db.get('notes', noteId);
      },

      async put(note: StoredNote) {
        note.chainId = chainId;
        note.updatedAt = Date.now();
        await db.put('notes', note);
      },

      async getAll() {
        return db.getAll('notes');
      },

      async getBySecret(contract: string) {
        return db.getAllFromIndex('notes', 'by-secret', contract.toLowerCase());
      },

      async getByKeyVault(contract: string, kvBlock: number) {
        const bySecret = await db.getAllFromIndex('notes', 'by-secret', contract.toLowerCase());
        return bySecret.filter((n) => n.keyVaultBlock === kvBlock);
      },

      async getDirty() {
        const all = await db.getAll('notes');
        return all.filter((n) => n.isDirty);
      },

      async getRecent(limit: number) {
        const all = await db.getAllFromIndex('notes', 'by-accessed');
        return all.reverse().slice(0, limit);
      },

      async delete(noteId: string) {
        await db.delete('notes', noteId);
      },
    },

    // ========================================================================
    // KeyVaults (V3)
    // ========================================================================
    keyVaults: {
      async get(keyVaultId: string) {
        return db.get('keyVaults', keyVaultId);
      },

      async put(keyVault: StoredKeyVault) {
        keyVault.chainId = chainId;
        keyVault.secretContract = keyVault.secretContract.toLowerCase();
        await db.put('keyVaults', keyVault);
      },

      async getAll() {
        return db.getAll('keyVaults');
      },

      async getBySecret(contract: string) {
        return db.getAllFromIndex('keyVaults', 'by-secret', contract.toLowerCase());
      },

      async getPrimary(contract: string) {
        const bySecret = await db.getAllFromIndex('keyVaults', 'by-secret', contract.toLowerCase());
        return bySecret.find((kv) => kv.isPrimary);
      },

      async delete(keyVaultId: string) {
        await db.delete('keyVaults', keyVaultId);
      },
    },

    // ========================================================================
    // Pending Operations (V2)
    // ========================================================================
    pendingOperations: {
      async get(operationId: string) {
        return db.get('pendingOperations', operationId);
      },

      async put(op: PendingOperation) {
        op.chainId = chainId;
        op.updatedAt = Date.now();
        await db.put('pendingOperations', op);
      },

      async getAll() {
        return db.getAll('pendingOperations');
      },

      async getByStatus(status: PendingOperationStatus) {
        return db.getAllFromIndex('pendingOperations', 'by-status', status);
      },

      async getByType(type: PendingOperationType) {
        return db.getAllFromIndex('pendingOperations', 'by-type', type);
      },

      async getPending() {
        return db.getAllFromIndex('pendingOperations', 'by-status', 'pending');
      },

      async delete(operationId: string) {
        await db.delete('pendingOperations', operationId);
      },
    },

    // ========================================================================
    // Clear All
    // ========================================================================
    async clear() {
      const stores = [
        'invites',
        'secrets',
        'publicKeys',
        'syncState',
        'messages',
        'notes',
        'keyVaults',
        'pendingOperations',
      ] as const;
      const tx = db.transaction(stores, 'readwrite');
      await Promise.all(stores.map((store) => tx.objectStore(store).clear()));
      await tx.done;
    },
  };
}

// ============================================================================
// In-Memory Database (for testing)
// ============================================================================

export function createMemoryDatabase(chainId: number): RootzDatabase {
  const invites = new Map<string, StoredInvite>();
  const secrets = new Map<string, StoredSecret>();
  const publicKeys = new Map<string, StoredPublicKey>();
  const syncStates = new Map<string, SyncState>();
  const messages = new Map<string, StoredMessage>();
  const notes = new Map<string, StoredNote>();
  const keyVaults = new Map<string, StoredKeyVault>();
  const pendingOperations = new Map<string, PendingOperation>();

  return {
    invites: {
      async get(inviteId) {
        return invites.get(inviteId);
      },
      async put(invite) {
        invite.chainId = chainId;
        invite.updatedAt = Date.now();
        invites.set(invite.inviteId, invite);
      },
      async getAll() {
        return Array.from(invites.values());
      },
      async getByStatus(status) {
        return Array.from(invites.values()).filter((i) => i.status === status);
      },
      async getBySecret(contract) {
        return Array.from(invites.values()).filter(
          (i) => i.secretContract.toLowerCase() === contract.toLowerCase()
        );
      },
      async getByMember(address) {
        return Array.from(invites.values()).filter(
          (i) => i.memberAddress.toLowerCase() === address.toLowerCase()
        );
      },
      async getByOwner(address) {
        return Array.from(invites.values()).filter(
          (i) => i.ownerAddress.toLowerCase() === address.toLowerCase()
        );
      },
      async getPending() {
        return Array.from(invites.values()).filter(
          (i) => !['complete', 'declined', 'expired'].includes(i.status)
        );
      },
      async delete(inviteId) {
        invites.delete(inviteId);
      },
    },

    secrets: {
      async get(contract) {
        return secrets.get(contract.toLowerCase());
      },
      async put(secret) {
        secret.chainId = chainId;
        secrets.set(secret.contractAddress.toLowerCase(), secret);
      },
      async getAll() {
        return Array.from(secrets.values());
      },
      async getOwned() {
        return Array.from(secrets.values()).filter((s) => s.isOwner);
      },
      async getShared() {
        return Array.from(secrets.values()).filter((s) => !s.isOwner);
      },
      async getRecent(limit) {
        return Array.from(secrets.values())
          .sort((a, b) => b.lastAccessedAt - a.lastAccessedAt)
          .slice(0, limit);
      },
      async delete(contract) {
        secrets.delete(contract.toLowerCase());
      },
    },

    publicKeys: {
      async get(address) {
        return publicKeys.get(address.toLowerCase());
      },
      async put(key) {
        key.chainId = chainId;
        key.updatedAt = Date.now();
        publicKeys.set(key.address.toLowerCase(), key);
      },
      async getAll() {
        return Array.from(publicKeys.values());
      },
      async delete(address) {
        publicKeys.delete(address.toLowerCase());
      },
    },

    syncState: {
      async get(key) {
        return syncStates.get(key);
      },
      async put(state) {
        state.chainId = chainId;
        syncStates.set(state.key, state);
      },
    },

    messages: {
      async get(txHash) {
        return messages.get(txHash.toLowerCase());
      },
      async put(message) {
        message.chainId = chainId;
        messages.set(message.txHash.toLowerCase(), message);
      },
      async getAll() {
        return Array.from(messages.values());
      },
      async getByType(type) {
        return Array.from(messages.values()).filter((m) => m.type === type);
      },
      async getUnprocessed() {
        return Array.from(messages.values()).filter((m) => !m.processed);
      },
      async getByBlock(blockNumber) {
        return Array.from(messages.values()).filter(
          (m) => m.blockNumber === blockNumber
        );
      },
      async getRecent(limit) {
        return Array.from(messages.values())
          .sort((a, b) => b.createdAt - a.createdAt)
          .slice(0, limit);
      },
      async delete(txHash) {
        messages.delete(txHash.toLowerCase());
      },
    },

    notes: {
      async get(noteId) {
        return notes.get(noteId);
      },
      async put(note) {
        note.chainId = chainId;
        note.updatedAt = Date.now();
        notes.set(note.noteId, note);
      },
      async getAll() {
        return Array.from(notes.values());
      },
      async getBySecret(contract) {
        return Array.from(notes.values()).filter(
          (n) => n.secretContract.toLowerCase() === contract.toLowerCase()
        );
      },
      async getByKeyVault(contract, kvBlock) {
        return Array.from(notes.values()).filter(
          (n) =>
            n.secretContract.toLowerCase() === contract.toLowerCase() &&
            n.keyVaultBlock === kvBlock
        );
      },
      async getDirty() {
        return Array.from(notes.values()).filter((n) => n.isDirty);
      },
      async getRecent(limit) {
        return Array.from(notes.values())
          .sort((a, b) => b.accessedAt - a.accessedAt)
          .slice(0, limit);
      },
      async delete(noteId) {
        notes.delete(noteId);
      },
    },

    keyVaults: {
      async get(keyVaultId) {
        return keyVaults.get(keyVaultId);
      },
      async put(keyVault) {
        keyVault.chainId = chainId;
        keyVault.secretContract = keyVault.secretContract.toLowerCase();
        keyVaults.set(keyVault.keyVaultId, keyVault);
      },
      async getAll() {
        return Array.from(keyVaults.values());
      },
      async getBySecret(contract) {
        return Array.from(keyVaults.values()).filter(
          (kv) => kv.secretContract.toLowerCase() === contract.toLowerCase()
        );
      },
      async getPrimary(contract) {
        return Array.from(keyVaults.values()).find(
          (kv) =>
            kv.secretContract.toLowerCase() === contract.toLowerCase() &&
            kv.isPrimary
        );
      },
      async delete(keyVaultId) {
        keyVaults.delete(keyVaultId);
      },
    },

    pendingOperations: {
      async get(operationId) {
        return pendingOperations.get(operationId);
      },
      async put(op) {
        op.chainId = chainId;
        op.updatedAt = Date.now();
        pendingOperations.set(op.operationId, op);
      },
      async getAll() {
        return Array.from(pendingOperations.values());
      },
      async getByStatus(status) {
        return Array.from(pendingOperations.values()).filter(
          (o) => o.status === status
        );
      },
      async getByType(type) {
        return Array.from(pendingOperations.values()).filter(
          (o) => o.type === type
        );
      },
      async getPending() {
        return Array.from(pendingOperations.values()).filter(
          (o) => o.status === 'pending'
        );
      },
      async delete(operationId) {
        pendingOperations.delete(operationId);
      },
    },

    async clear() {
      invites.clear();
      secrets.clear();
      publicKeys.clear();
      syncStates.clear();
      messages.clear();
      notes.clear();
      keyVaults.clear();
      pendingOperations.clear();
    },
  };
}
