/**
 * Document Secret Creation - Word Add-in Integration
 *
 * This module handles creating blockchain secrets from Word documents.
 * It is specifically designed for the Word Add-in Light Mode experience.
 *
 * Flow:
 * 1. User clicks "Save Document as Secret" in Create tab
 * 2. Document is captured with full metadata (proof of origin)
 * 3. User confirms the capture summary
 * 4. Secret is created on-chain with encrypted document content
 *
 * @module document-secret
 */

import {
  isOfficeContext,
  captureDocument,
  buildDocumentSecretContent,
  buildDocumentSummary,
  checkUnsavedChanges,
  type DocumentCapture,
} from './office-integration';
import { getStoredIdentityContract } from './storage';
import { setOwnerMode } from './create-secret';

/**
 * State for document secret creation
 */
interface DocumentSecretState {
  wallet: {
    address: string;
    signer: any;
    provider: any;
    publicKey?: string;
  };
  config: {
    contracts: {
      factory: string;
      registry: string;
      rateTable?: string;
    };
    network: {
      chainId: number;
      rpc: string;
    };
    ipfs?: any;
    gas?: any;
  };
  onSecretCreated?: (address: string) => void;
}

/**
 * Render the Document Secret section for Light Mode Create tab
 */
export function renderDocumentSecretSection(): string {
  const inOffice = isOfficeContext();

  if (!inOffice) {
    return `
      <section class="document-secret-section disabled">
        <h3>Save Document as Secret</h3>
        <p class="help-text">This feature is only available when running inside Microsoft Word.</p>
      </section>
    `;
  }

  return `
    <section class="document-secret-section">
      <h3>Save Document as Secret</h3>
      <p class="help-text">
        Capture the current Word document and save it as an encrypted secret on the blockchain.
        All document metadata will be preserved for proof of origin.
      </p>

      <!-- Owner Mode Selector -->
      <div class="doc-owner-mode-selector">
        <label>Owner:</label>
        <div class="mode-buttons">
          <button id="doc-identity-mode-btn" class="mode-btn" title="Secret owned by Identity contract - accessible from all your devices">
            Identity
          </button>
          <button id="doc-local-mode-btn" class="mode-btn active" title="Secret owned by local wallet only">
            Local
          </button>
        </div>
        <div id="doc-owner-mode-info" class="mode-info"></div>
      </div>

      <div id="document-capture-preview" class="capture-preview hidden">
        <h4>Document Preview</h4>
        <div class="preview-content"></div>
      </div>

      <div id="document-capture-status" class="status-message"></div>

      <div class="document-actions">
        <button id="capture-document-btn" class="primary">
          Capture Document
        </button>
        <button id="create-document-secret-btn" class="primary hidden">
          Create Secret
        </button>
      </div>
    </section>

    <style>
      .document-secret-section {
        margin-top: 24px;
        padding: 16px;
        background: var(--card-bg, #1e293b);
        border-radius: 8px;
        border: 1px solid var(--border-color, #334155);
      }
      .document-secret-section.disabled {
        opacity: 0.6;
      }
      .document-secret-section h3 {
        margin: 0 0 8px 0;
        font-size: 16px;
      }
      .document-secret-section .help-text {
        margin: 0 0 16px 0;
        color: var(--text-muted, #94a3b8);
        font-size: 13px;
      }
      .capture-preview {
        margin: 16px 0;
        padding: 12px;
        background: var(--bg-darker, #0f172a);
        border-radius: 6px;
        font-size: 13px;
      }
      .capture-preview.hidden {
        display: none;
      }
      .capture-preview h4 {
        margin: 0 0 12px 0;
        font-size: 14px;
        color: var(--text-color, #e2e8f0);
      }
      .preview-content {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 6px 12px;
      }
      .preview-content .label {
        color: var(--text-muted, #94a3b8);
      }
      .preview-content .value {
        color: var(--text-color, #e2e8f0);
        word-break: break-word;
      }
      .document-actions {
        display: flex;
        gap: 12px;
        flex-wrap: wrap;
      }
      .document-actions button {
        flex: 1;
        min-width: 140px;
      }
      .document-actions button.hidden {
        display: none;
      }
      /* Owner Mode Selector */
      .doc-owner-mode-selector {
        margin-bottom: 16px;
        padding: 12px;
        background: var(--bg-darker, #0f172a);
        border-radius: 6px;
      }
      .doc-owner-mode-selector label {
        display: block;
        font-size: 12px;
        color: var(--text-muted, #94a3b8);
        margin-bottom: 8px;
      }
      .mode-buttons {
        display: flex;
        gap: 8px;
        margin-bottom: 8px;
      }
      .mode-btn {
        flex: 1;
        padding: 8px 12px;
        border: 1px solid var(--border-color, #334155);
        background: transparent;
        color: var(--text-muted, #94a3b8);
        border-radius: 4px;
        font-size: 13px;
        cursor: pointer;
        transition: all 0.2s;
      }
      .mode-btn:hover {
        border-color: var(--primary, #667eea);
        color: var(--text-color, #e2e8f0);
      }
      .mode-btn.active {
        background: var(--primary, #667eea);
        border-color: var(--primary, #667eea);
        color: white;
      }
      .mode-btn.identity-active {
        background: #10b981;
        border-color: #10b981;
      }
      .mode-info {
        font-size: 11px;
        color: var(--text-muted, #94a3b8);
        line-height: 1.4;
      }
      .mode-info code {
        font-size: 10px;
        background: rgba(0,0,0,0.3);
        padding: 2px 4px;
        border-radius: 2px;
      }
    </style>
  `;
}

/**
 * Setup event handlers for document secret creation
 */
export async function setupDocumentSecretSection(state: DocumentSecretState): Promise<void> {
  if (!isOfficeContext()) {
    console.log('[DocumentSecret] Not in Office context, skipping setup');
    return;
  }

  const captureBtn = document.getElementById('capture-document-btn') as HTMLButtonElement;
  const createBtn = document.getElementById('create-document-secret-btn') as HTMLButtonElement;
  const preview = document.getElementById('document-capture-preview');
  const previewContent = preview?.querySelector('.preview-content');
  const status = document.getElementById('document-capture-status');

  let currentCapture: DocumentCapture | null = null;

  if (!captureBtn) {
    console.warn('[DocumentSecret] Capture button not found');
    return;
  }

  // Setup owner mode toggle
  const docIdentityBtn = document.getElementById('doc-identity-mode-btn');
  const docLocalBtn = document.getElementById('doc-local-mode-btn');
  const docModeInfo = document.getElementById('doc-owner-mode-info');

  // Get stored identity contract using the proper storage function
  const identityContract = getStoredIdentityContract(state.wallet.address);
  console.log('[DocumentSecret] Identity contract lookup:', identityContract);
  const hasIdentity = !!identityContract;

  const updateModeInfo = (mode: 'IDENTITY' | 'LOCAL') => {
    if (!docModeInfo) return;
    if (mode === 'IDENTITY' && identityContract) {
      docModeInfo.innerHTML = `
        <strong style="color: #10b981;">Identity Mode:</strong> Owned by your Identity contract<br>
        <code>${identityContract.slice(0, 20)}...</code><br>
        Accessible from all your devices.
      `;
    } else {
      docModeInfo.innerHTML = `
        <strong>Local Mode:</strong> Owned by this wallet only<br>
        <code>${state.wallet.address.slice(0, 20)}...</code>
      `;
    }
  };

  // Sync mode toggles between document section and main create form
  const setMode = (mode: 'IDENTITY' | 'LOCAL') => {
    // Update document section buttons
    if (docIdentityBtn && docLocalBtn) {
      if (mode === 'IDENTITY') {
        docIdentityBtn.classList.add('active', 'identity-active');
        docLocalBtn.classList.remove('active');
      } else {
        docLocalBtn.classList.add('active');
        docIdentityBtn.classList.remove('active', 'identity-active');
      }
    }
    // Directly set the owner mode in create-secret module
    // This ensures the mode is set regardless of whether the main form buttons exist
    setOwnerMode(mode);
    console.log('[DocumentSecret] Owner mode set to:', mode);
    updateModeInfo(mode);
  };

  // Initialize mode display
  if (docIdentityBtn && docLocalBtn) {
    // Disable Identity button if no identity contract
    if (!hasIdentity) {
      docIdentityBtn.setAttribute('disabled', 'true');
      docIdentityBtn.title = 'No Identity contract found. Create one in the Identity tab first.';
      docIdentityBtn.style.opacity = '0.5';
    }

    docIdentityBtn.addEventListener('click', () => {
      if (!hasIdentity) return;
      setMode('IDENTITY');
    });

    docLocalBtn.addEventListener('click', () => {
      setMode('LOCAL');
    });

    // Initialize to Local mode by default
    updateModeInfo('LOCAL');
  }

  // Capture document button
  captureBtn.addEventListener('click', async () => {
    captureBtn.disabled = true;
    captureBtn.textContent = 'Checking...';

    // Check for unsaved changes and prompt user to save first
    try {
      const hasUnsaved = await checkUnsavedChanges();
      if (hasUnsaved) {
        const proceed = confirm(
          'This document has unsaved changes.\n\n' +
          'For accurate proof-of-origin metadata, please save the document first.\n\n' +
          'Click OK to capture anyway (includes unsaved changes)\n' +
          'Click Cancel to save first, then try again.'
        );
        if (!proceed) {
          captureBtn.disabled = false;
          captureBtn.textContent = 'Capture Document';
          if (status) {
            status.textContent = 'Please save your document (Ctrl+S) and try again.';
            status.className = 'status-message info';
          }
          return;
        }
      }
    } catch (e) {
      // If we can't check, proceed anyway
      console.log('[DocumentSecret] Could not check unsaved status:', e);
    }

    captureBtn.textContent = 'Capturing...';
    if (status) {
      status.textContent = 'Capturing document and metadata...';
      status.className = 'status-message info';
    }

    try {
      currentCapture = await captureDocument();
      const summary = buildDocumentSummary(currentCapture);

      // Show preview
      if (preview && previewContent) {
        previewContent.innerHTML = Object.entries(summary)
          .filter(([_, value]) => value !== undefined && value !== null)
          .map(([key, value]) => `
            <span class="label">${formatLabel(key)}:</span>
            <span class="value">${formatValue(value)}</span>
          `).join('');
        preview.classList.remove('hidden');
      }

      if (status) {
        status.textContent = 'Document captured successfully. Review and click Create Secret.';
        status.className = 'status-message success';
      }

      // Show create button
      if (createBtn) {
        createBtn.classList.remove('hidden');
      }

      captureBtn.textContent = 'Re-capture';

    } catch (err: any) {
      console.error('[DocumentSecret] Capture failed:', err);
      if (status) {
        status.textContent = `Capture failed: ${err.message || err}`;
        status.className = 'status-message error';
      }
      currentCapture = null;
    } finally {
      captureBtn.disabled = false;
    }
  });

  // Create secret button
  if (createBtn) {
    createBtn.addEventListener('click', async () => {
      if (!currentCapture) {
        if (status) {
          status.textContent = 'Please capture the document first.';
          status.className = 'status-message error';
        }
        return;
      }

      createBtn.disabled = true;
      createBtn.textContent = 'Creating Secret...';
      if (status) {
        status.textContent = 'Creating encrypted secret on blockchain...';
        status.className = 'status-message info';
      }

      try {
        const secretAddress = await createDocumentSecret(state, currentCapture);

        if (status) {
          status.innerHTML = `
            Secret created successfully!<br>
            <a href="https://polygonscan.com/address/${secretAddress}" target="_blank">${secretAddress}</a>
          `;
          status.className = 'status-message success';
        }

        // Notify parent
        if (state.onSecretCreated) {
          state.onSecretCreated(secretAddress);
        }

        // Reset state
        currentCapture = null;
        createBtn.classList.add('hidden');
        if (preview) preview.classList.add('hidden');
        captureBtn.textContent = 'Capture Document';

      } catch (err: any) {
        console.error('[DocumentSecret] Create failed:', err);
        if (status) {
          status.textContent = `Failed to create secret: ${err.message || err}`;
          status.className = 'status-message error';
        }
      } finally {
        createBtn.disabled = false;
        createBtn.textContent = 'Create Secret';
      }
    });
  }
}

/**
 * Create a secret from the captured document by using the existing Create form.
 * This properly reuses all the form infrastructure including IDENTITY mode handling.
 */
async function createDocumentSecret(
  _state: DocumentSecretState,
  capture: DocumentCapture
): Promise<string> {
  // Build the secret content with all metadata
  const content = buildDocumentSecretContent(capture);

  console.log('[DocumentSecret] Creating secret for:', capture.metadata.filename);
  console.log('[DocumentSecret] Content size:', content.length, 'bytes');

  const secretName = capture.metadata.title || capture.metadata.filename.replace(/\.[^.]+$/, '');

  // Use the existing Create form - it already handles IDENTITY mode properly
  // Find and populate the form fields
  const nameInput = document.getElementById('secret-name') as HTMLInputElement;
  const typeSelect = document.getElementById('secret-type') as HTMLSelectElement;
  const contentTextarea = document.getElementById('secret-content') as HTMLTextAreaElement;
  const walletNameInput = document.getElementById('wallet-name') as HTMLInputElement;
  const submitBtn = document.getElementById('create-btn') as HTMLButtonElement;

  if (!nameInput || !typeSelect || !contentTextarea || !submitBtn) {
    throw new Error('Create form not found. Make sure you are on the Create tab.');
  }

  // Populate the form with document data
  nameInput.value = secretName;
  contentTextarea.value = content;
  if (walletNameInput) {
    walletNameInput.value = `Document Archive - ${new Date().toLocaleDateString()}`;
  }

  // Set type to document if available, otherwise use note
  const documentTypeOption = typeSelect.querySelector('option[value="document"]') ||
                             typeSelect.querySelector('option[value="word-document"]') ||
                             typeSelect.querySelector('option[value="note"]');
  if (documentTypeOption) {
    typeSelect.value = (documentTypeOption as HTMLOptionElement).value;
  }

  // Trigger change events to update any dependent UI
  nameInput.dispatchEvent(new Event('input', { bubbles: true }));
  contentTextarea.dispatchEvent(new Event('input', { bubbles: true }));
  typeSelect.dispatchEvent(new Event('change', { bubbles: true }));

  // Wait a tick for UI updates
  await new Promise(resolve => setTimeout(resolve, 50));

  // Create a promise to capture the result
  return new Promise((resolve, reject) => {
    // Set a timeout in case events don't fire
    let timeoutId: ReturnType<typeof setTimeout> | null = setTimeout(() => {
      cleanup();
      reject(new Error('Secret creation timed out'));
    }, 120000); // 2 minute timeout for blockchain operations

    const cleanup = () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      document.removeEventListener('secret-created', successHandler as EventListener);
      document.removeEventListener('secret-error', errorHandler as EventListener);
    };

    const successHandler = (event: CustomEvent) => {
      cleanup();
      resolve(event.detail.address);
    };

    const errorHandler = (event: CustomEvent) => {
      cleanup();
      reject(new Error(event.detail.message || 'Failed to create secret'));
    };

    document.addEventListener('secret-created', successHandler as EventListener);
    document.addEventListener('secret-error', errorHandler as EventListener);

    // Click the submit button to use all existing form logic (including IDENTITY mode)
    console.log('[DocumentSecret] Triggering Create form submission...');
    submitBtn.click();
  });
}

/**
 * Format a camelCase key as a readable label
 */
function formatLabel(key: string): string {
  return key
    .replace(/([A-Z])/g, ' $1')
    .replace(/^./, (s) => s.toUpperCase())
    .trim();
}

/**
 * Format a value for display
 */
function formatValue(value: unknown): string {
  if (value === null || value === undefined) return '—';
  if (typeof value === 'number') return value.toLocaleString();
  return String(value);
}
