// ============================================================================
// ChainReader Class
// ============================================================================

// Etherscan V2 API base URL
const ETHERSCAN_V2_API = 'https://api.etherscan.io/v2/api';

// Rate limiting: 5 calls/second for free tier
// GLOBAL rate limiter shared across ALL ChainReader instances
// Multiple instances (header, sync, identity tab) must not exceed the API key's rate limit
const RATE_LIMIT_MS = 400; // 400ms between calls = 2.5/sec (safe margin under 3/sec free tier)
let globalLastApiCall = 0;
let globalApiCallQueue: Promise<void> = Promise.resolve();

// Native currency symbols per chain
const CHAIN_SYMBOLS: Record<number, string> = {
  1: 'ETH',
  137: 'POL',
  80002: 'POL',
  81: 'JOC',
};

// Chains supported by Etherscan V2 API
// See: https://docs.etherscan.io/etherscan-v2/getting-started/supported-chains
const ETHERSCAN_SUPPORTED_CHAINS: Set<number> = new Set([
  1,      // Ethereum Mainnet
  11155111, // Sepolia
  17000,  // Holesky
  137,    // Polygon Mainnet
  80002,  // Polygon Amoy
  56,     // BNB Smart Chain
  97,     // BNB Testnet
  42161,  // Arbitrum One
  421614, // Arbitrum Sepolia
  10,     // Optimism
  11155420, // Optimism Sepolia
  8453,   // Base
  84532,  // Base Sepolia
  43114,  // Avalanche
  43113,  // Avalanche Fuji
  250,    // Fantom
  4002,   // Fantom Testnet
  59144,  // Linea
  59141,  // Linea Sepolia
  534352, // Scroll
  534351, // Scroll Sepolia
  324,    // zkSync Era
  300,    // zkSync Sepolia
  // Note: JOC (81) is NOT supported by Etherscan V2 API - uses Blockscout instead
]);

// Blockscout-compatible explorers (same API format as Etherscan, no API key needed)
// These chains use Blockscout which is API-compatible with Etherscan V2
const BLOCKSCOUT_EXPLORERS: Record<number, string> = {
  81: 'https://explorer.japanopenchain.org/api',      // JOC Mainnet
  10081: 'https://explorer.testnet.japanopenchain.org/api', // JOC Testnet
};

/**
 * Check if a chain has explorer API support (Etherscan V2 or Blockscout)
 */
function hasExplorerSupport(chainId: number): boolean {
  return ETHERSCAN_SUPPORTED_CHAINS.has(chainId) || chainId in BLOCKSCOUT_EXPLORERS;
}

/**
 * Get the explorer API URL for a chain
 * Returns Blockscout URL for JOC, Etherscan V2 for others
 */
function getExplorerApiUrl(chainId: number): string {
  if (chainId in BLOCKSCOUT_EXPLORERS) {
    return BLOCKSCOUT_EXPLORERS[chainId];
  }
  return ETHERSCAN_V2_API;
}

/**
 * Check if a chain uses Blockscout (no API key needed)
 */
function usesBlockscout(chainId: number): boolean {
  return chainId in BLOCKSCOUT_EXPLORERS;
}

/**
 * Build explorer API URL with appropriate parameters.
 * Handles both Etherscan V2 and Blockscout APIs.
 *
 * @param chainId - Chain ID
 * @param module - API module (e.g., 'account', 'logs')
 * @param action - API action (e.g., 'txlist', 'getLogs')
 * @param etherscanApiKey - API key (only used for Etherscan, not Blockscout)
 * @returns URL object ready for additional parameters
 */
function buildExplorerUrl(
  chainId: number,
  module: string,
  action: string,
  etherscanApiKey?: string
): URL {
  const baseUrl = getExplorerApiUrl(chainId);
  const url = new URL(baseUrl);

  // Blockscout doesn't need chainid (URL already identifies chain)
  // Etherscan V2 requires chainid parameter
  if (!usesBlockscout(chainId)) {
    url.searchParams.set('chainid', chainId.toString());
  }

  url.searchParams.set('module', module);
  url.searchParams.set('action', action);

  // Only add API key for Etherscan (Blockscout doesn't need it)
  if (!usesBlockscout(chainId) && etherscanApiKey) {
    url.searchParams.set('apikey', etherscanApiKey);
  }

  return url;
}

export class ChainReader {
  private chains: ChainConfig[];
  private wallets: Set<string>;
  private providers: Map<string, ethers.Provider> = new Map();
  private etherscanApiKey: string;

  /**
   * Create a ChainReader to monitor wallets across chains.
   *
   * READING vs WRITING:
   * - ChainReader is for reading transactions sent TO wallets
   * - Factory addresses are NOT needed for reading
   * - For creating secrets, use SecretOrchestrator
   *
   * @example
   * ```typescript
   * const reader = new ChainReader({
   *   chains: [
   *     { name: 'amoy', chainId: 80002, rpc: 'https://rpc-amoy.polygon.technology' },
   *     { name: 'joc', chainId: 81, rpc: 'https://rpc-1.japanopenchain.org:8545' },
   *   ],
   *   wallets: ['0x1234...', '0x5678...'],
   * });
   *
   * // Read all messages sent to these wallets
   * const messages = await reader.getWalletMessages(startBlock);
   * ```
   */
  constructor(config: ChainReaderConfig) {
    this.chains = config.chains;
    this.wallets = new Set(config.wallets.map(w => w.toLowerCase()));
    this.etherscanApiKey = config.etherscanApiKey || '';
  }

  /**
   * Get or create provider for a chain
   */
  private getProviderForChain(chain: ChainConfig): ethers.Provider {
    if (!this.providers.has(chain.name)) {
      this.providers.set(chain.name, new ethers.JsonRpcProvider(chain.rpc));
    }
    return this.providers.get(chain.name)!;
  }

  /**
   * Get configured chains
   */
  getChains(): ChainConfig[] {
    return [...this.chains];
  }

  /**
   * Add a wallet/Identity contract to monitor.
   * Useful for adding Identity contracts discovered from incoming invites.
   */
  addWallet(address: string): void {
    const normalized = address.toLowerCase();
    if (!this.wallets.has(normalized)) {
      this.wallets.add(normalized);
      console.log(`[ChainReader] Added wallet to monitor: ${address.slice(0, 10)}...`);
    }
  }

  /**
   * Get configured wallet addresses
   */
  getWallets(): string[] {
    return [...this.wallets];
  }

  /**
   * Add a chain to monitor
   */
  addChain(chain: ChainConfig): void {
    if (!this.chains.find(c => c.name === chain.name)) {
      this.chains.push(chain);
    }
  }

  // ==========================================================================
  // Rate-Limited API Helper
  // ==========================================================================

  /**
   * Make a rate-limited API call to Etherscan V2 API.
   * Uses GLOBAL rate limiter shared across all ChainReader instances.
   * Retries up to 3 times on rate limit errors with exponential backoff.
   */
  private async rateLimitedFetch<T>(url: string): Promise<T> {
    const maxRetries = 3;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      // Global queue — all ChainReader instances share this
      globalApiCallQueue = globalApiCallQueue.then(async () => {
        const now = Date.now();
        const timeSinceLastCall = now - globalLastApiCall;

        if (timeSinceLastCall < RATE_LIMIT_MS) {
          await new Promise(resolve => setTimeout(resolve, RATE_LIMIT_MS - timeSinceLastCall));
        }

        globalLastApiCall = Date.now();
      });

      await globalApiCallQueue;

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Etherscan API error: ${response.status} ${response.statusText}`);
      }

      const data = await response.json();

      // Check for rate limit response — retry with backoff
      const isRateLimit = data.status === '0' && (
        (typeof data.result === 'string' && data.result.includes('rate limit')) ||
        (typeof data.message === 'string' && data.message.includes('rate limit'))
      );

      if (isRateLimit && attempt < maxRetries) {
        const backoff = (attempt + 1) * 1000; // 1s, 2s, 3s
        console.warn(`[ChainReader] Rate limited, retrying in ${backoff}ms (attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, backoff));
        continue;
      }

      // Check for Etherscan API errors
      // Valid empty responses vary by endpoint:
      // - txlist: "No transactions found"
      // - logs: "No records found" (Etherscan) or "No logs found" (Blockscout)
      // - txlistinternal: "NOTOK" with result "No internal transactions found"
      const validEmptyMessages = ['No transactions found', 'No records found', 'No logs found', 'NOTOK'];
      if (data.status === '0' && !validEmptyMessages.includes(data.message)) {
        throw new Error(`Etherscan API: ${data.message || data.result}`);
      }

      return data;
    }

    throw new Error('Etherscan API: max retries exceeded');
  }

  // ==========================================================================
  // Balance Methods
  // ==========================================================================

  /**
   * Get balance for a wallet on a specific chain.
   * Uses RPC for direct balance query (more reliable than API).
   */
  async getBalance(wallet: string, chainName: string): Promise<WalletBalance> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    const provider = this.getProviderForChain(chain);
    // Normalize address to checksum format for ethers.js
    const normalizedWallet = ethers.getAddress(wallet.toLowerCase());
    const balance = await provider.getBalance(normalizedWallet);
    const symbol = CHAIN_SYMBOLS[chain.chainId] || 'ETH';

    return {
      chain: chain.name,
      chainId: chain.chainId,
      wallet: wallet.toLowerCase(),
      balance: balance.toString(),
      balanceFormatted: `${ethers.formatEther(balance)} ${symbol}`,
    };
  }

  /**
   * Get balances for all configured wallets on all configured chains.
   * Uses RPC calls with rate limiting.
   */
  async getBalances(): Promise<WalletBalance[]> {
    const balances: WalletBalance[] = [];

    for (const chain of this.chains) {
      for (const wallet of this.wallets) {
        try {
          const balance = await this.getBalance(wallet, chain.name);
          balances.push(balance);
        } catch (error) {
          console.error(`[ChainReader] Error getting balance for ${wallet} on ${chain.name}:`, error);
        }
      }
    }

    return balances;
  }

  // ==========================================================================
  // Block Methods
  // ==========================================================================

  /**
   * Fetch a specific block by number from a chain.
   * Uses RPC directly.
   */
  async fetchBlock(chainName: string, blockNumber: number | 'latest'): Promise<ethers.Block | null> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    const provider = this.getProviderForChain(chain);
    return provider.getBlock(blockNumber === 'latest' ? 'latest' : blockNumber);
  }

  // ==========================================================================
  // Transaction Methods
  // ==========================================================================

  /**
   * Fetch a specific transaction by hash.
   * Tries all configured chains if chainName not specified.
   */
  async fetchTransaction(txHash: string, chainName?: string): Promise<{ chain: string; tx: ethers.TransactionResponse } | null> {
    // If chain specified, use it directly
    if (chainName) {
      const chain = this.chains.find(c => c.name === chainName);
      if (!chain) {
        throw new Error(`Chain '${chainName}' not configured`);
      }

      const provider = this.getProviderForChain(chain);
      const tx = await provider.getTransaction(txHash);
      return tx ? { chain: chain.name, tx } : null;
    }

    // Try all chains
    for (const chain of this.chains) {
      try {
        const provider = this.getProviderForChain(chain);
        const tx = await provider.getTransaction(txHash);
        if (tx) {
          return { chain: chain.name, tx };
        }
      } catch {
        // Not on this chain, continue
        continue;
      }
    }

    return null;
  }

  /**
   * Fetch transaction receipt by hash.
   */
  async fetchTransactionReceipt(txHash: string, chainName?: string): Promise<{ chain: string; receipt: ethers.TransactionReceipt } | null> {
    // If chain specified, use it directly
    if (chainName) {
      const chain = this.chains.find(c => c.name === chainName);
      if (!chain) {
        throw new Error(`Chain '${chainName}' not configured`);
      }

      const provider = this.getProviderForChain(chain);
      const receipt = await provider.getTransactionReceipt(txHash);
      return receipt ? { chain: chain.name, receipt } : null;
    }

    // Try all chains
    for (const chain of this.chains) {
      try {
        const provider = this.getProviderForChain(chain);
        const receipt = await provider.getTransactionReceipt(txHash);
        if (receipt) {
          return { chain: chain.name, receipt };
        }
      } catch {
        continue;
      }
    }

    return null;
  }

  /**
   * Get internal transactions for a specific transaction hash.
   * Internal transactions are contract-to-contract calls within a transaction.
   * Uses Etherscan V2 API txlistinternal endpoint.
   *
   * @param txHash - The parent transaction hash
   * @param chainName - Which chain to query
   * @returns Array of internal transactions
   *
   * @example
   * ```typescript
   * // Get internal txs from a factory call that creates a secret
   * const internalTxs = await reader.getInternalTransactions(txHash, 'amoy');
   * const createTx = internalTxs.find(tx => tx.type === 'create');
   * console.log('Created contract:', createTx?.contractAddress);
   * ```
   */
  async getInternalTransactions(
    txHash: string,
    chainName: string
  ): Promise<InternalTransaction[]> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    // Check if chain has explorer API support (Etherscan V2 or Blockscout)
    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} (${chain.chainId}) not supported by any explorer API`);
      return [];
    }

    // Blockscout doesn't need an API key, but Etherscan does
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key - cannot query internal transactions');
      return [];
    }

    try {
      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'account');
      url.searchParams.set('action', 'txlistinternal');
      url.searchParams.set('txhash', txHash);
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: Array<{
          blockNumber: string;
          from: string;
          to: string;
          value: string;
          gas: string;
          gasUsed: string;
          input: string;
          type: string;
          contractAddress: string;
          isError: string;
          errCode: string;
        }> | string;
      }>(url.toString());

      // Handle "No internal transactions found"
      if (response.status === '0' && response.message === 'No transactions found') {
        return [];
      }

      if (response.status === '0' || typeof response.result === 'string') {
        console.error(`[ChainReader] API error for internal txs:`, response.result);
        return [];
      }

      return response.result.map(tx => ({
        chain: chain.name,
        chainId: chain.chainId,
        txHash,
        blockNumber: parseInt(tx.blockNumber, 10),
        from: tx.from.toLowerCase(),
        to: tx.to?.toLowerCase() || '',
        value: tx.value,
        gas: tx.gas,
        gasUsed: tx.gasUsed,
        input: tx.input,
        type: (tx.type?.toLowerCase() || 'call') as InternalTransaction['type'],
        contractAddress: tx.contractAddress?.toLowerCase() || undefined,
        isError: tx.isError === '1',
        errCode: tx.errCode || undefined,
      }));

    } catch (error) {
      console.error(`[ChainReader] Error fetching internal transactions:`, error);
      return [];
    }
  }

  // ==========================================================================
  // Main API - Wallet Message Reading
  // ==========================================================================

  /**
   * Get all messages sent TO configured wallets across all chains.
   * This is the primary read operation - monitoring incoming transactions.
   *
   * @param startBlock - Block number to start from (per chain)
   * @param options - Optional settings
   * @param options.includeSimpleTransfers - Include simple transfers with no input data (default: false)
   * @returns WalletMessage[] - All messages across all chains, sorted by block
   *
   * @example
   * ```typescript
   * // Get only Rootz protocol messages
   * const messages = await reader.getWalletMessages(0);
   *
   * // Include simple POL transfers (useful for debugging)
   * const allTx = await reader.getWalletMessages(0, { includeSimpleTransfers: true });
   * ```
   */
  async getWalletMessages(
    startBlock: number = 0,
    options: { includeSimpleTransfers?: boolean } = {}
  ): Promise<WalletMessage[]> {
    const { includeSimpleTransfers = false } = options;
    const allMessages: WalletMessage[] = [];

    // Query each chain in parallel
    const chainPromises = this.chains.map(async (chain) => {
      try {
        const provider = this.getProviderForChain(chain);
        const currentBlock = await provider.getBlockNumber();

        // Get transactions for each wallet on this chain
        const messages: WalletMessage[] = [];
        for (const wallet of this.wallets) {
          const walletMessages = await this.getMessagesForWallet(
            chain,
            wallet,
            startBlock,
            currentBlock,
            includeSimpleTransfers
          );
          messages.push(...walletMessages);
        }

        return messages;
      } catch (error) {
        console.error(`[ChainReader] Error querying chain ${chain.name}:`, error);
        return [];
      }
    });

    const results = await Promise.all(chainPromises);
    for (const messages of results) {
      allMessages.push(...messages);
    }

    // Sort by block number
    allMessages.sort((a, b) => a.blockNumber - b.blockNumber);

    return allMessages;
  }

  /**
   * Get messages for a specific wallet on a specific chain.
   * Uses Etherscan V2 API for transaction history.
   *
   * @param includeSimpleTransfers - If true, include simple POL transfers (no input data)
   */
  private async getMessagesForWallet(
    chain: ChainConfig,
    wallet: string,
    startBlock: number,
    endBlock: number,
    includeSimpleTransfers: boolean = false
  ): Promise<WalletMessage[]> {
    const messages: WalletMessage[] = [];

    // Check if chain has explorer API support (Etherscan V2 or Blockscout)
    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Skipping ${chain.name} (${chain.chainId}) - not supported by any explorer API`);
      return messages;
    }

    // Check if we have an API key (Blockscout doesn't need one)
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn(`[ChainReader] No Etherscan API key - cannot query ${chain.name} for wallet ${wallet}`);
      return messages;
    }

    try {
      // Build explorer API URL (Etherscan V2 or Blockscout)
      const url = buildExplorerUrl(chain.chainId, 'account', 'txlist', this.etherscanApiKey);
      url.searchParams.set('address', wallet);
      url.searchParams.set('startblock', startBlock.toString());
      url.searchParams.set('endblock', endBlock.toString());
      url.searchParams.set('sort', 'asc');

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EtherscanTx[] | string;
      }>(url.toString());

      // Handle "No transactions found" case
      if (response.status === '0' && response.message === 'No transactions found') {
        return messages;
      }

      // Handle error response
      if (response.status === '0' || typeof response.result === 'string') {
        console.error(`[ChainReader] API error for ${chain.name}:`, response.result);
        return messages;
      }

      const txList = response.result as EtherscanTx[];

      // Also query internal transactions (for messages from Identity contracts)
      // When a message is sent via Identity.executeTransaction(), it becomes an internal TX
      const internalUrl = buildExplorerUrl(chain.chainId, 'account', 'txlistinternal', this.etherscanApiKey);
      internalUrl.searchParams.set('address', wallet);
      internalUrl.searchParams.set('startblock', startBlock.toString());
      internalUrl.searchParams.set('endblock', endBlock.toString());
      internalUrl.searchParams.set('sort', 'asc');

      let internalTxList: EtherscanTx[] = [];
      try {
        const internalResponse = await this.rateLimitedFetch<{
          status: string;
          message: string;
          result: EtherscanTx[] | string;
        }>(internalUrl.toString());

        if (internalResponse.status === '1' && Array.isArray(internalResponse.result)) {
          internalTxList = internalResponse.result as EtherscanTx[];
        }
      } catch (internalError) {
        console.warn(`[ChainReader] Error fetching internal transactions:`, internalError);
      }

      // Query event logs for Identity→wallet messages (case: Identity sends to EOA)
      // When an Identity contract calls executeTransaction() with an EOA destination,
      // NO internal transaction is created (EOAs can't receive calls).
      // The message is ONLY in the event log emitted by the Identity contract.
      // Event signature: TransactionExecuted(address indexed destination, address indexed signer, bytes data)
      // Topic0: 0x8ce72e6ea6e17c38c1d47dbef9d86b9009c0f581fa49f0c92cc1686ac9560c86
      // Topic1: destination (recipient) - padded to 32 bytes
      // Topic2: signer (rivet) - padded to 32 bytes
      const eventMessages: WalletMessage[] = [];
      try {
        const IDENTITY_TX_EXECUTED_TOPIC = '0x8ce72e6ea6e17c38c1d47dbef9d86b9009c0f581fa49f0c92cc1686ac9560c86';
        const paddedWallet = '0x' + wallet.slice(2).toLowerCase().padStart(64, '0');

        const logsUrl = new URL(ETHERSCAN_V2_API);
        logsUrl.searchParams.set('chainid', chain.chainId.toString());
        logsUrl.searchParams.set('module', 'logs');
        logsUrl.searchParams.set('action', 'getLogs');
        logsUrl.searchParams.set('fromBlock', startBlock.toString());
        logsUrl.searchParams.set('toBlock', endBlock.toString());
        logsUrl.searchParams.set('topic0', IDENTITY_TX_EXECUTED_TOPIC);
        logsUrl.searchParams.set('topic1', paddedWallet);
        logsUrl.searchParams.set('topic0_1_opr', 'and');
        logsUrl.searchParams.set('apikey', this.etherscanApiKey);

        const logsResponse = await this.rateLimitedFetch<{
          status: string;
          message: string;
          result: EventLogResult[] | string;
        }>(logsUrl.toString());

        if (logsResponse.status === '1' && Array.isArray(logsResponse.result)) {
          const logs = logsResponse.result as EventLogResult[];

          for (const log of logs) {
            try {
              // TransactionExecuted event: (address indexed target, uint256 value, bytes data, address indexed sender, uint256 timestamp)
              // The log.data contains ABI-encoded: (uint256 value, bytes data, uint256 timestamp)
              // ABI encoding: slot 0 = value, slot 1 = offset to bytes, slot 2 = timestamp, then bytes data
              const data = log.data;
              if (!data || data === '0x' || data.length < 130) {
                continue;
              }

              // Read offset from slot 1, then extract bytes data from that position
              const offset = parseInt(data.slice(66, 130), 16);
              const lengthPosition = 2 + (offset * 2);
              const dataLength = parseInt(data.slice(lengthPosition, lengthPosition + 64), 16);
              const innerData = '0x' + data.slice(lengthPosition + 64, lengthPosition + 64 + (dataLength * 2));

              const messageType = this.identifyMessageType(innerData);
              const payload = this.decodeJsonMessage(innerData);

              if (messageType !== 'unknown' || payload) {
                // Extract signer (rivet) from topic2
                const signerTopic = log.topics[2];
                const signingRivet = signerTopic ? '0x' + signerTopic.slice(26) : undefined;

                // Parse blockNumber and timestamp - Etherscan returns decimal strings, not hex
                // Check if value starts with '0x' to determine format
                const blockNum = log.blockNumber.startsWith('0x')
                  ? parseInt(log.blockNumber, 16)
                  : parseInt(log.blockNumber, 10);
                const timestamp = log.timeStamp.startsWith('0x')
                  ? parseInt(log.timeStamp, 16)
                  : parseInt(log.timeStamp, 10);

                const message: WalletMessage = {
                  chain: chain.name,
                  chainId: chain.chainId,
                  txHash: log.transactionHash,
                  blockNumber: blockNum,
                  from: log.address.toLowerCase(), // Identity contract that emitted event
                  to: wallet.toLowerCase(),
                  timestamp: timestamp,
                  type: messageType,
                  payload,
                  raw: innerData,
                  signingRivet: signingRivet?.toLowerCase(),
                };
                eventMessages.push(message);
              }
            } catch (decodeError) {
              console.warn(`[ChainReader] Failed to decode event log data:`, decodeError);
            }
          }
        }
      } catch (logsError) {
        console.warn(`[ChainReader] Error fetching event logs:`, logsError);
      }

      // Combine regular and internal transactions
      const allTx = [...txList, ...internalTxList];
      const seenHashes = new Set<string>();

      // Add event-based messages (track hashes to avoid duplicates)
      for (const msg of eventMessages) {
        if (!seenHashes.has(msg.txHash)) {
          seenHashes.add(msg.txHash);
          messages.push(msg);
        }
      }

      // Process each transaction (regular + internal)
      for (const tx of allTx) {
        // Deduplicate by hash (in case same tx appears in both lists)
        if (seenHashes.has(tx.hash)) continue;
        seenHashes.add(tx.hash);

        // Check for executeTransaction calls TO Identity contracts where destination is our wallet
        // This handles messages sent via Identity.executeTransaction()
        // Method signature: executeTransaction(address destination, uint256 value, bytes data)
        // Method ID: 0x3f579f42
        const EXECUTE_TX_METHOD_ID = '0x3f579f42';
        if (tx.input?.startsWith(EXECUTE_TX_METHOD_ID) && tx.input.length > 138) {
          // Decode: methodId (4 bytes) + destination (32 bytes padded) + value (32 bytes) + data offset + data
          const destinationHex = '0x' + tx.input.slice(10, 74).replace(/^0+/, ''); // Remove leading zeros
          const destinationAddress = destinationHex.length >= 42 ? destinationHex : '0x' + tx.input.slice(34, 74);

          // Check if destination is ANY of our monitored wallets (not just current one)
          // This is critical for Identity mode: TX is TO Identity, but destination is the target wallet
          const normalizedDestination = destinationAddress.toLowerCase();
          if (this.wallets.has(normalizedDestination)) {
            // This is a message sent via Identity.executeTransaction() TO a monitored wallet!
            // Extract the inner message data
            // bytes data is at offset 68 (after methodId + destination + value)
            // First 32 bytes at offset 68 is the data offset pointer
            // Then 32 bytes for length, then the actual data
            try {
              const dataOffsetHex = tx.input.slice(138, 202); // offset pointer
              const dataOffset = parseInt(dataOffsetHex, 16) * 2; // Convert to string position
              const dataLengthHex = tx.input.slice(10 + dataOffset, 10 + dataOffset + 64);
              const dataLength = parseInt(dataLengthHex, 16) * 2;
              const innerData = '0x' + tx.input.slice(10 + dataOffset + 64, 10 + dataOffset + 64 + dataLength);

              // Process the inner message
              const messageType = this.identifyMessageType(innerData);
              const payload = this.decodeJsonMessage(innerData);

              if (messageType !== 'unknown' || payload) {
                const signingRivet = tx.from?.toLowerCase(); // Rivet that signed the tx
                messages.push({
                  chain: chain.name,
                  chainId: chain.chainId,
                  txHash: tx.hash,
                  blockNumber: parseInt(tx.blockNumber, 10),
                  from: tx.to!.toLowerCase(), // Identity contract is the "sender"
                  to: normalizedDestination,  // The actual target wallet
                  timestamp: parseInt(tx.timeStamp, 10),
                  type: messageType,
                  payload,
                  raw: innerData,
                  signingRivet,              // Rivet wallet to send response to (EOA)
                });
                continue; // Don't process as regular tx
              }
            } catch (decodeError) {
              console.warn(`[ChainReader] Failed to decode executeTransaction data:`, decodeError);
            }
          }
        }

        // Handle internal transactions with empty input data
        // When messages are sent via Identity.executeTransaction(), the internal TX to the recipient
        // has empty input - we need to fetch the parent TX to get the actual message data
        const isInternalTxWithNoData = (!tx.input || tx.input === '0x' || tx.input === '') &&
                                        tx.to?.toLowerCase() === wallet.toLowerCase();

        if (isInternalTxWithNoData) {
          // This might be an internal TX from an Identity contract
          // Fetch the parent transaction to get the executeTransaction data
          try {
            const chainProvider = this.getProviderForChain(chain);
            const parentTx = await chainProvider.getTransaction(tx.hash);
            if (parentTx && parentTx.data && parentTx.data.startsWith(EXECUTE_TX_METHOD_ID) && parentTx.data.length > 138) {
              // This is an executeTransaction call - decode the inner message
              const destinationHex = '0x' + parentTx.data.slice(10, 74).replace(/^0+/, '');
              const destinationAddress = destinationHex.length >= 42 ? destinationHex : '0x' + parentTx.data.slice(34, 74);

              if (destinationAddress.toLowerCase() === wallet.toLowerCase()) {
                // Extract the inner message data
                const dataOffsetHex = parentTx.data.slice(138, 202);
                const dataOffset = parseInt(dataOffsetHex, 16) * 2;
                const dataLengthHex = parentTx.data.slice(10 + dataOffset, 10 + dataOffset + 64);
                const dataLength = parseInt(dataLengthHex, 16) * 2;
                const innerData = '0x' + parentTx.data.slice(10 + dataOffset + 64, 10 + dataOffset + 64 + dataLength);

                const messageType = this.identifyMessageType(innerData);
                const payload = this.decodeJsonMessage(innerData);

                if (messageType !== 'unknown' || payload) {
                  const signingRivet = parentTx.from?.toLowerCase();
                  const identityContract = parentTx.to?.toLowerCase() || '';
                  messages.push({
                    chain: chain.name,
                    chainId: chain.chainId,
                    txHash: tx.hash,
                    blockNumber: parseInt(tx.blockNumber, 10),
                    from: identityContract, // Identity contract is the "sender"
                    to: wallet.toLowerCase(),
                    timestamp: parseInt(tx.timeStamp, 10),
                    type: messageType,
                    payload,
                    raw: innerData,
                    signingRivet,
                  });
                  continue;
                }
              }
            }
          } catch (fetchError) {
            console.warn(`[ChainReader] Failed to fetch parent TX for internal tx ${tx.hash.slice(0, 12)}...:`, fetchError);
          }
        }

        // Process both incoming (to) and outgoing (from) transactions
        // Incoming: we're the recipient (team-invite, team-keys, direct-keys received)
        // Outgoing: we're the sender (team-invite, invite-response, team-keys, direct-keys sent)
        const isIncoming = tx.to?.toLowerCase() === wallet.toLowerCase();
        const isOutgoing = tx.from?.toLowerCase() === wallet.toLowerCase();

        if (!isIncoming && !isOutgoing) {
          continue;
        }

        // Check for simple transfers (no input data)
        const isSimpleTransfer = !tx.input || tx.input === '0x';

        // For failed transactions: still read team messages (data is on chain)
        // Identity contracts may revert when receiving data, but rivets still need to read it
        if (tx.isError === '1') {
          // Only skip if it's a simple transfer or doesn't have team message data
          if (isSimpleTransfer) {
            continue;
          }
          // Check if this is a team message - if so, process it even though TX failed
          const failedMessageType = this.identifyMessageType(tx.input);
          const isTeamMessage = ['team-invite', 'invite-response', 'team-keys', 'direct-keys'].includes(failedMessageType);
          if (!isTeamMessage) {
            continue; // Skip failed non-team transactions
          }
          console.log(`[ChainReader] Reading team message from reverted TX: ${failedMessageType} in ${tx.hash.slice(0, 12)}...`);
        }

        // Skip simple transfers unless includeSimpleTransfers is true
        if (isSimpleTransfer && !includeSimpleTransfers) {
          continue;
        }

        // For simple transfers, use 'transfer' type
        let messageType: MessageType = 'transfer';
        let payload: TransactionPayload | null = null;

        if (!isSimpleTransfer) {
          // Try to parse the message
          messageType = this.identifyMessageType(tx.input);
          payload = this.decodeJsonMessage(tx.input);

          // Skip unrecognized messages unless it's a simple transfer
          if (messageType === 'unknown' && !payload) {
            continue;
          }
        }

        messages.push({
          chain: chain.name,
          chainId: chain.chainId,
          txHash: tx.hash,
          blockNumber: parseInt(tx.blockNumber, 10),
          from: tx.from.toLowerCase(),
          to: tx.to.toLowerCase(),
          timestamp: parseInt(tx.timeStamp, 10),
          type: messageType,
          payload,
          raw: tx.input,
        });
      }

      console.log(`[ChainReader] Parsed ${messages.length} Rootz messages from ${txList.length} regular + ${internalTxList.length} internal + ${eventMessages.length} event log sources`);
      return messages;

    } catch (error) {
      console.error(`[ChainReader] Error fetching transactions for ${wallet} on ${chain.name}:`, error);
      return messages;
    }
  }

  /**
   * Get current block number for a specific chain.
   */
  async getCurrentBlock(chainName: string): Promise<number> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }
    const provider = this.getProviderForChain(chain);
    return provider.getBlockNumber();
  }

  /**
   * Get current block numbers for all configured chains.
   */
  async getCurrentBlocks(): Promise<Map<string, number>> {
    const blocks = new Map<string, number>();

    await Promise.all(
      this.chains.map(async (chain) => {
        try {
          const provider = this.getProviderForChain(chain);
          const block = await provider.getBlockNumber();
          blocks.set(chain.name, block);
        } catch (error) {
          console.error(`[ChainReader] Error getting block for ${chain.name}:`, error);
        }
      })
    );

    return blocks;
  }

  /**
   * Parse a single transaction into a ChainMessage.
   */
  parseTransaction(tx: ethers.TransactionResponse): ChainMessage {
    const messageType = this.identifyMessageType(tx.data);
    const payload = this.decodeJsonMessage(tx.data);

    return {
      type: messageType,
      txHash: tx.hash,
      blockNumber: tx.blockNumber || 0,
      from: tx.from.toLowerCase(),
      to: tx.to?.toLowerCase() || '',
      timestamp: 0, // Will be filled from block
      payload,
      raw: tx.data,
    };
  }

  /**
   * Identify message type from transaction input data.
   */
  identifyMessageType(inputData: string): MessageType {
    const payload = this.decodeJsonMessage(inputData);
    if (!payload) return 'unknown';

    if (isTeamInvite(payload)) return 'team-invite';
    if (isInviteResponse(payload)) return 'invite-response';
    if (isTeamKeys(payload)) return 'team-keys';
    if (isEncryptedKeys(payload)) return 'encrypted-keys';
    if (isDirectKeys(payload)) return 'direct-keys';
    if (isGenesis(payload)) return 'genesis';

    return 'unknown';
  }

  /**
   * Decode JSON message from transaction input data.
   * Returns null silently for non-JSON data (contract calls, etc.)
   */
  decodeJsonMessage(inputData: string): TransactionPayload | null {
    if (!inputData || inputData === '0x') return null;

    // Quick check: JSON messages start with '{' (0x7b in hex)
    // Most contract calls start with function selectors that aren't valid UTF-8
    // Skip decoding attempt for obvious non-JSON data
    if (!inputData.startsWith('0x7b')) {
      return null;
    }

    try {
      const decoded = ethers.toUtf8String(inputData);
      const json = JSON.parse(decoded);
      return json as TransactionPayload;
    } catch {
      // Silent fail - most transaction data isn't JSON (contract calls, etc.)
      return null;
    }
  }

  // ==========================================================================
  // V5 Event Log Methods
  // ==========================================================================

  /**
   * Get secrets (contracts) created by a wallet.
   * Uses internal transactions to find contract creations from factory calls.
   *
   * @param wallet - Wallet address to check
   * @param chainName - Chain to query
   * @returns Array of created secret contract addresses
   */
  async getSecretsCreatedByWallet(
    wallet: string,
    chainName: string
  ): Promise<string[]> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for internal tx query`);
      return [];
    }

    // Blockscout doesn't need an API key, but Etherscan does
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for contract query');
      return [];
    }

    try {
      // Query all transactions FROM this wallet
      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'account');
      url.searchParams.set('action', 'txlist');
      url.searchParams.set('address', wallet);
      url.searchParams.set('startblock', '0');
      url.searchParams.set('endblock', '99999999');
      url.searchParams.set('sort', 'asc');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EtherscanTx[] | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        return [];
      }

      const txList = response.result as EtherscanTx[];
      const secretAddresses: string[] = [];

      // Find transactions FROM wallet that created contracts
      for (const tx of txList) {
        if (tx.from.toLowerCase() !== wallet.toLowerCase()) continue;
        if (tx.isError === '1') continue;

        // Get internal transactions to find contract creations
        const internalTxs = await this.getInternalTransactions(tx.hash, chain.name);
        for (const itx of internalTxs) {
          if (itx.type === 'create' && itx.contractAddress) {
            secretAddresses.push(itx.contractAddress.toLowerCase());
          }
        }
      }

      console.log(`[ChainReader] Found ${secretAddresses.length} secrets created by ${wallet}`);
      return secretAddresses;

    } catch (error) {
      console.error(`[ChainReader] Error finding secrets for ${wallet}:`, error);
      return [];
    }
  }

  /**
   * Get KeyVaultCreated events for a secret contract.
   * V5 contracts store all secret data in this event.
   *
   * @param secretAddress - Secret contract address
   * @param chainName - Chain to query
   * @returns Parsed KeyVaultCreated event data or null
   */
  async getKeyVaultCreatedEvent(
    secretAddress: string,
    chainName: string
  ): Promise<{
    blockNumber: number;
    creator: string;
    encryptedKeysData: string;
    schemaDefinition: string;
    timestamp: number;
    txHash: string;
  } | null> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      return null;
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      return null;
    }

    try {
      // KeyVaultCreated event signature:
      // KeyVaultCreated(uint256 indexed blockNumber, address indexed creator, bytes encryptedKeysData, bytes schemaDefinition, uint256 timestamp)
      const eventSignature = topic0('KeyVaultCreated');

      // Use buildExplorerUrl for Blockscout/Etherscan compatibility
      const url = buildExplorerUrl(chain.chainId, 'logs', 'getLogs', this.etherscanApiKey);
      url.searchParams.set('address', secretAddress);
      url.searchParams.set('topic0', eventSignature);
      url.searchParams.set('fromBlock', '0');
      url.searchParams.set('toBlock', 'latest');

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: Array<{
          address: string;
          topics: string[];
          data: string;
          blockNumber: string;
          transactionHash: string;
          timeStamp: string;
        }> | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        return null;
      }

      const logs = response.result;
      if (logs.length === 0) {
        return null;
      }

      // Parse the first (and typically only) KeyVaultCreated event
      const log = logs[0];

      // topics[1] = indexed blockNumber (uint256)
      // topics[2] = indexed creator (address)
      const vaultBlockNumber = parseInt(log.topics[1], 16);
      const creator = '0x' + log.topics[2].slice(-40);

      // Decode non-indexed parameters from data
      // data contains: encryptedKeysData (bytes), schemaDefinition (bytes), timestamp (uint256)
      const abiCoder = new ethers.AbiCoder();
      const decoded = abiCoder.decode(
        ['bytes', 'bytes', 'uint256'],
        log.data
      );

      const encryptedKeysData = ethers.toUtf8String(decoded[0]);
      const schemaDefinition = ethers.toUtf8String(decoded[1]);
      const timestamp = Number(decoded[2]);

      return {
        blockNumber: vaultBlockNumber,
        creator: creator.toLowerCase(),
        encryptedKeysData,
        schemaDefinition,
        timestamp,
        txHash: log.transactionHash,
      };

    } catch (error) {
      console.error(`[ChainReader] Error parsing KeyVaultCreated for ${secretAddress}:`, error);
      return null;
    }
  }

  /**
   * Get ALL KeyVaultCreated events for a secret contract.
   * Uses Etherscan API to query by contract address - no block scanning.
   *
   * @param secretAddress - Secret contract address
   * @param chainName - Chain to query
   * @returns Array of KeyVaultCreated events
   */
  async getKeyVaultCreatedEvents(
    secretAddress: string,
    chainName: string
  ): Promise<Array<{
    blockNumber: number;
    creator: string;
    encryptedKeysData: string;
    schemaDefinition: string;
    timestamp: number;
    txHash: string;
  }>> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported by any explorer API`);
      return [];
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for event query');
      return [];
    }

    try {
      // KeyVaultCreated event signature
      const eventSignature = topic0('KeyVaultCreated');

      // Use buildExplorerUrl for Blockscout/Etherscan compatibility
      const url = buildExplorerUrl(chain.chainId, 'logs', 'getLogs', this.etherscanApiKey);
      url.searchParams.set('address', secretAddress);
      url.searchParams.set('topic0', eventSignature);
      url.searchParams.set('fromBlock', '0');
      url.searchParams.set('toBlock', 'latest');

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: Array<{
          address: string;
          topics: string[];
          data: string;
          blockNumber: string;
          transactionHash: string;
          timeStamp: string;
        }> | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        return [];
      }

      const logs = response.result;
      const events: Array<{
        blockNumber: number;
        creator: string;
        encryptedKeysData: string;
        schemaDefinition: string;
        timestamp: number;
        txHash: string;
      }> = [];

      for (const log of logs) {
        try {
          // topics[1] = indexed blockNumber (uint256)
          // topics[2] = indexed creator (address)
          const vaultBlockNumber = parseInt(log.topics[1], 16);
          const creator = '0x' + log.topics[2].slice(-40);

          // Decode non-indexed parameters from data
          const abiCoder = new ethers.AbiCoder();
          const decoded = abiCoder.decode(['bytes', 'bytes', 'uint256'], log.data);

          const encryptedKeysData = ethers.toUtf8String(decoded[0]);
          const schemaDefinition = ethers.toUtf8String(decoded[1]);
          const timestamp = Number(decoded[2]);

          events.push({
            blockNumber: vaultBlockNumber,
            creator: creator.toLowerCase(),
            encryptedKeysData,
            schemaDefinition,
            timestamp,
            txHash: log.transactionHash,
          });
        } catch (parseError) {
          console.error(`[ChainReader] Error parsing log:`, parseError);
        }
      }

      return events;

    } catch (error) {
      console.error(`[ChainReader] Error querying KeyVaultCreated events:`, error);
      return [];
    }
  }

  /**
   * Get DataWritten events for a KeyVault.
   * Uses Etherscan API to query by contract address and keyVaultBlock - no block scanning.
   *
   * @param secretAddress - Secret contract address
   * @param chainName - Chain to query
   * @param kvBlock - KeyVault block number to filter by
   * @returns Array of DataWritten events
   */
  async getDataWrittenEvents(
    secretAddress: string,
    chainName: string,
    kvBlock: number
  ): Promise<Array<{
    secretContract: string;
    writer: string;
    keyVaultBlock: number;
    data: string;
    creditsCost: number;
    timestamp: number;
    txHash: string;
    blockNumber: number;
  }>> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported by any explorer API`);
      return [];
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for event query');
      return [];
    }

    try {
      // DataWritten event signature:
      // DataWritten(address indexed secretContract, address indexed writer, uint256 indexed keyVaultBlock, bytes data, uint256 creditsCost, uint256 timestamp)
      const eventSignature = topic0('DataWritten');

      // Convert kvBlock to hex for topic filter
      const kvBlockHex = '0x' + kvBlock.toString(16).padStart(64, '0');

      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'logs');
      url.searchParams.set('action', 'getLogs');
      url.searchParams.set('address', secretAddress);
      url.searchParams.set('topic0', eventSignature);
      url.searchParams.set('topic3', kvBlockHex);  // keyVaultBlock is topic3 (indexed)
      url.searchParams.set('topic0_3_opr', 'and'); // CRITICAL: Combine topic0 AND topic3 filters
      url.searchParams.set('fromBlock', '0');
      url.searchParams.set('toBlock', 'latest');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: Array<{
          address: string;
          topics: string[];
          data: string;
          blockNumber: string;
          transactionHash: string;
          timeStamp: string;
        }> | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        return [];
      }

      const logs = response.result;
      const events: Array<{
        secretContract: string;
        writer: string;
        keyVaultBlock: number;
        data: string;
        creditsCost: number;
        timestamp: number;
        txHash: string;
        blockNumber: number;
      }> = [];

      for (const log of logs) {
        try {
          // topics[1] = indexed secretContract (address)
          // topics[2] = indexed writer (address)
          // topics[3] = indexed keyVaultBlock (uint256)
          const secretContract = '0x' + log.topics[1].slice(-40);
          const writer = '0x' + log.topics[2].slice(-40);
          const keyVaultBlock = parseInt(log.topics[3], 16);

          // Decode non-indexed parameters from data
          const abiCoder = new ethers.AbiCoder();
          const decoded = abiCoder.decode(['bytes', 'uint256', 'uint256'], log.data);

          const data = decoded[0];
          const creditsCost = Number(decoded[1]);
          const timestamp = Number(decoded[2]) * 1000;
          const blockNumber = parseInt(log.blockNumber, 16);

          events.push({
            secretContract: secretContract.toLowerCase(),
            writer: writer.toLowerCase(),
            keyVaultBlock,
            data,
            creditsCost,
            timestamp,
            txHash: log.transactionHash,
            blockNumber,
          });
        } catch (parseError) {
          console.error(`[ChainReader] Error parsing DataWritten log:`, parseError);
        }
      }

      return events;

    } catch (error) {
      console.error(`[ChainReader] Error querying DataWritten events:`, error);
      return [];
    }
  }

  // ==========================================================================
  // Identity Discovery
  // ==========================================================================

  /**
   * Discover all Identity contracts where a wallet is a rivet (authorized device).
   *
   * This scans the factory's IdentityCreated events and checks each identity
   * to see if the target wallet is an authorized rivet.
   *
   * CRITICAL: This finds identities where the wallet was ADDED as a rivet,
   * not just identities the wallet created. Use this for new device discovery.
   *
   * @param walletAddress - Wallet address to check (defaults to first monitored wallet)
   * @param factoryAddress - Identity factory contract address
   * @param chainName - Chain to query
   * @param fromBlock - Start block for event scanning (default: 0)
   * @returns Array of identity contract addresses where wallet is a rivet
   *
   * @example
   * ```typescript
   * // After device is added as rivet by another device, discover the identity
   * const identities = await reader.discoverIdentities(
   *   newDeviceWallet,
   *   factoryAddress,
   *   'polygon'
   * );
   * if (identities.length > 0) {
   *   console.log(`Found ${identities.length} identities I'm a rivet on!`);
   * }
   * ```
   */
  async discoverIdentities(
    walletAddress: string,
    factoryAddress: string,
    chainNameOrId: string | number,
    fromBlock: number = 0
  ): Promise<string[]> {
    const normalizedWallet = walletAddress.toLowerCase();

    // Support both chain name and chainId for flexibility
    const chain = typeof chainNameOrId === 'number'
      ? this.chains.find(c => c.chainId === chainNameOrId)
      : this.chains.find(c => c.name === chainNameOrId || c.name.toLowerCase().includes(chainNameOrId.toLowerCase()));

    if (!chain) {
      console.warn(`[ChainReader] Chain '${chainNameOrId}' not configured, available: ${this.chains.map(c => c.name).join(', ')}`);
      return [];
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for Identity discovery`);
      return [];
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for Identity discovery');
      return [];
    }

    console.log(`[ChainReader] Discovering identities for ${normalizedWallet.slice(0, 10)}... on ${chain.name}`);

    try {
      // Query IdentityCreated events from factory
      // Event: IdentityCreated(address indexed identity, address indexed creator, uint256 creditsCost, uint256 timestamp)
      const IDENTITY_CREATED_TOPIC = topic0('IdentityCreated');

      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'logs');
      url.searchParams.set('action', 'getLogs');
      url.searchParams.set('address', factoryAddress);
      url.searchParams.set('topic0', IDENTITY_CREATED_TOPIC);
      url.searchParams.set('fromBlock', fromBlock.toString());
      url.searchParams.set('toBlock', '99999999');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EventLogResult[] | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        console.log(`[ChainReader] No IdentityCreated events found`);
        return [];
      }

      const events = response.result;
      console.log(`[ChainReader] Found ${events.length} identity contracts to check`);

      const identities: string[] = [];

      // Get or create provider for this chain
      let provider = this.providers.get(chain.name);
      if (!provider) {
        provider = new ethers.JsonRpcProvider(chain.rpc);
        this.providers.set(chain.name, provider);
      }

      // Check each identity contract to see if wallet is a rivet
      for (const event of events) {
        // Identity address is in topic1 (indexed)
        const identityTopic = event.topics[1];
        if (!identityTopic) continue;

        const identityAddress = '0x' + identityTopic.slice(26); // Remove padding

        try {
          // Call isRivet() on the identity contract
          const abi = ['function isRivet(address) external view returns (bool)'];
          const contract = new ethers.Contract(identityAddress, abi, provider);

          const isRivet = await contract.isRivet(normalizedWallet);
          if (isRivet) {
            identities.push(identityAddress.toLowerCase());
            console.log(`[ChainReader] Found: ${identityAddress} (wallet is rivet)`);
          }
        } catch (e) {
          // Skip invalid contracts
        }
      }

      console.log(`[ChainReader] Discovered ${identities.length} identities for wallet`);
      return identities;

    } catch (error) {
      console.error(`[ChainReader] Error discovering identities:`, error);
      return [];
    }
  }

  // ==========================================================================
  // Identity Mode - Owner-Based Query
  // ==========================================================================

  /**
   * Get secrets (contracts) OWNED by an address.
   *
   * CRITICAL FOR IDENTITY MODE:
   * In Identity mode, the Identity contract is the OWNER of secrets, not the creator.
   * The rivet wallet sends the transaction, but the Identity is named as owner.
   *
   * This method queries WalletCreated events from the Factory filtered by owner.
   *
   * @param ownerAddress - Owner address (typically an Identity contract)
   * @param factoryAddress - Factory contract address that emitted WalletCreated events
   * @param chainName - Chain to query
   * @returns Array of secret contract addresses owned by this address
   *
   * @example
   * ```typescript
   * // Find all secrets owned by an Identity contract
   * const secrets = await reader.getSecretsOwnedByAddress(
   *   identityContract,
   *   factoryAddress,
   *   'amoy'
   * );
   * console.log(`Found ${secrets.length} secrets owned by Identity`);
   * ```
   */
  async getSecretsOwnedByAddress(
    ownerAddress: string,
    factoryAddress: string,
    chainName: string
  ): Promise<string[]> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for Identity query`);
      return [];
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for Identity query');
      return [];
    }

    try {
      // NEW APPROACH: Query transactions TO the Identity contract
      // When a rivet creates a secret via Identity mode, the transaction goes TO the Identity
      // The Identity then executes a call to the factory which creates the secret contract
      // By querying transactions TO the Identity, we find all secret creations from ANY rivet
      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'account');
      url.searchParams.set('action', 'txlist');
      url.searchParams.set('address', ownerAddress);
      url.searchParams.set('startblock', '0');
      url.searchParams.set('endblock', '99999999');
      url.searchParams.set('sort', 'asc');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EtherscanTx[] | string;
      }>(url.toString());

      if (response.status === '0' || typeof response.result === 'string') {
        return [];
      }

      const txList = response.result as EtherscanTx[];
      const secretAddresses: string[] = [];

      // Find transactions TO the Identity contract that created contracts
      // These are rivet transactions that used the Identity to create secrets
      let txToIdentity = 0;
      for (const tx of txList) {
        // Only look at transactions TO the Identity (not FROM, those are internal)
        if (tx.to?.toLowerCase() !== ownerAddress.toLowerCase()) continue;
        if (tx.isError === '1') continue;
        txToIdentity++;

        // Get internal transactions to find contract creations
        const internalTxs = await this.getInternalTransactions(tx.hash, chain.name);
        for (const itx of internalTxs) {
          if (itx.type === 'create' && itx.contractAddress) {
            secretAddresses.push(itx.contractAddress.toLowerCase());
          }
        }
      }

      return secretAddresses;

    } catch (error) {
      console.error(`[ChainReader] Error querying secrets by Identity:`, error);
      return [];
    }
  }

  // ==========================================================================
  // Factory WalletCreated Events - Proper Owner Query
  // ==========================================================================

  /**
   * Get secrets owned by an address by querying WalletCreated events from Factory.
   *
   * This is the proper V5/V6 approach:
   * - Factory emits WalletCreated(wallet, owner, newborn, timestamp) when creating secrets
   * - topic1 = wallet (secret contract address)
   * - topic2 = owner (the owning address - wallet or Identity)
   *
   * Works for both regular wallets AND Identity contracts as owners.
   *
   * @param ownerAddress - Address to find secrets for (wallet or Identity)
   * @param factoryAddress - Factory contract that emitted WalletCreated events
   * @param chainName - Chain to query
   * @param fromBlock - Start block for event scanning (default: 0)
   * @returns Object with secret addresses and highest block seen
   */
  async getSecretsFromFactoryByOwner(
    ownerAddress: string,
    factoryAddress: string,
    chainName: string,
    fromBlock: number = 0
  ): Promise<{ addresses: string[]; highestBlock: number }> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for event query`);
      return { addresses: [], highestBlock: fromBlock };
    }

    // Blockscout doesn't need API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No API key for Factory event query');
      return { addresses: [], highestBlock: fromBlock };
    }

    try {
      // WalletCreated event signatures vary by contract version:
      // V6.2+: WalletCreated(address indexed wallet, address indexed owner, address indexed newborn, string walletType, uint256 timestamp)
      // V5/V6.0: WalletCreated(address indexed wallet, address indexed owner, address indexed newborn, uint256 timestamp)
      //
      // topic0 = event signature hash
      // topic1 = wallet (secret contract address) - indexed
      // topic2 = owner - indexed (THIS IS WHAT WE FILTER BY)
      // topic3 = newborn - indexed
      const WALLET_CREATED_TOPICS = [
        '0xdccb4dfe68c3cc7c8b9bdc8577a418c2c77377328c5b1c3791069c7fa53b1128', // V6.2+ with walletType string
        '0xc0d3202a50abc7f3fabd832828407a448f8cb500fe11db77a44113ee6899474d', // V5/V6.0 without walletType
      ];
      const paddedOwner = '0x' + ownerAddress.slice(2).toLowerCase().padStart(64, '0');

      const secretAddresses: string[] = [];
      let highestBlock = fromBlock;

      // Try each event signature (different contract versions)
      for (const topic0 of WALLET_CREATED_TOPICS) {
        const url = buildExplorerUrl(chain.chainId, 'logs', 'getLogs', this.etherscanApiKey);
        url.searchParams.set('address', factoryAddress);
        url.searchParams.set('fromBlock', fromBlock.toString());
        url.searchParams.set('toBlock', 'latest');
        url.searchParams.set('topic0', topic0);
        url.searchParams.set('topic2', paddedOwner);  // Filter by owner (topic2)
        url.searchParams.set('topic0_2_opr', 'and');

        console.log(`[ChainReader] Querying WalletCreated events (${topic0.slice(0, 10)}...) from Factory ${factoryAddress.slice(0, 10)}... for owner ${ownerAddress.slice(0, 10)}... fromBlock=${fromBlock}`);

        try {
          const response = await this.rateLimitedFetch<{
            status: string;
            message: string;
            result: EventLogResult[] | string;
          }>(url.toString());

          if (response.status === '1' && Array.isArray(response.result)) {
            const logs = response.result as EventLogResult[];
            for (const log of logs) {
              // topic1 contains the wallet (secret contract) address
              if (log.topics && log.topics[1]) {
                const secretAddress = '0x' + log.topics[1].slice(26);
                secretAddresses.push(secretAddress.toLowerCase());
              }
              // Track highest block for incremental sync
              const blockNum = parseInt(log.blockNumber, 16);
              if (blockNum > highestBlock) {
                highestBlock = blockNum;
              }
            }
            console.log(`[ChainReader] Found ${logs.length} events with signature ${topic0.slice(0, 10)}...`);
          }
        } catch (err) {
          // Continue to next signature on error
          console.log(`[ChainReader] No events for signature ${topic0.slice(0, 10)}...`);
        }
      }

      // Deduplicate addresses
      const uniqueAddresses = [...new Set(secretAddresses)];
      console.log(`[ChainReader] Found ${uniqueAddresses.length} total secrets owned by ${ownerAddress.slice(0, 10)}... via WalletCreated events (highestBlock: ${highestBlock})`);
      return { addresses: uniqueAddresses, highestBlock };

    } catch (error) {
      console.error(`[ChainReader] Error querying WalletCreated events:`, error);
      return { addresses: [], highestBlock: fromBlock };
    }
  }

  // ==========================================================================
  // Utility Methods
  // ==========================================================================

  /**
   * Normalize address to lowercase.
   */
  normalizeAddress(address: string): string {
    return address.toLowerCase();
  }

  // ==========================================================================
  // Identity Public Key Lookup
  // ==========================================================================

  /**
   * Get the registered public key for an Identity contract.
   *
   * Queries PublicKeyRegistered events from the Identity contract to find
   * the ECDH public key registered by any rivet. Returns the most recent key.
   *
   * This enables 1-step direct sharing: lookup public key → direct-keys
   * No need for 3-step invite flow when Identity has registered keys.
   *
   * @param identityAddress - Identity contract address
   * @param chainName - Chain to query
   * @returns Public key string (0x04...) or null if not found
   *
   * @example
   * ```typescript
   * const pubKey = await reader.getIdentityPublicKey(identityAddress, 'amoy');
   * if (pubKey) {
   *   // Direct share - no invite needed
   *   await directShare(identityAddress, pubKey, masterKey);
   * } else {
   *   // Fall back to 3-step invite flow
   *   await sendInvite(identityAddress);
   * }
   * ```
   */
  async getIdentityPublicKey(
    identityAddress: string,
    chainName: string
  ): Promise<string | null> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) {
      throw new Error(`Chain '${chainName}' not configured`);
    }

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for Identity query`);
      return null;
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for Identity query');
      return null;
    }

    try {
      // PublicKeyRegistered(address indexed rivet, string publicKey, uint256 timestamp)
      // topic0 = keccak256("PublicKeyRegistered(address,string,uint256)")
      const PUBLIC_KEY_REGISTERED_TOPIC = topic0('PublicKeyRegistered');

      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'logs');
      url.searchParams.set('action', 'getLogs');
      url.searchParams.set('address', identityAddress);
      url.searchParams.set('topic0', PUBLIC_KEY_REGISTERED_TOPIC);
      url.searchParams.set('fromBlock', '0');
      url.searchParams.set('toBlock', '99999999');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EventLogResult[] | string;
      }>(url.toString());

      if (response.status !== '1' || !Array.isArray(response.result)) {
        return null;
      }

      const logs = response.result as EventLogResult[];
      if (logs.length === 0) {
        return null;
      }

      // Get the most recent registration (last in list, sorted by block)
      const latestLog = logs[logs.length - 1];

      // Decode the event data
      // PublicKeyRegistered has: indexed rivet (topic1), string publicKey (data), uint256 timestamp (data)
      // ABI encoding for (string, uint256):
      // - offset to string (32 bytes)
      // - timestamp (32 bytes)
      // - string length (32 bytes)
      // - string data (padded to 32 bytes)
      const data = latestLog.data;
      if (!data || data === '0x' || data.length < 130) {
        return null;
      }

      // Parse ABI-encoded (string publicKey, uint256 timestamp)
      const abiCoder = ethers.AbiCoder.defaultAbiCoder();
      const decoded = abiCoder.decode(['string', 'uint256'], data);
      const publicKey = decoded[0] as string;

      if (publicKey && publicKey.length > 60) {
        return publicKey;
      }

      return null;

    } catch (error) {
      console.error(`[ChainReader] Error fetching Identity public key:`, error);
      return null;
    }
  }

  /**
   * Check if an address is likely an Identity contract.
   *
   * Heuristic: If address has PublicKeyRegistered or RivetAdded events, it's an Identity.
   * This is faster than calling contract methods.
   *
   * @param address - Address to check
   * @param chainName - Chain to query
   * @returns true if likely an Identity contract
   */
  async isIdentityContract(
    address: string,
    chainName: string
  ): Promise<boolean> {
    const chain = this.chains.find(c => c.name === chainName);
    if (!chain) return false;

    if (!hasExplorerSupport(chain.chainId)) return false;
    // Blockscout doesn't need an API key, but Etherscan does
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) return false;

    try {
      // Check for PublicKeyRegistered events (Identity contracts have these)
      const PUBLIC_KEY_REGISTERED_TOPIC = topic0('PublicKeyRegistered');

      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'logs');
      url.searchParams.set('action', 'getLogs');
      url.searchParams.set('address', address);
      url.searchParams.set('topic0', PUBLIC_KEY_REGISTERED_TOPIC);
      url.searchParams.set('fromBlock', '0');
      url.searchParams.set('toBlock', '99999999');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EventLogResult[] | string;
      }>(url.toString());

      // If we found any PublicKeyRegistered events, it's an Identity
      if (response.status === '1' && Array.isArray(response.result) && response.result.length > 0) {
        return true;
      }

      return false;

    } catch {
      return false;
    }
  }

  // ==========================================================================
  // Identity Contract Direct Calls
  // ==========================================================================

  /**
   * Get all rivets with their public keys from an Identity contract.
   *
   * Calls the contract's getRivetsWithPublicKeys() view function directly.
   * Used to build fat packages for multi-rivet encryption.
   *
   * @param identityAddress - Identity contract address
   * @param chainName - Chain to query
   * @returns Array of rivets with addresses, names, and public keys
   *
   * @example
   * ```typescript
   * const rivets = await reader.getIdentityRivetsWithPublicKeys(identity, 'amoy');
   * // Returns: [{ address: '0x...', name: 'laptop', publicKey: '0x04...' }, ...]
   * // Use to create fat package with encrypted key for each rivet
   * ```
   */
  async getIdentityRivetsWithPublicKeys(
    identityAddress: string,
    chainNameOrId: string | number
  ): Promise<Array<{ address: string; name: string; publicKey: string }>> {
    // Support both chain name and chainId for flexibility
    const chain = typeof chainNameOrId === 'number'
      ? this.chains.find(c => c.chainId === chainNameOrId)
      : this.chains.find(c => c.name === chainNameOrId || c.name.toLowerCase().includes(chainNameOrId.toLowerCase()));
    if (!chain) {
      console.warn(`[ChainReader] Chain '${chainNameOrId}' not configured, available: ${this.chains.map(c => c.name).join(', ')}`);
      return [];
    }

    // Get or create provider for this chain
    let provider = this.providers.get(chain.name);
    if (!provider) {
      provider = new ethers.JsonRpcProvider(chain.rpc);
      this.providers.set(chain.name, provider);
    }

    try {
      // Create contract interface with just the view function we need
      const abi = [
        'function getRivetsWithPublicKeys() external view returns (address[] addresses, string[] names, string[] publicKeys)'
      ];
      const contract = new ethers.Contract(identityAddress, abi, provider);

      // Call the view function
      const [addresses, names, publicKeys] = await contract.getRivetsWithPublicKeys();

      // Map to objects
      const rivets: Array<{ address: string; name: string; publicKey: string }> = [];
      for (let i = 0; i < addresses.length; i++) {
        rivets.push({
          address: addresses[i].toLowerCase(),
          name: names[i] || '',
          publicKey: publicKeys[i] || '',
        });
      }

      return rivets;

    } catch (error) {
      console.error(`[ChainReader] Error calling getRivetsWithPublicKeys:`, error);
      return [];
    }
  }

  /**
   * Query MessageReceived events from an Identity contract.
   *
   * Used to discover messages sent TO an Identity (invites, responses, keys).
   * All rivets can query their Identity's MessageReceived events.
   *
   * @param identityAddress - Identity contract address
   * @param chainName - Chain to query
   * @param fromBlock - Start block (default: 0)
   * @returns Array of received messages with sender, data, and metadata
   */
  async getIdentityMessages(
    identityAddress: string,
    chainNameOrId: string | number,
    fromBlock: number = 0
  ): Promise<Array<{
    from: string;
    data: string;
    value: string;
    messageIndex: number;
    timestamp: number;
    txHash: string;
    blockNumber: number;
  }>> {
    console.log(`[ChainReader] getIdentityMessages called for ${identityAddress.slice(0, 12)}... on chain ${chainNameOrId}`);

    // Support both chain name and chainId for flexibility
    const chain = typeof chainNameOrId === 'number'
      ? this.chains.find(c => c.chainId === chainNameOrId)
      : this.chains.find(c => c.name === chainNameOrId || c.name.toLowerCase().includes(chainNameOrId.toLowerCase()));
    if (!chain) {
      console.warn(`[ChainReader] getIdentityMessages: Chain '${chainNameOrId}' not configured, available: ${this.chains.map(c => c.name).join(', ')}`);
      return [];
    }

    console.log(`[ChainReader] getIdentityMessages: Using chain ${chain.name} (${chain.chainId})`);

    if (!hasExplorerSupport(chain.chainId)) {
      console.log(`[ChainReader] Chain ${chain.name} not supported for event query`);
      return [];
    }

    // Blockscout doesn't need an API key
    if (!usesBlockscout(chain.chainId) && !this.etherscanApiKey) {
      console.warn('[ChainReader] No Etherscan API key for event query');
      return [];
    }

    try {
      // MessageReceived(address indexed from, bytes data, uint256 value, uint256 indexed messageIndex, uint256 timestamp)
      const MESSAGE_RECEIVED_TOPIC = topic0('MessageReceived');
      console.log(`[ChainReader] Querying MessageReceived events on ${identityAddress.slice(0, 12)}...`);

      const url = new URL(ETHERSCAN_V2_API);
      url.searchParams.set('chainid', chain.chainId.toString());
      url.searchParams.set('module', 'logs');
      url.searchParams.set('action', 'getLogs');
      url.searchParams.set('address', identityAddress);
      url.searchParams.set('topic0', MESSAGE_RECEIVED_TOPIC);
      url.searchParams.set('fromBlock', fromBlock.toString());
      url.searchParams.set('toBlock', '99999999');
      url.searchParams.set('apikey', this.etherscanApiKey);

      const response = await this.rateLimitedFetch<{
        status: string;
        message: string;
        result: EventLogResult[] | string;
      }>(url.toString());

      console.log(`[ChainReader] getIdentityMessages API response: status=${response.status}, message=${response.message}, resultCount=${Array.isArray(response.result) ? response.result.length : 'not an array'}`);

      if (response.status !== '1' || !Array.isArray(response.result)) {
        console.log(`[ChainReader] getIdentityMessages: No events found (status=${response.status})`);
        return [];
      }

      const messages: Array<{
        from: string;
        data: string;
        value: string;
        messageIndex: number;
        timestamp: number;
        txHash: string;
        blockNumber: number;
      }> = [];

      for (const log of response.result) {
        try {
          // topic1 = from (indexed address)
          // topic2 = messageIndex (indexed uint256)
          // data = (bytes data, uint256 value, uint256 timestamp)
          const from = '0x' + log.topics[1].slice(26);
          const messageIndex = parseInt(log.topics[2], 16);

          // Decode non-indexed data: (bytes data, uint256 value, uint256 timestamp)
          const abiCoder = ethers.AbiCoder.defaultAbiCoder();
          const decoded = abiCoder.decode(['bytes', 'uint256', 'uint256'], log.data);
          const data = decoded[0] as string;
          const value = decoded[1].toString();
          const timestamp = Number(decoded[2]);

          const blockNumber = log.blockNumber.startsWith('0x')
            ? parseInt(log.blockNumber, 16)
            : parseInt(log.blockNumber, 10);

          messages.push({
            from: from.toLowerCase(),
            data,
            value,
            messageIndex,
            timestamp,
            txHash: log.transactionHash,
            blockNumber,
          });
        } catch (decodeError) {
          console.warn(`[ChainReader] Failed to decode MessageReceived log:`, decodeError);
        }
      }

      return messages;

    } catch (error) {
      console.error(`[ChainReader] Error querying MessageReceived events:`, error);
      return [];
    }
  }

}
