/**
 * Browser localStorage adapter for wallet storage.
 *
 * Used by web applications (Dashboard).
 * Stores wallet data in browser localStorage.
 *
 * Security: LOW - Private keys stored in plaintext in localStorage.
 * Use only for development/testing or when TPM is not available.
 */

import type { StorageAdapter, StoredWallet } from '../types.js';

const DEFAULT_STORAGE_KEY = 'rootz_browser_wallet';

/**
 * Browser localStorage storage adapter.
 */
export class BrowserStorageAdapter implements StorageAdapter {
  readonly type = 'browser' as const;
  readonly supportsEncryption = false;

  constructor(private readonly storageKey: string = DEFAULT_STORAGE_KEY) {}

  /**
   * Check if localStorage is available.
   */
  isAvailable(): boolean {
    try {
      const test = '__rootz_storage_test__';
      localStorage.setItem(test, test);
      localStorage.removeItem(test);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Check if a wallet exists in storage.
   */
  async exists(): Promise<boolean> {
    if (!this.isAvailable()) {
      return false;
    }
    return localStorage.getItem(this.storageKey) !== null;
  }

  /**
   * Load wallet from localStorage.
   */
  async load(): Promise<StoredWallet | null> {
    if (!this.isAvailable()) {
      return null;
    }

    const stored = localStorage.getItem(this.storageKey);
    if (!stored) {
      return null;
    }

    try {
      const wallet = JSON.parse(stored) as StoredWallet;

      // Update last accessed
      wallet.lastAccessedAt = Date.now();
      localStorage.setItem(this.storageKey, JSON.stringify(wallet));

      return wallet;
    } catch {
      // Corrupted data - remove it
      localStorage.removeItem(this.storageKey);
      return null;
    }
  }

  /**
   * Save wallet to localStorage.
   */
  async save(wallet: StoredWallet): Promise<void> {
    if (!this.isAvailable()) {
      throw new Error('localStorage is not available');
    }

    // Ensure source is set
    const toStore: StoredWallet = {
      ...wallet,
      source: 'browser',
      lastAccessedAt: Date.now(),
    };

    localStorage.setItem(this.storageKey, JSON.stringify(toStore));
  }

  /**
   * Delete wallet from localStorage.
   */
  async delete(): Promise<void> {
    if (this.isAvailable()) {
      localStorage.removeItem(this.storageKey);
    }
  }
}
