/**
 * V4/V5 Factory Contract ABI
 * Used on Polygon Amoy and JOC networks.
 */
export const FACTORY_ABI = [
  // Read functions
  'function getUserNonce(address user) view returns (uint256)',
  'function getUserSecrets(address user) view returns (address[])',
  'function isActive() view returns (bool)',
  'function factoryVersion() view returns (string)',
  'function operationsVersion() view returns (string)',
  'function registry() view returns (address)',
  'function rootzKey() view returns (address)',
  'function serviceWallet() view returns (address)',
  'function getRegistry() view returns (address)',
  'function userNonces(address) view returns (uint256)',
  'function userSecrets(address, uint256) view returns (address)',

  // Write functions
  'function createSovereignWalletAsNewborn(address userAuthorizer, address newbornAddress, string walletName, string secretName, string secretType, bytes authSignature, uint256 nonce) payable returns (address)',
  'function setActive(bool _isActive)',
  'function updateServiceWallet(address _serviceWallet)',

  // Events
  'event WalletCreated(address indexed wallet, address indexed owner, address indexed newborn, uint256 timestamp)',
  'event FactoryStatusChanged(bool active, uint256 timestamp)',
] as const;

/**
 * V4 Secret Contract ABI (Legacy)
 * Used with V4 Factory contracts that have mintSecret.
 *
 * @deprecated Use SECRET_ABI_V5 for new deployments
 */
export const SECRET_ABI_V4 = [
  // Read functions
  'function owner() view returns (address)',
  'function name() view returns (string)',
  'function secretType() view returns (string)',
  'function getSecretData() view returns (string ipfsHash, bytes encryptedContent, bytes encryptedPrivateKey)',

  // Write functions - V4 uses mintSecret
  'function mintSecret(string _ipfsHash, bytes _encryptedContent, bytes _encryptedPrivateKey) external',
  'function createKeyVault(string schema) returns (uint256)',

  // Events
  'event SecretMinted(address indexed owner, string ipfsHash)',
  'event KeyVaultCreated(uint256 indexed vaultId, string schema)',
] as const;

/**
 * V5 Secret Contract ABI (Current Production)
 * Used with V5 Factory contracts that support Identity Mode.
 *
 * V5 Architecture:
 * - No mintSecret function - data stored via createKeyVault
 * - createKeyVault takes (bytes encryptedKeysData, bytes schemaDefinition)
 * - Data stored in KeyVaultCreated event logs (gas efficient)
 * - Supports LOCAL (EOA) and IDENTITY (contract) wallet modes
 * - EIP-1271 signature validation for contract wallets
 */
export const SECRET_ABI_V5 = [
  // Read functions
  'function owner() view returns (address)',
  'function originOwner() view returns (address)',
  'function newbornOwner() view returns (address)',
  'function walletName() view returns (string)',
  'function secretName() view returns (string)',
  'function secretType() view returns (string)',
  'function getTeamMember(address member) view returns (uint8 role, bool active, string publicKey, uint256 grantedAt)',
  'function getKeyVaultStatus(uint256 blockNumber) view returns (bool active, address creator, int256 creditBalance, int256 ownerTotalCredits)',
  'function ownerCredits(address) view returns (int256)',
  'function teamMemberCount() view returns (uint256)',

  // Write functions - V5 uses createKeyVault for data storage
  'function createKeyVault(bytes encryptedKeysData, bytes schemaDefinition) external',
  'function writeData(uint256 keyVaultBlock, bytes data, uint256 expiresAt, uint8 v, bytes32 r, bytes32 s) external',
  'function addTeamMember(address member, uint8 role, string encryptedAccessKey, string publicKey) external',
  'function submitRivetSignature(bytes signature) external returns (bytes32)',
  'function fundOperations(address owner, int256 credits) external',

  // Events
  'event KeyVaultCreated(uint256 indexed blockNumber, address indexed creator, bytes encryptedKeysData, bytes schemaDefinition, uint256 timestamp)',
  'event DataWritten(address indexed secretContract, address indexed writer, uint256 indexed keyVaultBlock, bytes data, uint256 creditsCost, uint256 timestamp)',
  'event TeamMemberAdded(address indexed member, uint8 role, address indexed addedBy, uint256 timestamp)',
  'event RivetSignatureStored(bytes32 indexed signatureHash, address indexed submitter, uint256 timestamp)',
] as const;

/**
 * Default Secret Contract ABI
 * Points to V5 for new development.
 * Use SECRET_ABI_V4 for legacy compatibility.
 */
export const SECRET_ABI = SECRET_ABI_V5;

