// ============================================================================
// EVENT PARSING UTILITIES
// ============================================================================

/**
 * Transaction receipt log structure (ethers v6 compatible).
 */
export interface TransactionLog {
  address: string;
  topics: readonly string[];
  data: string;
}

/**
 * Transaction receipt structure (minimal).
 */
export interface TransactionReceipt {
  hash: string;
  blockNumber: number;
  logs: readonly TransactionLog[];
  contractAddress?: string | null;
}

/**
 * Extract contract address from WalletCreated event in transaction logs.
 *
 * Uses three methods with fallback:
 * 1. Parse event with interface (if provided)
 * 2. Extract from indexed topics (topics[1] = wallet)
 * 3. Use receipt.contractAddress as last resort
 *
 * @param receipt - Transaction receipt with logs
 * @param factoryAddress - Factory contract address (to filter logs)
 * @param parseLog - Optional function to parse logs (from ethers Interface)
 * @returns Contract address or null if not found
 */
export function extractContractAddressFromReceipt(
  receipt: TransactionReceipt,
  factoryAddress?: string,
  parseLog?: (log: { topics: string[]; data: string }) => { name: string; args: Record<string, unknown> } | null
): string | null {
  // Method 1: Try parsing with interface if provided
  if (parseLog) {
    for (const log of receipt.logs) {
      try {
        const parsed = parseLog({ topics: [...log.topics], data: log.data });
        if (parsed && parsed.name === 'WalletCreated') {
          // Try multiple ways to get wallet address (ethers v5/v6 compatibility)
          const wallet = parsed.args.wallet || parsed.args.newborn || parsed.args[0];
          if (wallet && typeof wallet === 'string') {
            return wallet;
          }
        }
      } catch {
        // Not our event, continue
      }
    }
  }

  // Method 2: Extract from indexed topics directly
  // WalletCreated(address indexed wallet, address indexed owner, address indexed newborn, uint256 timestamp)
  // topics[0] = event signature hash
  // topics[1] = wallet (32 bytes, address is last 20 bytes)
  // topics[2] = owner
  // topics[3] = newborn
  for (const log of receipt.logs) {
    // Skip logs not from factory (if address provided)
    if (factoryAddress && log.address.toLowerCase() !== factoryAddress.toLowerCase()) {
      continue;
    }

    // Check if this log has enough topics for WalletCreated
    if (log.topics && log.topics.length >= 2) {
      const walletTopic = log.topics[1];
      // Validate topic format (0x + 64 hex chars = 32 bytes)
      if (walletTopic && walletTopic.length === 66) {
        // Extract address: last 40 chars (20 bytes)
        const address = '0x' + walletTopic.slice(-40);
        // Basic validation: should start with 0x and have some non-zero chars
        if (address.length === 42 && address !== '0x0000000000000000000000000000000000000000') {
          return address;
        }
      }
    }
  }

  // Method 3: Fallback to receipt.contractAddress
  if (receipt.contractAddress) {
    return receipt.contractAddress;
  }

  return null;
}

/**
 * Extract vault ID from KeyVaultCreated event.
 *
 * @param receipt - Transaction receipt with logs
 * @param parseLog - Optional function to parse logs
 * @returns Vault ID or null if not found
 */
export function extractVaultIdFromReceipt(
  receipt: TransactionReceipt,
  parseLog?: (log: { topics: string[]; data: string }) => { name: string; args: Record<string, unknown> } | null
): bigint | null {
  // Try parsing with interface if provided
  if (parseLog) {
    for (const log of receipt.logs) {
      try {
        const parsed = parseLog({ topics: [...log.topics], data: log.data });
        if (parsed && parsed.name === 'KeyVaultCreated') {
          const vaultId = parsed.args.vaultId || parsed.args[0];
          if (typeof vaultId === 'bigint') {
            return vaultId;
          }
          if (typeof vaultId === 'number') {
            return BigInt(vaultId);
          }
        }
      } catch {
        // Not our event, continue
      }
    }
  }

  // Fallback: extract from topics[1] if available
  for (const log of receipt.logs) {
    if (log.topics && log.topics.length >= 2) {
      try {
        // topics[1] is the indexed vaultId
        const vaultIdHex = log.topics[1];
        if (vaultIdHex && vaultIdHex.length === 66) {
          return BigInt(vaultIdHex);
        }
      } catch {
        // Invalid format, continue
      }
    }
  }

  return null;
}

