/**
 * @rootz/message-processor - SyncService
 *
 * Connects ChainReader to MessageProcessor to keep local storage in sync.
 *
 * ## Architecture
 *
 * ```
 * ┌─────────────────┐     sync()      ┌──────────────┐     pull       ┌────────────┐
 * │  SyncService    │ ───────────────▶│ ChainReader  │ ───────────────▶│ Blockchain │
 * │  (coordinator)  │                 │  (passive)   │                 │  Etherscan │
 * └─────────────────┘                 └──────────────┘                 └────────────┘
 *         │                                  │
 *         │ store                            │ WalletMessage[]
 *         ▼                                  ▼
 * ┌─────────────────┐              ┌──────────────────┐
 * │ MessageProcessor │◀─────────────│  getWalletMessages(lastBlock)
 * │ + RootzDatabase  │              └──────────────────┘
 * └─────────────────┘
 * ```
 *
 * ## Usage
 *
 * ```typescript
 * import { SyncService } from '@rootz/message-processor';
 * import { ChainReader, KNOWN_CHAINS } from '@rootz/chain-reader';
 *
 * // Create reader
 * const reader = new ChainReader({
 *   chains: [KNOWN_CHAINS.amoy],
 *   wallets: ['0xMyWallet...'],
 *   etherscanApiKey: 'your-key',
 * });
 *
 * // Create sync service
 * const sync = new SyncService({
 *   reader,
 *   processor,
 *   database,
 *   chainId: 80002,
 *   walletAddress: '0xMyWallet...',
 * });
 *
 * // Sync from last known block
 * const result = await sync.sync();
 * console.log(`Synced ${result.messagesProcessed} messages`);
 *
 * // Set up periodic sync
 * sync.startPolling(60000); // Every 60 seconds
 * ```
 *
 * @version 1.0.0
 */

import type { ChainReader, WalletMessage } from '@rootz/chain-reader';
import type { MessageProcessor, ChainMessage } from './processor.js';
import type { RootzDatabase, SyncState, SyncError } from './types.js';

// ============================================================================
// Configuration
// ============================================================================

/**
 * SyncService configuration.
 */
export interface SyncConfig {
  /** ChainReader instance for fetching blockchain data */
  reader: ChainReader;
  /** MessageProcessor instance for processing messages */
  processor: MessageProcessor;
  /** RootzDatabase instance for sync state tracking */
  database: RootzDatabase;
  /** Chain ID (e.g., 80002 for Amoy) */
  chainId: number;
  /** Chain name (e.g., 'amoy') - must match reader config */
  chainName: string;
  /** Wallet address to sync */
  walletAddress: string;
  /**
   * Optional: Identity contract addresses where this wallet is a rivet.
   * Used to sync secrets owned by Identity contracts (multi-device support).
   * When provided, syncOwnedSecrets will also find secrets OWNED by these
   * Identity contracts and mark them as owned.
   */
  identityContracts?: string[];
  /**
   * Optional: Factory contract address for querying secrets by owner.
   * Required for Identity mode sync (to find secrets owned by Identity contracts).
   */
  factoryAddress?: string;
  /** Optional: Store raw messages for audit/verification */
  storeRawMessages?: boolean;
  /** Optional: Callback for sync progress */
  onProgress?: (progress: SyncProgress) => void;
  /** Optional: Callback for sync errors */
  onError?: (error: Error, message?: WalletMessage) => void;
}

/**
 * Sync progress information.
 */
export interface SyncProgress {
  chainId: number;
  chainName: string;
  fromBlock: number;
  toBlock: number;
  messagesFound: number;
  messagesProcessed: number;
  status: 'starting' | 'fetching' | 'processing' | 'complete' | 'error';
}

/**
 * Sync result returned after sync completes.
 */
export interface SyncResult {
  chainId: number;
  chainName: string;
  fromBlock: number;
  toBlock: number;
  messagesFound: number;
  messagesProcessed: number;
  errors: SyncError[];
  durationMs: number;
}

// ============================================================================
// SyncService Class
// ============================================================================

/**
 * SyncService - Coordinates syncing between ChainReader and storage.
 *
 * Key responsibilities:
 * - Track last synced block per chain/wallet
 * - Pull new messages from ChainReader
 * - Process messages through MessageProcessor
 * - Store sync state for resumption
 * - Handle errors gracefully
 */
export class SyncService {
  private reader: ChainReader;
  private processor: MessageProcessor;
  private database: RootzDatabase;
  private chainId: number;
  private chainName: string;
  private walletAddress: string;
  private identityContracts: string[];
  private factoryAddress: string | undefined;
  private storeRawMessages: boolean;
  private onProgress?: (progress: SyncProgress) => void;
  private onError?: (error: Error, message?: WalletMessage) => void;

  // Polling state
  private pollingInterval: ReturnType<typeof setInterval> | null = null;
  private isSyncing = false;

  // Raw messages storage (in-memory, optional)
  private rawMessages: Map<string, WalletMessage> = new Map();

  /**
   * Create a new SyncService.
   */
  constructor(config: SyncConfig) {
    this.reader = config.reader;
    this.processor = config.processor;
    this.database = config.database;
    this.chainId = config.chainId;
    this.chainName = config.chainName;
    this.walletAddress = config.walletAddress.toLowerCase();
    this.identityContracts = (config.identityContracts ?? []).map(a => a.toLowerCase());
    this.factoryAddress = config.factoryAddress?.toLowerCase();
    this.storeRawMessages = config.storeRawMessages ?? false;
    this.onProgress = config.onProgress;
    this.onError = config.onError;
  }

  /**
   * Update the list of Identity contracts for this wallet.
   * Call this when the user adds or removes Identity associations.
   */
  setIdentityContracts(contracts: string[]): void {
    const oldCount = this.identityContracts.length;
    this.identityContracts = contracts.map(a => a.toLowerCase());
    console.log(`[SyncService] setIdentityContracts called:`);
    console.log(`  - Previous count: ${oldCount}`);
    console.log(`  - New count: ${this.identityContracts.length}`);
    if (this.identityContracts.length > 0) {
      this.identityContracts.forEach((c, i) => console.log(`  - [${i}] ${c}`));
    }
  }

  // ==========================================================================
  // Main API
  // ==========================================================================

  /**
   * Sync new messages from blockchain to local storage.
   *
   * Fetches all messages since the last synced block, processes them,
   * and updates sync state.
   *
   * @param fromBlock - Optional: Start block (defaults to last synced)
   * @returns SyncResult with statistics
   *
   * @example
   * ```typescript
   * const result = await sync.sync();
   * console.log(`Synced ${result.messagesProcessed} messages in ${result.durationMs}ms`);
   * ```
   */
  async sync(fromBlock?: number): Promise<SyncResult> {
    if (this.isSyncing) {
      return {
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: 0,
        toBlock: 0,
        messagesFound: 0,
        messagesProcessed: 0,
        errors: [{ txHash: '', error: 'Sync already in progress', timestamp: Date.now(), retryCount: 0 }],
        durationMs: 0,
      };
    }

    this.isSyncing = true;
    const startTime = Date.now();
    const errors: SyncError[] = [];

    try {
      // Get sync state
      const syncKey = this.getSyncKey();
      const syncState = await this.database.syncState.get(syncKey);
      const startBlock = fromBlock ?? (syncState?.lastSyncedBlock ?? 0) + 1;

      // Get current block
      const currentBlock = await this.reader.getCurrentBlock(this.chainName);

      this.emitProgress({
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: startBlock,
        toBlock: currentBlock,
        messagesFound: 0,
        messagesProcessed: 0,
        status: 'fetching',
      });

      // Fetch messages from chain reader
      const messages = await this.reader.getWalletMessages(startBlock);

      this.emitProgress({
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: startBlock,
        toBlock: currentBlock,
        messagesFound: messages.length,
        messagesProcessed: 0,
        status: 'processing',
      });

      // Process each message
      let processedCount = 0;
      for (const message of messages) {
        try {
          // Convert WalletMessage to ChainMessage
          const chainMessage: ChainMessage = {
            type: message.type as ChainMessage['type'],
            txHash: message.txHash,
            blockNumber: message.blockNumber,
            from: message.from,
            to: message.to,
            timestamp: message.timestamp,
            payload: message.payload,
            raw: message.raw,
          };

          // Process through MessageProcessor
          await this.processor.processMessage(chainMessage);
          processedCount++;

          // Store raw message if enabled
          if (this.storeRawMessages) {
            this.rawMessages.set(message.txHash, message);
          }
        } catch (error) {
          const syncError: SyncError = {
            txHash: message.txHash,
            error: error instanceof Error ? error.message : String(error),
            timestamp: Date.now(),
            retryCount: 0,
          };
          errors.push(syncError);
          this.onError?.(error instanceof Error ? error : new Error(String(error)), message);
        }
      }

      // Update sync state
      const newSyncState: SyncState = {
        key: syncKey,
        chainId: this.chainId,
        lastSyncedBlock: currentBlock,
        lastSyncedAt: Date.now(),
        messagesProcessed: (syncState?.messagesProcessed ?? 0) + processedCount,
        errors: [...(syncState?.errors ?? []).slice(-50), ...errors], // Keep last 50 + new
      };
      await this.database.syncState.put(newSyncState);

      this.emitProgress({
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: startBlock,
        toBlock: currentBlock,
        messagesFound: messages.length,
        messagesProcessed: processedCount,
        status: 'complete',
      });

      return {
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: startBlock,
        toBlock: currentBlock,
        messagesFound: messages.length,
        messagesProcessed: processedCount,
        errors,
        durationMs: Date.now() - startTime,
      };
    } catch (error) {
      const syncError: SyncError = {
        txHash: '',
        error: error instanceof Error ? error.message : String(error),
        timestamp: Date.now(),
        retryCount: 0,
      };
      errors.push(syncError);
      this.onError?.(error instanceof Error ? error : new Error(String(error)));

      this.emitProgress({
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: 0,
        toBlock: 0,
        messagesFound: 0,
        messagesProcessed: 0,
        status: 'error',
      });

      return {
        chainId: this.chainId,
        chainName: this.chainName,
        fromBlock: 0,
        toBlock: 0,
        messagesFound: 0,
        messagesProcessed: 0,
        errors,
        durationMs: Date.now() - startTime,
      };
    } finally {
      this.isSyncing = false;
    }
  }

  /**
   * Start periodic polling for new messages.
   *
   * @param intervalMs - Polling interval in milliseconds (default: 60000)
   *
   * @example
   * ```typescript
   * sync.startPolling(30000); // Every 30 seconds
   * ```
   */
  startPolling(intervalMs: number = 60000): void {
    if (this.pollingInterval) {
      return; // Already polling
    }

    // Initial sync
    this.sync().catch(console.error);

    // Set up interval
    this.pollingInterval = setInterval(() => {
      this.sync().catch(console.error);
    }, intervalMs);
  }

  /**
   * Stop periodic polling.
   */
  stopPolling(): void {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }
  }

  /**
   * Check if currently syncing.
   */
  isBusy(): boolean {
    return this.isSyncing;
  }

  /**
   * Get current sync state.
   */
  async getSyncState(): Promise<SyncState | undefined> {
    return this.database.syncState.get(this.getSyncKey());
  }

  /**
   * Reset sync state (will re-sync from block 0).
   */
  async resetSyncState(): Promise<void> {
    const syncKey = this.getSyncKey();
    await this.database.syncState.put({
      key: syncKey,
      chainId: this.chainId,
      lastSyncedBlock: 0,
      lastSyncedAt: Date.now(),
      messagesProcessed: 0,
      errors: [],
    });
    this.rawMessages.clear();
  }

  // ==========================================================================
  // Raw Message Access
  // ==========================================================================

  /**
   * Get a raw message by transaction hash.
   * Only available if storeRawMessages is enabled.
   */
  getRawMessage(txHash: string): WalletMessage | undefined {
    return this.rawMessages.get(txHash);
  }

  /**
   * Get all stored raw messages.
   * Only available if storeRawMessages is enabled.
   */
  getAllRawMessages(): WalletMessage[] {
    return Array.from(this.rawMessages.values());
  }

  // ==========================================================================
  // V5 Secret Sync
  // ==========================================================================

  /**
   * Sync V5 secrets owned by this wallet.
   *
   * V5 contracts store all data in KeyVaultCreated event logs, not in
   * transaction input data. This method orchestrates:
   * 1. Find contracts created by wallet (ChainReader.getSecretsCreatedByWallet)
   * 2. Get KeyVaultCreated event for each (ChainReader.getKeyVaultCreatedEvent)
   * 3. Parse and store via MessageProcessor
   *
   * @returns Array of synced secrets
   *
   * @example
   * ```typescript
   * const secrets = await sync.syncOwnedSecrets();
   * console.log(`Found ${secrets.length} V5 secrets`);
   * ```
   */
  async syncOwnedSecrets(): Promise<Array<{
    chain: string;
    chainId: number;
    contractAddress: string;
    owner: string;
    keyVaultBlock: number;
    name: string;
    type: string;
    timestamp: number;
    txHash: string;
  }>> {
    console.log(`[SyncService] syncOwnedSecrets called`);
    console.log(`[SyncService]   wallet: ${this.walletAddress}`);
    console.log(`[SyncService]   chainName: ${this.chainName}`);
    console.log(`[SyncService]   identityContracts: ${JSON.stringify(this.identityContracts)}`);
    console.log(`[SyncService]   factoryAddress: ${this.factoryAddress || 'NOT SET'}`);

    const results: Array<{
      chain: string;
      chainId: number;
      contractAddress: string;
      owner: string;
      keyVaultBlock: number;
      name: string;
      type: string;
      timestamp: number;
      txHash: string;
    }> = [];

    try {
      const walletSecrets: string[] = [];

      // Step 1: Query secrets via Factory events (efficient — 1-2 API calls)
      if (this.factoryAddress) {
        try {
          console.log(`[SyncService] Step 1: Querying secrets via Factory events...`);
          const result = await this.reader.getSecretsFromFactoryByOwner(
            this.walletAddress,
            this.factoryAddress,
            this.chainName
          );
          console.log(`[SyncService] Found ${result.addresses.length} secrets OWNED by wallet via Factory`);
          walletSecrets.push(...result.addresses);
        } catch (err) {
          console.warn(`[SyncService] Error querying wallet-owned secrets:`, err);
        }
      }

      // Step 1 fallback: Only use brute-force internal TX scan if no factory address
      // getSecretsCreatedByWallet makes 1 API call per wallet TX — too slow for 500+ TXs
      if (!this.factoryAddress) {
        console.log(`[SyncService] Step 1 fallback: No factory address, using internal TX scan...`);
        const bruteForceSecrets = await this.reader.getSecretsCreatedByWallet(
          this.walletAddress,
          this.chainName
        );
        console.log(`[SyncService] Found ${bruteForceSecrets.length} contracts via internal TX scan`);
        walletSecrets.push(...bruteForceSecrets);
      }

      // Step 1b: Query secrets OWNED by Identity contracts via Factory WalletCreated events
      // Same approach - query WalletCreated events where Identity is the owner
      const identitySecrets: Array<{ address: string; identityOwner: string }> = [];

      if (this.identityContracts.length > 0 && this.factoryAddress) {
        console.log(`[SyncService] Querying secrets owned by ${this.identityContracts.length} Identity contract(s)`);

        for (const identityContract of this.identityContracts) {
          try {
            // Query transactions TO the Identity contract to find secrets created by any rivet
            // This works because rivet txs go TO Identity, which then creates the secret
            const secrets = await this.reader.getSecretsOwnedByAddress(
              identityContract,
              this.factoryAddress,
              this.chainName
            );
            console.log(`[SyncService] Found ${secrets.length} secrets OWNED by Identity ${identityContract.slice(0, 10)}...`);
            for (const addr of secrets) {
              identitySecrets.push({ address: addr, identityOwner: identityContract });
            }
          } catch (err) {
            console.warn(`[SyncService] Error querying secrets for Identity ${identityContract}:`, err);
          }
        }
      } else if (this.identityContracts.length > 0 && !this.factoryAddress) {
        console.warn('[SyncService] Cannot query Identity-owned secrets: factoryAddress not provided');
      }

      // Combine and deduplicate (in case wallet directly created some too)
      const secretAddresses = [...new Set([
        ...walletSecrets,
        ...identitySecrets.map(s => s.address)
      ])];

      // Map to track which secrets are Identity-owned (for setting isOwner correctly)
      const identityOwnerMap = new Map<string, string>();
      for (const { address, identityOwner } of identitySecrets) {
        identityOwnerMap.set(address.toLowerCase(), identityOwner);
      }

      console.log(`[SyncService] Total unique secrets to sync: ${secretAddresses.length} (${identitySecrets.length} from Identity contracts)`);

      // Step 2: Get KeyVaultCreated event for each contract
      for (const contractAddress of secretAddresses) {
        try {
          const event = await this.reader.getKeyVaultCreatedEvent(contractAddress, this.chainName);

          // V4 contracts don't have KeyVaultCreated events - skip them
          if (!event) {
            console.log(`[SyncService] No KeyVaultCreated event for ${contractAddress} (likely V4)`);
            continue;
          }

          // Parse JSON fields
          let encryptedKeysData: unknown = event.encryptedKeysData;
          let schema: unknown = event.schemaDefinition;

          try {
            encryptedKeysData = JSON.parse(event.encryptedKeysData);
          } catch {
            // Keep as string if not valid JSON
          }

          try {
            schema = JSON.parse(event.schemaDefinition);
          } catch {
            // Keep as string if not valid JSON
          }

          // Extract name and type from schema
          let secretName = 'Unnamed Secret';
          let secretType = 'unknown';

          if (schema && typeof schema === 'object') {
            const s = schema as { secretName?: string; secretType?: string; name?: string; type?: string };
            secretName = s.secretName || s.name || secretName;
            secretType = s.secretType || s.type || secretType;
          }

          // Extract encryptedIPFSHash and ipfsIV from encryptedKeysData (V5 KeyVault stores these)
          let encryptedIPFSHash = '';
          let ipfsIV = '';
          if (encryptedKeysData && typeof encryptedKeysData === 'object') {
            const keysObj = encryptedKeysData as Record<string, unknown>;
            console.log(`[SyncService] encryptedKeysData keys:`, Object.keys(keysObj));

            // Handle encryptedIPFSHash - could be string or object with 'encrypted' property
            const rawIpfsHash = keysObj.encryptedIPFSHash;
            if (typeof rawIpfsHash === 'string') {
              encryptedIPFSHash = rawIpfsHash;
            } else if (rawIpfsHash && typeof rawIpfsHash === 'object') {
              // Some versions store as {encrypted: "0x...", iv: "0x..."}
              const hashObj = rawIpfsHash as { encrypted?: string };
              encryptedIPFSHash = hashObj.encrypted || '';
            }

            // Handle ipfsIV - could be at root or inside encryptedIPFSHash object
            const rawIV = keysObj.ipfsIV;
            if (typeof rawIV === 'string') {
              ipfsIV = rawIV;
            } else if (rawIpfsHash && typeof rawIpfsHash === 'object') {
              const hashObj = rawIpfsHash as { iv?: string };
              ipfsIV = hashObj.iv || '';
            }

            if (encryptedIPFSHash) {
              console.log(`[SyncService] Found encryptedIPFSHash: ${encryptedIPFSHash.substring(0, 30)}...`);
              console.log(`[SyncService] Found ipfsIV: ${ipfsIV.substring(0, 20)}...`);
            }
          }

          // Step 3: Store via MessageProcessor
          const secretMessage: ChainMessage = {
            type: 'keyvault-created',
            txHash: event.txHash,
            blockNumber: event.blockNumber,
            from: event.creator,
            to: contractAddress,
            timestamp: event.timestamp,
            payload: {
              type: 'keyvault-created',
              blockNumber: event.blockNumber,
              creator: event.creator,
              encryptedKeysData,
              schemaDefinition: schema,
              timestamp: event.timestamp,
              txHash: event.txHash,
              contractAddress,
            },
            raw: JSON.stringify(encryptedKeysData),
          };

          console.log(`[SyncService] About to call processMessage with:`, JSON.stringify({
            type: secretMessage.type,
            txHash: secretMessage.txHash?.slice(0, 20),
            from: secretMessage.from,
            to: secretMessage.to,
          }));
          const processResult = await this.processor.processMessage(secretMessage);
          console.log(`[SyncService] processMessage result:`, processResult);

          // If processor returned ignore, try storing directly as a workaround
          if (processResult.action === 'ignore') {
            console.log(`[SyncService] Processor ignored message - storing secret directly`);
            // isOwner is true if:
            // 1. Wallet directly created the secret, OR
            // 2. Secret was created by an Identity contract where this wallet is a rivet
            const creatorLower = event.creator.toLowerCase();
            const isDirectOwner = creatorLower === this.walletAddress;
            const isIdentityOwner = identityOwnerMap.has(contractAddress.toLowerCase());
            const isOwner = isDirectOwner || isIdentityOwner;

            // Get Identity contract address if this is Identity-owned
            const identityOwner = identityOwnerMap.get(contractAddress.toLowerCase());
            if (isIdentityOwner && identityOwner) {
              console.log(`[SyncService] Secret owned by Identity ${identityOwner.slice(0, 10)}... - marking as IDENTITY mode`);
            }
            const directSecret = {
              contractAddress: contractAddress.toLowerCase(),
              chainId: this.chainId,
              name: secretName,
              type: secretType,
              ownerAddress: event.creator.toLowerCase(),
              isOwner,
              role: (isOwner ? 'OWNER' : 'VIEWER') as 'OWNER' | 'VIEWER',
              // IDENTITY MODE: Set ownerType and identityContract for Identity-owned secrets
              ownerType: (isIdentityOwner ? 'IDENTITY' : 'EOA') as 'EOA' | 'IDENTITY',
              identityContract: identityOwner,
              mintBlockNumber: event.blockNumber,
              mintTxHash: event.txHash,
              deployBlockNumber: event.blockNumber,
              keyVaultBlock: event.blockNumber,
              keyVaultName: `${secretName} Vault`,
              ipfsHash: encryptedIPFSHash,  // Extracted from encryptedKeysData
              ipfsIV: ipfsIV,                // IV for decrypting IPFS hash
              rawKeysData: typeof encryptedKeysData === 'object' ? JSON.stringify(encryptedKeysData, null, 2) : String(encryptedKeysData),
              teamMembers: [],
              pendingInvites: [],
              lastAccessedAt: Date.now(),
              lastSyncedAt: Date.now(),
              accessCount: 0,
              status: 'active' as const,
            };
            console.log(`[SyncService] Direct storing secret:`, directSecret.name, directSecret.isOwner);
            await this.database.secrets.put(directSecret);
            console.log(`[SyncService] Direct store complete`);
          }

          // Verify the secret was stored
          const storedSecret = await this.database.secrets.get(contractAddress);
          console.log(`[SyncService] Verification - secret in DB: ${!!storedSecret}, isOwner: ${storedSecret?.isOwner}`);

          results.push({
            chain: this.chainName,
            chainId: this.chainId,
            contractAddress,
            owner: event.creator,
            keyVaultBlock: event.blockNumber,
            name: secretName,
            type: secretType,
            timestamp: event.timestamp,
            txHash: event.txHash,
          });

          console.log(`[SyncService] Synced V5 secret: ${secretName} (${contractAddress})`);

        } catch (error) {
          console.error(`[SyncService] Error processing secret ${contractAddress}:`, error);
          this.onError?.(error instanceof Error ? error : new Error(String(error)));
        }
      }

      console.log(`[SyncService] Synced ${results.length} V5 secrets`);
      return results;
    } catch (error) {
      console.error('[SyncService] Error syncing owned secrets:', error);
      this.onError?.(error instanceof Error ? error : new Error(String(error)));
      return results;
    }
  }

  /**
   * Full sync including V5 secrets.
   * Combines wallet messages (for invites) with V5 secret discovery.
   *
   * @param fromBlock - Optional start block for message sync
   * @returns Combined sync result
   */
  async fullSync(fromBlock?: number): Promise<SyncResult & { secretsFound: number; fatPackagesFound?: number }> {
    console.log(`========================================`);
    console.log(`[SyncService] FULL SYNC STARTING`);
    console.log(`[SyncService] Wallet: ${this.walletAddress}`);
    console.log(`[SyncService] Chain: ${this.chainName} (${this.chainId})`);
    console.log(`[SyncService] Identity contracts count: ${this.identityContracts.length}`);
    if (this.identityContracts.length > 0) {
      console.log(`[SyncService] Identity contracts:`);
      this.identityContracts.forEach((c, i) => console.log(`  [${i}] ${c}`));
    } else {
      console.log(`[SyncService] ⚠️ NO Identity contracts - fat packages will NOT be synced!`);
    }
    console.log(`[SyncService] Factory address: ${this.factoryAddress || 'NOT SET'}`);
    console.log(`========================================`);

    // Sync wallet messages (invites, responses, keys)
    const messageResult = await this.sync(fromBlock);

    // Sync V5 owned secrets (including Identity-owned)
    console.log(`[SyncService] Calling syncOwnedSecrets...`);
    const secrets = await this.syncOwnedSecrets();
    console.log(`[SyncService] syncOwnedSecrets returned ${secrets.length} secrets`);

    // Sync fat packages from Identity's MessageReceived events
    let fatPackagesFound = 0;
    console.log(`========================================`);
    console.log(`[SyncService] FAT PACKAGE SYNC CHECK`);
    console.log(`[SyncService] identityContracts.length = ${this.identityContracts.length}`);
    if (this.identityContracts.length > 0) {
      console.log(`[SyncService] ✓ Will sync fat packages from ${this.identityContracts.length} Identity contract(s)`);
      try {
        fatPackagesFound = await this.syncFatPackages();
        console.log(`[SyncService] ✓ syncFatPackages completed: found ${fatPackagesFound} fat packages`);
      } catch (fatError) {
        console.error(`[SyncService] ✗ syncFatPackages error:`, fatError);
      }
    } else {
      console.log(`[SyncService] ✗ SKIPPING fat package sync - no Identity contracts configured`);
    }
    console.log(`========================================`);

    return {
      ...messageResult,
      secretsFound: secrets.length,
      fatPackagesFound,
    };
  }

  /**
   * Sync fat packages from Identity's MessageReceived events.
   * Fat packages are sent TO Identity contracts when sharing with Identity recipients.
   * Each rivet on the Identity can find and decrypt their portion.
   *
   * @returns Number of fat packages processed
   */
  async syncFatPackages(): Promise<number> {
    let packagesProcessed = 0;

    console.log(`[syncFatPackages] ========================================`);
    console.log(`[syncFatPackages] Starting fat package sync`);
    console.log(`[syncFatPackages] Identity contracts: ${this.identityContracts.length}`);
    console.log(`[syncFatPackages] Chain: ${this.chainName} (${this.chainId})`);
    console.log(`[syncFatPackages] Wallet: ${this.walletAddress}`);
    console.log(`[syncFatPackages] ========================================`);

    for (let idx = 0; idx < this.identityContracts.length; idx++) {
      const identityAddress = this.identityContracts[idx];
      try {
        console.log(`[syncFatPackages] [${idx + 1}/${this.identityContracts.length}] Querying Identity: ${identityAddress}`);

        // Query MessageReceived events from the Identity contract
        // Use chainId instead of chainName for reliable matching
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const messages = await (this.reader as any).getIdentityMessages(
          identityAddress,
          this.chainId,  // Use chainId for reliable chain matching
          0  // fromBlock - could be optimized to track last synced
        );

        console.log(`[syncFatPackages] getIdentityMessages returned: ${messages?.length ?? 0} messages`);
        if (!messages || messages.length === 0) {
          console.log(`[syncFatPackages] ⚠️ No MessageReceived events found on ${identityAddress.slice(0, 12)}`);
          continue;
        }
        console.log(`[syncFatPackages] ✓ Found ${messages.length} messages to process`);

        for (const msg of messages) {
          try {
            // Parse the message data (hex → utf8 → JSON)
            if (!msg.data || msg.data === '0x') {
              console.log(`[syncFatPackages] Skipping empty message in tx ${msg.txHash?.slice(0, 12)}`);
              continue;
            }
            console.log(`[syncFatPackages] Processing message from tx ${msg.txHash?.slice(0, 12)}, data length: ${msg.data.length}`);

            // Remove '0x' prefix and decode hex to string (browser-compatible)
            const hexData = msg.data.startsWith('0x') ? msg.data.slice(2) : msg.data;
            // Convert hex to bytes, then to UTF-8 string
            const bytes = new Uint8Array(hexData.match(/.{1,2}/g)!.map((byte: string) => parseInt(byte, 16)));
            const jsonString = new TextDecoder().decode(bytes);

            let payload: unknown;
            try {
              payload = JSON.parse(jsonString);
            } catch {
              // Not valid JSON, skip
              continue;
            }

            // Check if this is a fat-key-package
            const payloadType = typeof payload === 'object' && payload !== null ? (payload as Record<string, unknown>).type : 'unknown';
            console.log(`[syncFatPackages] Message type: ${payloadType}`);

            if (payloadType === 'fat-key-package') {
              console.log(`[syncFatPackages] ✓ Found fat-key-package!`);
              const fatPackage = payload as {
                type: 'fat-key-package';
                version: string;
                secretContract: string;
                secretName?: string;
                keyVaultBlock?: number;
                identityContract: string;
                sender?: string;
                senderIdentity?: string;
                devices: Array<{
                  deviceAddress: string;
                  deviceName?: string;
                  ephemeralPublicKey?: string;
                  encryptedMasterKey: string;
                  encryptedKeyVaultKey?: string;
                }>;
                writeAuthorization?: {
                  v: number;
                  r: string;
                  s: string;
                  expiresAt: number;
                };
                createdAt?: number;
              };

              console.log(`[syncFatPackages] Fat package details:`);
              console.log(`  - Secret: ${fatPackage.secretContract}`);
              console.log(`  - Name: ${fatPackage.secretName || 'unnamed'}`);
              console.log(`  - Sender: ${msg.from}`);
              console.log(`  - Devices: ${fatPackage.devices?.length || 0}`);

              // Check if this device is in the package's devices list
              const myDeviceEntry = fatPackage.devices.find(
                d => d.deviceAddress.toLowerCase() === this.walletAddress.toLowerCase()
              );

              if (!myDeviceEntry) {
                console.log(`[syncFatPackages] ⚠️ This device NOT in fat package devices list`);
                console.log(`  - My wallet: ${this.walletAddress}`);
                console.log(`  - Package devices: ${fatPackage.devices.map(d => d.deviceAddress).join(', ')}`);
                continue;
              }

              console.log(`[syncFatPackages] ✓ Found my device entry in fat package!`);

              // Create a chain message to process this as a shared secret (similar to direct-keys)
              const chainMessage: ChainMessage = {
                type: 'fat-key-package',
                txHash: msg.txHash,
                blockNumber: msg.blockNumber,
                from: msg.from,
                to: identityAddress,
                timestamp: msg.timestamp,
                payload: fatPackage,
                raw: msg.data,
              };

              // Process the fat package through the message processor
              console.log(`[syncFatPackages] Processing fat package through MessageProcessor...`);
              const result = await this.processor.processMessage(chainMessage);
              if (result.action !== 'error') {
                packagesProcessed++;
                console.log(`[syncFatPackages] ✓ Fat package processed! Action: ${result.action}`);
              } else {
                console.error(`[syncFatPackages] ✗ Error processing: ${result.error}`);
              }
            }
          } catch (parseError) {
            // Skip unparseable messages
            console.log(`[syncFatPackages] Failed to parse message:`, parseError);
            continue;
          }
        }
      } catch (error) {
        console.error(`[syncFatPackages] Error syncing Identity ${identityAddress}:`, error);
      }
    }

    console.log(`[syncFatPackages] ========================================`);
    console.log(`[syncFatPackages] COMPLETE: Processed ${packagesProcessed} fat packages`);
    console.log(`[syncFatPackages] ========================================`);
    return packagesProcessed;
  }

  /**
   * Sync notes for a specific secret's KeyVault.
   * Uses ChainReader.getDataWrittenEvents to fetch and store notes.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @returns Number of notes synced
   */
  async syncNotes(secretAddress: string, kvBlock: number): Promise<{
    notesFound: number;
    notesSynced: number;
    errors: string[];
  }> {
    const errors: string[] = [];
    let notesSynced = 0;

    try {
      // Use ChainReader to get DataWritten events (no block scanning)
      const events = await this.reader.getDataWrittenEvents(
        secretAddress,
        this.chainName,
        kvBlock
      );

      console.log(`[SyncService] Found ${events.length} DataWritten events for ${secretAddress} kvBlock ${kvBlock}`);

      // Process each event through MessageProcessor
      for (const event of events) {
        try {
          const chainMessage: ChainMessage = {
            type: 'data-written',
            txHash: event.txHash,
            blockNumber: event.blockNumber,
            from: event.writer,
            to: secretAddress,
            timestamp: event.timestamp,
            payload: {
              type: 'data-written',
              secretContract: event.secretContract,
              writer: event.writer,
              keyVaultBlock: event.keyVaultBlock,
              data: event.data,
              creditsCost: event.creditsCost,
              timestamp: event.timestamp,
              txHash: event.txHash,
              blockNumber: event.blockNumber,
            },
            raw: event.data,
          };

          const result = await this.processor.processMessage(chainMessage);
          if (result.action !== 'error') {
            notesSynced++;
          } else {
            errors.push(result.error || 'Unknown error');
          }
        } catch (error) {
          const msg = error instanceof Error ? error.message : String(error);
          errors.push(msg);
          console.error(`[SyncService] Error processing note event:`, error);
        }
      }

      // Update KeyVault sync state
      const kvId = `kv_${secretAddress.toLowerCase()}_${kvBlock}`;
      const keyVault = await this.database.keyVaults.get(kvId);
      if (keyVault) {
        keyVault.noteCount = notesSynced;
        keyVault.lastSyncedBlock = events.length > 0
          ? Math.max(...events.map(e => e.blockNumber))
          : keyVault.lastSyncedBlock;
        await this.database.keyVaults.put(keyVault);
      }

      console.log(`[SyncService] Synced ${notesSynced}/${events.length} notes for ${secretAddress}`);

      return {
        notesFound: events.length,
        notesSynced,
        errors,
      };
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      errors.push(msg);
      console.error(`[SyncService] Error syncing notes:`, error);

      return {
        notesFound: 0,
        notesSynced: 0,
        errors,
      };
    }
  }

  /**
   * Sync all KeyVaults for a specific secret.
   * Uses ChainReader.getKeyVaultCreatedEvents to fetch and store KeyVaults.
   *
   * @param secretAddress - Secret contract address
   * @returns Number of KeyVaults synced
   */
  async syncKeyVaults(secretAddress: string): Promise<{
    keyVaultsFound: number;
    keyVaultsSynced: number;
    errors: string[];
  }> {
    const errors: string[] = [];
    let keyVaultsSynced = 0;

    try {
      // Use ChainReader to get KeyVaultCreated events (no block scanning)
      const events = await this.reader.getKeyVaultCreatedEvents(
        secretAddress,
        this.chainName
      );

      console.log(`[SyncService] Found ${events.length} KeyVaultCreated events for ${secretAddress}`);

      // Process each event through MessageProcessor
      for (const event of events) {
        try {
          // Parse JSON fields
          let encryptedKeysData: unknown = event.encryptedKeysData;
          let schema: unknown = event.schemaDefinition;

          try {
            encryptedKeysData = JSON.parse(event.encryptedKeysData);
          } catch {
            // Keep as string if not valid JSON
          }

          try {
            schema = JSON.parse(event.schemaDefinition);
          } catch {
            // Keep as string if not valid JSON
          }

          const chainMessage: ChainMessage = {
            type: 'keyvault-created',
            txHash: event.txHash,
            blockNumber: event.blockNumber,
            from: event.creator,
            to: secretAddress,
            timestamp: event.timestamp,
            payload: {
              type: 'keyvault-created',
              blockNumber: event.blockNumber,
              creator: event.creator,
              encryptedKeysData,
              schemaDefinition: schema,
              timestamp: event.timestamp,
              txHash: event.txHash,
              contractAddress: secretAddress,
            },
            raw: event.encryptedKeysData,
          };

          const result = await this.processor.processMessage(chainMessage);
          if (result.action !== 'error') {
            keyVaultsSynced++;
          } else {
            errors.push(result.error || 'Unknown error');
          }
        } catch (error) {
          const msg = error instanceof Error ? error.message : String(error);
          errors.push(msg);
          console.error(`[SyncService] Error processing KeyVault event:`, error);
        }
      }

      console.log(`[SyncService] Synced ${keyVaultsSynced}/${events.length} KeyVaults for ${secretAddress}`);

      return {
        keyVaultsFound: events.length,
        keyVaultsSynced,
        errors,
      };
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      errors.push(msg);
      console.error(`[SyncService] Error syncing KeyVaults:`, error);

      return {
        keyVaultsFound: 0,
        keyVaultsSynced: 0,
        errors,
      };
    }
  }

  // ==========================================================================
  // Verification
  // ==========================================================================

  /**
   * Verify a stored invite/secret against blockchain data.
   * Uses ChainReader to fetch the original transaction and compare.
   *
   * @param txHash - Transaction hash to verify
   * @returns Verification result
   *
   * @example
   * ```typescript
   * const result = await sync.verifyFromChain('0xabc...');
   * if (result.verified) {
   *   console.log('Data matches blockchain');
   * }
   * ```
   */
  async verifyFromChain(txHash: string): Promise<{
    verified: boolean;
    found: boolean;
    blockNumber?: number;
    error?: string;
  }> {
    try {
      const result = await this.reader.fetchTransaction(txHash);
      if (!result) {
        return { verified: false, found: false, error: 'Transaction not found' };
      }

      const { tx } = result;

      // Check if we have this message stored
      const storedMessage = this.rawMessages.get(txHash);
      if (!storedMessage) {
        return { verified: false, found: true, blockNumber: tx.blockNumber ?? undefined, error: 'Not in local cache' };
      }

      // Compare raw data
      const verified = storedMessage.raw === tx.data;
      return {
        verified,
        found: true,
        blockNumber: tx.blockNumber ?? undefined,
        error: verified ? undefined : 'Data mismatch',
      };
    } catch (error) {
      return {
        verified: false,
        found: false,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }

  // ==========================================================================
  // Helper Methods
  // ==========================================================================

  private getSyncKey(): string {
    return `wallet_${this.chainId}_${this.walletAddress}`;
  }

  private emitProgress(progress: SyncProgress): void {
    this.onProgress?.(progress);
  }
}

// ============================================================================
// Factory Function
// ============================================================================

/**
 * Create a configured SyncService instance.
 *
 * @example
 * ```typescript
 * const sync = createSyncService({
 *   reader,
 *   processor,
 *   database,
 *   chainId: 80002,
 *   chainName: 'amoy',
 *   walletAddress: '0x123...',
 * });
 * ```
 */
export function createSyncService(config: SyncConfig): SyncService {
  return new SyncService(config);
}
