/**
 * Rootz V6 Dashboard - Wallet Tab
 *
 * Hardware wallet management with proper UX flow:
 * 1. Connect wallet (MetaMask)
 * 2. Setup on-chain (stores encrypted device key)
 * 3. Unlock (sign to decrypt)
 * 4. Recover (from tx hash)
 */

import { BrowserProvider } from 'ethers';
import { ChainDeviceKeyManager, getDeviceKeyCache, clearDeviceKeyCache } from '@rootz/hardware-keys';
import {
  getWalletSource,
  setWalletSource,
  hasHardwareWallet,
  getStoredHardwareWallet,
  clearHardwareWallet,
  hasTpmWallet,
  type WalletState,
  type StoredHardwareWallet,
} from '../wallet.js';
import type { AppConfig } from '../config.js';

// Module state
let appConfig: AppConfig;
let dashboardWallet: WalletState | null = null;
let connectedAddress: string | null = null;
let connectedSigner: any = null;
let isUnlocked = false;

/**
 * Check if hardware wallet is already unlocked (from main.ts initialization)
 */
function checkIfAlreadyUnlocked(wallet: WalletState | null): boolean {
  if (!wallet) return false;

  // If dashboard has a working hardware wallet with keys, it's unlocked
  const source = getWalletSource();
  if (source === 'hardware' && wallet.privateKey && wallet.publicKey) {
    console.log('[Wallet Tab] Hardware wallet already unlocked from main initialization');
    return true;
  }
  return false;
}

// Chain configuration
const CHAIN_CONFIG: Record<number, { name: string; rpc: string }> = {
  137: { name: 'Polygon Mainnet', rpc: 'https://polygon-rpc.com' },
  80002: { name: 'Polygon Amoy (Testnet)', rpc: 'https://rpc-amoy.polygon.technology' },
};

/**
 * Render the Wallet tab
 */
export function renderWalletTab(
  container: HTMLElement,
  cfg: AppConfig,
  state: WalletState | null
): string {
  appConfig = cfg;
  dashboardWallet = state;

  // Check if wallet was already unlocked during main initialization
  if (checkIfAlreadyUnlocked(state)) {
    isUnlocked = true;
    // Also set the connected address from the dashboard wallet
    if (state?.address) {
      connectedAddress = state.address;
    }
  }

  const source = getWalletSource();
  const hwInfo = getStoredHardwareWallet();
  const chainCache = getDeviceKeyCache();

  // Determine current state
  const hasCache = hwInfo !== null || chainCache !== null;
  const networkId = hwInfo?.chainId || chainCache?.chainId || cfg.network.chainId;
  const networkName = CHAIN_CONFIG[networkId]?.name || `Chain ${networkId}`;

  const html = `
    <h2>Hardware Wallet</h2>

    <!-- Status Banner -->
    <div id="hw-banner" class="status-banner ${getBannerClass(hasCache, isUnlocked, connectedAddress)}">
      ${getBannerMessage(hasCache, isUnlocked, connectedAddress)}
    </div>

    <!-- Wallet Connection -->
    <section class="card">
      <h3>1. Connect Wallet</h3>
      <p class="description">Connect your hardware wallet (Trezor/Ledger) via MetaMask. The system will automatically check the blockchain for your existing device key.</p>
      <div class="status-row">
        <span class="label">Status:</span>
        <span id="connect-status" class="value ${connectedAddress ? 'success' : 'muted'}">${connectedAddress ? 'Connected' : 'Not Connected'}</span>
      </div>
      <div class="status-row">
        <span class="label">Address:</span>
        <span id="connect-address" class="value monospace">${connectedAddress || '-'}</span>
      </div>
      <div class="button-row">
        <button id="hw-connect-btn" class="btn-primary ${connectedAddress ? 'btn-disabled' : ''}">
          ${connectedAddress ? '✓ Connected' : 'Connect Wallet'}
        </button>
      </div>
    </section>

    <!-- On-Chain Storage -->
    <section class="card">
      <h3>2. Device Key (On-Chain)</h3>
      <p class="description">Your encryption key is stored encrypted on Polygon. Only you can decrypt it with your hardware wallet signature.</p>
      <div class="status-row">
        <span class="label">Setup Status:</span>
        <span id="setup-status" class="value ${hasCache ? 'success' : 'muted'}">${hasCache ? 'Configured' : 'Not Set Up'}</span>
      </div>
      <div class="status-row">
        <span class="label">Lock Status:</span>
        <span id="lock-status" class="value ${isUnlocked ? 'success' : 'warning'}">${isUnlocked ? 'Unlocked' : 'Locked'}</span>
      </div>
      ${hwInfo ? `
      <div class="status-row">
        <span class="label">Tx Hash:</span>
        <span class="value monospace">${hwInfo.txHash.slice(0, 24)}...</span>
      </div>
      ` : ''}
      <div class="status-row">
        <span class="label">Network:</span>
        <span class="value">${networkName}</span>
        <input type="hidden" id="hw-network" value="${cfg.network.chainId}" />
      </div>
      <div class="button-row">
        <button id="hw-setup-btn" class="btn-primary" ${!connectedAddress || hasCache ? 'disabled' : ''}>
          Setup On-Chain
        </button>
        <button id="hw-unlock-btn" class="btn-success" ${!connectedAddress || !hasCache || isUnlocked ? 'disabled' : ''}>
          Unlock
        </button>
        <button id="hw-lock-btn" class="btn-secondary" ${!isUnlocked ? 'disabled' : ''}>
          Lock
        </button>
        <button id="hw-clear-btn" class="btn-danger" ${!hasCache ? 'disabled' : ''}>
          Reset
        </button>
      </div>
    </section>

    <!-- Recovery -->
    <section class="card">
      <h3>3. Recovery</h3>
      <p class="description">
        <strong>Automatic recovery:</strong> When you connect your wallet, the system automatically scans ${networkName} for your device key.
        <br><br>
        <strong>Manual recovery:</strong> If auto-discovery doesn't find your key (e.g., created on a different network), enter the transaction hash below.
      </p>
      <div class="input-row">
        <input type="text" id="hw-recover-tx" class="text-input" placeholder="0x... transaction hash (optional)" />
        <button id="hw-recover-btn" class="btn-secondary">Manual Recover</button>
      </div>
    </section>

    <!-- Current Dashboard Wallet -->
    <section class="card">
      <h3>Dashboard Wallet Status</h3>
      <div class="status-row">
        <span class="label">Wallet Type:</span>
        <span class="value">${formatWalletType(source)}</span>
      </div>
      <div class="status-row">
        <span class="label">Address:</span>
        <span class="value monospace">${dashboardWallet?.address || 'Not connected'}</span>
      </div>
      <div class="status-row">
        <span class="label">Balance:</span>
        <span class="value">${dashboardWallet?.balance || '0'} POL</span>
      </div>
      <div class="wallet-type-info">
        <div class="wallet-type ${source === 'hardware' ? 'active' : ''}">
          <strong>Hardware</strong> - Keys protected by Trezor/Ledger
        </div>
        <div class="wallet-type ${source === 'tpm' ? 'active' : ''}">
          <strong>TPM</strong> - Keys protected by TPM chip ${hasTpmWallet() ? '✓' : ''}
        </div>
        <div class="wallet-type ${source === 'standard' ? 'active' : ''}">
          <strong>Browser</strong> - Keys in localStorage
        </div>
      </div>
    </section>

    <!-- Activity Log -->
    <section class="card">
      <h3>Activity Log</h3>
      <div id="hw-log" class="log-container">
        <div class="log-entry info">Hardware wallet tab ready</div>
      </div>
    </section>

    <div id="wallet-status" class="status-message"></div>
  `;

  container.innerHTML = html;
  setupWalletTab(container);
  return html;
}

/**
 * Get banner CSS class based on state
 */
function getBannerClass(hasCache: boolean, unlocked: boolean, connected: string | null): string {
  if (!connected) return 'banner-warning';
  if (!hasCache) return 'banner-warning';
  if (!unlocked) return 'banner-error';
  return 'banner-success';
}

/**
 * Get banner message based on state
 */
function getBannerMessage(hasCache: boolean, unlocked: boolean, connected: string | null): string {
  if (!connected) return '🔌 Connect wallet - we will auto-discover your device key from chain';
  if (!hasCache) return '⚙️ No device key found on chain. Click "Setup On-Chain" to create one';
  if (!unlocked) return '🔒 Device key found! Click "Unlock" to decrypt with your wallet signature';
  return '🔓 Device key unlocked - Ready to encrypt/decrypt';
}

/**
 * Format wallet type for display
 */
function formatWalletType(source: string): string {
  switch (source) {
    case 'hardware': return 'Hardware Wallet (Trezor/Ledger)';
    case 'tpm': return 'TPM Protected';
    case 'standard': return 'Browser Wallet';
    default: return source;
  }
}

/**
 * Log message to activity log
 */
function log(message: string, type: 'info' | 'success' | 'error' | 'warning' = 'info'): void {
  const logEl = document.getElementById('hw-log');
  if (!logEl) return;

  const entry = document.createElement('div');
  entry.className = `log-entry ${type}`;
  const time = new Date().toLocaleTimeString();
  entry.textContent = `[${time}] ${message}`;
  logEl.appendChild(entry);
  logEl.scrollTop = logEl.scrollHeight;

  console.log(`[Wallet Tab] ${message}`);
}

/**
 * Update UI state
 */
function updateUI(): void {
  const hwInfo = getStoredHardwareWallet();
  const chainCache = getDeviceKeyCache();
  const hasCache = hwInfo !== null || chainCache !== null;

  // Update status displays
  const connectStatus = document.getElementById('connect-status');
  const connectAddress = document.getElementById('connect-address');
  const setupStatus = document.getElementById('setup-status');
  const lockStatus = document.getElementById('lock-status');
  const banner = document.getElementById('hw-banner');

  if (connectStatus) {
    connectStatus.textContent = connectedAddress ? 'Connected' : 'Not Connected';
    connectStatus.className = `value ${connectedAddress ? 'success' : 'muted'}`;
  }
  if (connectAddress) {
    connectAddress.textContent = connectedAddress || '-';
  }
  if (setupStatus) {
    setupStatus.textContent = hasCache ? 'Configured' : 'Not Set Up';
    setupStatus.className = `value ${hasCache ? 'success' : 'muted'}`;
  }
  if (lockStatus) {
    lockStatus.textContent = isUnlocked ? 'Unlocked' : 'Locked';
    lockStatus.className = `value ${isUnlocked ? 'success' : 'warning'}`;
  }
  if (banner) {
    banner.textContent = getBannerMessage(hasCache, isUnlocked, connectedAddress);
    banner.className = `status-banner ${getBannerClass(hasCache, isUnlocked, connectedAddress)}`;
  }

  // Update buttons
  const connectBtn = document.getElementById('hw-connect-btn') as HTMLButtonElement;
  const setupBtn = document.getElementById('hw-setup-btn') as HTMLButtonElement;
  const unlockBtn = document.getElementById('hw-unlock-btn') as HTMLButtonElement;
  const lockBtn = document.getElementById('hw-lock-btn') as HTMLButtonElement;
  const clearBtn = document.getElementById('hw-clear-btn') as HTMLButtonElement;

  if (connectBtn) {
    connectBtn.disabled = !!connectedAddress;
    connectBtn.textContent = connectedAddress ? '✓ Connected' : 'Connect Wallet';
  }
  if (setupBtn) setupBtn.disabled = !connectedAddress || hasCache;
  if (unlockBtn) unlockBtn.disabled = !connectedAddress || !hasCache || isUnlocked;
  if (lockBtn) lockBtn.disabled = !isUnlocked;
  if (clearBtn) clearBtn.disabled = !hasCache;
}

/**
 * Setup event handlers
 */
export function setupWalletTab(container: HTMLElement): void {
  container.querySelector('#hw-connect-btn')?.addEventListener('click', handleConnect);
  container.querySelector('#hw-setup-btn')?.addEventListener('click', handleSetup);
  container.querySelector('#hw-unlock-btn')?.addEventListener('click', handleUnlock);
  container.querySelector('#hw-lock-btn')?.addEventListener('click', handleLock);
  container.querySelector('#hw-clear-btn')?.addEventListener('click', handleClear);
  container.querySelector('#hw-recover-btn')?.addEventListener('click', handleRecover);

  // Listen for MetaMask account changes
  if (window.ethereum) {
    window.ethereum.on('accountsChanged', (accounts: string[]) => {
      if (accounts.length === 0) {
        connectedAddress = null;
        connectedSigner = null;
        isUnlocked = false;
        sessionStorage.removeItem('hw_connected_address');
        log('Wallet disconnected', 'warning');
      } else {
        handleConnect();
      }
      updateUI();
    });

    // Auto-reconnect if wallet was previously connected in this session
    const savedAddress = sessionStorage.getItem('hw_connected_address');
    if (savedAddress && !connectedAddress) {
      log('Reconnecting to wallet...');
      autoReconnect();
    }
  }
}

/**
 * Auto-reconnect to wallet if previously connected
 */
async function autoReconnect(): Promise<void> {
  if (!window.ethereum) return;

  try {
    const provider = new BrowserProvider(window.ethereum);
    const accounts = await provider.send('eth_accounts', []);

    if (accounts && accounts.length > 0) {
      connectedSigner = await provider.getSigner();
      connectedAddress = await connectedSigner.getAddress();
      log(`Reconnected: ${connectedAddress}`, 'success');

      // Check if we need to auto-discover
      const hwInfo = getStoredHardwareWallet();
      if (!hwInfo || hwInfo.address.toLowerCase() !== connectedAddress.toLowerCase()) {
        await autoDiscoverDeviceKey();
      }

      updateUI();
    }
  } catch (error: any) {
    console.warn('[Wallet Tab] Auto-reconnect failed:', error);
  }
}

/**
 * Connect to MetaMask - with auto-discovery from chain
 */
async function handleConnect(): Promise<void> {
  log('Connecting to MetaMask...');

  if (!window.ethereum) {
    log('MetaMask not found! Install MetaMask and connect your hardware wallet.', 'error');
    return;
  }

  try {
    const provider = new BrowserProvider(window.ethereum);
    await provider.send('eth_requestAccounts', []);
    connectedSigner = await provider.getSigner();
    connectedAddress = await connectedSigner.getAddress();

    log(`Connected: ${connectedAddress}`, 'success');

    // Persist connection in sessionStorage for this session
    sessionStorage.setItem('hw_connected_address', connectedAddress);

    // Check if this matches any stored config
    const hwInfo = getStoredHardwareWallet();
    if (hwInfo) {
      if (hwInfo.address.toLowerCase() !== connectedAddress.toLowerCase()) {
        log(`Warning: Different wallet than stored (${hwInfo.address.slice(0, 10)}...)`, 'warning');
        log('Auto-discovering device key on chain...', 'info');
        // Try to auto-discover for this new wallet
        await autoDiscoverDeviceKey();
      } else {
        log('Hardware wallet configured - click Unlock to continue');
      }
    } else {
      // No stored config - try auto-discovery
      log('No local config found, checking chain...', 'info');
      await autoDiscoverDeviceKey();
    }

    updateUI();
  } catch (error: any) {
    log(`Connection failed: ${error.message}`, 'error');
  }
}

/**
 * Auto-discover device key from chain using Polygonscan
 */
async function autoDiscoverDeviceKey(): Promise<void> {
  if (!connectedAddress) return;

  const chainId = appConfig.network.chainId;
  const rpcUrl = appConfig.network.rpc;
  const networkName = CHAIN_CONFIG[chainId]?.name || `Chain ${chainId}`;

  log(`Scanning ${networkName} for device key...`);

  try {
    const manager = new ChainDeviceKeyManager(rpcUrl, chainId);
    const result = await manager.discoverDeviceKeyTx(connectedAddress);

    if (result.success) {
      log(`Found device key on chain! Tx: ${result.txHash?.slice(0, 16)}...`, 'success');

      // Store the discovered info
      const hwWalletData: StoredHardwareWallet = {
        address: connectedAddress,
        publicKey: result.publicKey!,
        txHash: result.txHash!,
        chainId,
        createdAt: Date.now(),
      };
      localStorage.setItem('rootz_hardware_wallet', JSON.stringify(hwWalletData));
      setWalletSource('hardware');

      log('Configuration restored. Click Unlock to continue.', 'success');
      updateUI();
    } else {
      log('No device key found on chain. Click "Setup On-Chain" to create one.', 'info');
    }
  } catch (error: any) {
    log(`Auto-discovery error: ${error.message}`, 'warning');
  }
}

/**
 * Setup device key on-chain
 */
async function handleSetup(): Promise<void> {
  if (!connectedSigner || !connectedAddress) {
    log('Connect wallet first', 'error');
    return;
  }

  // Use the dashboard's configured network
  const chainId = appConfig.network.chainId;
  const rpcUrl = appConfig.network.rpc;
  const networkName = CHAIN_CONFIG[chainId]?.name || `Chain ${chainId}`;

  log(`Setting up device key on ${networkName}...`);

  try {
    // Switch to correct network
    try {
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: '0x' + chainId.toString(16) }],
      });
    } catch (switchError: any) {
      if (switchError.code === 4902) {
        log('Network not configured in wallet', 'error');
        return;
      }
      throw switchError;
    }

    // Refresh signer after network switch
    const provider = new BrowserProvider(window.ethereum);
    connectedSigner = await provider.getSigner();

    // Create chain device key manager using dashboard's RPC
    const manager = new ChainDeviceKeyManager(rpcUrl, chainId);

    log('Requesting signature (check hardware wallet)...', 'warning');
    const result = await manager.setup(connectedSigner);

    if (!result.success) {
      log(`Setup failed: ${result.error}`, 'error');
      return;
    }

    log(`Transaction sent: ${result.txHash?.slice(0, 20)}...`, 'success');

    // Store metadata locally
    const hwWalletData: StoredHardwareWallet = {
      address: connectedAddress,
      publicKey: result.publicKey!,
      txHash: result.txHash!,
      chainId,
      createdAt: Date.now(),
    };
    localStorage.setItem('rootz_hardware_wallet', JSON.stringify(hwWalletData));
    setWalletSource('hardware');

    isUnlocked = true;
    log('Device key created and unlocked!', 'success');
    log('Page will reload to use hardware wallet...', 'info');

    // Reload after delay
    setTimeout(() => window.location.reload(), 2000);

    updateUI();
  } catch (error: any) {
    log(`Setup failed: ${error.message}`, 'error');
  }
}

/**
 * Unlock device key
 */
async function handleUnlock(): Promise<void> {
  if (!connectedSigner || !connectedAddress) {
    log('Connect wallet first', 'error');
    return;
  }

  const hwInfo = getStoredHardwareWallet();
  if (!hwInfo) {
    log('No device key configured', 'error');
    return;
  }

  if (connectedAddress.toLowerCase() !== hwInfo.address.toLowerCase()) {
    log(`Wrong wallet! Need ${hwInfo.address.slice(0, 10)}...`, 'error');
    return;
  }

  const config = CHAIN_CONFIG[hwInfo.chainId];
  if (!config) {
    log('Unknown network in stored config', 'error');
    return;
  }

  log(`Unlocking from ${config.name}...`);

  try {
    const manager = new ChainDeviceKeyManager(config.rpc, hwInfo.chainId);

    log('Requesting signature (check hardware wallet)...', 'warning');
    const result = await manager.unlockFromCache(connectedSigner);

    if (!result.success) {
      log(`Unlock failed: ${result.error}`, 'error');
      return;
    }

    isUnlocked = true;
    log('Unlocked!', 'success');
    log('Page will reload...', 'info');

    setTimeout(() => window.location.reload(), 1500);

    updateUI();
  } catch (error: any) {
    log(`Unlock failed: ${error.message}`, 'error');
  }
}

/**
 * Lock device key
 */
function handleLock(): void {
  isUnlocked = false;
  clearDeviceKeyCache();
  log('Locked');
  updateUI();
}

/**
 * Clear/reset device key
 */
function handleClear(): void {
  if (confirm('Clear hardware wallet configuration?\n\nYou can recover using your hardware wallet and the stored transaction hash.')) {
    clearHardwareWallet();
    isUnlocked = false;
    log('Configuration cleared', 'warning');
    updateUI();
  }
}

/**
 * Recover from transaction hash
 */
async function handleRecover(): Promise<void> {
  const txInput = document.getElementById('hw-recover-tx') as HTMLInputElement;
  const txHash = txInput?.value.trim();

  if (!txHash || !txHash.startsWith('0x')) {
    log('Enter a valid transaction hash (0x...)', 'error');
    return;
  }

  // Use the dashboard's configured network
  const chainId = appConfig.network.chainId;
  const rpcUrl = appConfig.network.rpc;
  const networkName = CHAIN_CONFIG[chainId]?.name || `Chain ${chainId}`;

  log(`Recovering from tx ${txHash.slice(0, 16)}... on ${networkName}`);

  try {
    const manager = new ChainDeviceKeyManager(rpcUrl, chainId);
    const result = await manager.recoverFromTx(txHash);

    if (!result.success) {
      log(`Recovery failed: ${result.error}`, 'error');
      return;
    }

    // Store the recovered info
    const hwWalletData: StoredHardwareWallet = {
      address: result.walletAddress!,
      publicKey: result.publicKey!,
      txHash: txHash,
      chainId,
      createdAt: Date.now(),
    };
    localStorage.setItem('rootz_hardware_wallet', JSON.stringify(hwWalletData));
    setWalletSource('hardware');

    log(`Recovered! Device key for ${result.walletAddress?.slice(0, 10)}...`, 'success');
    log('Connect wallet and click Unlock to continue');

    txInput.value = '';
    updateUI();
  } catch (error: any) {
    log(`Recovery failed: ${error.message}`, 'error');
  }
}

// Add ethereum type declaration
declare global {
  interface Window {
    ethereum?: any;
  }
}
