/**
 * Office.js Integration for Rootz Dashboard
 *
 * Provides document extraction and Office context detection
 * when the dashboard runs inside Word Add-in.
 */

// Declare Office.js types for TypeScript
declare const Office: any;
declare const Word: any;

/**
 * Check if running inside Office.js context (Word Add-in)
 */
export function isOfficeContext(): boolean {
  return typeof Office !== 'undefined' && Office.context?.document !== undefined;
}

/**
 * Check if the document has unsaved changes
 * Returns true if there are unsaved changes, false if saved or unknown
 */
export async function checkUnsavedChanges(): Promise<boolean> {
  if (!isOfficeContext()) {
    return false;
  }

  return new Promise((resolve) => {
    try {
      // Word.run to check document state
      Word.run(async (context: any) => {
        const doc = context.document;
        doc.load('saved');
        await context.sync();
        // 'saved' is true if no unsaved changes
        resolve(!doc.saved);
      }).catch(() => {
        // If we can't determine, assume no unsaved changes
        resolve(false);
      });
    } catch {
      resolve(false);
    }
  });
}

/**
 * Initialize Office.js if available
 * Returns true if Office is ready, false if not in Office context
 */
export async function initOffice(): Promise<boolean> {
  if (typeof Office === 'undefined') {
    console.log('[Office] Not in Office.js context');
    return false;
  }

  return new Promise((resolve) => {
    Office.onReady((info: any) => {
      console.log('[Office] Ready:', info.host, info.platform);
      resolve(true);
    });

    // Timeout after 3 seconds if Office doesn't initialize
    setTimeout(() => {
      console.log('[Office] Timeout waiting for Office.onReady');
      resolve(false);
    }, 3000);
  });
}

/**
 * Document metadata extracted from Word
 * Captures comprehensive proof-of-origin data
 */
export interface DocumentMetadata {
  // Basic document info
  filename: string;
  title: string;
  author?: string;

  // Source location
  sourceType: 'sharepoint' | 'onedrive' | 'local';
  url?: string;

  // Document statistics
  wordCount?: number;
  characterCount?: number;
  paragraphCount?: number;

  // Document properties (proof of origin)
  createdDate?: string;
  lastModifiedDate?: string;
  lastModifiedBy?: string;
  company?: string;
  subject?: string;
  keywords?: string;
  comments?: string;
  category?: string;
  template?: string;
  revisionNumber?: string;

  // Office environment (machine context)
  appVersion?: string;
  platform?: string;
  hostName?: string;
  contentLanguage?: string;
  displayLanguage?: string;

  // Document security
  isReadOnly?: boolean;
  hasUnsavedChanges?: boolean;
}

/**
 * Document content and metadata for creating a secret
 */
export interface DocumentCapture {
  metadata: DocumentMetadata;
  bytes: Uint8Array;
  hash: string;
  mimeType: string;
  capturedAt: number;
}

/**
 * Extract document bytes from Word
 */
export async function extractDocumentBytes(): Promise<Uint8Array> {
  if (!isOfficeContext()) {
    throw new Error('Not in Office.js context');
  }

  return new Promise((resolve, reject) => {
    Office.context.document.getFileAsync(
      Office.FileType.Compressed, // .docx format
      { sliceSize: 4 * 1024 * 1024 }, // 4MB slices
      async (result: any) => {
        if (result.status !== Office.AsyncResultStatus.Succeeded) {
          reject(new Error(result.error?.message || 'Failed to get file'));
          return;
        }

        const file = result.value;
        const sliceCount = file.sliceCount;
        const chunks: Uint8Array[] = [];

        try {
          // Read all slices
          for (let i = 0; i < sliceCount; i++) {
            const sliceData = await getSlice(file, i);
            chunks.push(new Uint8Array(sliceData));
          }

          // Concatenate all slices
          const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
          const bytes = new Uint8Array(totalLength);
          let offset = 0;
          for (const chunk of chunks) {
            bytes.set(chunk, offset);
            offset += chunk.length;
          }

          resolve(bytes);
        } catch (err) {
          reject(err);
        } finally {
          // CRITICAL: Always close the file
          file.closeAsync();
        }
      }
    );
  });
}

/**
 * Get a single slice from the file
 */
function getSlice(file: any, index: number): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    file.getSliceAsync(index, (result: any) => {
      if (result.status !== Office.AsyncResultStatus.Succeeded) {
        reject(new Error(result.error?.message || 'Failed to get slice'));
        return;
      }
      resolve(result.value.data);
    });
  });
}

/**
 * Extract comprehensive document metadata from Word
 * Captures all available proof-of-origin data
 */
export async function extractDocumentMetadata(): Promise<DocumentMetadata> {
  if (!isOfficeContext()) {
    throw new Error('Not in Office.js context');
  }

  return new Promise((resolve, reject) => {
    Word.run(async (context: any) => {
      try {
        const doc = context.document;
        const properties = doc.properties;
        const body = doc.body;

        // Load all available document properties
        properties.load([
          'title',
          'author',
          'subject',
          'keywords',
          'comments',
          'category',
          'template',
          'lastAuthor',
          'revisionNumber',
          'creationDate',
          'lastSaveTime',
          'company',
        ]);

        // Load body for text statistics
        body.load('text');

        await context.sync();

        // Calculate text statistics
        const text = body.text || '';
        const words = text.split(/\s+/).filter((w: string) => w.length > 0);
        const wordCount = words.length;
        const characterCount = text.replace(/\s/g, '').length;
        const paragraphCount = text.split(/\n\n+/).filter((p: string) => p.trim().length > 0).length;

        // Extract URL and determine source type
        const rawUrl = Office.context.document?.url || '';
        let sourceType: 'sharepoint' | 'onedrive' | 'local' = 'local';
        let url: string | undefined;

        const isValidHttpUrl = rawUrl.startsWith('http://') || rawUrl.startsWith('https://');
        if (isValidHttpUrl) {
          try {
            const parsed = new URL(rawUrl);
            url = parsed.href;
          } catch {
            url = rawUrl.replace(/ /g, '%20');
          }
        }

        if (rawUrl.includes('sharepoint.com')) {
          sourceType = 'sharepoint';
        } else if (rawUrl.includes('onedrive') || rawUrl.includes('1drv.ms')) {
          sourceType = 'onedrive';
        }

        // Extract filename from URL or use default
        const filename = rawUrl
          ? rawUrl.split('/').pop()?.split('?')[0] || 'Document.docx'
          : 'Document.docx';

        // Get Office environment info
        const diagnostics = Office.context.diagnostics;
        const appVersion = diagnostics?.version;
        const platform = diagnostics?.platform;
        const hostName = diagnostics?.host;

        // Get language settings
        const contentLanguage = Office.context.contentLanguage;
        const displayLanguage = Office.context.displayLanguage;

        // Format dates as ISO strings
        const formatDate = (date: any): string | undefined => {
          if (!date) return undefined;
          try {
            return new Date(date).toISOString();
          } catch {
            return String(date);
          }
        };

        resolve({
          // Basic info
          filename,
          title: properties.title || filename.replace(/\.[^.]+$/, ''),
          author: properties.author,

          // Source location
          sourceType,
          url,

          // Document statistics
          wordCount,
          characterCount,
          paragraphCount,

          // Document properties (proof of origin)
          createdDate: formatDate(properties.creationDate),
          lastModifiedDate: formatDate(properties.lastSaveTime),
          lastModifiedBy: properties.lastAuthor,
          company: properties.company,
          subject: properties.subject,
          keywords: properties.keywords,
          comments: properties.comments,
          category: properties.category,
          template: properties.template,
          revisionNumber: properties.revisionNumber ? String(properties.revisionNumber) : undefined,

          // Office environment
          appVersion,
          platform,
          hostName,
          contentLanguage,
          displayLanguage,

          // Document state - these require additional API calls
          // isReadOnly and hasUnsavedChanges could be added if needed
        });
      } catch (err) {
        reject(err);
      }
    });
  });
}

/**
 * Compute SHA-256 hash of content
 */
export async function computeHash(data: Uint8Array): Promise<string> {
  // Create a new ArrayBuffer to avoid SharedArrayBuffer type issues
  const buffer = new ArrayBuffer(data.length);
  new Uint8Array(buffer).set(data);
  const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Convert Uint8Array to base64 string
 */
export function bytesToBase64(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

/**
 * Capture the current Word document for creating a secret
 */
export async function captureDocument(): Promise<DocumentCapture> {
  console.log('[Office] Capturing document...');

  const [metadata, bytes] = await Promise.all([
    extractDocumentMetadata(),
    extractDocumentBytes(),
  ]);

  const hash = await computeHash(bytes);

  console.log('[Office] Document captured:', {
    filename: metadata.filename,
    title: metadata.title,
    sizeBytes: bytes.length,
    hash: hash.slice(0, 16) + '...',
    wordCount: metadata.wordCount,
  });

  return {
    metadata,
    bytes,
    hash,
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    capturedAt: Date.now(),
  };
}

/**
 * Build secret content JSON from document capture
 * This is the structure stored as the secret's encrypted content
 *
 * The content structure provides comprehensive proof-of-origin:
 * - Document identity (hash, filename, title)
 * - Authorship (author, lastModifiedBy)
 * - Temporal proof (createdDate, lastModifiedDate, capturedAt)
 * - Source location (sourceType, sourceUrl)
 * - Machine context (officeVersion, platform, hostName)
 * - Document statistics (wordCount, characterCount, paragraphCount)
 */
export function buildDocumentSecretContent(capture: DocumentCapture): string {
  const meta = capture.metadata;

  const content = {
    // Schema version
    type: 'word-document',
    version: '2.0',

    // Document identity
    filename: meta.filename,
    title: meta.title,
    mimeType: capture.mimeType,
    sizeBytes: capture.bytes.length,
    contentHash: `sha256:${capture.hash}`,

    // Authorship (proof of origin)
    author: meta.author,
    lastModifiedBy: meta.lastModifiedBy,
    company: meta.company,

    // Temporal proof
    createdDate: meta.createdDate,
    lastModifiedDate: meta.lastModifiedDate,
    capturedAt: new Date(capture.capturedAt).toISOString(),
    capturedAtMs: capture.capturedAt,

    // Source location
    sourceType: meta.sourceType,
    sourceUrl: meta.url,

    // Document metadata
    subject: meta.subject,
    keywords: meta.keywords,
    comments: meta.comments,
    category: meta.category,
    template: meta.template,
    revisionNumber: meta.revisionNumber,

    // Document statistics
    wordCount: meta.wordCount,
    characterCount: meta.characterCount,
    paragraphCount: meta.paragraphCount,

    // Machine context (environment attestation)
    environment: {
      officeVersion: meta.appVersion,
      platform: meta.platform,
      hostName: meta.hostName,
      contentLanguage: meta.contentLanguage,
      displayLanguage: meta.displayLanguage,
    },

    // Base64-encoded document binary
    data: bytesToBase64(capture.bytes),
  };

  return JSON.stringify(content, null, 2);
}

/**
 * Build a summary of the document for display (without the binary data)
 */
export function buildDocumentSummary(capture: DocumentCapture): Record<string, unknown> {
  const meta = capture.metadata;
  return {
    filename: meta.filename,
    title: meta.title,
    author: meta.author,
    sizeBytes: capture.bytes.length,
    sizeMB: (capture.bytes.length / (1024 * 1024)).toFixed(2),
    wordCount: meta.wordCount,
    contentHash: capture.hash.slice(0, 16) + '...',
    sourceType: meta.sourceType,
    createdDate: meta.createdDate,
    lastModifiedDate: meta.lastModifiedDate,
    capturedAt: new Date(capture.capturedAt).toISOString(),
  };
}
