/**
 * Rootz V6 Dashboard - Teams Tab
 *
 * Component module for team sharing and auto-send functionality.
 * Handles polling for invite-responses and auto-sending team-keys.
 *
 * ## Architecture
 *
 * This module follows the component pattern:
 * - @rootz/identity-provider → tabs/identity.ts
 * - @rootz/teams → tabs/teams.ts (this file)
 *
 * ## Public API
 *
 * - TeamsPollingManager: Manages polling for team messages
 * - startPolling(state, callback): Start polling every 30s
 * - stopPolling(): Stop polling
 *
 * ## Reusability
 *
 * The polling logic can be used independently of the UI.
 * Other implementations (desktop, agent) can import this manager.
 */

// ============================================================================
// Types
// ============================================================================

/**
 * Callback for when polling finds new messages
 */
export type OnPollCallback = () => Promise<void>;

/**
 * Polling manager state
 */
export interface TeamsPollingState {
  isPolling: boolean;
  intervalId: ReturnType<typeof setInterval> | null;
  lastPollTime: number | null;
  pollCount: number;
}

// ============================================================================
// TeamsPollingManager
// ============================================================================

/**
 * Manages periodic polling for team messages.
 *
 * Features:
 * - Polls every 30 seconds while active
 * - Automatically stops when tab is hidden
 * - Logs poll activity for debugging
 *
 * @example
 * ```typescript
 * const polling = new TeamsPollingManager();
 *
 * // Start polling
 * polling.start(async () => {
 *   await loadTeamStatus(state);
 * });
 *
 * // Stop when leaving tab
 * polling.stop();
 * ```
 */
export class TeamsPollingManager {
  private state: TeamsPollingState = {
    isPolling: false,
    intervalId: null,
    lastPollTime: null,
    pollCount: 0,
  };

  private callback: OnPollCallback | null = null;
  private readonly pollIntervalMs: number;

  /**
   * Create a new polling manager
   * @param pollIntervalMs - Polling interval in milliseconds (default: 30000)
   */
  constructor(pollIntervalMs = 30_000) {
    this.pollIntervalMs = pollIntervalMs;
  }

  /**
   * Start polling for team messages
   * @param callback - Function to call on each poll
   */
  start(callback: OnPollCallback): void {
    if (this.state.isPolling) {
      console.log('[TeamsPolling] Already polling, ignoring start()');
      return;
    }

    this.callback = callback;
    this.state.isPolling = true;
    this.state.pollCount = 0;

    console.log(`[TeamsPolling] Starting auto-poll (every ${this.pollIntervalMs / 1000}s)`);

    this.state.intervalId = setInterval(async () => {
      this.state.pollCount++;
      this.state.lastPollTime = Date.now();

      console.log(`[TeamsPolling] Poll #${this.state.pollCount} at ${new Date().toLocaleTimeString()}`);

      try {
        if (this.callback) {
          await this.callback();
        }
      } catch (error) {
        console.error('[TeamsPolling] Error during poll:', error);
      }
    }, this.pollIntervalMs);
  }

  /**
   * Stop polling
   */
  stop(): void {
    if (!this.state.isPolling) {
      return;
    }

    console.log(`[TeamsPolling] Stopping auto-poll (ran ${this.state.pollCount} times)`);

    if (this.state.intervalId) {
      clearInterval(this.state.intervalId);
      this.state.intervalId = null;
    }

    this.state.isPolling = false;
    this.callback = null;
  }

  /**
   * Check if currently polling
   */
  isActive(): boolean {
    return this.state.isPolling;
  }

  /**
   * Get polling statistics
   */
  getStats(): { isPolling: boolean; pollCount: number; lastPollTime: number | null } {
    return {
      isPolling: this.state.isPolling,
      pollCount: this.state.pollCount,
      lastPollTime: this.state.lastPollTime,
    };
  }

  /**
   * Force an immediate poll (in addition to scheduled ones)
   */
  async pollNow(): Promise<void> {
    if (this.callback) {
      console.log('[TeamsPolling] Manual poll triggered');
      this.state.pollCount++;
      this.state.lastPollTime = Date.now();
      await this.callback();
    }
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

/**
 * Global polling manager instance.
 * Use this for the dashboard's teams tab.
 */
export const teamsPolling = new TeamsPollingManager();

// ============================================================================
// Tab Visibility Handler
// ============================================================================

/**
 * Setup visibility-based polling control.
 * Automatically stops polling when tab is hidden, restarts when visible.
 *
 * @param onVisible - Callback when tab becomes visible
 * @param onHidden - Callback when tab becomes hidden
 * @returns Cleanup function
 */
export function setupVisibilityPolling(
  onVisible: () => void,
  onHidden: () => void
): () => void {
  const handleVisibilityChange = () => {
    if (document.hidden) {
      console.log('[TeamsPolling] Tab hidden, pausing');
      onHidden();
    } else {
      console.log('[TeamsPolling] Tab visible, resuming');
      onVisible();
    }
  };

  document.addEventListener('visibilitychange', handleVisibilityChange);

  return () => {
    document.removeEventListener('visibilitychange', handleVisibilityChange);
  };
}

// ============================================================================
// Pending Invite Storage
// ============================================================================

/**
 * Pending invite data stored in localStorage
 */
export interface PendingInvite {
  secretContract: string;
  secretName: string;
  keyVaultBlock: number;
  invitee: string;
  inviter: string;
  grantWrite: boolean;
  writeExpiresAt?: number;
  txHash: string;
  blockNumber: number;
  timestamp: number;
}

/**
 * Get the localStorage key for a pending invite
 */
export function getPendingInviteKey(secretContract: string, memberAddress: string): string {
  return `pending_invite_${secretContract.toLowerCase()}_${memberAddress.toLowerCase()}`;
}

/**
 * Store a pending invite in localStorage
 */
export function storePendingInvite(invite: PendingInvite): void {
  const key = getPendingInviteKey(invite.secretContract, invite.invitee);
  localStorage.setItem(key, JSON.stringify(invite));
  console.log(`[Teams] Stored pending invite: ${key}`);
}

/**
 * Get a pending invite from localStorage
 */
export function getPendingInvite(secretContract: string, memberAddress: string): PendingInvite | null {
  const key = getPendingInviteKey(secretContract, memberAddress);
  const json = localStorage.getItem(key);
  if (!json) return null;

  try {
    return JSON.parse(json) as PendingInvite;
  } catch {
    return null;
  }
}

/**
 * Remove a pending invite from localStorage
 */
export function removePendingInvite(secretContract: string, memberAddress: string): void {
  const key = getPendingInviteKey(secretContract, memberAddress);
  localStorage.removeItem(key);
  console.log(`[Teams] Removed pending invite: ${key}`);
}

/**
 * Get all pending invites from localStorage
 */
export function getAllPendingInvites(): PendingInvite[] {
  const invites: PendingInvite[] = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key?.startsWith('pending_invite_')) {
      const json = localStorage.getItem(key);
      if (json) {
        try {
          invites.push(JSON.parse(json) as PendingInvite);
        } catch {
          // Skip invalid entries
        }
      }
    }
  }
  return invites;
}
