/**
 * Agents Tab — Agent Dashboard
 *
 * Shows all AI agents, their status, MCP router connections,
 * policy state, and recent activity. The control center for
 * owner-managed AI agents.
 *
 * Data sources:
 *   - Sovereign Secrets with birth certificates (chain-reader)
 *   - Router connections and call log (McpProxy via API)
 *   - Settlement history (DataWritten events)
 *   - Agent TEE status (tee_status via MCP)
 */

import { formatAddress } from '../wallet';

const DESKTOP_API = 'http://localhost:3020';
const MCP_RELAY = 'http://localhost:3021';

export interface AgentsTabState {
  wallet: {
    address: string;
    signer: any;
  };
}

// ── API Helpers ─────────────────────────────────────────

async function callMcpTool(tool: string, args: Record<string, unknown> = {}): Promise<string> {
  try {
    const res = await fetch(MCP_RELAY + '/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: Date.now(),
        method: 'tools/call',
        params: { name: tool, arguments: args },
      }),
    });
    const text = await res.text();

    // Parse SSE or JSON
    for (const line of text.split('\n')) {
      if (line.startsWith('data:')) {
        try {
          const data = JSON.parse(line.slice(5));
          return data?.result?.content?.[0]?.text ?? '';
        } catch { /* skip */ }
      }
    }
    try {
      const data = JSON.parse(text);
      return data?.result?.content?.[0]?.text ?? text;
    } catch {
      return text;
    }
  } catch (err) {
    return `Error: ${(err as Error).message}`;
  }
}

// ── Render ──────────────────────────────────────────────

export function renderAgentsTab(_state: AgentsTabState): string {
  return `
    <div class="agents-tab">
      <div class="agents-header">
        <h2>AI Agents</h2>
        <p class="agents-subtitle">Your agents, connections, and activity</p>
        <div class="agents-actions">
          <button class="home-action-btn" id="agents-refresh-btn">Refresh</button>
        </div>
      </div>

      <!-- Agent List -->
      <div class="home-card" id="agents-list-card">
        <h3>Agents</h3>
        <div id="agents-list" class="agents-loading">Loading agents...</div>
      </div>

      <!-- MCP Router -->
      <div class="home-card" id="agents-router-card">
        <h3>MCP Router</h3>
        <div id="router-status" class="agents-loading">Loading router status...</div>
      </div>

      <!-- MCP Connections -->
      <div class="home-card" id="agents-connections-card">
        <h3>MCP Connections</h3>
        <div id="connections-list" class="agents-loading">Loading connections...</div>
        <div class="agents-actions" style="margin-top: 12px;">
          <button class="home-action-btn secondary" id="add-connection-btn">+ Add Connection</button>
        </div>
      </div>

      <!-- Recent Activity -->
      <div class="home-card" id="agents-activity-card">
        <h3>Recent Activity</h3>
        <div id="activity-log" class="agents-loading">Loading activity...</div>
      </div>
    </div>
  `;
}

// ── Setup ───────────────────────────────────────────────

export async function setupAgentsTab(_state: AgentsTabState): Promise<void> {
  // Load all sections
  await Promise.all([
    loadAgentList(),
    loadRouterStatus(),
    loadConnections(),
    loadActivity(),
  ]);

  // Wire refresh button
  const refreshBtn = document.getElementById('agents-refresh-btn');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', async () => {
      refreshBtn.textContent = 'Refreshing...';
      await Promise.all([
        loadAgentList(),
        loadRouterStatus(),
        loadConnections(),
        loadActivity(),
      ]);
      refreshBtn.textContent = 'Refresh';
    });
  }

  // Wire add connection button
  const addBtn = document.getElementById('add-connection-btn');
  if (addBtn) {
    addBtn.addEventListener('click', showAddConnectionDialog);
  }
}

// ── Load Agent List ─────────────────────────────────────

async function loadAgentList(): Promise<void> {
  const container = document.getElementById('agents-list');
  if (!container) return;

  try {
    // Check if morpheus-agent has status
    const morpheusStatus = await callMcpTool('morpheus_status');
    let morpheusData: any = null;
    try { morpheusData = JSON.parse(morpheusStatus); } catch { /* not JSON */ }

    // Check TEE status
    const teeStatus = await callMcpTool('tee_status', { verbose: false });
    let teeData: any = null;
    try { teeData = JSON.parse(teeStatus); } catch { /* not JSON */ }

    let html = '';

    // Morpheus agent
    if (morpheusData?.initialized) {
      html += renderAgentCard({
        name: 'Morpheus Agent',
        address: morpheusData.agentAddress,
        model: 'kimi-k2.5 (Morpheus)',
        sessions: morpheusData.sessionNotes || 0,
        tokens: morpheusData.totalTokens || 0,
        status: morpheusData.revoked ? 'revoked' : 'active',
        chainHeight: morpheusData.sessionNotes || 0,
        lastHash: morpheusData.lastNoteHash,
        skills: morpheusData.skills || [],
      });
    }

    // TEE agent
    if (teeData?.healthy) {
      html += renderAgentCard({
        name: 'Agent TEE',
        address: teeData.agentAddress,
        model: teeData.policyName || 'research-agent',
        sessions: 0,
        tokens: 0,
        status: teeData.chainAnchored ? 'active' : 'initializing',
        chainHeight: teeData.chainHeight || 0,
        lastHash: '',
        skills: Object.keys(teeData.skills || {}),
        extraInfo: `Policy: ${teeData.policyName} | Chain: ${teeData.chainHeight} blocks | Skills: ${teeData.skillCount || 0}`,
      });
    }

    if (!html) {
      html = '<div class="agents-empty">No agents running. Create one with morpheus_create_agent.</div>';
    }

    container.innerHTML = html;
  } catch (err) {
    container.innerHTML = `<div class="agents-error">Error loading agents: ${(err as Error).message}</div>`;
  }
}

function renderAgentCard(agent: {
  name: string;
  address: string;
  model: string;
  sessions: number;
  tokens: number;
  status: string;
  chainHeight: number;
  lastHash: string;
  skills: string[];
  extraInfo?: string;
}): string {
  const statusColor = agent.status === 'active' ? '#10b981' :
                      agent.status === 'revoked' ? '#ef4444' : '#f59e0b';
  const statusIcon = agent.status === 'active' ? '🟢' :
                     agent.status === 'revoked' ? '🔴' : '🟡';

  return `
    <div class="agent-card">
      <div class="agent-card-header">
        <span class="agent-status">${statusIcon}</span>
        <strong>${agent.name}</strong>
        <span class="agent-address mono" title="${agent.address}">${formatAddress(agent.address)}</span>
      </div>
      <div class="agent-card-body">
        <div class="agent-stat">Model: ${agent.model}</div>
        <div class="agent-stat">Chain: ${agent.chainHeight} entries</div>
        <div class="agent-stat">Tokens: ${agent.tokens.toLocaleString()}</div>
        ${agent.skills.length > 0 ? `<div class="agent-stat">Skills: ${agent.skills.join(', ')}</div>` : ''}
        ${agent.extraInfo ? `<div class="agent-stat">${agent.extraInfo}</div>` : ''}
        ${agent.lastHash ? `<div class="agent-stat mono" style="font-size: 0.75rem;">Last: ${agent.lastHash.slice(0, 20)}...</div>` : ''}
      </div>
    </div>
  `;
}

// ── Load Router Status ──────────────────────────────────

async function loadRouterStatus(): Promise<void> {
  const container = document.getElementById('router-status');
  if (!container) return;

  try {
    const statusText = await callMcpTool('proxy_status');
    let status: any = null;
    try { status = JSON.parse(statusText); } catch { /* not JSON */ }

    if (!status || !status.initialized) {
      container.innerHTML = `
        <div class="router-status-row">
          <span class="router-label">Status:</span>
          <span class="router-value">Not initialized (add a connection to start)</span>
        </div>
      `;
      return;
    }

    container.innerHTML = `
      <div class="router-status-grid">
        <div class="router-stat">
          <div class="router-stat-value">${status.connections}</div>
          <div class="router-stat-label">Connections</div>
        </div>
        <div class="router-stat">
          <div class="router-stat-value" style="color: ${status.healthyConnections === status.connections ? '#10b981' : '#f59e0b'}">${status.healthyConnections}</div>
          <div class="router-stat-label">Healthy</div>
        </div>
        <div class="router-stat">
          <div class="router-stat-value">${status.totalTools}</div>
          <div class="router-stat-label">Total Tools</div>
        </div>
        <div class="router-stat">
          <div class="router-stat-value" style="color: #10b981">${status.allowedTools}</div>
          <div class="router-stat-label">Allowed</div>
        </div>
        <div class="router-stat">
          <div class="router-stat-value">${status.callsThisSession}</div>
          <div class="router-stat-label">Calls Today</div>
        </div>
      </div>
    `;
  } catch (err) {
    container.innerHTML = `<div class="agents-error">Router error: ${(err as Error).message}</div>`;
  }
}

// ── Load Connections Inventory ───────────────────────────

async function loadConnections(): Promise<void> {
  const container = document.getElementById('connections-list');
  if (!container) return;

  try {
    const statusText = await callMcpTool('proxy_status');
    let status: any = null;
    try { status = JSON.parse(statusText); } catch { /* not JSON */ }

    if (!status?.initialized || status.connections === 0) {
      container.innerHTML = `
        <div class="agents-empty">No MCP connections. Click "+ Add Connection" to connect a service.</div>
      `;
      return;
    }

    // Get the tools list which includes connection info
    const toolsRes = await fetch(MCP_RELAY + '/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: 'tools/list', params: {} }),
    });
    const toolsText = await toolsRes.text();

    // Parse tools to group by connection
    const connections = new Map<string, { tools: string[]; descriptions: string[] }>();

    let toolsData: any = null;
    for (const line of toolsText.split('\n')) {
      if (line.startsWith('data:')) {
        try { toolsData = JSON.parse(line.slice(5)); } catch { /* skip */ }
      }
    }
    if (!toolsData) {
      try { toolsData = JSON.parse(toolsText); } catch { /* skip */ }
    }

    const tools = toolsData?.result?.tools ?? [];
    for (const tool of tools) {
      const match = tool.description?.match(/\(via (.+)\)$/);
      if (match) {
        const connId = match[1];
        if (!connections.has(connId)) {
          connections.set(connId, { tools: [], descriptions: [] });
        }
        const conn = connections.get(connId)!;
        conn.tools.push(tool.name);
        conn.descriptions.push(tool.description);
      }
    }

    if (connections.size === 0) {
      container.innerHTML = `
        <div class="agents-empty">${status.connections} connection(s) registered, tools pending discovery.</div>
      `;
      return;
    }

    let html = '';
    for (const [connId, conn] of connections) {
      html += `
        <div class="connection-card">
          <div class="connection-header">
            <span class="connection-status">🟢</span>
            <strong>${connId}</strong>
            <span class="connection-tools-count">${conn.tools.length} tools</span>
          </div>
          <div class="connection-tools">
            ${conn.tools.map(t => {
              const shortName = t.replace(`${connId}_`, '');
              const isConfirm = conn.descriptions[conn.tools.indexOf(t)]?.includes('REQUIRES CONFIRMATION');
              return `<span class="connection-tool ${isConfirm ? 'confirm' : ''}">${shortName}</span>`;
            }).join(' ')}
          </div>
        </div>
      `;
    }

    container.innerHTML = html;
  } catch (err) {
    container.innerHTML = `<div class="agents-error">Connections error: ${(err as Error).message}</div>`;
  }
}

// ── Load Activity ───────────────────────────────────────

async function loadActivity(): Promise<void> {
  const container = document.getElementById('activity-log');
  if (!container) return;

  // For now, show a placeholder. Full implementation will read from the call log.
  container.innerHTML = `
    <div class="activity-list">
      <div class="agents-empty">Activity log will show proxied calls, policy decisions, and settlements. Use the AI to interact with services through the router to see activity here.</div>
    </div>
  `;
}

// ── Add Connection Dialog ───────────────────────────────

function showAddConnectionDialog(): void {
  // Create a simple modal overlay
  const existing = document.getElementById('add-connection-modal');
  if (existing) existing.remove();

  const modal = document.createElement('div');
  modal.id = 'add-connection-modal';
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal-content" style="max-width: 500px;">
      <h3>Add MCP Connection</h3>
      <div class="modal-form">
        <label>Connection ID<input type="text" id="conn-id" placeholder="e.g., intuit-tax, morpheus, email" /></label>
        <label>Name<input type="text" id="conn-name" placeholder="e.g., Intuit Tax Service" /></label>
        <label>MCP Endpoint URL<input type="text" id="conn-url" placeholder="https://mcp.example.com" /></label>
        <label>Auth Token (optional)<input type="text" id="conn-token" placeholder="Bearer token or API key" /></label>
      </div>
      <div class="modal-actions">
        <button class="home-action-btn secondary" id="conn-cancel">Cancel</button>
        <button class="home-action-btn" id="conn-add">Add Connection</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  // Wire buttons
  document.getElementById('conn-cancel')?.addEventListener('click', () => modal.remove());
  document.getElementById('conn-add')?.addEventListener('click', async () => {
    const id = (document.getElementById('conn-id') as HTMLInputElement)?.value;
    const name = (document.getElementById('conn-name') as HTMLInputElement)?.value;
    const url = (document.getElementById('conn-url') as HTMLInputElement)?.value;
    const token = (document.getElementById('conn-token') as HTMLInputElement)?.value;

    if (!id || !name || !url) {
      alert('ID, Name, and URL are required');
      return;
    }

    const addBtn = document.getElementById('conn-add') as HTMLButtonElement;
    addBtn.textContent = 'Connecting...';
    addBtn.disabled = true;

    const args: any = { id, name, url };
    if (token) {
      args.authType = 'bearer';
      args.authToken = token;
    }

    const result = await callMcpTool('proxy_add_connection', args);
    modal.remove();

    // Refresh the connections and router status
    await loadConnections();
    await loadRouterStatus();
  });

  // Close on overlay click
  modal.addEventListener('click', (e) => {
    if (e.target === modal) modal.remove();
  });
}
