/**
 * @rootz/crypto - Utility Functions
 *
 * Hex conversion and validation utilities.
 */

/**
 * Convert ArrayBuffer to hex string.
 * @param buffer - ArrayBuffer or Uint8Array
 * @returns Hex string without 0x prefix
 */
export function arrayBufferToHex(buffer: ArrayBuffer | Uint8Array): string {
  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Convert hex string to Uint8Array.
 * @param hex - Hex string (with or without 0x prefix)
 * @returns Uint8Array
 */
export function hexToBytes(hex: string): Uint8Array {
  const cleanHex = hex.startsWith('0x') ? hex.slice(2) : hex;
  const bytes = new Uint8Array(cleanHex.length / 2);
  for (let i = 0; i < cleanHex.length; i += 2) {
    bytes[i / 2] = parseInt(cleanHex.substr(i, 2), 16);
  }
  return bytes;
}

/**
 * Convert Uint8Array to hex string with 0x prefix.
 * @param bytes - Uint8Array
 * @returns Hex string with 0x prefix
 */
export function bytesToHex(bytes: Uint8Array): string {
  return '0x' + arrayBufferToHex(bytes);
}

/**
 * Normalize hex string (add 0x prefix if missing).
 * @param hex - Hex string
 * @returns Hex string with 0x prefix
 */
export function normalizeHex(hex: string): string {
  return hex.startsWith('0x') ? hex : '0x' + hex;
}

/**
 * Strip 0x prefix from hex string.
 * @param hex - Hex string
 * @returns Hex string without 0x prefix
 */
export function stripHexPrefix(hex: string): string {
  return hex.startsWith('0x') ? hex.slice(2) : hex;
}

/**
 * Validate hex string length.
 * @param hex - Hex string
 * @param expectedBytes - Expected number of bytes
 * @throws Error if invalid
 */
export function validateHexLength(hex: string, expectedBytes: number): void {
  const clean = stripHexPrefix(hex);
  if (clean.length !== expectedBytes * 2) {
    throw new Error(
      `Invalid hex length: got ${clean.length / 2} bytes, expected ${expectedBytes} bytes`
    );
  }
}

/**
 * Validate that a string is valid hex.
 * @param hex - String to validate
 * @returns true if valid hex
 */
export function isValidHex(hex: string): boolean {
  const clean = stripHexPrefix(hex);
  return /^[0-9a-fA-F]*$/.test(clean) && clean.length % 2 === 0;
}

/**
 * Generate cryptographically secure random bytes.
 * Works in both Node.js and browser environments.
 * @param length - Number of bytes
 * @returns Uint8Array of random bytes
 */
export function randomBytes(length: number): Uint8Array {
  const bytes = new Uint8Array(length);

  // Use globalThis.crypto for both browser and Node.js 19+
  const cryptoObj = typeof globalThis !== 'undefined' ? globalThis.crypto :
                    typeof window !== 'undefined' ? window.crypto :
                    typeof self !== 'undefined' ? self.crypto : undefined;

  if (cryptoObj && cryptoObj.getRandomValues) {
    cryptoObj.getRandomValues(bytes);
    return bytes;
  }

  // For Node.js < 19, try to import webcrypto
  // Note: This won't work in browser but browser always has crypto
  throw new Error('No crypto.getRandomValues available. Use Node.js 19+ or a modern browser.');
}

/**
 * Get the global crypto object.
 * Works in both Node.js and browser environments.
 */
export function getCrypto(): Crypto {
  // Try globalThis first (works in both modern Node.js and browser)
  if (typeof globalThis !== 'undefined' && globalThis.crypto) {
    return globalThis.crypto;
  }

  // Browser fallback
  if (typeof window !== 'undefined' && window.crypto) {
    return window.crypto;
  }

  // Web Worker fallback
  if (typeof self !== 'undefined' && self.crypto) {
    return self.crypto;
  }

  throw new Error('No Web Crypto API available. Use Node.js 19+ or a modern browser.');
}
