/**
 * @rootz/crypto - RootzCrypto Provider
 *
 * Unified crypto provider that implements the CryptoProvider interface.
 * This is the main class for integrating with @rootz/secret-orchestrator.
 */

import type { Signer } from 'ethers';
import type {
  CryptoProvider,
  EncryptedData,
  VDNHash,
  MasterKeyPackage,
} from './types.js';
import { AES } from './aes.js';
import { MasterKey } from './master-key.js';

/**
 * RootzCrypto - Production crypto provider.
 *
 * Implements the CryptoProvider interface for @rootz/secret-orchestrator.
 * Uses real AES-256-GCM encryption and signature-based key derivation.
 *
 * @example
 * ```typescript
 * import { RootzCrypto } from '@rootz/crypto';
 * import { SecretOrchestrator } from '@rootz/secret-orchestrator';
 *
 * const crypto = new RootzCrypto();
 * const orchestrator = new SecretOrchestrator(config, crypto, factory);
 *
 * const result = await orchestrator.createSecret({
 *   name: 'My Secret',
 *   type: 'ai-context',
 *   content: 'Secret content...',
 * });
 * ```
 */
export class RootzCrypto implements CryptoProvider {
  /**
   * Generate a random 32-byte master key.
   *
   * @returns Hex-encoded key with 0x prefix
   */
  generateMasterKey(): string {
    return MasterKey.generate();
  }

  /**
   * Encrypt content with AES-256-GCM.
   *
   * @param content - Content to encrypt
   * @param key - Hex-encoded 32-byte key
   * @returns Encrypted data with IV
   */
  async encryptContent(content: string, key: string): Promise<EncryptedData> {
    return AES.encrypt(content, key);
  }

  /**
   * Decrypt content with AES-256-GCM.
   *
   * @param encrypted - Encrypted data
   * @param key - Hex-encoded 32-byte key
   * @returns Decrypted content
   */
  async decryptContent(encrypted: EncryptedData, key: string): Promise<string> {
    return AES.decrypt(encrypted, key);
  }

  /**
   * Encrypt IPFS hash (VDN pattern).
   *
   * @param ipfsHash - IPFS hash to encrypt
   * @param key - Master key
   * @returns VDN encrypted hash
   */
  async encryptIPFSHash(ipfsHash: string, key: string): Promise<VDNHash> {
    return AES.encryptIPFSHash(ipfsHash, key);
  }

  /**
   * Decrypt IPFS hash (VDN pattern).
   *
   * @param vdn - VDN encrypted hash
   * @param key - Master key
   * @returns Original IPFS hash
   */
  async decryptIPFSHash(vdn: VDNHash, key: string): Promise<string> {
    return AES.decryptIPFSHash(vdn, key);
  }

  /**
   * Encrypt master key for owner using signature-based key derivation.
   *
   * @param masterKey - Master key to encrypt
   * @param ownerAddress - Owner's address
   * @param signer - Signer for key derivation
   * @param metadata - Additional metadata
   * @returns Master key package
   */
  async encryptMasterKeyForOwner(
    masterKey: string,
    ownerAddress: string,
    signer: Signer,
    metadata: {
      secretName: string;
      secretType: string;
      contractAddress: string;
    }
  ): Promise<MasterKeyPackage> {
    return MasterKey.encryptForOwner(masterKey, ownerAddress, signer, metadata);
  }

  /**
   * Decrypt master key from package.
   *
   * @param package_ - Master key package
   * @param signer - Owner's signer
   * @returns Decrypted master key
   */
  async decryptMasterKeyForOwner(
    package_: MasterKeyPackage,
    signer: Signer
  ): Promise<string> {
    return MasterKey.decryptFromPackage(package_, signer);
  }
}
