// ============================================================================
// Manager Options
// ============================================================================

/**
 * ChainReader interface for reading chain data.
 * This allows dependency injection without requiring the full @rootz/chain-reader package.
 */
export interface ChainReaderInterface {
  getKeyVaultCreatedEvents(
    secretAddress: string,
    chainName: string
  ): Promise<Array<{
    blockNumber: number;
    creator: string;
    encryptedKeysData: string;
    schemaDefinition: string;
    timestamp: number;
    txHash: string;
  }>>;

  getDataWrittenEvents(
    secretAddress: string,
    chainName: string,
    kvBlock: number
  ): Promise<Array<{
    secretContract: string;
    writer: string;
    keyVaultBlock: number;
    data: string;
    creditsCost: number;
    timestamp: number;
    txHash: string;
    blockNumber: number;
  }>>;
}

/**
 * Database interface for local note storage.
 * Allows NoteManager to read from local cache instead of chain.
 */
export interface NotesDatabaseInterface {
  notes: {
    getByKeyVault(contract: string, kvBlock: number): Promise<Array<{
      noteId: string;
      secretContract: string;
      keyVaultBlock: number;
      content: string;
      encryptedData?: string;
      encryptedIv?: string;
      writeTxHash?: string;
      writeBlockNumber?: number;
      writerAddress?: string;
      timestamp?: number;
      isDecrypted: boolean;
    }>>;
    put(note: {
      noteId: string;
      chainId: number;
      secretContract: string;
      keyVaultBlock: number;
      title: string;
      content: string;
      contentType: 'text' | 'markdown' | 'json' | 'file';
      encryptedData?: string;
      encryptedIv?: string;
      writeTxHash?: string;
      writeBlockNumber?: number;
      writerAddress?: string;
      timestamp?: number;
      version: number;
      createdAt: number;
      updatedAt: number;
      accessedAt: number;
      accessCount: number;
      isDirty: boolean;
      isDeleted: boolean;
      isDecrypted: boolean;
    }): Promise<void>;
  };
}

/**
 * Options for NoteManager.
 */
export interface NoteManagerConfig {
  /** Chain configuration */
  chainId: number;

  /** Chain name (e.g., 'polygon', 'amoy') - required for ChainReader queries */
  chainName?: string;

  /** RPC URL */
  rpcUrl: string;

  /** ChainReader instance for querying chain data (recommended) */
  chainReader?: ChainReaderInterface;

  /** Database for local note cache (recommended) */
  database?: NotesDatabaseInterface;

  /** Static gas settings (used when dynamicGas is false) */
  gasSettings?: {
    maxFeePerGas?: bigint;
    maxPriorityFeePerGas?: bigint;
    gasLimit?: number;
  };

  /**
   * Enable dynamic gas pricing from network.
   * When true, fetches current base fee and applies tier multipliers.
   * Recommended for production (default: true).
   */
  dynamicGas?: boolean;

  /**
   * Gas tier for dynamic pricing.
   * - 'slow': base fee only (may get stuck)
   * - 'standard': 1.2x base fee (reliable)
   * - 'fast': 1.5x base fee (prioritized)
   * Default: 'standard'
   */
  gasTier?: 'slow' | 'standard' | 'fast';

  // ============================================================================
  // V7 Auto-Funding Configuration
  // ============================================================================

  /**
   * Registry contract address for V7 vault funding.
   * Required for auto-funding to work.
   */
  registryAddress?: string;

  /**
   * Enable automatic vault funding when balance is insufficient.
   * When true, NoteManager will automatically fund the vault before writes
   * if the vault balance is below zero (V7 requirement).
   * Default: true
   */
  autoFundEnabled?: boolean;

  /**
   * Amount of credits to add when auto-funding a vault.
   * User-configurable setting to control funding amounts.
   * Default: 25000 (25K credits)
   */
  autoFundAmount?: number;

  // ============================================================================
  // IPFS Configuration (for large content)
  // ============================================================================

  /**
   * IPFS configuration for storing large note content.
   * When content exceeds ipfsSizeThreshold, it's uploaded to IPFS
   * and only the CID reference is stored on-chain.
   *
   * This prevents "oversized data" transaction errors on Polygon
   * which has a ~131KB transaction limit.
   */
  ipfs?: {
    /** Pinata API key */
    apiKey: string;
    /** Pinata secret API key */
    secretKey: string;
    /** Optional custom endpoint (default: https://api.pinata.cloud) */
    endpoint?: string;
    /** Optional custom gateway (default: https://gateway.pinata.cloud) */
    gateway?: string;
  };

  /**
   * Size threshold in bytes for when to use IPFS instead of on-chain storage.
   * Content larger than this (after encryption) goes to IPFS.
   * Default: 100000 (100KB, safe margin below 131KB limit)
   */
  ipfsSizeThreshold?: number;
}

/**
 * Options for creating a KeyVault.
 */
export interface CreateKeyVaultOptions {
  /** Secret contract address */
  secretAddress: string;

  /** Master key (to encrypt KV key) */
  masterKey: Uint8Array;

  /** Optional schema (defaults to note schema v1.0.0) */
  schema?: KeyVaultSchema;
}

/**
 * KeyVault schema definition.
 */
export interface KeyVaultSchema {
  /** Schema type */
  type: 'note' | 'config' | 'custom';

  /** Schema version */
  version: string;

  /** Field definitions */
  fields: string[];

  /** Optional description */
  description?: string;
}

/**
 * Default note schema.
 */
export const DEFAULT_NOTE_SCHEMA: KeyVaultSchema = {
  type: 'note',
  version: '1.0.0',
  fields: ['content', 'author', 'timestamp', 'files', 'version', 'previousNote', 'metadata'],
  description: 'Standard encrypted note with optional file attachments',
};

/**
 * Write authorization for team members (delegated write access).
 * Uses PATH 2 (ECDSA) or PATH 3 (Identity/executeTransaction) authorization.
 *
 * ## Authorization Paths
 *
 * PATH 2 (ECDSA - EOA owner):
 *   v >= 27, r = sig.r, s = sig.s
 *   Single TX: writeData(kvBlock, data, expiresAt, v, r, s)
 *
 * PATH 3 (Identity contract owner):
 *   Device calls: identityContract.executeTransaction(secretAddr, 0, writeDataCalldata)
 *   IdentityContract (as owner) executes writeData with PATH 1 (v=0, r=0, s=0)
 */
export interface WriteAuthorization {
  /** ECDSA recovery parameter (27 or 28 for PATH 2, ignored for PATH 3) */
  v: number;
  /** ECDSA r component (32 bytes hex) - for PATH 2 */
  r: string;
  /** ECDSA s component (32 bytes hex) - for PATH 2 */
  s: string;
  /** Expiration timestamp (seconds since epoch) - for PATH 2 */
  expiresAt: number;

  // === Identity Mode Fields (PATH 3) ===

  /** Identity contract address for Identity mode (PATH 3) */
  identityContract?: string;

  /** Whether this authorization is for Identity mode (PATH 3) */
  isIdentityMode?: boolean;

  /** Authorized writer address (needed for hash verification in PATH 2) */
  authorizedWriter?: string;

  /** Secret contract address (needed for hash computation in PATH 2) */
  secretContract?: string;

  /** KeyVault block number (needed for hash computation in PATH 2) */
  keyVaultBlock?: number;
}

/**
 * Options for writing a note.
 */
export interface WriteNoteOptions {
  /** Secret contract address */
  secretAddress: string;

  /** KeyVault block number */
  kvBlock: number;

  /** Note content (can be empty for file-only notes) */
  content: string;

  /** KV key for encryption */
  kvKey: Uint8Array;

  /**
   * Optional file attachments (plaintext IPFS hashes).
   * IPFS hashes will be VDN-encrypted before storage.
   */
  files?: NoteFileInput[];

  /** Optional version string */
  version?: string;

  /** Optional reference to previous note */
  previousNote?: number;

  /** Optional metadata */
  metadata?: Record<string, unknown>;

  /**
   * Optional write authorization for team members.
   * If provided, uses PATH 2 (ECDSA pre-signed auth) instead of PATH 1 (direct owner).
   * Team members must have this authorization to write notes.
   */
  writeAuthorization?: WriteAuthorization;
}

/**
 * Result of writing a note.
 */
export interface WriteNoteResult {
  /** Transaction hash */
  txHash: string;

  /** Block number */
  blockNumber: number;

  /** Note index in KeyVault */
  noteIndex: number;

  /** Credits charged */
  creditsCharged: number;
}

/**
 * Options for reading notes.
 */
export interface ReadNotesOptions {
  /** Secret contract address */
  secretAddress: string;

  /** KeyVault block number */
  kvBlock: number;

  /** KV key for decryption */
  kvKey: Uint8Array;

  /** Starting index (default: 0) */
  fromIndex?: number;

  /** Number of notes to read (default: all) */
  count?: number;
}

// ============================================================================
// Credit Operations (V6.2)
// ============================================================================

/**
 * V6.2 Credit Constants.
 *
 * The contract enforces BOTH per-vault and per-owner credit limits.
 */
export const CREDIT_CONSTANTS = {
  /** Vault credit limit - vault balance can go down to this value */
  CREDIT_LIMIT_PER_VAULT: -1000n,

  /** Owner credit limit - balance can go down to this value */
  CREDIT_LIMIT_PER_OWNER: -10000n,

  /** Base cost per write operation */
  DATA_WRITE_BASE_COST: 10n,

  /** Cost per byte written */
  DATA_WRITE_PER_BYTE: 1n,

  /** Initial credits granted at secret creation */
  INITIAL_OWNER_CREDITS: 1000n,
};

/**
 * Result of checking write capability.
 * Used to pre-validate writes before sending transactions.
 */
export interface WriteCapabilityCheck {
  /** Whether the write can proceed */
  canWrite: boolean;

  /** Owner's current credit balance */
  ownerCredits: bigint;

  /** Owner's remaining capacity (credits until limit) */
  ownerRemaining: bigint;

  /** Estimated cost of the write */
  estimatedCost: bigint;

  /** KeyVault credit balance (informational only in V6.2) */
  vaultBalance: bigint;

  /** Human-readable reason if canWrite is false */
  reason?: string;
}

/**
 * Comprehensive credit status for display.
 * Returns all 3 balances + owner status + warnings.
 *
 * V7 Credit Model:
 * - Registry: User's global credits (can fund secrets/vaults)
 * - Owner: Per-secret credits (limit -10000)
 * - Vault: Per-KeyVault balance (team members blocked at -1000)
 */
export interface CreditStatus {
  /** User's global credits at Registry */
  registryBalance: bigint;

  /** Owner's credits for this secret */
  ownerCredits: bigint;

  /** Owner's remaining capacity (credits until -10000 limit) */
  ownerCapacity: bigint;

  /** Vault credit balance */
  vaultBalance: bigint;

  /** Vault remaining capacity for team members (until -1000 limit) */
  vaultCapacity: bigint;

  /** Whether vault is below -1000 (team members blocked) */
  vaultOverLimit: boolean;

  /** Whether the signer is the owner of this secret */
  isOwner: boolean;
}
