async function createNewIdentity(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Promise<void> {
  const createBtn = document.getElementById('create-identity-btn') as HTMLButtonElement;
  if (createBtn) {
    createBtn.disabled = true;
    createBtn.textContent = 'Creating...';
  }

  try {
    log('Step 1/2: Creating identity contract...');
    log('Sending transaction to factory...');

    const result = await manager.createIdentity();

    log(`Identity created!`);
    log(`Address: ${result.identityAddress}`);
    log(`TX: ${result.txHash}`);
    log(`Block: ${result.blockNumber}`);
    log(`First rivet: ${result.firstRivetAddress}`);

    // CRITICAL: Step 2 - Register our public key on the new identity
    // Without this, we cannot decrypt secrets created under this identity!
    log('');
    log('Step 2/2: Registering public key on identity contract...');

    const signingKey = new ethers.SigningKey(state.wallet.privateKey);
    const myPublicKey = signingKey.publicKey;

    const registerResult = await manager.registerPublicKey(result.identityAddress, myPublicKey);
    log(`✅ Public key registered!`);
    log(`TX: ${registerResult.txHash.slice(0, 14)}...`);

    // Add to multi-identity storage and set as active
    addIdentityContract(state.wallet.address, result.identityAddress);
    setActiveIdentity(state.wallet.address, result.identityAddress);
    log('Identity saved to localStorage (sync enabled)');

    log('');
    log('🎉 Identity fully configured! You can now create secrets.');

    // Refresh the view
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error: ${error.message}`);
    if (createBtn) {
      createBtn.disabled = false;
      createBtn.textContent = 'Create Identity Contract';
    }
  }
}

async function addNewRivet(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Promise<void> {
  const addressInput = document.getElementById('new-rivet-address') as HTMLInputElement;
  const nameInput = document.getElementById('new-rivet-name') as HTMLInputElement;
  const addBtn = document.getElementById('add-rivet-btn') as HTMLButtonElement;

  const rivetAddress = addressInput?.value?.trim();
  const rivetName = nameInput?.value?.trim() || 'New Device';

  if (!rivetAddress || !rivetAddress.startsWith('0x') || rivetAddress.length !== 42) {
    log('Error: Invalid device address (must be 0x + 40 hex chars)');
    return;
  }

  // Use ACTIVE identity from multi-identity system
  const identityAddress = getActiveIdentity(state.wallet.address);
  if (!identityAddress) {
    log('Error: No active identity contract found');
    return;
  }
  log(`Using active identity: ${identityAddress.slice(0, 10)}...`);

  if (addBtn) {
    addBtn.disabled = true;
    addBtn.textContent = 'Adding...';
  }

  try {
    // Step 1: Add device to identity contract
    log(`Step 1: Adding device "${rivetName}" to identity contract...`);

    const result = await manager.addRivet({
      identityAddress,
      rivetAddress,
      rivetName,
    });

    log(`✅ Device added to contract!`);
    log(`TX: ${result.txHash}`);
    log(`Block: ${result.blockNumber}`);

    // Step 2: Send invite TX to the new device
    log('');
    log(`Step 2: Sending invite notification to ${rivetAddress}...`);

    // Create the invite data
    const inviteId = `invite_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;
    const signingKey = new ethers.SigningKey(state.wallet.privateKey);
    const myPublicKey = signingKey.publicKey;

    const invite: DeviceInvite = {
      type: 'device-invite',
      version: '1.0.0',
      inviteId,
      identityContract: identityAddress,
      inviterAddress: state.wallet.address,
      inviterPublicKey: myPublicKey,
      inviterName: 'Primary Device',
      timestamp: Date.now(),
      expiresAt: Date.now() + 24 * 60 * 60 * 1000, // 24 hours
      chainId: state.config.network.chainId,
    };

    // Encode invite as TX data
    const inviteJson = JSON.stringify(invite);
    const txData = ethers.hexlify(ethers.toUtf8Bytes(inviteJson));

    // Get gas settings from GasProvider
    const signer = state.wallet.signer as ethers.Signer;
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gasSettings = await gasProvider.getTransactionGas('standard');

    log(`Gas: ${(Number(gasSettings.maxFeePerGas) / 1e9).toFixed(2)} Gwei max`);

    // Send 0-value TX to new device with invite data
    const inviteTx = await signer.sendTransaction({
      to: rivetAddress,
      data: txData,
      value: 0n,
      gasLimit: GAS_LIMITS.deviceInvite,
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
    });

    log(`Invite TX sent: ${inviteTx.hash}`);
    await inviteTx.wait();

    log('✅ Invite sent!');
    log('');
    log('The new device can now:');
    log('1. Scan for invites to see this identity');
    log('2. Load the identity contract address');
    log('3. Register their public key for key sharing');

    // Store pending invite
    pendingInvites.set(rivetAddress.toLowerCase(), invite);

    // Clear inputs
    if (addressInput) addressInput.value = '';
    if (nameInput) nameInput.value = '';

    // Refresh the view
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error: ${error.message}`);
  } finally {
    if (addBtn) {
      addBtn.disabled = false;
      addBtn.textContent = 'Add Device Manually';
    }
  }
}

async function removeRivet(
  identityAddress: string,
  rivetAddress: string,
  manager: IdentityManager,
  state: IdentityTabState,
  log: LogFunction
): Promise<void> {
  if (!confirm(`Are you sure you want to remove device ${rivetAddress.slice(0, 10)}...?`)) {
    return;
  }

  log(`Removing device ${rivetAddress.slice(0, 10)}...`);

  try {
    const result = await manager.removeRivet({
      identityAddress,
      rivetAddress,
    });

    log(`Device removed!`);
    log(`TX: ${result.txHash}`);

    // Refresh the view
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error: ${error.message}`);
  }
}

async function loadExistingIdentity(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Promise<void> {
  const addressInput = document.getElementById('load-identity-address') as HTMLInputElement;
  const loadBtn = document.getElementById('load-identity-btn') as HTMLButtonElement;

  const identityAddress = addressInput?.value?.trim();

  if (!identityAddress || !identityAddress.startsWith('0x') || identityAddress.length !== 42) {
    log('Error: Invalid identity address');
    return;
  }

  if (loadBtn) {
    loadBtn.disabled = true;
    loadBtn.textContent = 'Loading...';
  }

  try {
    log(`Loading identity ${identityAddress}...`);

    const info = await manager.getIdentityInfo(identityAddress);

    // Check if current wallet is a rivet
    const isRivet = info.rivets.some(r =>
      r.address.toLowerCase() === state.wallet.address.toLowerCase()
    );

    if (!isRivet) {
      log('Warning: Your wallet is NOT an authorized rivet for this identity');
      log('You can view but not manage this identity');
    } else {
      log('Your wallet IS an authorized rivet!');
    }

    // Add to multi-identity storage and set as active
    addIdentityContract(state.wallet.address, identityAddress);
    setActiveIdentity(state.wallet.address, identityAddress);
    if (isRivet) {
      log('Identity saved to localStorage (sync enabled)');
    } else {
      log('Identity saved to localStorage (sync NOT enabled - not a rivet)');
    }

    // Clear input
    if (addressInput) addressInput.value = '';

    // Refresh the view
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error: ${error.message}`);
    log('Make sure this is a valid IdentityContract address');
  } finally {
    if (loadBtn) {
      loadBtn.disabled = false;
      loadBtn.textContent = 'Load Identity';
    }
  }
}

