// Store pending invites locally (keyed by target address)
const pendingInvites: Map<string, DeviceInvite> = new Map();

/**
 * Send a device invite via blockchain transaction.
 * This function:
 * 1. Adds the target device as a rivet on the identity contract
 * 2. Sends an invite TX to the target with identity info
 */
async function sendDeviceInvite(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Promise<void> {
  const targetInput = document.getElementById('invite-target-address') as HTMLInputElement;
  const sendBtn = document.getElementById('send-invite-btn') as HTMLButtonElement;
  const statusDiv = document.getElementById('invite-sent-status');

  const targetAddress = targetInput?.value?.trim();

  if (!targetAddress || !targetAddress.startsWith('0x') || targetAddress.length !== 42) {
    log('Error: Invalid target address (must be 0x + 40 hex chars)');
    return;
  }

  // Use active identity (from selector) or fall back to stored identity
  const identityAddress = getActiveIdentity(state.wallet.address) ||
    localStorage.getItem(`identity_${state.wallet.address.toLowerCase()}`);
  if (!identityAddress) {
    log('Error: No identity contract found. Create one first.');
    return;
  }
  log(`Using Identity: ${identityAddress.slice(0, 12)}...`);

  if (sendBtn) {
    sendBtn.disabled = true;
    sendBtn.textContent = 'Adding device...';
  }

  try {
    // Step 1: Add the device as a rivet on the identity contract (if not already)
    log(`Step 1: Adding ${targetAddress.slice(0, 10)}... as a rivet on Identity contract...`);

    const rivetName = `Device ${targetAddress.slice(0, 8)}`;
    try {
      const addResult = await manager.addRivet({
        identityAddress,
        rivetAddress: targetAddress,
        rivetName,
      });
      log(`✅ Device added to contract!`);
      log(`TX: ${addResult.txHash}`);
    } catch (addError: any) {
      // Check if device is already a rivet - that's OK, continue with invite
      if (addError.message?.includes('already a rivet') || addError.message?.includes('already authorized')) {
        log(`ℹ️ Device is already a rivet - proceeding to send invite notification...`);
      } else {
        // Re-throw other errors
        throw addError;
      }
    }

    // Step 2: Send the invite notification
    if (sendBtn) {
      sendBtn.textContent = 'Sending invite...';
    }

    log(`Step 2: Sending invite notification to ${targetAddress.slice(0, 10)}...`);

    // Create the invite data
    const inviteId = `invite_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;
    const signingKey = new ethers.SigningKey(state.wallet.privateKey);
    const myPublicKey = signingKey.publicKey;

    const invite: DeviceInvite = {
      type: 'device-invite',
      version: '1.0.0',
      inviteId,
      identityContract: identityAddress,
      inviterAddress: state.wallet.address,
      inviterPublicKey: myPublicKey,
      inviterName: 'Primary Device',
      timestamp: Date.now(),
      expiresAt: Date.now() + 24 * 60 * 60 * 1000, // 24 hours
      chainId: state.config.network.chainId,
    };

    // Encode invite as TX data
    const inviteJson = JSON.stringify(invite);
    const txData = ethers.hexlify(ethers.toUtf8Bytes(inviteJson));

    // Get gas settings from GasProvider
    const signer = state.wallet.signer as ethers.Signer;
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gasSettings = await gasProvider.getTransactionGas('standard');

    log(`Gas: ${(Number(gasSettings.maxFeePerGas) / 1e9).toFixed(2)} Gwei max`);

    // Send 0-value TX to target with invite data
    const tx = await signer.sendTransaction({
      to: targetAddress,
      data: txData,
      value: 0n,
      gasLimit: GAS_LIMITS.deviceInvite,
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
    });

    log(`Invite TX sent: ${tx.hash}`);
    await tx.wait();

    log('✅ Invite sent successfully!');
    log('');
    log('The target device can now:');
    log('1. Scan for invites to see this identity');
    log('2. Accept the invite to load the identity');
    log('3. Register their public key for key sharing');

    // Store pending invite
    pendingInvites.set(targetAddress.toLowerCase(), invite);
    updatePendingInvitesUI(log);

    // Show status
    if (statusDiv) statusDiv.style.display = 'block';

    // Clear input
    if (targetInput) targetInput.value = '';

    // Refresh to show the new rivet
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error: ${error.message}`);
  } finally {
    if (sendBtn) {
      sendBtn.disabled = false;
      sendBtn.textContent = 'Send Invite';
    }
  }
}

// Store received invites for UI display
const receivedInvites: Map<string, DeviceInvite> = new Map();

/**
 * Scan blockchain for received invites (for device without identity).
 * Uses ChainReader to find incoming transactions with device-invite payloads.
 */
async function scanForReceivedInvites(
  state: IdentityTabState,
  log: LogFunction
): Promise<void> {
  const scanBtn = document.getElementById('scan-invites-btn') as HTMLButtonElement;
  const listDiv = document.getElementById('received-invites-list');

  if (scanBtn) {
    scanBtn.disabled = true;
    scanBtn.textContent = 'Scanning...';
  }

  try {
    log('Scanning blockchain for invites sent to this wallet...');

    // Determine which chain to scan based on network config
    const chainId = state.config.network.chainId;
    let chainConfig;

    if (chainId === 137) {
      chainConfig = KNOWN_CHAINS.polygon;
    } else if (chainId === 80002) {
      chainConfig = KNOWN_CHAINS.amoy;
    } else if (chainId === 81) {
      // Japan Open Chain
      chainConfig = {
        name: 'joc',
        chainId: 81,
        rpc: state.config.network.rpc,
        explorer: state.config.network.explorer,
      };
    } else {
      log(`⚠️ ChainReader not configured for chain ${chainId}`);
      log('Device invite scanning only works on Polygon (137), Amoy (80002), or JOC (81)');
      return;
    }

    // Get etherscan API key from config (it's at config level, not nested)
    const fullConfig = state.config as { etherscanApiKey?: string };
    const etherscanApiKey = fullConfig.etherscanApiKey || '';
    if (!etherscanApiKey) {
      log('⚠️ No Etherscan API key - scanning will be limited.');
      log('Add "etherscanApiKey" to config.json for full scanning.');
    }

    // Create ChainReader instance
    const reader = new ChainReader({
      chains: [chainConfig],
      wallets: [state.wallet.address],
      etherscanApiKey,
    });

    log(`Using ChainReader on ${chainConfig.name} (${chainId})`);
    log(`Scanning for messages to ${state.wallet.address.slice(0, 10)}...`);

    // Get all messages to this wallet
    const messages = await reader.getWalletMessages(0);

    log(`Found ${messages.length} total messages`);

    // Filter for device-invite messages
    const inviteMessages = messages.filter((msg: WalletMessage) => {
      const payload = msg.payload as { type?: string } | null;
      return payload?.type === 'device-invite';
    });

    log(`Found ${inviteMessages.length} device invite(s)`);

    // Clear old invites and add new ones
    receivedInvites.clear();

    for (const msg of inviteMessages) {
      const invite = msg.payload as unknown as DeviceInvite;
      receivedInvites.set(invite.inviteId, invite);

      log(`📧 Invite from ${invite.inviterAddress.slice(0, 10)}...`);
      log(`   Identity: ${invite.identityContract.slice(0, 10)}...`);
      log(`   TX: ${msg.txHash.slice(0, 10)}...`);
    }

    // Update UI
    updateReceivedInvitesUI(state, log);

  } catch (e) {
    const error = e as Error;
    log(`Error scanning: ${error.message}`);

    if (listDiv) {
      listDiv.innerHTML = `<p class="error">Error: ${error.message}</p>`;
    }
  } finally {
    if (scanBtn) {
      scanBtn.disabled = false;
      scanBtn.textContent = 'Scan for Invites';
    }
  }
}

/**
 * Update the received invites UI panel.
 */
function updateReceivedInvitesUI(state: IdentityTabState, log: LogFunction): void {
  const listDiv = document.getElementById('received-invites-list');
  if (!listDiv) return;

  if (receivedInvites.size === 0) {
    listDiv.innerHTML = '<p>No invites received</p>';
    return;
  }

  listDiv.innerHTML = Array.from(receivedInvites.values()).map(invite => {
    const isExpired = Date.now() > invite.expiresAt;
    const expiryText = isExpired
      ? '<span class="expired">Expired</span>'
      : `Expires: ${new Date(invite.expiresAt).toLocaleString()}`;

    return `
      <div class="received-invite-card ${isExpired ? 'expired' : ''}">
        <div><strong>From:</strong> ${invite.inviterAddress.slice(0, 10)}...${invite.inviterAddress.slice(-8)}</div>
        <div><strong>Identity:</strong> <code>${invite.identityContract}</code></div>
        <div><strong>Inviter:</strong> ${invite.inviterName || 'Unknown'}</div>
        <div><strong>Sent:</strong> ${new Date(invite.timestamp).toLocaleString()}</div>
        <div>${expiryText}</div>
        ${!isExpired ? `
          <button class="accept-invite-btn primary" data-invite-id="${invite.inviteId}">
            Accept & Load Identity
          </button>
        ` : ''}
      </div>
    `;
  }).join('');

  // Setup accept buttons
  const acceptButtons = listDiv.querySelectorAll('.accept-invite-btn');
  acceptButtons.forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const target = e.target as HTMLElement;
      const inviteId = target.getAttribute('data-invite-id');
      if (inviteId) {
        await acceptReceivedInvite(inviteId, state, log);
      }
    });
  });
}

/**
 * Accept a received device invite.
 * This automatically:
 * 1. Saves the identity contract to localStorage
 * 2. Caches the inviter's public key
 * 3. Sends our public key as invite-response
 * 4. Registers our public key on the identity contract
 */
async function acceptReceivedInvite(
  inviteId: string,
  state: IdentityTabState,
  log: LogFunction
): Promise<void> {
  const invite = receivedInvites.get(inviteId);
  if (!invite) {
    log('Error: Invite not found');
    return;
  }

  // Disable the accept button while processing
  const acceptBtn = document.querySelector(`[data-invite-id="${inviteId}"]`) as HTMLButtonElement;
  if (acceptBtn) {
    acceptBtn.disabled = true;
    acceptBtn.textContent = 'Processing...';
  }

  try {
    log(`Accepting invite from ${invite.inviterAddress.slice(0, 10)}...`);

    // Step 1: Add to multi-identity storage and set as active
    log(`Step 1/4: Saving identity contract...`);
    addIdentityContract(state.wallet.address, invite.identityContract);
    setActiveIdentity(state.wallet.address, invite.identityContract);
    log(`✅ Identity saved: ${invite.identityContract.slice(0, 12)}...`);

    // Step 2: Cache the inviter's public key for future ECDH
    log(`Step 2/4: Caching inviter's public key...`);
    localStorage.setItem(
      `pubkey_${invite.inviterAddress.toLowerCase()}`,
      invite.inviterPublicKey
    );
    log(`✅ Inviter's public key cached`);

    // Generate our public key
    const signingKey = new ethers.SigningKey(state.wallet.privateKey);
    const myPublicKey = signingKey.publicKey;

    // Step 3: Send our public key back to the inviter via Identity contract
    log(`Step 3/4: Sending public key response...`);

    const response = {
      type: 'invite-response',
      version: '1.0.0',
      inviteId: invite.inviteId,
      identityContract: invite.identityContract,
      responderAddress: state.wallet.address,
      responderPublicKey: myPublicKey,
      responderName: `Device ${state.wallet.address.slice(0, 8)}`,
      timestamp: Date.now(),
    };

    const responseJson = JSON.stringify(response);
    const txData = ethers.hexlify(ethers.toUtf8Bytes(responseJson));

    // Get gas settings from GasProvider
    const signer = state.wallet.signer as ethers.Signer;
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gasSettings = await gasProvider.getTransactionGas('standard');

    log(`Gas: ${(Number(gasSettings.maxFeePerGas) / 1e9).toFixed(2)} Gwei max`);

    const responseTx = await signer.sendTransaction({
      to: invite.identityContract,
      data: txData,
      value: 0n,
      gasLimit: GAS_LIMITS.inviteResponse,
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
    });

    await responseTx.wait();
    log(`✅ Public key response sent`);

    // Step 4: Register our public key on the identity contract
    log(`Step 4/4: Registering public key on identity contract...`);

    // Create IdentityManager with gas callback to register public key
    const gasProviderInstance = new GasProvider(state.wallet.provider as any);
    const identityManager = new IdentityManager({
      signer: state.wallet.signer as any,
      chainId: state.config.network.chainId,
      factoryAddress: state.config.contracts.identityFactory || undefined,
      getGasSettings: async () => gasProviderInstance.getTransactionGas('standard'),
    });

    const registerResult = await identityManager.registerPublicKey(invite.identityContract, myPublicKey);
    log(`✅ Public key registered on contract`);
    log(`TX: ${registerResult.txHash.slice(0, 14)}...`);

    log('');
    log('🎉 All done! Identity fully configured.');
    log('You can now receive encrypted secret keys from other devices.');

    // Remove from received invites
    receivedInvites.delete(inviteId);

    // Refresh the page to show the loaded identity
    refreshIdentityTab(state);

  } catch (e) {
    const error = e as Error;
    log(`Error accepting invite: ${error.message}`);
  }
}

/**
 * Check for responses to sent invites.
 */
async function checkForInviteResponses(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Promise<void> {
  const checkBtn = document.getElementById('check-responses-btn') as HTMLButtonElement;

  if (checkBtn) {
    checkBtn.disabled = true;
    checkBtn.textContent = 'Checking...';
  }

  try {
    log('Checking for invite responses...');

    if (pendingInvites.size === 0) {
      log('No pending invites to check.');
      return;
    }

    // For each pending invite, check if we received a response TX
    log(`Checking ${pendingInvites.size} pending invite(s)...`);
    log('Note: Full response detection requires ChainReader integration.');

    // Placeholder - real implementation would scan for TXs TO this address
    // with device-invite-response data
    for (const [targetAddr, invite] of pendingInvites) {
      log(`- Invite to ${targetAddr.slice(0, 10)}... (${invite.inviteId})`);
    }

    log('');
    log('For now, use Manual Add if you know the device responded.');

  } catch (e) {
    const error = e as Error;
    log(`Error checking responses: ${error.message}`);
  } finally {
    if (checkBtn) {
      checkBtn.disabled = false;
      checkBtn.textContent = 'Check for Responses';
    }
  }
}

function updatePendingInvitesUI(log: LogFunction): void {
  const pendingList = document.getElementById('pending-invites-list');
  if (!pendingList) return;

  if (pendingInvites.size === 0) {
    pendingList.innerHTML = '<p>No pending invites</p>';
    return;
  }

  pendingList.innerHTML = Array.from(pendingInvites.entries()).map(([addr, invite]) => `
    <div class="pending-invite-card">
      <div><strong>To:</strong> ${addr.slice(0, 10)}...${addr.slice(-8)}</div>
      <div><strong>Sent:</strong> ${new Date(invite.timestamp).toLocaleString()}</div>
      <div><strong>Expires:</strong> ${new Date(invite.expiresAt).toLocaleString()}</div>
      <p class="invite-status">Waiting for response...</p>
    </div>
  `).join('');
}

// ============================================================================
// Event Handlers
// ============================================================================

function setupEventHandlers(
  state: IdentityTabState,
  manager: IdentityManager,
  log: LogFunction
): Array<() => void> {
  const cleanupFns: Array<() => void> = [];

  // Identity selector dropdown (for multi-identity support)
  const identitySelector = document.getElementById('identity-selector') as HTMLSelectElement;
  if (identitySelector) {
    const handler = async () => {
      const selectedIdentity = identitySelector.value;
      log(`Switching to Identity: ${selectedIdentity.slice(0, 12)}...`);

      // Update active identity in storage
      setActiveIdentity(state.wallet.address, selectedIdentity);

      // Update sync service with all identities (active one used for operations)
      const allIdentities = getAllIdentityContracts(state.wallet.address);
      setIdentityContracts(allIdentities);

      // Show status
      const statusDiv = document.getElementById('identity-selector-status');
      if (statusDiv) {
        statusDiv.innerHTML = `<p class="success">Switched to ${selectedIdentity.slice(0, 10)}...${selectedIdentity.slice(-8)}</p>`;
        setTimeout(() => { statusDiv.innerHTML = ''; }, 3000);
      }

      // Refresh the entire tab to show the new identity's details
      await refreshIdentityTab(state);
    };
    identitySelector.addEventListener('change', handler);
    cleanupFns.push(() => identitySelector.removeEventListener('change', handler));
  }

  // Create identity button (shown when no identity exists)
  const createBtn = document.getElementById('create-identity-btn');
  if (createBtn) {
    const handler = () => createNewIdentity(state, manager, log);
    createBtn.addEventListener('click', handler);
    cleanupFns.push(() => createBtn.removeEventListener('click', handler));
  }

  // Create additional identity button (shown when user already has identity)
  const createAdditionalBtn = document.getElementById('create-additional-identity-btn');
  if (createAdditionalBtn) {
    const handler = () => createNewIdentity(state, manager, log);
    createAdditionalBtn.addEventListener('click', handler);
    cleanupFns.push(() => createAdditionalBtn.removeEventListener('click', handler));
  }

  // Add rivet button
  const addRivetBtn = document.getElementById('add-rivet-btn');
  if (addRivetBtn) {
    const handler = () => addNewRivet(state, manager, log);
    addRivetBtn.addEventListener('click', handler);
    cleanupFns.push(() => addRivetBtn.removeEventListener('click', handler));
  }

  // Load identity button
  const loadBtn = document.getElementById('load-identity-btn');
  if (loadBtn) {
    const handler = () => loadExistingIdentity(state, manager, log);
    loadBtn.addEventListener('click', handler);
    cleanupFns.push(() => loadBtn.removeEventListener('click', handler));
  }

  // Register public key button
  const registerPubKeyBtn = document.getElementById('register-pubkey-btn');
  if (registerPubKeyBtn) {
    const handler = async () => {
      // Use ACTIVE identity from multi-identity system, with fallback to first stored identity
      let identityAddress = getActiveIdentity(state.wallet.address);

      // Fallback: if no active identity, try to get first stored identity
      if (!identityAddress) {
        const allIdentities = getAllIdentityContracts(state.wallet.address);
        if (allIdentities.length > 0) {
          identityAddress = allIdentities[0];
          // Set it as active so future operations work
          setActiveIdentity(state.wallet.address, identityAddress);
          log(`No active identity set, using first stored: ${identityAddress.slice(0, 10)}...`);
        }
      }

      if (identityAddress) {
        log(`Registering on identity: ${identityAddress.slice(0, 10)}...`);
        await registerDevicePublicKey(identityAddress, manager, state, log);
      } else {
        log('Error: No identity contract found. Create or load one first.');
      }
    };
    registerPubKeyBtn.addEventListener('click', handler);
    cleanupFns.push(() => registerPubKeyBtn.removeEventListener('click', handler));
  }

  // Send invite button
  const sendInviteBtn = document.getElementById('send-invite-btn');
  if (sendInviteBtn) {
    const handler = () => sendDeviceInvite(state, manager, log);
    sendInviteBtn.addEventListener('click', handler);
    cleanupFns.push(() => sendInviteBtn.removeEventListener('click', handler));
  }

  // Scan for invites button
  const scanInvitesBtn = document.getElementById('scan-invites-btn');
  if (scanInvitesBtn) {
    const handler = () => scanForReceivedInvites(state, log);
    scanInvitesBtn.addEventListener('click', handler);
    cleanupFns.push(() => scanInvitesBtn.removeEventListener('click', handler));
  }

  // Check for responses button
  const checkResponsesBtn = document.getElementById('check-responses-btn');
  if (checkResponsesBtn) {
    const handler = () => checkForInviteResponses(state, manager, log);
    checkResponsesBtn.addEventListener('click', handler);
    cleanupFns.push(() => checkResponsesBtn.removeEventListener('click', handler));
  }

  return cleanupFns;
}

// ============================================================================
// Refresh Helper
// ============================================================================

/**
 * Refresh the identity tab by re-rendering and re-setting up handlers.
 * This is called after operations that change state (create, add, remove).
 */
async function refreshIdentityTab(state: IdentityTabState): Promise<void> {
  const content = document.getElementById('content');
  if (content) {
    content.innerHTML = renderIdentityTab(state);
    await setupIdentityTab(state);
  }
}

// ============================================================================
// Bootstrap Sync Functions
// ============================================================================

/**
 * Setup click handlers for the "Sync Keys" buttons on device cards.
 */
function setupSyncKeyButtons(
  identityAddress: string,
  state: IdentityTabState,
  log: LogFunction
): void {
  const syncButtons = document.querySelectorAll('.sync-keys-btn');
  syncButtons.forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const target = e.target as HTMLElement;
      const deviceAddress = target.getAttribute('data-device-address');
      const devicePubkey = target.getAttribute('data-device-pubkey');
      const deviceName = target.getAttribute('data-device-name') || 'Device';

      if (deviceAddress && devicePubkey) {
        await syncKeysToDevice(
          identityAddress,
          deviceAddress,
          devicePubkey,
          deviceName,
          state,
          log
        );
      }
    });
  });
}

/**
 * Sync all keys to a target device via Bootstrap Sync.
 * Creates an encrypted sync package and sends it to the Identity contract.
 */
async function syncKeysToDevice(
  identityAddress: string,
  targetDeviceAddress: string,
  targetDevicePublicKey: string,
  targetDeviceName: string,
  state: IdentityTabState,
  log: LogFunction
): Promise<void> {
  log(`Starting Bootstrap Sync to ${targetDeviceName} (${targetDeviceAddress.slice(0, 10)}...)`);

  // Find and disable the button
  const btn = document.querySelector(
    `.sync-keys-btn[data-device-address="${targetDeviceAddress}"]`
  ) as HTMLButtonElement;
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Syncing...';
  }

  try {
    // Step 1: Gather all keys from storage
    log('Step 1/3: Gathering keys from storage...');

    const ownedSecrets = await getOwnedSecrets();
    const sharedSecrets = await getSharedSecrets();

    log(`Found ${ownedSecrets.length} owned secrets, ${sharedSecrets.length} shared secrets`);

    // Step 2: Read master keys and create sync package
    log('Step 2/3: Creating encrypted sync package...');

    const keySharing = new KeySharing();
    const { privateKey: ephemeralPrivateKey, publicKey: ephemeralPublicKey } =
      keySharing.generateEphemeralKeyPair();

    // Gather owned secret keys (from fat package decryption in localStorage)
    const ownedSecretData: BootstrapSyncPackage['ownedSecrets'] = [];

    for (const secret of ownedSecrets) {
      // Try to get master key from localStorage (cached from fat package decryption)
      const keysDataStr = localStorage.getItem(`secret_keys_${secret.contractAddress.toLowerCase()}`);
      if (keysDataStr) {
        try {
          const keysData = JSON.parse(keysDataStr);
          if (keysData.masterKey) {
            // Encrypt for target device
            const encryptedJson = await keySharing.encryptWithEphemeralKey(
              keysData.masterKey,
              targetDevicePublicKey,
              ephemeralPrivateKey
            );
            ownedSecretData.push({
              secretContract: secret.contractAddress,
              secretName: secret.name,
              mintBlockNumber: secret.mintBlockNumber,
              keyVaultBlock: secret.keyVaultBlock || undefined,
              keyVaultName: secret.keyVaultName || undefined,
              encryptedMasterKey: JSON.parse(encryptedJson),
            });
            log(`  - Encrypted key for ${secret.name || secret.contractAddress.slice(0, 10)}...`);
          }
        } catch (e) {
          // Skip secrets we can't read
        }
      }
    }

    // Gather shared secret keys
    const teamShareData: BootstrapSyncPackage['teamShares'] = [];

    for (const secret of sharedSecrets) {
      const keysDataStr = localStorage.getItem(`secret_keys_${secret.contractAddress.toLowerCase()}`);
      if (keysDataStr) {
        try {
          const keysData = JSON.parse(keysDataStr);
          if (keysData.masterKey) {
            const encryptedJson = await keySharing.encryptWithEphemeralKey(
              keysData.masterKey,
              targetDevicePublicKey,
              ephemeralPrivateKey
            );
            teamShareData.push({
              secretContract: secret.contractAddress,
              secretName: secret.name,
              mintBlockNumber: secret.mintBlockNumber,
              keyVaultBlock: secret.keyVaultBlock || undefined,
              keyVaultName: secret.keyVaultName || undefined,
              ownerAddress: keysData.sharedBy || secret.ownerAddress,
              encryptedMasterKey: JSON.parse(encryptedJson),
              writeAuthorization: keysData.writeAuthorization || undefined,
            });
            log(`  - Encrypted shared key for ${secret.name || secret.contractAddress.slice(0, 10)}...`);
          }
        } catch (e) {
          // Skip secrets we can't read
        }
      }
    }

    const totalKeys = ownedSecretData.length + teamShareData.length;
    if (totalKeys === 0) {
      log('No keys found to sync. Make sure you have decrypted some secrets first.');
      return;
    }

    // Build the sync package
    const syncPackage: BootstrapSyncPackage = {
      type: 'bootstrap-sync',
      version: '1.0',
      identityContract: identityAddress,
      sourceDevice: state.wallet.address,
      targetDevice: targetDeviceAddress,
      ownedSecrets: ownedSecretData,
      teamShares: teamShareData,
      ephemeralPublicKey,
      timestamp: Date.now(),
    };

    log(`Sync package created: ${totalKeys} keys (${ownedSecretData.length} owned, ${teamShareData.length} shared)`);

    // Step 3: Send to Identity contract
    log('Step 3/3: Sending sync package to Identity contract...');

    const packageJson = JSON.stringify(syncPackage);
    const txData = ethers.hexlify(ethers.toUtf8Bytes(packageJson));

    const signer = state.wallet.signer as ethers.Signer;
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gasSettings = await gasProvider.getTransactionGas('standard');

    log(`Gas: ${(Number(gasSettings.maxFeePerGas) / 1e9).toFixed(2)} Gwei max`);

    // Send TX to Identity contract (will emit MessageReceived event)
    const tx = await signer.sendTransaction({
      to: identityAddress,
      data: txData,
      value: 0n,
      gasLimit: 500_000n,
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
    });

    log(`TX sent: ${tx.hash}`);
    await tx.wait();

    log(`✅ Bootstrap Sync complete!`);
    log(`${targetDeviceName} can now receive ${totalKeys} secret keys.`);
    log('');
    log('The target device should:');
    log('1. Go to Identity tab');
    log('2. Click "Scan for Sync Packages" (if available)');
    log('3. Keys will be automatically imported');

  } catch (e) {
    const error = e as Error;
    log(`Error during Bootstrap Sync: ${error.message}`);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = `Sync Keys to ${targetDeviceName}`;
    }
  }
}

