/**
 * @rootz/crypto - AES-256-GCM Implementation
 *
 * Provides symmetric encryption using AES-256-GCM.
 * This is the core encryption algorithm used throughout Rootz.
 */

import type { EncryptedData, VDNHash } from './types.js';
import {
  hexToBytes,
  bytesToHex,
  validateHexLength,
  randomBytes,
  getCrypto,
} from './utils.js';

/**
 * Convert Uint8Array to ArrayBuffer for Web Crypto API compatibility.
 * This handles the TypeScript strict typing issue with BufferSource.
 */
function toBuffer(arr: Uint8Array): ArrayBuffer {
  return arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength) as ArrayBuffer;
}

/**
 * AES encryption/decryption class.
 *
 * Uses AES-256-GCM with:
 * - 256-bit key (32 bytes)
 * - 96-bit IV (12 bytes)
 * - 128-bit authentication tag (16 bytes)
 */
export class AES {
  /**
   * Encrypt content with AES-256-GCM.
   *
   * @param content - Plain text content to encrypt
   * @param key - Hex-encoded 32-byte key (with or without 0x)
   * @returns Encrypted data with IV
   *
   * @example
   * ```typescript
   * const key = '0x' + '00'.repeat(32); // 32-byte key
   * const encrypted = await AES.encrypt('Hello World', key);
   * console.log(encrypted.encrypted); // Hex ciphertext
   * console.log(encrypted.iv); // Hex IV
   * ```
   */
  static async encrypt(content: string, key: string): Promise<EncryptedData> {
    const crypto = getCrypto();

    // Validate and convert key
    validateHexLength(key, 32);
    const keyBytes = hexToBytes(key);

    // Import AES key
    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt']
    );

    // Generate random IV (12 bytes for GCM)
    const iv = randomBytes(12);

    // Convert content to bytes
    const encoder = new TextEncoder();
    const contentBytes = encoder.encode(content);

    // Encrypt
    const ciphertext = await crypto.subtle.encrypt(
      {
        name: 'AES-GCM',
        iv: toBuffer(iv),
        tagLength: 128, // 16-byte auth tag
      },
      cryptoKey,
      toBuffer(contentBytes)
    );

    return {
      encrypted: bytesToHex(new Uint8Array(ciphertext)),
      iv: bytesToHex(iv),
      algorithm: 'AES-256-GCM',
    };
  }

  /**
   * Decrypt content with AES-256-GCM.
   *
   * @param encrypted - Encrypted data
   * @param key - Hex-encoded 32-byte key (with or without 0x)
   * @returns Decrypted plain text
   *
   * @example
   * ```typescript
   * const key = '0x' + '00'.repeat(32);
   * const encrypted = await AES.encrypt('Hello World', key);
   * const decrypted = await AES.decrypt(encrypted, key);
   * console.log(decrypted); // 'Hello World'
   * ```
   */
  static async decrypt(encrypted: EncryptedData, key: string): Promise<string> {
    const crypto = getCrypto();

    // Validate and convert key
    validateHexLength(key, 32);
    const keyBytes = hexToBytes(key);

    // Import AES key
    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    // Convert encrypted data and IV
    const ciphertext = hexToBytes(encrypted.encrypted);
    const iv = hexToBytes(encrypted.iv);

    // Decrypt
    const plaintext = await crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv: toBuffer(iv),
        tagLength: 128,
      },
      cryptoKey,
      toBuffer(ciphertext)
    );

    // Convert to string
    const decoder = new TextDecoder();
    return decoder.decode(plaintext);
  }

  /**
   * Encrypt IPFS hash with master key (VDN pattern).
   *
   * This hides the real IPFS location from blockchain analysis.
   * Only someone with the master key can discover where the data is stored.
   *
   * @param ipfsHash - IPFS hash (e.g., "QmXxx...")
   * @param masterKey - Hex-encoded master key
   * @returns VDN encrypted hash
   */
  static async encryptIPFSHash(
    ipfsHash: string,
    masterKey: string
  ): Promise<VDNHash> {
    const crypto = getCrypto();

    validateHexLength(masterKey, 32);
    const keyBytes = hexToBytes(masterKey);
    const iv = randomBytes(12);

    const encoder = new TextEncoder();
    const hashBytes = encoder.encode(ipfsHash);

    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt']
    );

    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      cryptoKey,
      toBuffer(hashBytes)
    );

    return {
      encrypted: bytesToHex(new Uint8Array(ciphertext)),
      iv: bytesToHex(iv),
      version: '5.0',
    };
  }

  /**
   * Decrypt IPFS hash from VDN encrypted data.
   *
   * @param vdn - VDN encrypted hash
   * @param masterKey - Hex-encoded master key
   * @returns Original IPFS hash
   */
  static async decryptIPFSHash(vdn: VDNHash, masterKey: string): Promise<string> {
    const crypto = getCrypto();

    validateHexLength(masterKey, 32);
    const keyBytes = hexToBytes(masterKey);
    const ciphertext = hexToBytes(vdn.encrypted);
    const iv = hexToBytes(vdn.iv);

    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    const plaintext = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      cryptoKey,
      toBuffer(ciphertext)
    );

    const decoder = new TextDecoder();
    return decoder.decode(plaintext);
  }

  /**
   * Encrypt raw bytes with AES-256-GCM.
   *
   * @param data - Data to encrypt (Uint8Array)
   * @param key - Hex-encoded 32-byte key
   * @returns Encrypted data with IV
   */
  static async encryptBytes(
    data: Uint8Array,
    key: string
  ): Promise<{ encrypted: Uint8Array; iv: Uint8Array }> {
    const crypto = getCrypto();

    validateHexLength(key, 32);
    const keyBytes = hexToBytes(key);
    const iv = randomBytes(12);

    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt']
    );

    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      cryptoKey,
      toBuffer(data)
    );

    return {
      encrypted: new Uint8Array(ciphertext),
      iv,
    };
  }

  /**
   * Decrypt raw bytes with AES-256-GCM.
   *
   * @param encrypted - Encrypted data
   * @param iv - IV used for encryption
   * @param key - Hex-encoded 32-byte key
   * @returns Decrypted data
   */
  static async decryptBytes(
    encrypted: Uint8Array,
    iv: Uint8Array,
    key: string
  ): Promise<Uint8Array> {
    const crypto = getCrypto();

    validateHexLength(key, 32);
    const keyBytes = hexToBytes(key);

    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      toBuffer(keyBytes),
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    const plaintext = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      cryptoKey,
      toBuffer(encrypted)
    );

    return new Uint8Array(plaintext);
  }

  /**
   * Derive AES key from arbitrary data using SHA-256.
   *
   * @param data - Data to derive key from
   * @returns 32-byte hex-encoded key
   */
  static async deriveKey(data: string | Uint8Array): Promise<string> {
    const crypto = getCrypto();

    const encoder = new TextEncoder();
    const dataBytes = typeof data === 'string' ? encoder.encode(data) : data;

    const hash = await crypto.subtle.digest('SHA-256', toBuffer(dataBytes));
    return bytesToHex(new Uint8Array(hash));
  }
}
