/**
 * Rootz V6 Dashboard - Create Secret Component
 *
 * UI component for creating new secrets using SecretOrchestrator.
 * Integrates with the 7-step creation process.
 *
 * ## Standard I/O Implementation
 *
 * This component is the **first I/O implementation** of the standard SecretInput
 * contract. It demonstrates how to:
 *
 * 1. Build a SecretInput object from user form data
 * 2. Add InputSource tracking for traceability
 * 3. Generate requestIds for correlation
 * 4. Handle SecretResult with type guards
 *
 * ### Input Flow
 * ```
 * User Form → buildSecretInput() → SecretInput → SecretOrchestrator → SecretResult
 * ```
 *
 * ### Source Tracking
 * All secrets created from this UI are tagged with:
 * ```json
 * {
 *   "source": {
 *     "type": "human",
 *     "platform": "rootz-dashboard",
 *     "version": "6.0.0",
 *     "sessionId": "browser-session-uuid"
 *   }
 * }
 * ```
 */

import { parseEther, JsonRpcProvider, Contract } from 'ethers';
import {
  // Crypto
  RootzCrypto,
  // Secret orchestrator
  SecretOrchestrator,
  OrchestrationError,
  DEFAULT_GAS_SETTINGS,
  isSecretSuccess,
  isSecretError,
  VERSION,
  // Identity
  IdentityManager,
  IDENTITY_CONTRACT_ABI,
  // Transaction Management
  TransactionManager,
  type TransactionPreview,
  type ClassifiedError,
  // Types
  type SecretType,
  type SecretInput,
  type SecretOutput,
  type SecretResult,
  type SecretErrorOutput,
  type InputSource,
  type StepProgress,
  type IdentityExecutor,
} from '@rootz/integration';
import { createFactoryContract, FactoryContractAdapter } from './factory-contract';
import { getStoredIdentityContract } from './storage';
import type { AppConfig } from './config';
import type { WalletState } from './wallet';
import { getCurrencySymbol } from './network-utils';

/**
 * Create secret configuration
 */
export interface CreateSecretConfig {
  config: AppConfig;
  wallet: WalletState;
  crypto: RootzCrypto;
  onSuccess?: (result: SecretOutput) => void;
  onError?: (error: Error) => void;
}

// ============================================================================
// Session & Request ID Management
// ============================================================================

/**
 * Browser session ID - persists for the browser session.
 * Used for source tracking in SecretInput.
 */
const SESSION_ID = (() => {
  // Check if we already have a session ID in sessionStorage
  const existing = sessionStorage.getItem('rootz-session-id');
  if (existing) return existing;

  // Generate a new UUID v4-like session ID
  const id = 'sess-' + crypto.randomUUID();
  sessionStorage.setItem('rootz-session-id', id);
  return id;
})();

/**
 * Generate a unique request ID for each secret creation.
 * Format: req-{timestamp}-{random}
 */
function generateRequestId(): string {
  const timestamp = Date.now().toString(36);
  const random = Math.random().toString(36).substring(2, 8);
  return `req-${timestamp}-${random}`;
}

/**
 * Build the standard InputSource for dashboard human input.
 */
function buildInputSource(): InputSource {
  return {
    type: 'human',
    platform: 'rootz-dashboard',
    version: VERSION,
    sessionId: SESSION_ID,
    capturedAt: Date.now(),
    extra: {
      userAgent: navigator.userAgent,
      screenWidth: window.innerWidth,
      screenHeight: window.innerHeight,
    },
  };
}

/**
 * Build a standard SecretInput from form data.
 *
 * This is the key function that transforms user form data into the
 * standard SecretInput contract that ANY input source should produce.
 *
 * @param formData - The form data from the user
 * @returns A fully populated SecretInput object
 */
function buildSecretInput(formData: {
  name: string;
  type: SecretType;
  content: string;
  tags?: string[];
  description?: string;
  isPublic?: boolean;
}): SecretInput {
  const input: SecretInput = {
    // Required fields
    name: formData.name.trim(),
    type: formData.type,
    content: formData.content,

    // Public publication mode
    isPublic: formData.isPublic || false,

    // Source tracking (recommended for all implementations)
    source: buildInputSource(),

    // Request ID for correlation
    requestId: generateRequestId(),

    // Optional fields
    tags: formData.tags && formData.tags.length > 0 ? formData.tags : undefined,
    description: formData.description?.trim() || undefined,
  };

  console.log('[CreateSecret] Built SecretInput:', {
    name: input.name,
    type: input.type,
    contentLength: input.content.length,
    isPublic: input.isPublic,
    source: input.source,
    requestId: input.requestId,
    tags: input.tags,
  });

  return input;
}

