/**
 * Set the owner mode for secret creation.
 * Used by document-secret.ts to sync owner mode selection.
 */
export function setOwnerMode(mode: 'LOCAL' | 'IDENTITY'): void {
  currentOwnerMode = mode;
  console.log('[CreateSecret] Owner mode set to:', mode);

  // Update the UI buttons if they exist
  const identityModeBtn = document.getElementById('identity-mode-btn');
  const localModeBtn = document.getElementById('local-mode-btn');

  if (identityModeBtn && localModeBtn) {
    if (mode === 'IDENTITY') {
      identityModeBtn.classList.add('active');
      localModeBtn.classList.remove('active');
    } else {
      localModeBtn.classList.add('active');
      identityModeBtn.classList.remove('active');
    }
  }
}

/**
 * Get the current owner mode.
 */
export function getOwnerMode(): 'LOCAL' | 'IDENTITY' {
  return currentOwnerMode;
}

/**
 * Gas price thresholds for alerts (in gwei)
 * Normal Polygon gas: 30-100 gwei
 */
const GAS_ALERT_THRESHOLDS = {
  WARNING: 200,   // Yellow warning: 2x normal
  CRITICAL: 500,  // Red alert: 5x+ normal
};

/**
 * Get the current network's native currency symbol
 */
function getCurrentSymbol(): string {
  if (!currentConfig) return 'ETH';
  return getCurrencySymbol(currentConfig.config.network.chainId);
}

/**
 * Format native currency value for display (removes excessive decimals)
 */
function formatNativeCurrency(value: string): string {
  const num = parseFloat(value);
  if (num < 0.0001) return '< 0.0001';
  if (num < 0.01) return num.toFixed(6);
  if (num < 1) return num.toFixed(4);
  return num.toFixed(3);
}

/**
 * Get gas alert level based on current gas price
 */
function getGasAlertLevel(baseFeeGwei: number): 'normal' | 'warning' | 'critical' {
  if (baseFeeGwei >= GAS_ALERT_THRESHOLDS.CRITICAL) return 'critical';
  if (baseFeeGwei >= GAS_ALERT_THRESHOLDS.WARNING) return 'warning';
  return 'normal';
}

/**
 * Render gas alert banner if gas is abnormally high
 */
function renderGasAlert(baseFeeGwei: number): string {
  const level = getGasAlertLevel(baseFeeGwei);

  if (level === 'normal') return '';

  const multiplier = Math.round(baseFeeGwei / 50); // Normal is ~50 gwei

  if (level === 'critical') {
    return `
      <div class="gas-alert gas-alert-critical">
        <span class="alert-icon">🚨</span>
        <div class="alert-content">
          <strong>NETWORK CONGESTION ALERT</strong>
          <p>Gas is ${multiplier}x higher than normal (${baseFeeGwei.toFixed(0)} gwei vs ~50 gwei typical).</p>
          <p>Consider waiting for gas prices to normalize before creating secrets.</p>
        </div>
      </div>
    `;
  }

  // Warning level
  return `
    <div class="gas-alert gas-alert-warning">
      <span class="alert-icon">⚠️</span>
      <div class="alert-content">
        <strong>High Gas Prices</strong>
        <p>Gas is ${multiplier}x higher than normal (${baseFeeGwei.toFixed(0)} gwei). You may want to wait.</p>
      </div>
    </div>
  `;
}

