/**
 * Setup form event handlers
 */
function setupCreateSecretForm(onCancel?: () => void): void {
  const form = document.getElementById('create-secret-form') as HTMLFormElement;
  const cancelBtn = document.getElementById('cancel-btn');

  if (form) {
    form.addEventListener('submit', handleCreateSecret);
  }

  if (cancelBtn && onCancel) {
    cancelBtn.addEventListener('click', onCancel);
  }

  // Setup input method toggle
  const textMethodBtn = document.getElementById('text-method-btn');
  const fileMethodBtn = document.getElementById('file-method-btn');
  const textInputSection = document.getElementById('text-input-section');
  const fileInputSection = document.getElementById('file-input-section');

  if (textMethodBtn && fileMethodBtn && textInputSection && fileInputSection) {
    textMethodBtn.addEventListener('click', () => {
      currentInputMethod = 'text';
      textMethodBtn.classList.add('active');
      fileMethodBtn.classList.remove('active');
      textInputSection.style.display = 'block';
      fileInputSection.style.display = 'none';
    });

    fileMethodBtn.addEventListener('click', () => {
      currentInputMethod = 'file';
      fileMethodBtn.classList.add('active');
      textMethodBtn.classList.remove('active');
      fileInputSection.style.display = 'block';
      textInputSection.style.display = 'none';
    });
  }

  // Setup file selection handler
  const fileInput = document.getElementById('secret-file') as HTMLInputElement;
  const filePreview = document.getElementById('file-preview');
  const filePreviewContent = document.getElementById('file-preview-content');

  if (fileInput && filePreview && filePreviewContent) {
    fileInput.addEventListener('change', (event) => {
      const file = (event.target as HTMLInputElement).files?.[0];
      if (!file) {
        currentFileContent = null;
        filePreview.style.display = 'none';
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        currentFileContent = e.target?.result as string;

        // Show preview (truncated if too long)
        const previewText = currentFileContent.length > 2000
          ? currentFileContent.substring(0, 2000) + '\n\n... (truncated for preview)'
          : currentFileContent;

        filePreviewContent.textContent = previewText;
        filePreview.style.display = 'block';
      };
      reader.readAsText(file);
    });
  }

  // Setup encryption mode toggle (encrypted vs public)
  const encryptedModeBtn = document.getElementById('encrypted-mode-btn');
  const publicModeBtn = document.getElementById('public-mode-btn');
  const encryptionModeInfo = document.getElementById('encryption-mode-info');

  if (encryptedModeBtn && publicModeBtn && encryptionModeInfo) {
    const updateEncryptionModeInfo = () => {
      const contentHint = document.getElementById('content-encryption-hint');
      const processInfo = document.getElementById('creation-process-info');
      const createBtn = document.getElementById('create-btn');

      if (currentEncryptionMode === 'public') {
        encryptionModeInfo.innerHTML = `
          <p class="mode-description" style="color: #f0ad4e;">
            <strong>Public Publication:</strong> Content is NOT encrypted.<br/>
            Publicly readable on IPFS. Signed by your wallet for authorship proof.<br/>
            SHA-256 content hash stored on-chain for integrity verification.
          </p>
        `;
        if (contentHint) contentHint.textContent = 'Content will be published in plaintext with SHA-256 integrity hash';
        if (createBtn) createBtn.textContent = 'Publish (Public)';
        if (processInfo) processInfo.innerHTML = `
          <h4>Publication Process (4 steps)</h4>
          <ol>
            <li>Deploy secret contract</li>
            <li>Prepare plaintext content + SHA-256 hash</li>
            <li>Upload plaintext to IPFS</li>
            <li>Store IPFS hash + content hash on blockchain</li>
          </ol>
        `;
      } else {
        encryptionModeInfo.innerHTML = `
          <p class="mode-description">
            <strong>Encrypted:</strong> Content encrypted with AES-256-GCM.<br/>
            Only authorized wallet holders can decrypt and read the content.
          </p>
        `;
        if (contentHint) contentHint.textContent = 'Your content will be encrypted with AES-256-GCM';
        if (createBtn) createBtn.textContent = 'Create Secret';
        if (processInfo) processInfo.innerHTML = `
          <h4>Creation Process (7 steps)</h4>
          <ol>
            <li>Generate master encryption key</li>
            <li>Deploy secret contract</li>
            <li>Encrypt content (AES-256-GCM)</li>
            <li>Upload to IPFS</li>
            <li>Encrypt IPFS hash (VDN)</li>
            <li>Encrypt master key for owner</li>
            <li>Store on blockchain (KeyVault)</li>
          </ol>
        `;
      }
    };

    encryptedModeBtn.addEventListener('click', () => {
      currentEncryptionMode = 'encrypted';
      encryptedModeBtn.classList.add('active');
      publicModeBtn.classList.remove('active');
      updateEncryptionModeInfo();
    });

    publicModeBtn.addEventListener('click', () => {
      currentEncryptionMode = 'public';
      publicModeBtn.classList.add('active');
      encryptedModeBtn.classList.remove('active');
      updateEncryptionModeInfo();
    });
  }

  // Setup owner mode toggle (if identity is available)
  const identityModeBtn = document.getElementById('identity-mode-btn');
  const localModeBtn = document.getElementById('local-mode-btn');
  const ownerModeInfo = document.getElementById('owner-mode-info');

  if (identityModeBtn && localModeBtn && ownerModeInfo) {
    const updateOwnerModeInfo = () => {
      if (!currentConfig) return;
      const identityContract = getStoredIdentityContract(currentConfig.wallet.address);

      if (currentOwnerMode === 'IDENTITY') {
        ownerModeInfo.innerHTML = `
          <p class="mode-description">
            <strong>Identity Mode:</strong> Secret owned by your identity contract.<br/>
            <code style="font-size: 0.8rem;">${identityContract?.slice(0, 18)}...</code><br/>
            All devices in your identity can access this secret.
          </p>
        `;
      } else {
        ownerModeInfo.innerHTML = `
          <p class="mode-description">
            <strong>Local Mode:</strong> Secret owned by this device wallet only.<br/>
            <code style="font-size: 0.8rem;">${currentConfig.wallet.address.slice(0, 18)}...</code><br/>
            Other devices cannot access this secret.
          </p>
        `;
      }
    };

    identityModeBtn.addEventListener('click', () => {
      currentOwnerMode = 'IDENTITY';
      identityModeBtn.classList.add('active');
      localModeBtn.classList.remove('active');
      updateOwnerModeInfo();
    });

    localModeBtn.addEventListener('click', () => {
      currentOwnerMode = 'LOCAL';
      localModeBtn.classList.add('active');
      identityModeBtn.classList.remove('active');
      updateOwnerModeInfo();
    });
  }

  // Reset state
  currentFileContent = null;
  currentInputMethod = 'text';
  currentEncryptionMode = 'encrypted';

  // Trigger initial gas preview (async, won't block form)
  updateGasPreview().catch(e => console.warn('[CreateSecret] Initial gas preview failed:', e));
}

/**
 * Handle form submission.
 *
 * This demonstrates the standard I/O flow:
 * 1. Extract form data
 * 2. Build SecretInput using buildSecretInput()
 * 3. Pass to orchestrator
 * 4. Handle SecretResult using type guards
 */
async function handleCreateSecret(event: Event): Promise<void> {
  event.preventDefault();

  if (isCreating || !currentConfig) {
    return;
  }

  const form = event.target as HTMLFormElement;
  const formData = new FormData(form);

  // Extract form values
  const name = formData.get('name') as string;
  const type = formData.get('type') as SecretType;
  const description = formData.get('description') as string;
  const tagsStr = formData.get('tags') as string;

  // Get content based on input method
  let content: string;
  if (currentInputMethod === 'file') {
    if (!currentFileContent) {
      showError('Please select a file');
      return;
    }
    content = currentFileContent;
  } else {
    content = formData.get('content') as string;
  }

  // Parse tags
  const tags = tagsStr
    .split(',')
    .map(t => t.trim())
    .filter(t => t.length > 0);

  // Validate required fields
  if (!name || !content) {
    showError('Please fill in all required fields');
    return;
  }

  // Check balance
  const balance = parseFloat(currentConfig.wallet.balance);
  if (balance < 0.02) {
    const symbol = getCurrentSymbol();
    showError(`Insufficient balance. You need at least 0.02 ${symbol}, but have ${balance.toFixed(4)} ${symbol}`);
    return;
  }

  // =========================================================================
  // Build Standard SecretInput
  // =========================================================================
  // This is the key step - transform user form data into the standard contract
  const secretInput = buildSecretInput({
    name,
    type,
    content,
    description: description || undefined,
    tags: tags.length > 0 ? tags : undefined,
    isPublic: currentEncryptionMode === 'public',
  });

  // Start creation
  isCreating = true;
  showProgress();
  disableForm(true);

  try {
    // =========================================================================
    // Execute Orchestrator
    // =========================================================================
    const result = await createSecret(secretInput);

    // =========================================================================
    // Handle Success
    // =========================================================================
    console.log('[CreateSecret] Success:', {
      contractAddress: result.contractAddress,
      requestId: result.input?.requestId,
      source: result.input?.source,
      timing: result.timing,
    });

    showSuccess(result);

    // Dispatch event for programmatic listeners (e.g., document-secret)
    document.dispatchEvent(new CustomEvent('secret-created', {
      detail: { address: result.contractAddress }
    }));

    // Await the callback to ensure sync completes before tab switch
    await currentConfig.onSuccess?.(result);

  } catch (error) {
    // =========================================================================
    // Handle Error
    // =========================================================================
    console.error('[CreateSecret] Error:', error);

    if (error instanceof OrchestrationError) {
      showError(`Failed at step "${error.step}": ${error.message}`);
      if (error.partialResult) {
        console.log('[CreateSecret] Partial result (contract may exist):', {
          contractAddress: error.partialResult.contractAddress,
          transactions: error.partialResult.transactions,
        });
      }
    } else {
      showError(error instanceof Error ? error.message : 'Unknown error');
    }

    // Dispatch event for programmatic listeners (e.g., document-secret)
    document.dispatchEvent(new CustomEvent('secret-error', {
      detail: { message: error instanceof Error ? error.message : String(error) }
    }));

    currentConfig.onError?.(error instanceof Error ? error : new Error(String(error)));

  } finally {
    isCreating = false;
    disableForm(false);
  }
}

/**
 * Create a secret using the orchestrator
 */
async function createSecret(input: SecretInput): Promise<SecretOutput> {
  if (!currentConfig) {
    throw new Error('Configuration not set');
  }

  const { config, wallet, crypto } = currentConfig;

  // Create factory contract adapter with gas config
  const factory = createFactoryContract(
    config.contracts.factory!,
    wallet.provider,
    wallet.signer as any, // RootzSigner extends Signer
    config.gas
  );

  // Build owner config
  const ownerConfig = buildOwnerConfig(wallet.address, wallet.publicKey);

  // Query Factory and Registry diagnostics
  try {
    const factoryContract = new Contract(
      config.contracts.factory!,
      [
        'function factoryVersion() view returns (string)',
        'function operationsVersion() view returns (string)',
        'function isActive() view returns (bool)',
        'function creditCheckEnabled() view returns (bool)',
        'function getUserNonce(address) view returns (uint256)',
        'function rateTable() view returns (address)',
        'function registry() view returns (address)',
      ],
      wallet.provider
    );
    const registryContract = new Contract(
      config.contracts.registry!,
      [
        'function authorizedFactories(address) view returns (bool)',
        'function getUserCredits(address) view returns (uint256)',
      ],
      wallet.provider
    );

    const [factoryVersion, opsVersion, isActive, creditCheckEnabled, userNonce, factoryRateTable, factoryRegistry, isFactoryAuthorized, userCredits] = await Promise.all([
      factoryContract.factoryVersion().catch(() => 'unknown'),
      factoryContract.operationsVersion().catch(() => 'unknown'),
      factoryContract.isActive().catch(() => 'unknown'),
      factoryContract.creditCheckEnabled().catch(() => 'unknown'),
      factoryContract.getUserNonce(wallet.address).catch(() => 'unknown'),
      factoryContract.rateTable().catch(() => 'unknown'),
      factoryContract.registry().catch(() => 'unknown'),
      registryContract.authorizedFactories(config.contracts.factory!).catch(() => 'unknown'),
      registryContract.getUserCredits(wallet.address).catch(() => 'unknown'),
    ]);
    console.log(`[CreateSecret] Factory version: ${factoryVersion}, Operations: ${opsVersion}`);
    console.log(`[CreateSecret] Factory address: ${config.contracts.factory}`);
    console.log(`[CreateSecret] Factory isActive: ${isActive}`);
    console.log(`[CreateSecret] Factory creditCheckEnabled: ${creditCheckEnabled}`);
    console.log(`[CreateSecret] User nonce: ${userNonce}`);
    console.log(`[CreateSecret] Factory internal rateTable: ${factoryRateTable}`);
    console.log(`[CreateSecret] Factory internal registry: ${factoryRegistry}`);
    console.log(`[CreateSecret] Config rateTable: ${config.contracts.rateTable}`);
    console.log(`[CreateSecret] Config registry: ${config.contracts.registry}`);
    console.log(`[CreateSecret] Factory authorized in Registry: ${isFactoryAuthorized}`);
    console.log(`[CreateSecret] User credits: ${userCredits}`);

    // Check for address mismatches
    if (factoryRateTable !== 'unknown' && factoryRateTable.toLowerCase() !== config.contracts.rateTable?.toLowerCase()) {
      console.error('[CreateSecret] ⚠️ CRITICAL: Factory rateTable mismatch!');
      console.error(`[CreateSecret]   Factory uses: ${factoryRateTable}`);
      console.error(`[CreateSecret]   Config has: ${config.contracts.rateTable}`);
    }
    if (factoryRegistry !== 'unknown' && factoryRegistry.toLowerCase() !== config.contracts.registry?.toLowerCase()) {
      console.error('[CreateSecret] ⚠️ CRITICAL: Factory registry mismatch!');
      console.error(`[CreateSecret]   Factory uses: ${factoryRegistry}`);
      console.error(`[CreateSecret]   Config has: ${config.contracts.registry}`);
    }

    // CRITICAL CHECK: Factory must be authorized to spend credits
    if (isFactoryAuthorized === false) {
      console.error('[CreateSecret] ⚠️ CRITICAL: Factory is NOT authorized in Registry! spendCredits will fail.');
      console.error('[CreateSecret] The Registry owner must call authorizeFactory() to fix this.');
    }

    // Query rate table costs - the Factory reads these when deploying
    const rateTableContract = new Contract(
      config.contracts.rateTable!,
      ['function getCost(string) view returns (uint256)'],
      wallet.provider
    );
    const [createSecretCost, keyVaultCreationCost, writeDataBaseCost, writeDataPerByteCost, initialSecretCreditsCost] = await Promise.all([
      rateTableContract.getCost('createSecret').catch((e: Error) => `ERROR: ${e.message?.slice(0, 50)}`),
      rateTableContract.getCost('keyVaultCreation').catch((e: Error) => `ERROR: ${e.message?.slice(0, 50)}`),
      rateTableContract.getCost('writeDataBase').catch((e: Error) => `ERROR: ${e.message?.slice(0, 50)}`),
      rateTableContract.getCost('writeDataPerByte').catch((e: Error) => `ERROR: ${e.message?.slice(0, 50)}`),
      rateTableContract.getCost('initialSecretCredits').catch((e: Error) => `ERROR: ${e.message?.slice(0, 50)}`),
    ]);
    console.log('[CreateSecret] RateTable costs:');
    console.log(`  - createSecret: ${createSecretCost}`);
    console.log(`  - keyVaultCreation: ${keyVaultCreationCost}`);
    console.log(`  - writeDataBase: ${writeDataBaseCost}`);
    console.log(`  - writeDataPerByte: ${writeDataPerByteCost}`);
    console.log(`  - initialSecretCredits: ${initialSecretCreditsCost}`);

    if (typeof initialSecretCreditsCost === 'string' && initialSecretCreditsCost.startsWith('ERROR')) {
      console.error('[CreateSecret] ⚠️ CRITICAL: initialSecretCredits not defined in RateTable!');
      console.error('[CreateSecret] The Factory will fail when deploying secrets. RateTable needs setCost("initialSecretCredits", value).');
    }

    // =========================================================================
    // CRITICAL CHECK: Verify user has sufficient credits BEFORE attempting tx
    // =========================================================================
    if (typeof userCredits === 'bigint' && typeof createSecretCost === 'bigint') {
      if (userCredits < createSecretCost) {
        const creditsNeeded = createSecretCost - userCredits;
        const errorMessage = `Insufficient credits to create a secret.\n\n` +
          `You have: ${userCredits.toLocaleString()} credits\n` +
          `Required: ${createSecretCost.toLocaleString()} credits\n` +
          `Shortfall: ${creditsNeeded.toLocaleString()} credits\n\n` +
          `Please purchase more credits to continue.`;
        console.error('[CreateSecret] Insufficient credits:', {
          available: userCredits.toString(),
          required: createSecretCost.toString(),
          shortfall: creditsNeeded.toString(),
        });
        throw new Error(errorMessage);
      }
      console.log(`[CreateSecret] Credits check passed: ${userCredits} >= ${createSecretCost}`);
    }
  } catch (e) {
    // Re-throw credit errors with friendly message
    if (e instanceof Error && e.message.includes('Insufficient credits')) {
      throw e;
    }
    console.log('[CreateSecret] Could not query diagnostics:', e);
  }

  // Create identity executor for IDENTITY mode
  let identityExecutor: IdentityExecutor | undefined;
  if (ownerConfig.mode === 'IDENTITY' && ownerConfig.identityContract) {
    console.log('[CreateSecret] Creating IdentityExecutor for IDENTITY mode');
    const identityManager = new IdentityManager({
      provider: wallet.provider as JsonRpcProvider,
      signer: wallet.signer as any,
    });

    // Verify device is registered as rivet on the Identity contract
    try {
      const identityInfo = await identityManager.getIdentityInfo(ownerConfig.identityContract);
      console.log('[CreateSecret] Identity info:', {
        address: identityInfo.address,
        rivetCount: identityInfo.rivetCount,
        rivets: identityInfo.rivets.map(r => r.address),
        balance: identityInfo.balance?.toString(),
      });

      const isDeviceRegistered = identityInfo.rivets.some(
        r => r.address.toLowerCase() === wallet.address.toLowerCase() && r.active
      );
      console.log(`[CreateSecret] Device ${wallet.address} is registered: ${isDeviceRegistered}`);

      if (!isDeviceRegistered) {
        throw new Error(`Device ${wallet.address} is not registered as a rivet on Identity ${ownerConfig.identityContract}`);
      }

      // CRITICAL: Also verify the device has its PUBLIC KEY registered on this Identity
      // Without a public key, the encrypted master key cannot be created for this device,
      // and the device won't be able to decrypt the secret it just created.
      // NOTE: Public publications skip this check — no encryption means no decryption needed.
      if (!input.isPublic) {
        const devicesWithKeys = await identityManager.getDevicesWithPublicKeys(ownerConfig.identityContract);
        const thisDeviceHasPublicKey = devicesWithKeys.some(
          d => d.address.toLowerCase() === wallet.address.toLowerCase() && d.hasPublicKey
        );
        console.log(`[CreateSecret] Device ${wallet.address.slice(0, 10)}... has public key: ${thisDeviceHasPublicKey}`);

        if (!thisDeviceHasPublicKey) {
          throw new Error(
            `Cannot create secret: This device (${wallet.address.slice(0, 10)}...) does not have its public key registered on Identity ${ownerConfig.identityContract.slice(0, 10)}...\n\n` +
            `To fix this:\n` +
            `1. Go to the Identity tab\n` +
            `2. Click "Register Public Key" for this device\n` +
            `3. Then return here to create your secret\n\n` +
            `Without a registered public key, you won't be able to decrypt secrets created under this Identity.`
          );
        }
      } else {
        console.log('[CreateSecret] PUBLIC mode: Skipping public key check (no encryption needed)');
      }
    } catch (e) {
      console.error('[CreateSecret] Failed to verify Identity registration:', e);
      throw e;
    }

    // Wrap IdentityManager methods as IdentityExecutor
    identityExecutor = {
      executeTransaction: async (params) => {
        console.log('[CreateSecret] Executing through Identity contract:', params.identityAddress);
        return identityManager.executeTransaction(params);
      },

      // CRITICAL: Required for multi-device encryption in Identity mode
      // This allows the orchestrator to discover all rivets and encrypt the master key for each
      getDevicesWithPublicKeys: async (identityAddress: string) => {
        console.log('[CreateSecret] Getting devices with public keys for:', identityAddress);
        const devices = await identityManager.getDevicesWithPublicKeys(identityAddress);
        console.log(`[CreateSecret] Found ${devices.length} devices, ${devices.filter(d => d.hasPublicKey).length} with public keys`);
        return devices;
      },
    };
  }

  // Create orchestrator with ECDH owner config
  const orchestrator = new SecretOrchestrator(
    {
      factory: {
        address: config.contracts.factory!,
        chainId: config.network.chainId,
        rpcUrl: config.network.rpc,
        gas: DEFAULT_GAS_SETTINGS,
      },
      ipfs: {
        apiKey: config.ipfs.apiKey || '',
        secretKey: config.ipfs.secretKey || '',
        // Prefer the server-side pin proxy (no secret in the browser); fall back
        // to the direct Pinata API for desktop/local where the key lives on-device.
        // NEVER the gateway — that's a download endpoint and rejects pin POSTs.
        endpoint: config.ipfs.pinEndpoint || 'https://api.pinata.cloud',
      },
      signer: wallet.signer as any,
      onProgress: handleProgress,
      createKeyVault: true,
      retryAttempts: 1, // No retries for blockchain ops - not idempotent
      // V6 ECDH: Owner config based on mode selection
      owner: ownerConfig,
      // Identity executor for IDENTITY mode
      identityExecutor,
    },
    crypto,
    factory
  );

  return orchestrator.createSecret(input);
}

/**
 * Handle progress updates
 */
function handleProgress(progress: StepProgress): void {
  const stepsContainer = document.getElementById('progress-steps');
  const fillBar = document.getElementById('progress-fill');
  const statusEl = document.getElementById('progress-status');

  if (!stepsContainer || !fillBar || !statusEl) return;

  // Update progress bar
  const percent = (progress.stepNumber / progress.totalSteps) * 100;
  fillBar.style.width = `${percent}%`;

  // Update status
  const statusIcon = progress.status === 'completed' ? '✓' :
                     progress.status === 'failed' ? '✗' :
                     progress.status === 'in-progress' ? '...' : '○';

  statusEl.textContent = `${statusIcon} ${progress.message || progress.step}`;

  // Add step to list
  const existingStep = stepsContainer.querySelector(`[data-step="${progress.step}"]`);
  if (existingStep) {
    existingStep.className = `progress-step ${progress.status}`;
    existingStep.innerHTML = `
      <span class="step-icon">${statusIcon}</span>
      <span class="step-name">${progress.message || progress.step}</span>
    `;
  } else {
    const stepEl = document.createElement('div');
    stepEl.className = `progress-step ${progress.status}`;
    stepEl.dataset.step = progress.step;
    stepEl.innerHTML = `
      <span class="step-icon">${statusIcon}</span>
      <span class="step-name">${progress.message || progress.step}</span>
    `;
    stepsContainer.appendChild(stepEl);
  }
}

/**
 * Show progress panel
 */
function showProgress(): void {
  const progressEl = document.getElementById('creation-progress');
  const resultEl = document.getElementById('creation-result');
  const stepsEl = document.getElementById('progress-steps');
  const fillEl = document.getElementById('progress-fill');

  if (progressEl) progressEl.classList.remove('hidden');
  if (resultEl) resultEl.classList.add('hidden');
  if (stepsEl) stepsEl.innerHTML = '';
  if (fillEl) fillEl.style.width = '0%';
}

/**
 * Show success result.
 *
 * Displays the SecretOutput with:
 * - Contract address and explorer link
 * - Transaction hashes with explorer links
 * - Input echo-back (name, type, requestId, source)
 * - Timing information
 */
