// ============================================================================
// Programmatic Secret Creation API
// ============================================================================

/**
 * Parameters for programmatic secret creation
 */
interface CreateSecretWithContentParams {
  name: string;
  type: string;
  content: string;
  walletName?: string;
}

/**
 * Create a secret programmatically with pre-built content.
 * This is used by the Word Add-in document-to-secret flow.
 *
 * @param state - Wallet and config state
 * @param params - Secret parameters
 * @returns Created secret address
 */
async function createSecretWithContent(
  state: {
    wallet: { address: string; signer: any; provider: any; publicKey?: string };
    config: { contracts: { factory: string; registry: string; rateTable?: string }; network: { chainId: number; rpc: string }; ipfs?: any; gas?: any };
  },
  params: CreateSecretWithContentParams
): Promise<{ address: string }> {
  console.log('[CreateSecret] Creating secret with content:', params.name);

  // Build input source for traceability
  const source: InputSource = {
    type: 'human',
    platform: 'word-addin',
    version: VERSION,
    sessionId: SESSION_ID,
  };

  // Build the secret input
  const input: SecretInput = {
    requestId: generateRequestId(),
    name: params.name,
    type: params.type as SecretType,
    content: params.content,
    walletName: params.walletName || `Document Secret - ${new Date().toLocaleDateString()}`,
    source,
    timestamp: Date.now(),
  };

  // Get public key for ECDH encryption
  const publicKey = state.wallet.publicKey || await getPublicKeyFromSigner(state.wallet.signer);

  // Create crypto instance
  const crypto = new RootzCrypto();

  // Create factory contract adapter
  const factory = createFactoryContract(
    state.config.contracts.factory,
    state.wallet.provider,
    state.wallet.signer,
    state.config.gas
  );

  // Build owner config for ECDH
  const ownerConfig = buildOwnerConfig(state.wallet.address, publicKey);

  // Create orchestrator
  const orchestrator = new SecretOrchestrator(
    {
      factory: {
        address: state.config.contracts.factory,
        chainId: state.config.network.chainId,
        rpcUrl: state.config.network.rpc,
        gas: state.config.gas || DEFAULT_GAS_SETTINGS,
      },
      ipfs: state.config.ipfs ? {
        apiKey: state.config.ipfs.apiKey || '',
        secretKey: state.config.ipfs.secretKey || '',
        // Prefer the server-side pin proxy; fall back to the direct Pinata API for
        // desktop/local. NEVER the gateway — it's downloads-only and rejects pins.
        endpoint: state.config.ipfs.pinEndpoint || 'https://api.pinata.cloud',
      } : undefined,
      signer: state.wallet.signer,
      onProgress: (progress) => {
        console.log(`[CreateSecret] Step ${progress.stepNumber}/${progress.totalSteps}: ${progress.stepName} - ${progress.status}`);
      },
      createKeyVault: true,
      retryAttempts: 1,
      owner: ownerConfig,
    },
    crypto,
    factory
  );

  // Create the secret
  const result = await orchestrator.createSecret(input);

  if (isSecretError(result)) {
    throw new Error(result.error.message);
  }

  if (!isSecretSuccess(result)) {
    throw new Error('Unknown error creating secret');
  }

  console.log('[CreateSecret] Secret created:', result.secretAddress);
  return { address: result.secretAddress };
}

/**
 * Get public key from signer (helper)
 */
async function getPublicKeyFromSigner(signer: any): Promise<string> {
  // Try to get public key from signer
  if (signer.publicKey) {
    return signer.publicKey;
  }

  // For standard signers, we need to derive from a signature
  const message = 'Rootz public key derivation';
  const signature = await signer.signMessage(message);

  // Use ethers to recover the public key
  const { ethers } = await import('ethers');
  const msgHash = ethers.hashMessage(message);
  const recoveredPubKey = ethers.SigningKey.recoverPublicKey(msgHash, signature);

  return recoveredPubKey;
}

