/**
 * EOA (Externally Owned Account) Signer
 *
 * Direct private key signer implementing RootzSigner interface.
 * Wraps ethers.Wallet with storage adapter integration.
 */

import {
  Wallet,
  HDNodeWallet,
  SigningKey,
  type Provider,
  type TransactionRequest,
  type TransactionResponse,
} from 'ethers';
import type {
  RootzSigner,
  StorageAdapter,
  StoredWallet,
  TypedDataDomain,
  TypedDataField,
} from './types.js';

/**
 * EOA Signer - Direct private key signing.
 *
 * Implements RootzSigner for EOA wallets.
 * Other packages use this through the RootzSigner interface.
 */
export class EOASigner implements RootzSigner {
  readonly signerType = 'eoa' as const;

  private ethersWallet: Wallet;
  private _publicKey: string;
  private _provider: Provider | null;

  private constructor(
    privateKey: string,
    publicKey: string,
    provider: Provider | null = null
  ) {
    this._publicKey = publicKey;
    this._provider = provider;
    this.ethersWallet = provider
      ? new Wallet(privateKey, provider)
      : new Wallet(privateKey);
  }

  /**
   * Create a new random wallet.
   */
  static create(): { signer: EOASigner; mnemonic: string; stored: StoredWallet } {
    const ethersWallet = Wallet.createRandom();
    const signingKey = new SigningKey(ethersWallet.privateKey);
    const publicKey = signingKey.publicKey;

    const stored: StoredWallet = {
      address: ethersWallet.address,
      publicKey: publicKey,
      privateKey: ethersWallet.privateKey,
      mnemonic: ethersWallet.mnemonic?.phrase || '',
      source: 'browser', // Will be overwritten by storage adapter
      createdAt: Date.now(),
      lastAccessedAt: Date.now(),
    };

    const signer = new EOASigner(stored.privateKey, stored.publicKey);

    return {
      signer,
      mnemonic: stored.mnemonic || '',
      stored,
    };
  }

  /**
   * Recover wallet from mnemonic.
   */
  static fromMnemonic(
    mnemonic: string,
    derivationPath: string = "m/44'/60'/0'/0/0"
  ): { signer: EOASigner; stored: StoredWallet } {
    const ethersWallet = HDNodeWallet.fromPhrase(mnemonic, undefined, derivationPath);
    const signingKey = new SigningKey(ethersWallet.privateKey);
    const publicKey = signingKey.publicKey;

    const stored: StoredWallet = {
      address: ethersWallet.address,
      publicKey: publicKey,
      privateKey: ethersWallet.privateKey,
      mnemonic: mnemonic,
      source: 'browser',
      createdAt: Date.now(),
      lastAccessedAt: Date.now(),
    };

    const signer = new EOASigner(stored.privateKey, stored.publicKey);

    return { signer, stored };
  }

  /**
   * Load from stored wallet data.
   */
  static fromStored(stored: StoredWallet): EOASigner {
    return new EOASigner(stored.privateKey, stored.publicKey);
  }

  /**
   * Create from private key directly.
   */
  static fromPrivateKey(privateKey: string): EOASigner {
    const signingKey = new SigningKey(privateKey);
    const publicKey = signingKey.publicKey;
    return new EOASigner(privateKey, publicKey);
  }

  // ============================================================================
  // RootzSigner Interface Implementation
  // ============================================================================

  get provider(): Provider | null {
    return this._provider;
  }

  async getAddress(): Promise<string> {
    return this.ethersWallet.address;
  }

  getPublicKey(): string {
    return this._publicKey;
  }

  async signMessage(message: string | Uint8Array): Promise<string> {
    return this.ethersWallet.signMessage(message);
  }

  async signTypedData(
    domain: TypedDataDomain,
    types: Record<string, TypedDataField[]>,
    value: Record<string, unknown>
  ): Promise<string> {
    return this.ethersWallet.signTypedData(domain, types, value);
  }

  async sendTransaction(tx: TransactionRequest): Promise<TransactionResponse> {
    if (!this._provider) {
      throw new Error('No provider connected. Call connect() first.');
    }
    return this.ethersWallet.sendTransaction(tx);
  }

  connect(provider: Provider): RootzSigner {
    const connected = new EOASigner(
      this.ethersWallet.privateKey,
      this._publicKey,
      provider
    );
    return connected;
  }

  // ============================================================================
  // Additional Methods
  // ============================================================================

  /**
   * Get the underlying ethers Wallet.
   * Use with caution - prefer the RootzSigner interface.
   */
  getEthersWallet(): Wallet {
    return this.ethersWallet;
  }

  /**
   * Get the address synchronously (already computed).
   */
  get address(): string {
    return this.ethersWallet.address;
  }
}
