/**
 * @rootz/message-processor - KeyStorage
 *
 * localStorage wrapper for encryption keys.
 * All keys are chain-namespaced: rootz_{chainId}_*
 */

import { KeyStorage, WriteAuthorization } from './types.js';

// ============================================================================
// Key Patterns
// ============================================================================

const KEY_PATTERNS = {
  masterKey: (chainId: number, contract: string) =>
    `rootz_${chainId}_master_${contract.toLowerCase()}`,

  kvKey: (chainId: number, kvBlock: number) =>
    `rootz_${chainId}_kv_${kvBlock}`,

  writeAuth: (chainId: number, contract: string, kvBlock: number) =>
    `rootz_${chainId}_auth_${contract.toLowerCase()}_${kvBlock}`,

  publicKey: (chainId: number, address: string) =>
    `rootz_${chainId}_pubkey_${address.toLowerCase()}`,

  chainPrefix: (chainId: number) =>
    `rootz_${chainId}_`,
};

// ============================================================================
// Browser localStorage Implementation
// ============================================================================

export function createBrowserKeyStorage(): KeyStorage {
  return {
    // Master key
    getMasterKey(chainId: number, contract: string): string | null {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      return localStorage.getItem(key);
    },

    setMasterKey(chainId: number, contract: string, value: string): void {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      localStorage.setItem(key, value);
    },

    deleteMasterKey(chainId: number, contract: string): void {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      localStorage.removeItem(key);
    },

    // KV key
    getKVKey(chainId: number, kvBlock: number): string | null {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      return localStorage.getItem(key);
    },

    setKVKey(chainId: number, kvBlock: number, value: string): void {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      localStorage.setItem(key, value);
    },

    deleteKVKey(chainId: number, kvBlock: number): void {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      localStorage.removeItem(key);
    },

    // Write authorization
    getWriteAuth(chainId: number, contract: string, kvBlock: number): WriteAuthorization | null {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      const value = localStorage.getItem(key);
      if (!value) return null;
      try {
        return JSON.parse(value) as WriteAuthorization;
      } catch {
        return null;
      }
    },

    setWriteAuth(chainId: number, contract: string, kvBlock: number, auth: WriteAuthorization): void {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      localStorage.setItem(key, JSON.stringify(auth));
    },

    deleteWriteAuth(chainId: number, contract: string, kvBlock: number): void {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      localStorage.removeItem(key);
    },

    // Public key (fast lookup)
    getPublicKey(chainId: number, address: string): string | null {
      const key = KEY_PATTERNS.publicKey(chainId, address);
      return localStorage.getItem(key);
    },

    setPublicKey(chainId: number, address: string, pubKey: string): void {
      const key = KEY_PATTERNS.publicKey(chainId, address);
      localStorage.setItem(key, pubKey);
    },

    // Clear all keys for a chain
    clearChain(chainId: number): void {
      const prefix = KEY_PATTERNS.chainPrefix(chainId);
      const keysToRemove: string[] = [];

      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(prefix)) {
          keysToRemove.push(key);
        }
      }

      for (const key of keysToRemove) {
        localStorage.removeItem(key);
      }
    },
  };
}

// ============================================================================
// In-Memory Implementation (for testing / Node.js)
// ============================================================================

export function createMemoryKeyStorage(): KeyStorage {
  const store = new Map<string, string>();

  return {
    getMasterKey(chainId: number, contract: string): string | null {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      return store.get(key) || null;
    },

    setMasterKey(chainId: number, contract: string, value: string): void {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      store.set(key, value);
    },

    deleteMasterKey(chainId: number, contract: string): void {
      const key = KEY_PATTERNS.masterKey(chainId, contract);
      store.delete(key);
    },

    getKVKey(chainId: number, kvBlock: number): string | null {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      return store.get(key) || null;
    },

    setKVKey(chainId: number, kvBlock: number, value: string): void {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      store.set(key, value);
    },

    deleteKVKey(chainId: number, kvBlock: number): void {
      const key = KEY_PATTERNS.kvKey(chainId, kvBlock);
      store.delete(key);
    },

    getWriteAuth(chainId: number, contract: string, kvBlock: number): WriteAuthorization | null {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      const value = store.get(key);
      if (!value) return null;
      try {
        return JSON.parse(value) as WriteAuthorization;
      } catch {
        return null;
      }
    },

    setWriteAuth(chainId: number, contract: string, kvBlock: number, auth: WriteAuthorization): void {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      store.set(key, JSON.stringify(auth));
    },

    deleteWriteAuth(chainId: number, contract: string, kvBlock: number): void {
      const key = KEY_PATTERNS.writeAuth(chainId, contract, kvBlock);
      store.delete(key);
    },

    getPublicKey(chainId: number, address: string): string | null {
      const key = KEY_PATTERNS.publicKey(chainId, address);
      return store.get(key) || null;
    },

    setPublicKey(chainId: number, address: string, pubKey: string): void {
      const key = KEY_PATTERNS.publicKey(chainId, address);
      store.set(key, pubKey);
    },

    clearChain(chainId: number): void {
      const prefix = KEY_PATTERNS.chainPrefix(chainId);
      for (const key of store.keys()) {
        if (key.startsWith(prefix)) {
          store.delete(key);
        }
      }
    },
  };
}

// ============================================================================
// Export key patterns for migration
// ============================================================================

export { KEY_PATTERNS };
