/**
 * Settings Tab
 *
 * Network selector and application settings.
 */

import type { AppConfig, NetworkConfig } from '../config';
import { getCurrencySymbol, getChainName } from '../network-utils';

interface SettingsState {
  config: AppConfig;
  wallet: {
    address: string;
    balance: string;
  };
}

/**
 * Render the Settings tab
 */
export function renderSettingsTab(state: SettingsState): string {
  const { config } = state;
  const currentChainId = config.network.chainId;
  const currentSymbol = getCurrencySymbol(currentChainId);

  // Build network options from config.networks
  const networkOptions = Object.entries(config.networks || {})
    .map(([key, network]) => {
      const isActive = network.chainId === currentChainId &&
                       config.defaultNetwork === key;
      return `
        <option value="${key}" ${isActive ? 'selected' : ''}>
          ${network.name} (Chain ${network.chainId}) - ${getCurrencySymbol(network.chainId)}
        </option>
      `;
    })
    .join('');

  return `
    <div class="settings-tab">
      <h2>Settings</h2>

      <section class="settings-section">
        <h3>Network Configuration</h3>
        <div class="setting-row">
          <label for="network-select">Active Network:</label>
          <select id="network-select" class="network-selector">
            ${networkOptions}
          </select>
        </div>
        <div class="network-info">
          <div class="info-row">
            <span class="label">Chain ID:</span>
            <span class="value">${currentChainId}</span>
          </div>
          <div class="info-row">
            <span class="label">Currency:</span>
            <span class="value">${currentSymbol}</span>
          </div>
          <div class="info-row">
            <span class="label">RPC:</span>
            <span class="value rpc-url">${config.network.rpc}</span>
          </div>
          <div class="info-row">
            <span class="label">Explorer:</span>
            <a href="${config.network.explorer}" target="_blank" class="value">${config.network.explorer}</a>
          </div>
          <div class="info-row">
            <span class="label">Contract Set:</span>
            <span class="value">${config.network.contractSet}</span>
          </div>
        </div>
        <button id="switch-network-btn" class="primary">Switch Network</button>
        <p id="network-switch-status" class="status-message"></p>
      </section>

      <section class="settings-section">
        <h3>Contract Addresses</h3>
        <div class="contracts-info">
          ${renderContractRow('Factory', config.contracts.factory)}
          ${renderContractRow('Registry', config.contracts.registry)}
          ${renderContractRow('Rate Table', config.contracts.rateTable)}
          ${renderContractRow('Identity Factory', config.contracts.identityFactory)}
          ${renderContractRow('Identity Template', config.contracts.identityTemplate)}
          ${renderContractRow('MultiToken Purchase', config.contracts.multiTokenPurchase)}
        </div>
      </section>

      <section class="settings-section">
        <h3>Application Info</h3>
        <div class="app-info">
          <div class="info-row">
            <span class="label">Dashboard Version:</span>
            <span class="value">${config.version}</span>
          </div>
          <div class="info-row">
            <span class="label">Contract Version:</span>
            <span class="value">${config.contractVersion}</span>
          </div>
        </div>
      </section>

      <section class="settings-section">
        <h3>Credits Management</h3>
        <div class="credits-info">
          <div class="info-row">
            <span class="label">Registry Credits:</span>
            <span id="settings-credits-balance" class="value">Loading...</span>
          </div>
          <p class="help-text">Credits are used for creating secrets and identities on the blockchain.</p>
        </div>
        <div class="credits-actions">
          <button id="settings-buy-credits-btn" class="primary">Buy 100K Credits (0.1 POL)</button>
          <button id="settings-refresh-credits-btn" class="secondary">Refresh Balance</button>
        </div>
        <p id="credits-status" class="status-message"></p>
      </section>

      <section class="settings-section">
        <h3>Wallet Management</h3>
        <div class="wallet-actions">
          <button id="export-mnemonic-btn" class="secondary">Export Mnemonic</button>
          <button id="clear-storage-btn" class="secondary danger">Clear Local Storage</button>
        </div>
        <p class="warning-text">Warning: Clearing storage will remove all cached secrets and require a full chain sync.</p>
      </section>

      <section class="settings-section">
        <h3>Data Recovery</h3>
        <p class="help-text">If your local archive is missing secrets, use Sync from Origin to rescan the entire blockchain.</p>
        <div class="recovery-actions">
          <button id="sync-from-origin-btn" class="secondary">Sync from Origin</button>
        </div>
        <p id="sync-status" class="status-message"></p>
      </section>
    </div>
  `;
}

function renderContractRow(label: string, address: string | null | undefined): string {
  if (!address) {
    return `
      <div class="contract-row not-deployed">
        <span class="label">${label}:</span>
        <span class="value">Not deployed</span>
      </div>
    `;
  }
  return `
    <div class="contract-row">
      <span class="label">${label}:</span>
      <span class="value address" title="${address}">${address.slice(0, 10)}...${address.slice(-8)}</span>
      <button class="copy-btn" data-address="${address}">Copy</button>
    </div>
  `;
}

/**
 * Credits callback interface for Settings tab
 */
interface CreditsCallbacks {
  onBuyCredits: () => Promise<void>;
  onRefreshCredits: () => Promise<number>;
}

/**
 * Setup event handlers for the Settings tab
 */
export async function setupSettingsTab(
  state: SettingsState,
  onNetworkSwitch: (networkKey: string) => Promise<void>,
  creditsCallbacks?: CreditsCallbacks
): Promise<void> {
  // Setup credits section if callbacks provided
  if (creditsCallbacks) {
    const creditsBalance = document.getElementById('settings-credits-balance');
    const buyCreditsBtn = document.getElementById('settings-buy-credits-btn');
    const refreshCreditsBtn = document.getElementById('settings-refresh-credits-btn');
    const creditsStatus = document.getElementById('credits-status');

    // Refresh credits balance
    const refreshCredits = async () => {
      if (creditsBalance) creditsBalance.textContent = 'Loading...';
      try {
        const balance = await creditsCallbacks.onRefreshCredits();
        if (creditsBalance) {
          creditsBalance.textContent = balance.toLocaleString();
          creditsBalance.className = balance > 0 ? 'value has-credits' : 'value no-credits';
        }
      } catch (e: any) {
        if (creditsBalance) creditsBalance.textContent = 'Error';
        console.error('[Settings] Failed to refresh credits:', e);
      }
    };

    // Initial load
    refreshCredits();

    // Refresh button
    if (refreshCreditsBtn) {
      refreshCreditsBtn.addEventListener('click', refreshCredits);
    }

    // Buy credits button
    if (buyCreditsBtn) {
      buyCreditsBtn.addEventListener('click', async () => {
        buyCreditsBtn.disabled = true;
        buyCreditsBtn.textContent = 'Buying...';
        if (creditsStatus) {
          creditsStatus.textContent = 'Purchasing credits...';
          creditsStatus.className = 'status-message info';
        }

        try {
          await creditsCallbacks.onBuyCredits();
          if (creditsStatus) {
            creditsStatus.textContent = 'Credits purchased successfully!';
            creditsStatus.className = 'status-message success';
          }
          // Refresh balance after purchase
          await refreshCredits();
        } catch (e: any) {
          console.error('[Settings] Failed to buy credits:', e);
          if (creditsStatus) {
            creditsStatus.textContent = `Failed: ${e.message || e}`;
            creditsStatus.className = 'status-message error';
          }
        } finally {
          buyCreditsBtn.disabled = false;
          buyCreditsBtn.textContent = 'Buy 100K Credits (0.1 POL)';
        }
      });
    }
  }
  // Network switch button
  const switchBtn = document.getElementById('switch-network-btn');
  const networkSelect = document.getElementById('network-select') as HTMLSelectElement;
  const statusEl = document.getElementById('network-switch-status');

  if (switchBtn && networkSelect) {
    switchBtn.addEventListener('click', async () => {
      const selectedNetwork = networkSelect.value;

      if (statusEl) {
        statusEl.textContent = 'Switching network...';
        statusEl.className = 'status-message info';
      }

      try {
        // Try to switch MetaMask network if available
        if (window.ethereum) {
          const networkConfig = state.config.networks[selectedNetwork];
          if (networkConfig) {
            const chainIdHex = '0x' + networkConfig.chainId.toString(16);

            try {
              await window.ethereum.request({
                method: 'wallet_switchEthereumChain',
                params: [{ chainId: chainIdHex }],
              });
            } catch (switchError: any) {
              // Chain not added to MetaMask, try to add it
              if (switchError.code === 4902) {
                const symbol = getCurrencySymbol(networkConfig.chainId);
                await window.ethereum.request({
                  method: 'wallet_addEthereumChain',
                  params: [{
                    chainId: chainIdHex,
                    chainName: networkConfig.name,
                    nativeCurrency: {
                      name: symbol,
                      symbol: symbol,
                      decimals: 18,
                    },
                    rpcUrls: [networkConfig.rpc],
                    blockExplorerUrls: networkConfig.explorer ? [networkConfig.explorer] : [],
                  }],
                });
              } else {
                throw switchError;
              }
            }
          }
        }

        // Call the network switch callback
        await onNetworkSwitch(selectedNetwork);

        if (statusEl) {
          statusEl.textContent = 'Network switched! Reloading...';
          statusEl.className = 'status-message success';
        }

        // Store selected network and reload
        localStorage.setItem('rootz_selected_network', selectedNetwork);
        setTimeout(() => window.location.reload(), 1000);

      } catch (error: any) {
        console.error('[Settings] Network switch failed:', error);
        if (statusEl) {
          statusEl.textContent = `Failed to switch: ${error.message || error}`;
          statusEl.className = 'status-message error';
        }
      }
    });
  }

  // Export mnemonic button
  const exportBtn = document.getElementById('export-mnemonic-btn');
  if (exportBtn) {
    exportBtn.addEventListener('click', () => {
      const mnemonic = localStorage.getItem('epistery_mnemonic');
      if (mnemonic) {
        const confirmed = confirm(
          'Your mnemonic phrase will be displayed.\n\n' +
          'NEVER share this with anyone!\n\n' +
          'Anyone with this phrase can access your wallet.'
        );
        if (confirmed) {
          alert(`Your mnemonic phrase:\n\n${mnemonic}\n\nWrite this down and store it safely!`);
        }
      } else {
        alert('No mnemonic found in local storage.');
      }
    });
  }

  // Clear storage button
  const clearBtn = document.getElementById('clear-storage-btn');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      const confirmed = confirm(
        'This will clear all cached data including:\n\n' +
        '- Cached secrets\n' +
        '- Sync state\n' +
        '- Identity associations\n\n' +
        'Your wallet mnemonic will NOT be deleted.\n\n' +
        'Continue?'
      );
      if (confirmed) {
        // Clear IndexedDB
        indexedDB.deleteDatabase('rootz-secrets');

        // Clear related localStorage items (but not mnemonic)
        const keysToRemove = [];
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i);
          if (key && (
            key.startsWith('rootz_') ||
            key.startsWith('identity_') ||
            key.startsWith('known_identities_')
          )) {
            keysToRemove.push(key);
          }
        }
        keysToRemove.forEach(key => localStorage.removeItem(key));

        alert('Storage cleared. Reloading...');
        window.location.reload();
      }
    });
  }

  // Copy buttons for contract addresses
  document.querySelectorAll('.copy-btn[data-address]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      const address = target.getAttribute('data-address');
      if (address) {
        navigator.clipboard.writeText(address);
        target.textContent = 'Copied!';
        setTimeout(() => { target.textContent = 'Copy'; }, 1500);
      }
    });
  });

  // Sync from Origin button (data recovery)
  const syncFromOriginBtn = document.getElementById('sync-from-origin-btn');
  const syncStatus = document.getElementById('sync-status');
  if (syncFromOriginBtn) {
    syncFromOriginBtn.addEventListener('click', async () => {
      const confirmed = confirm(
        'Sync from Origin will rescan the entire blockchain from block 0.\n\n' +
        'This may take several minutes for wallets with many secrets.\n\n' +
        'Use this if your local archive is missing secrets or corrupted.\n\n' +
        'Continue?'
      );
      if (!confirmed) return;

      syncFromOriginBtn.textContent = 'Syncing...';
      (syncFromOriginBtn as HTMLButtonElement).disabled = true;
      if (syncStatus) {
        syncStatus.textContent = 'Starting full resync from block 0...';
        syncStatus.className = 'status-message info';
      }

      try {
        const response = await fetch('http://localhost:3020/api/chain-sync/sync-from-origin', {
          method: 'POST',
        });

        if (!response.ok) {
          throw new Error(`Server error: ${response.status}`);
        }

        const result = await response.json();

        if (syncStatus) {
          syncStatus.textContent = `Sync complete! Found ${result.status?.newArchives || 0} new, ${result.status?.updatedArchives || 0} updated secrets.`;
          syncStatus.className = 'status-message success';
        }

        // Optionally reload to refresh the UI
        setTimeout(() => {
          if (confirm('Sync complete. Reload page to see updated data?')) {
            window.location.reload();
          }
        }, 1500);

      } catch (error: any) {
        console.error('[Settings] Sync from origin failed:', error);
        if (syncStatus) {
          syncStatus.textContent = `Sync failed: ${error.message || error}`;
          syncStatus.className = 'status-message error';
        }
      } finally {
        syncFromOriginBtn.textContent = 'Sync from Origin';
        (syncFromOriginBtn as HTMLButtonElement).disabled = false;
      }
    });
  }
}

// Add ethereum type for TypeScript
declare global {
  interface Window {
    ethereum?: {
      request: (args: { method: string; params?: any[] }) => Promise<any>;
    };
  }
}
