/**
 * Rootz V6 Dashboard - Wallet Integration
 *
 * Uses @rootz/wallet package for wallet management.
 * This file provides dashboard-specific wrappers and state management.
 *
 * Supports two wallet modes:
 * - Standard: Browser localStorage (default)
 * - TPM-Enhanced: Two-factor hardware+software protection (desktop only)
 *
 * TPM wallet derivation: privateKey = keccak256(entropy || TPM_signature)
 */

import { JsonRpcProvider, BrowserProvider, formatEther, Wallet, keccak256, hexlify, randomBytes, computeAddress, SigningKey } from 'ethers';
import { ChainDeviceKeyManager, getDeviceKeyCache, clearDeviceKeyCache } from '@rootz/hardware-keys';
import {
  loadOrCreateWallet,
  BrowserStorageAdapter,
  getMnemonic as getStoredMnemonic,
  deleteWallet,
  EOASigner,
  type RootzSigner,
  type WalletState as PackageWalletState,
} from '@rootz/wallet';
import type { AppConfig } from './config';
import { getCurrencySymbol } from './network-utils';

// ============================================================================
// Wallet Source Types
// ============================================================================

export type WalletSourceType = 'standard' | 'tpm' | 'hardware' | 'secure-enclave';

/** Stored TPM wallet metadata */
export interface StoredTpmWallet {
  address: string;
  publicKey: string;
  entropy: string;  // The 32-byte entropy (first factor)
  salt: string;     // The salt used for TPM signing
  createdAt: number;
}

/** Archived wallet data for safe switching */
export interface ArchivedWallet {
  source: WalletSourceType;
  address: string;
  publicKey: string;
  archivedAt: number;
  // For standard wallets: includes private key
  privateKey?: string;
  mnemonic?: string;
  // For TPM wallets: includes entropy
  entropy?: string;
  salt?: string;
}

/** Stored Secure Enclave wallet metadata (macOS). The entropy is the backup-able
 *  first factor; the SE device factor is non-exportable and lives in the enclave. */
export interface StoredSecureEnclaveWallet {
  address: string;
  publicKey: string;
  entropy: string;   // 32-byte first factor (back this up)
  createdAt: number;
}

// localStorage keys
const WALLET_SOURCE_KEY = 'rootz_wallet_source';
const TPM_WALLET_KEY = 'rootz_tpm_wallet';
const HARDWARE_WALLET_KEY = 'rootz_hardware_wallet';
const SECURE_ENCLAVE_WALLET_KEY = 'rootz_secure_enclave_wallet';
const ARCHIVED_WALLETS_KEY = 'rootz_archived_wallets';

/**
 * Dashboard wallet state - extends package state with ethers objects
 */
export interface WalletState {
  address: string;
  publicKey: string;
  privateKey: string;  // Needed for ECDH decryption
  balance: string;
  signer: RootzSigner;
  provider: JsonRpcProvider;
  isNew: boolean;
}

// Storage adapter instance
const storage = new BrowserStorageAdapter();

// Store mnemonic temporarily for new wallet display
let temporaryMnemonic: string | null = null;

/**
 * Connect to Epistery browser wallet
 * Uses @rootz/wallet package for wallet management
 */
export async function connectWallet(config: AppConfig): Promise<WalletState> {
  console.log('Connecting Epistery wallet...');

  // Create provider for blockchain connection
  const provider = new JsonRpcProvider(config.network.rpc);

  // Load or create wallet using the package
  const { signer, state, mnemonic } = await loadOrCreateWallet({
    storage,
    provider,
  });

  // Store mnemonic temporarily for display
  temporaryMnemonic = mnemonic || null;

  // Get balance
  let balance = '0';
  try {
    const balanceWei = await provider.getBalance(state.address);
    balance = formatEther(balanceWei);
    console.log(`Balance: ${parseFloat(balance).toFixed(4)} ${getCurrencySymbol(config.network.chainId)}`);
  } catch (error) {
    console.warn('Could not fetch balance:', error);
  }

  // Verify network
  try {
    const network = await provider.getNetwork();
    const chainId = Number(network.chainId);
    if (chainId !== config.network.chainId) {
      console.warn(`Connected to chain ${chainId}, expected ${config.network.chainId}`);
    } else {
      console.log(`Connected to ${config.network.name} (${chainId})`);
    }
  } catch (error) {
    console.warn('Could not verify network:', error);
  }

  console.log(`Wallet ready: ${state.address}`);

  // Extract private key from EOASigner for ECDH operations
  let privateKey = '';
  if (signer.signerType === 'eoa') {
    const eoaSigner = signer as unknown as EOASigner;
    privateKey = eoaSigner.getEthersWallet().privateKey;
  }

  return {
    address: state.address,
    publicKey: state.publicKey,
    privateKey,
    balance,
    signer,
    provider,
    isNew: state.isNew,
  };
}

/**
 * Format address for display (0x1234...5678)
 */
export function formatAddress(address: string): string {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

/**
 * Get mnemonic for backup display (only for new wallets)
 * Returns the temporarily stored mnemonic from wallet creation
 */
export function getMnemonic(): string | null {
  return temporaryMnemonic;
}

/**
 * Check if wallet exists in storage
 */
export async function hasStoredWallet(): Promise<boolean> {
  return storage.exists();
}

/**
 * Clear wallet from storage (for testing/reset)
 */
export async function clearWallet(): Promise<void> {
  await deleteWallet(storage);
  temporaryMnemonic = null;
  console.log('Wallet cleared from storage');
}

/**
 * Get the stored mnemonic (for backup later)
 */
export async function getStoredMnemonicPhrase(): Promise<string | null> {
  return getStoredMnemonic(storage);
}

// ============================================================================
// TPM Wallet Functions
// ============================================================================

/**
 * Get current wallet source (standard or tpm)
 */
export function getWalletSource(): WalletSourceType {
  return (localStorage.getItem(WALLET_SOURCE_KEY) as WalletSourceType) || 'standard';
}

/**
 * Set wallet source
 */
export function setWalletSource(source: WalletSourceType): void {
  localStorage.setItem(WALLET_SOURCE_KEY, source);
}

/**
 * Check if TPM wallet exists in storage
 */
export function hasTpmWallet(): boolean {
  return localStorage.getItem(TPM_WALLET_KEY) !== null;
}

/**
 * Get stored TPM wallet metadata
 */
export function getStoredTpmWallet(): StoredTpmWallet | null {
  const stored = localStorage.getItem(TPM_WALLET_KEY);
  if (!stored) return null;
  try {
    return JSON.parse(stored) as StoredTpmWallet;
  } catch {
    return null;
  }
}

/**
 * Create a new TPM-enhanced wallet
 * Uses two-factor derivation: privateKey = keccak256(entropy || TPM_signature)
 *
 * @returns The new wallet state and entropy (user should backup entropy)
 */
export async function createTpmWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  entropy: string;
  isNew: boolean;
}> {
  if (!window.tpm) {
    throw new Error('TPM API not available. Are you running in Desktop mode?');
  }

  // Check TPM availability
  const tpmStatus = await window.tpm.isAvailable();
  if (!tpmStatus.available) {
    throw new Error(`TPM not available: ${tpmStatus.reason}`);
  }

  // Ensure TPM key exists
  const keyResult = await window.tpm.ensureKey();
  if (!keyResult.success) {
    throw new Error(`Failed to ensure TPM key: ${keyResult.error}`);
  }

  // Check if we already have a TPM wallet
  const existingWallet = getStoredTpmWallet();
  if (existingWallet) {
    // Load existing TPM wallet
    console.log('[TPM Wallet] Loading existing TPM wallet...');
    return loadTpmWallet(config);
  }

  console.log('[TPM Wallet] Creating new TPM-enhanced wallet...');

  // Generate random entropy (32 bytes)
  const entropyBytes = randomBytes(32);
  const entropy = hexlify(entropyBytes);
  const salt = 'rootz-tpm-wallet-v1';

  // Get TPM signature for two-factor derivation
  const deriveResult = await window.tpm.deriveKey(entropy, salt);
  if (!deriveResult.success || !deriveResult.tpmSignature) {
    throw new Error(`TPM key derivation failed: ${deriveResult.error}`);
  }

  // Derive private key: keccak256(entropy || tpmSignature)
  const combined = entropy + deriveResult.tpmSignature;
  const privateKey = keccak256(combined);

  // Create wallet from derived key
  const provider = new JsonRpcProvider(config.network.rpc);
  const wallet = new Wallet(privateKey, provider);

  // Get public key (uncompressed)
  const signingKey = new SigningKey(privateKey);
  const publicKey = signingKey.publicKey;

  // Store TPM wallet metadata
  const tpmWalletData: StoredTpmWallet = {
    address: wallet.address,
    publicKey,
    entropy,
    salt,
    createdAt: Date.now(),
  };
  localStorage.setItem(TPM_WALLET_KEY, JSON.stringify(tpmWalletData));

  // Set wallet source to TPM
  setWalletSource('tpm');

  // Get balance
  let balance = '0';
  try {
    const balanceWei = await provider.getBalance(wallet.address);
    balance = formatEther(balanceWei);
    console.log(`[TPM Wallet] Balance: ${parseFloat(balance).toFixed(4)} ${getCurrencySymbol(config.network.chainId)}`);
  } catch (error) {
    console.warn('[TPM Wallet] Could not fetch balance:', error);
  }

  console.log(`[TPM Wallet] Created: ${wallet.address}`);

  // Create a simple RootzSigner wrapper
  const tpmSigner = createTpmSignerWrapper(wallet, publicKey);

  return {
    wallet: {
      address: wallet.address,
      publicKey,
      privateKey,
      balance,
      signer: tpmSigner,
      provider,
      isNew: true,
    },
    entropy,
    isNew: true,
  };
}

/**
 * Load existing TPM wallet from storage
 */
export async function loadTpmWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  entropy: string;
  isNew: boolean;
}> {
  if (!window.tpm) {
    throw new Error('TPM API not available. Are you running in Desktop mode?');
  }

  const stored = getStoredTpmWallet();
  if (!stored) {
    throw new Error('No TPM wallet found in storage');
  }

  console.log('[TPM Wallet] Loading from storage...');

  // Re-derive the private key using stored entropy.
  // Retry with backoff: the first TPM call after a BIOS/UEFI update or cold boot
  // can be slow (TPM re-provisioning + PowerShell cold start) and time out. The
  // chip warms up after the first touch, so a couple of retries turn a transient
  // "derivation failed" into a normal load. This does NOT change the derived key:
  // the TPM signature is deterministic, so a retry yields the same wallet address.
  const MAX_DERIVE_ATTEMPTS = 3;
  let deriveResult = await window.tpm.deriveKey(stored.entropy, stored.salt);
  for (
    let attempt = 2;
    attempt <= MAX_DERIVE_ATTEMPTS && (!deriveResult.success || !deriveResult.tpmSignature);
    attempt++
  ) {
    console.warn(
      `[TPM Wallet] deriveKey attempt ${attempt - 1} failed (${deriveResult.error || 'no signature'}); ` +
      `retrying (${attempt}/${MAX_DERIVE_ATTEMPTS}) — TPM may be warming up after a firmware change...`
    );
    await new Promise(resolve => setTimeout(resolve, 1000 * (attempt - 1)));
    deriveResult = await window.tpm.deriveKey(stored.entropy, stored.salt);
  }
  if (!deriveResult.success || !deriveResult.tpmSignature) {
    throw new Error(`TPM key derivation failed: ${deriveResult.error}`);
  }

  // Derive private key
  const combined = stored.entropy + deriveResult.tpmSignature;
  const privateKey = keccak256(combined);

  // Create wallet
  const provider = new JsonRpcProvider(config.network.rpc);
  const wallet = new Wallet(privateKey, provider);

  // Verify address matches
  if (wallet.address.toLowerCase() !== stored.address.toLowerCase()) {
    throw new Error(`TPM wallet address mismatch! Expected ${stored.address}, got ${wallet.address}`);
  }

  // Get balance
  let balance = '0';
  try {
    const balanceWei = await provider.getBalance(wallet.address);
    balance = formatEther(balanceWei);
  } catch (error) {
    console.warn('[TPM Wallet] Could not fetch balance:', error);
  }

  console.log(`[TPM Wallet] Loaded: ${wallet.address}`);

  // Create signer wrapper
  const tpmSigner = createTpmSignerWrapper(wallet, stored.publicKey);

  return {
    wallet: {
      address: wallet.address,
      publicKey: stored.publicKey,
      privateKey,
      balance,
      signer: tpmSigner,
      provider,
      isNew: false,
    },
    entropy: stored.entropy,
    isNew: false,
  };
}

/**
 * Create a RootzSigner wrapper for TPM wallet
 */
function createTpmSignerWrapper(wallet: Wallet, publicKey: string): RootzSigner {
  return {
    getAddress: async () => wallet.address,
    signMessage: async (message: string | Uint8Array) => wallet.signMessage(message),
    signTypedData: async (domain, types, value) => wallet.signTypedData(domain, types, value),
    sendTransaction: async (tx) => wallet.sendTransaction(tx),
    connect: (provider) => {
      const connected = wallet.connect(provider);
      return createTpmSignerWrapper(connected as Wallet, publicKey);
    },
    provider: wallet.provider,
    getPublicKey: () => publicKey,
    signerType: 'eoa' as const,
  };
}

// ============================================================================
// Secure Enclave Wallet (macOS) — device-bound via the Apple Secure Enclave.
//
// privateKey = keccak256(domain || entropy || ECDH(SE_key, anchor)), computed in the
// main process (window.secureEnclave.deriveWallet) and returned to the renderer to
// build the signer — the same renderer-owns-key model as the TPM wallet. The SE
// factor is non-exportable, so the wallet cannot be reconstructed on another machine
// even with the entropy backup.
// ============================================================================

/** Whether a Secure Enclave wallet exists in storage. */
export function hasSecureEnclaveWallet(): boolean {
  return localStorage.getItem(SECURE_ENCLAVE_WALLET_KEY) !== null;
}

/** Get stored Secure Enclave wallet metadata. */
export function getStoredSecureEnclaveWallet(): StoredSecureEnclaveWallet | null {
  const stored = localStorage.getItem(SECURE_ENCLAVE_WALLET_KEY);
  if (!stored) return null;
  try {
    return JSON.parse(stored) as StoredSecureEnclaveWallet;
  } catch {
    return null;
  }
}

/**
 * Create a new Secure Enclave-bound wallet. Returns the wallet + entropy to back up.
 */
export async function createSecureEnclaveWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  entropy: string;
  isNew: boolean;
}> {
  if (!window.secureEnclave) {
    throw new Error('Secure Enclave API not available. Are you running in Desktop mode on macOS?');
  }

  const status = await window.secureEnclave.isAvailable();
  if (!status.available) {
    throw new Error(`Secure Enclave not available: ${status.reason}`);
  }

  // If a wallet already exists, load it instead of overwriting.
  if (getStoredSecureEnclaveWallet()) {
    console.log('[SE Wallet] Existing Secure Enclave wallet found, loading...');
    return loadSecureEnclaveWallet(config);
  }

  console.log('[SE Wallet] Creating new Secure Enclave-bound wallet...');

  const entropy = hexlify(randomBytes(32));
  const result = await window.secureEnclave.deriveWallet(entropy);
  if (!result.success || !result.privateKey) {
    throw new Error(`Secure Enclave derivation failed: ${result.error}`);
  }

  const provider = new JsonRpcProvider(config.network.rpc);
  const wallet = new Wallet(result.privateKey, provider);
  const publicKey = new SigningKey(result.privateKey).publicKey;

  const stored: StoredSecureEnclaveWallet = {
    address: wallet.address,
    publicKey,
    entropy,
    createdAt: Date.now(),
  };
  localStorage.setItem(SECURE_ENCLAVE_WALLET_KEY, JSON.stringify(stored));
  setWalletSource('secure-enclave');

  let balance = '0';
  try {
    balance = formatEther(await provider.getBalance(wallet.address));
  } catch (error) {
    console.warn('[SE Wallet] Could not fetch balance:', error);
  }

  console.log(`[SE Wallet] Created: ${wallet.address}`);
  return {
    wallet: {
      address: wallet.address,
      publicKey,
      privateKey: result.privateKey,
      balance,
      signer: createTpmSignerWrapper(wallet, publicKey),
      provider,
      isNew: true,
    },
    entropy,
    isNew: true,
  };
}

/**
 * Load the existing Secure Enclave wallet by re-deriving from stored entropy.
 */
export async function loadSecureEnclaveWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  entropy: string;
  isNew: boolean;
}> {
  if (!window.secureEnclave) {
    throw new Error('Secure Enclave API not available. Are you running in Desktop mode on macOS?');
  }

  const stored = getStoredSecureEnclaveWallet();
  if (!stored) {
    throw new Error('No Secure Enclave wallet found in storage');
  }

  console.log('[SE Wallet] Loading from storage...');

  // Retry with backoff: the first SE op after launch can prompt/warm up. ECDH is
  // deterministic, so a retry yields the same wallet address.
  const MAX_DERIVE_ATTEMPTS = 3;
  let result = await window.secureEnclave.deriveWallet(stored.entropy);
  for (
    let attempt = 2;
    attempt <= MAX_DERIVE_ATTEMPTS && (!result.success || !result.privateKey);
    attempt++
  ) {
    console.warn(
      `[SE Wallet] deriveWallet attempt ${attempt - 1} failed (${result.error || 'no key'}); ` +
      `retrying (${attempt}/${MAX_DERIVE_ATTEMPTS})...`
    );
    await new Promise(resolve => setTimeout(resolve, 1000 * (attempt - 1)));
    result = await window.secureEnclave.deriveWallet(stored.entropy);
  }
  if (!result.success || !result.privateKey) {
    throw new Error(`Secure Enclave derivation failed: ${result.error}`);
  }

  const provider = new JsonRpcProvider(config.network.rpc);
  const wallet = new Wallet(result.privateKey, provider);

  if (wallet.address.toLowerCase() !== stored.address.toLowerCase()) {
    throw new Error(`Secure Enclave wallet address mismatch! Expected ${stored.address}, got ${wallet.address}`);
  }

  let balance = '0';
  try {
    balance = formatEther(await provider.getBalance(wallet.address));
  } catch (error) {
    console.warn('[SE Wallet] Could not fetch balance:', error);
  }

  console.log(`[SE Wallet] Loaded: ${wallet.address}`);
  return {
    wallet: {
      address: wallet.address,
      publicKey: stored.publicKey,
      privateKey: result.privateKey,
      balance,
      signer: createTpmSignerWrapper(wallet, stored.publicKey),
      provider,
      isNew: false,
    },
    entropy: stored.entropy,
    isNew: false,
  };
}

// ============================================================================
// Archive Functions
// ============================================================================

/**
 * Archive current wallet before switching
 */
export function archiveCurrentWallet(currentWallet: WalletState): void {
  const source = getWalletSource();
  const archived: ArchivedWallet = {
    source,
    address: currentWallet.address,
    publicKey: currentWallet.publicKey,
    archivedAt: Date.now(),
  };

  if (source === 'tpm') {
    const tpmData = getStoredTpmWallet();
    if (tpmData) {
      archived.entropy = tpmData.entropy;
      archived.salt = tpmData.salt;
    }
  } else {
    // For standard wallets, we can get the private key
    archived.privateKey = currentWallet.privateKey;
  }

  // Add to archived wallets list
  const existingArchived = getArchivedWallets();
  existingArchived.push(archived);
  localStorage.setItem(ARCHIVED_WALLETS_KEY, JSON.stringify(existingArchived));

  console.log(`[Wallet] Archived ${source} wallet: ${currentWallet.address}`);
}

/**
 * Get list of archived wallets
 */
export function getArchivedWallets(): ArchivedWallet[] {
  const stored = localStorage.getItem(ARCHIVED_WALLETS_KEY);
  if (!stored) return [];
  try {
    return JSON.parse(stored) as ArchivedWallet[];
  } catch {
    return [];
  }
}

/**
 * Clear TPM wallet from storage
 */
export function clearTpmWallet(): void {
  localStorage.removeItem(TPM_WALLET_KEY);
  if (getWalletSource() === 'tpm') {
    setWalletSource('standard');
  }
  console.log('[TPM Wallet] Cleared from storage');
}

// ============================================================================
// Hardware Wallet Functions
// ============================================================================

/** Stored hardware wallet metadata */
export interface StoredHardwareWallet {
  address: string;
  publicKey: string;
  txHash: string;      // On-chain tx hash for recovery
  chainId: number;
  createdAt: number;
}

/**
 * Check if hardware wallet exists in storage
 */
export function hasHardwareWallet(): boolean {
  return localStorage.getItem(HARDWARE_WALLET_KEY) !== null;
}

/**
 * Get stored hardware wallet metadata
 */
export function getStoredHardwareWallet(): StoredHardwareWallet | null {
  const stored = localStorage.getItem(HARDWARE_WALLET_KEY);
  if (!stored) return null;
  try {
    const data = JSON.parse(stored) as StoredHardwareWallet;
    // Validate required fields
    if (!data.address || !data.txHash || !data.chainId) {
      console.warn('[Hardware Wallet] Invalid stored data, missing required fields');
      return null;
    }
    // publicKey might be missing from old buggy storage - that's OK, we'll recover it on unlock
    return data;
  } catch {
    return null;
  }
}

/**
 * Create a new hardware wallet
 * Stores encrypted device key on-chain, caches tx hash locally
 */
export async function createHardwareWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  txHash: string;
  isNew: boolean;
}> {
  if (!window.ethereum) {
    throw new Error('MetaMask not found. Install MetaMask and connect your hardware wallet.');
  }

  // Check if we already have a hardware wallet
  const existingWallet = getStoredHardwareWallet();
  if (existingWallet) {
    console.log('[Hardware Wallet] Loading existing wallet...');
    return loadHardwareWallet(config);
  }

  console.log('[Hardware Wallet] Creating new hardware wallet...');

  // Connect to MetaMask
  const browserProvider = new BrowserProvider(window.ethereum);
  await browserProvider.send('eth_requestAccounts', []);
  const metamaskSigner = await browserProvider.getSigner();
  const address = await metamaskSigner.getAddress();

  // Create chain device key manager
  const manager = new ChainDeviceKeyManager(config.network.rpc, config.network.chainId);

  // Setup: generates ECDH key, encrypts with signature, stores on-chain
  const result = await manager.setup(metamaskSigner);
  if (!result.success) {
    throw new Error(`Hardware wallet setup failed: ${result.error}`);
  }

  // Get the unlocked key pair
  const keyPair = manager.getKeyPair();

  // Store metadata locally
  const hwWalletData: StoredHardwareWallet = {
    address,
    publicKey: keyPair.publicKey,
    txHash: result.txHash!,
    chainId: config.network.chainId,
    createdAt: Date.now(),
  };
  localStorage.setItem(HARDWARE_WALLET_KEY, JSON.stringify(hwWalletData));

  // Set wallet source
  setWalletSource('hardware');

  // Create provider for blockchain operations
  const provider = new JsonRpcProvider(config.network.rpc);

  // Create signer wrapper - uses ECDH key for encryption, MetaMask for transactions
  const hwSigner = createHardwareSignerWrapper(keyPair, address, metamaskSigner, provider);

  // Get balance
  let balance = '0';
  try {
    const balanceWei = await provider.getBalance(address);
    balance = formatEther(balanceWei);
    console.log(`[Hardware Wallet] Balance: ${parseFloat(balance).toFixed(4)} ${getCurrencySymbol(config.network.chainId)}`);
  } catch (error) {
    console.warn('[Hardware Wallet] Could not fetch balance:', error);
  }

  console.log(`[Hardware Wallet] Created: ${address}`);

  return {
    wallet: {
      address,
      publicKey: keyPair.publicKey,
      privateKey: keyPair.privateKey,
      balance,
      signer: hwSigner,
      provider,
      isNew: true,
    },
    txHash: result.txHash!,
    isNew: true,
  };
}

/**
 * Load existing hardware wallet from storage
 * Requires signature to decrypt device key from chain
 */
export async function loadHardwareWallet(config: AppConfig): Promise<{
  wallet: WalletState;
  txHash: string;
  isNew: boolean;
}> {
  if (!window.ethereum) {
    throw new Error('MetaMask not found');
  }

  const stored = getStoredHardwareWallet();
  if (!stored) {
    throw new Error('No hardware wallet found in storage');
  }

  console.log('[Hardware Wallet] Loading from storage...');

  // Connect to MetaMask
  const browserProvider = new BrowserProvider(window.ethereum);
  await browserProvider.send('eth_requestAccounts', []);
  const metamaskSigner = await browserProvider.getSigner();
  const address = await metamaskSigner.getAddress();

  // Verify address matches
  if (address.toLowerCase() !== stored.address.toLowerCase()) {
    throw new Error(`Wrong wallet! Expected ${stored.address.slice(0,10)}..., got ${address.slice(0,10)}...`);
  }

  // Unlock from chain
  const manager = new ChainDeviceKeyManager(config.network.rpc, stored.chainId);
  const result = await manager.unlockFromCache(metamaskSigner);
  if (!result.success) {
    throw new Error(`Hardware wallet unlock failed: ${result.error}`);
  }

  // Get the unlocked key pair
  const keyPair = manager.getKeyPair();

  // Create provider and signer - uses ECDH key for encryption, MetaMask for transactions
  const provider = new JsonRpcProvider(config.network.rpc);
  const hwSigner = createHardwareSignerWrapper(keyPair, address, metamaskSigner, provider);

  // Get balance
  let balance = '0';
  try {
    const balanceWei = await provider.getBalance(address);
    balance = formatEther(balanceWei);
  } catch (error) {
    console.warn('[Hardware Wallet] Could not fetch balance:', error);
  }

  console.log(`[Hardware Wallet] Loaded: ${address}`);

  // Use keyPair.publicKey from decrypted data (stored.publicKey might be corrupted from old bug)
  const publicKey = keyPair.publicKey || stored.publicKey;

  // Update stored data if publicKey was missing
  if (!stored.publicKey && keyPair.publicKey) {
    const updatedData: StoredHardwareWallet = {
      ...stored,
      publicKey: keyPair.publicKey,
    };
    localStorage.setItem(HARDWARE_WALLET_KEY, JSON.stringify(updatedData));
    console.log('[Hardware Wallet] Updated stored publicKey from decrypted data');
  }

  return {
    wallet: {
      address,
      publicKey,
      privateKey: keyPair.privateKey,
      balance,
      signer: hwSigner,
      provider,
      isNew: false,
    },
    txHash: stored.txHash,
    isNew: false,
  };
}

/**
 * Create a RootzSigner for hardware wallet
 *
 * SIMPLE APPROACH: Use MetaMask signer directly for all signing/transaction operations.
 * Only add getPublicKey for ECDH encryption (the ECDH private key is stored in WalletState.privateKey).
 *
 * This works because:
 * - MetaMask signer is a proper ethers Signer that Contract understands
 * - Transactions are signed by the hardware wallet (Trezor/Ledger) via MetaMask
 * - ECDH encryption uses WalletState.privateKey directly (not through signer)
 * - getPublicKey returns the ECDH public key for encryption
 */
function createHardwareSignerWrapper(
  keyPair: { privateKey: string; publicKey: string },
  address: string,
  metamaskSigner: any,  // The MetaMask signer (JsonRpcSigner from BrowserProvider)
  provider: JsonRpcProvider
): RootzSigner {
  console.log('[Hardware Wallet] Creating simple signer wrapper...');
  console.log('[Hardware Wallet] MetaMask address:', address);
  console.log('[Hardware Wallet] ECDH public key:', keyPair.publicKey.slice(0, 20) + '...');

  // Use MetaMask signer directly - it's a proper ethers Signer
  // Just add the RootzSigner interface methods
  const signer = metamaskSigner;

  // Add getPublicKey for ECDH encryption operations
  (signer as any).getPublicKey = () => keyPair.publicKey;
  (signer as any).signerType = 'eoa' as const;

  // Make sure connect returns a properly augmented signer
  const originalConnect = signer.connect?.bind(signer);
  (signer as any).connect = (p: any) => {
    const connected = originalConnect ? originalConnect(p) : metamaskSigner;
    (connected as any).getPublicKey = () => keyPair.publicKey;
    (connected as any).signerType = 'eoa' as const;
    return connected;
  };

  console.log('[Hardware Wallet] Signer wrapper ready - using MetaMask directly for transactions');

  return signer as RootzSigner;
}

/**
 * Clear hardware wallet from storage
 */
export function clearHardwareWallet(): void {
  localStorage.removeItem(HARDWARE_WALLET_KEY);
  clearDeviceKeyCache();
  if (getWalletSource() === 'hardware') {
    setWalletSource('standard');
  }
  console.log('[Hardware Wallet] Cleared from storage');
}
