/**
 * Archive Tab - "Thinking as Asset"
 *
 * Browse, search, and manage local archives of AI conversations.
 * Archives capture the full thinking process for future replay.
 */

// Types for archive data
export interface LocalArchive {
  id: string;
  title: string;
  content: string;
  contentHash?: string;
  transcript?: string;
  transcriptHash?: string;
  sessionId?: string;
  source: 'local' | 'chain';
  secretAddress?: string;
  templateType?: string;
  tags: string[];
  messageCount?: number;
  createdAt: number;
  updatedAt: number;
  // Search result extras
  score?: number;
  snippet?: string;
  matchedIn?: ('title' | 'content' | 'transcript' | 'tags')[];
}

export interface ArchiveStats {
  totalArchives: number;
  localArchives: number;
  chainArchives: number;
  totalTags: number;
  totalDecisions: number;
}

export interface ArchiveTabState {
  wallet: {
    address: string;
  };
}

// Project config interface
export interface ProjectConfig {
  projectSlug: string;
  secretAddress: string;
  chainId: number;
  totalChunksArchived: number;
  totalBytesArchived: number;
  lastArchivedAt?: number;
}

// Project with pending chunks data
interface ProjectWithPending {
  projectSlug: string;
  subDirectory?: string;       // Subdirectory within project (e.g., "rootz-v6")
  effectiveKey: string;        // Combined key for lookups (slug + subdir)
  pendingChunks: number;
  totalSize: number;
  config: ProjectConfig | null;
}

/**
 * Get the effective project key for archive operations.
 * Matches the logic in database.ts for subdirectory-based organization.
 */
function getEffectiveProjectKey(projectSlug: string, subDirectory?: string): string {
  if (subDirectory) {
    // Extract a shorter base name from the slug
    const parts = projectSlug.split('-').filter(p => p.length > 0);
    let shortBase = 'project';
    for (let i = 0; i < parts.length; i++) {
      if (parts[i].toLowerCase().includes('claud')) {
        shortBase = parts.slice(i, Math.min(i + 2, parts.length)).join('-');
        break;
      }
    }
    return `${shortBase}--${subDirectory}`;
  }
  return projectSlug;
}

