/**
 * Show a simple push confirmation modal.
 * Returns '0' (push all) on confirm, null on cancel.
 */
function showPushConfirmModal(
  _title: string,
  message: string,
  _defaultValue: string = '0'
): Promise<string | null> {
  return new Promise((resolve) => {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.display = 'flex';
    modal.innerHTML = `
      <div class="modal-backdrop"></div>
      <div class="modal-content" style="max-width: 400px;">
        <div class="modal-body" style="padding: 1.5rem;">
          <div style="margin-bottom: 1.25rem; font-size: 0.95rem; line-height: 1.6;">${message}</div>
          <div style="display: flex; gap: 0.75rem;">
            <button id="push-modal-cancel" class="secondary" style="flex: 1;">Cancel</button>
            <button id="push-modal-confirm" class="primary" style="flex: 1;">Push All</button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const cancelBtn = modal.querySelector('#push-modal-cancel') as HTMLButtonElement;
    const confirmBtn = modal.querySelector('#push-modal-confirm') as HTMLButtonElement;
    const backdrop = modal.querySelector('.modal-backdrop') as HTMLElement;

    // Focus confirm button
    setTimeout(() => confirmBtn.focus(), 100);

    // Handle Escape key
    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        modal.remove();
        document.removeEventListener('keydown', handleKeydown);
        resolve(null);
      } else if (e.key === 'Enter') {
        modal.remove();
        document.removeEventListener('keydown', handleKeydown);
        resolve('0'); // Push all
      }
    };
    document.addEventListener('keydown', handleKeydown);

    cancelBtn.addEventListener('click', () => {
      modal.remove();
      document.removeEventListener('keydown', handleKeydown);
      resolve(null);
    });

    confirmBtn.addEventListener('click', () => {
      modal.remove();
      document.removeEventListener('keydown', handleKeydown);
      resolve('0'); // Push all
    });

    backdrop.addEventListener('click', () => {
      modal.remove();
      document.removeEventListener('keydown', handleKeydown);
      resolve(null);
    });
  });
}

/**
 * Show archive stats in a modal.
 * Displays session count, message count, and on-chain archive count.
 */
function showArchiveStatsModal(stats: {
  totalSessions?: number;
  totalMessages?: number;
  chainArchives?: { title: string; address: string; createdAt?: string }[];
  error?: string;
}): void {
  const modal = document.createElement('div');
  modal.className = 'modal';
  modal.style.display = 'flex';

  const chainCount = stats.chainArchives?.length ?? 0;
  const recentArchives = stats.chainArchives?.slice(0, 10) ?? [];

  modal.innerHTML = `
    <div class="modal-backdrop"></div>
    <div class="modal-content" style="max-width: 500px;">
      <div class="modal-header">
        <h3>Archive Statistics</h3>
        <button class="modal-close">&times;</button>
      </div>
      <div class="modal-body" style="padding: 1.5rem;">
        ${stats.error ? `
          <div class="archive-error" style="color: var(--error); margin-bottom: 1rem;">${stats.error}</div>
        ` : ''}

        <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin-bottom: 1.5rem;">
          <div style="text-align: center; padding: 1rem; background: var(--bg-secondary); border-radius: 8px;">
            <div style="font-size: 1.75rem; font-weight: bold; color: var(--primary);">${stats.totalSessions ?? '-'}</div>
            <div style="font-size: 0.85rem; color: var(--text-secondary);">Sessions</div>
          </div>
          <div style="text-align: center; padding: 1rem; background: var(--bg-secondary); border-radius: 8px;">
            <div style="font-size: 1.75rem; font-weight: bold; color: var(--primary);">${stats.totalMessages ?? '-'}</div>
            <div style="font-size: 0.85rem; color: var(--text-secondary);">Messages</div>
          </div>
          <div style="text-align: center; padding: 1rem; background: var(--bg-secondary); border-radius: 8px;">
            <div style="font-size: 1.75rem; font-weight: bold; color: var(--success);">${chainCount}</div>
            <div style="font-size: 0.85rem; color: var(--text-secondary);">On-Chain</div>
          </div>
        </div>

        ${recentArchives.length > 0 ? `
          <div style="margin-top: 1rem;">
            <h4 style="margin-bottom: 0.75rem; font-size: 0.9rem;">Recent On-Chain Archives</h4>
            <div style="max-height: 200px; overflow-y: auto; font-size: 0.85rem;">
              ${recentArchives.map(a => `
                <div style="padding: 0.5rem 0; border-bottom: 1px solid var(--border-color);">
                  <div style="font-weight: 500;">${a.title}</div>
                  <div style="color: var(--text-secondary); font-size: 0.75rem;">
                    ${a.address.slice(0, 10)}...${a.address.slice(-6)}
                    ${a.createdAt ? ` | ${new Date(a.createdAt).toLocaleDateString()}` : ''}
                  </div>
                </div>
              `).join('')}
            </div>
          </div>
        ` : ''}

        <div style="margin-top: 1.5rem; text-align: right;">
          <button class="primary modal-close-btn">Close</button>
        </div>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  // Close handlers
  const closeModal = () => modal.remove();
  modal.querySelector('.modal-backdrop')?.addEventListener('click', closeModal);
  modal.querySelector('.modal-close')?.addEventListener('click', closeModal);
  modal.querySelector('.modal-close-btn')?.addEventListener('click', closeModal);

  const handleKeydown = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      closeModal();
      document.removeEventListener('keydown', handleKeydown);
    }
  };
  document.addEventListener('keydown', handleKeydown);
}

