/**
 * Render the archive list
 */
function renderArchiveList(archiveList: LocalArchive[]): string {
  if (archiveList.length === 0) {
    return `
      <div class="archive-empty">
        <div class="empty-icon">📚</div>
        <h3>No archives yet</h3>
        <p>Archives will appear here as you capture AI conversations.</p>
        <p class="hint">Use Claude Code MCP tools or the browser extension to create archives.</p>
      </div>
    `;
  }

  return archiveList.map(archive => {
    const title = archive.title || 'Untitled Archive';
    const content = archive.content || '';
    const tags = archive.tags || [];
    const source = archive.source || 'local';
    const matchedIn = archive.matchedIn || [];
    const snippet = archive.snippet;

    // Determine preview text - use snippet if from search, otherwise content preview
    let previewText = '';
    if (snippet) {
      previewText = escapeHtml(snippet);
    } else if (content) {
      previewText = `${escapeHtml(content.substring(0, 150))}${content.length > 150 ? '...' : ''}`;
    } else {
      previewText = '<em>No content</em>';
    }

    return `
    <div class="archive-card" data-id="${archive.id}">
      <div class="archive-card-header">
        <span class="archive-source ${source}">${source === 'chain' ? '⛓️' : '💾'}</span>
        <span class="archive-date">${formatDate(archive.createdAt)}</span>
        ${archive.score ? `<span class="archive-score" title="Relevance score">🎯 ${archive.score}</span>` : ''}
      </div>
      <h3 class="archive-card-title">${escapeHtml(title)}</h3>
      <div class="archive-card-meta">
        ${archive.templateType ? `<span class="archive-template">${TEMPLATE_LABELS[archive.templateType] || archive.templateType}</span>` : ''}
        ${archive.transcript ? '<span class="archive-has-transcript" title="Has full transcript">📜</span>' : ''}
        ${archive.messageCount ? `<span class="archive-messages">${archive.messageCount} msgs</span>` : ''}
        ${matchedIn.length > 0 ? `<span class="archive-matched-in" title="Matched in: ${matchedIn.join(', ')}">📍 ${matchedIn.join(', ')}</span>` : ''}
      </div>
      <div class="archive-card-tags">
        ${tags.slice(0, 4).map(tag => `<span class="archive-tag">${escapeHtml(tag)}</span>`).join('')}
        ${tags.length > 4 ? `<span class="archive-tag more">+${tags.length - 4}</span>` : ''}
      </div>
      <div class="archive-card-preview">
        ${previewText}
      </div>
    </div>
  `;
  }).join('');
}

