/**
 * Load archives from API
 * Uses advanced search when any search filters are active
 */
async function loadArchives(): Promise<void> {
  isLoading = true;
  try {
    // Check if we need advanced search (any filters active)
    const needsAdvancedSearch = searchQuery ||
      includeTranscript ||
      dateFrom ||
      dateTo ||
      hasTranscriptFilter !== 'all' ||
      selectedTag ||
      selectedTemplate;

    if (needsAdvancedSearch) {
      // Use advanced search endpoint
      const body: Record<string, unknown> = {
        query: searchQuery || undefined,
        includeTranscript,
        limit: 50
      };

      // Add date filters
      if (dateFrom) {
        body.dateFrom = new Date(dateFrom).getTime();
      }
      if (dateTo) {
        // End of day
        body.dateTo = new Date(dateTo).getTime() + (24 * 60 * 60 * 1000) - 1;
      }

      // Has transcript filter
      if (hasTranscriptFilter === 'yes') {
        body.hasTranscript = true;
      } else if (hasTranscriptFilter === 'no') {
        body.hasTranscript = false;
      }

      // Tag filter
      if (selectedTag) {
        body.tags = [selectedTag];
      }

      // Template filter
      if (selectedTemplate) {
        body.templateType = selectedTemplate;
      }

      const response = await fetch(`${API_BASE}/api/local-archives/advanced-search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json();
      archives = data.archives || [];
    } else {
      // Simple list
      const response = await fetch(`${API_BASE}/api/local-archives`);
      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json();
      archives = data.archives || [];
    }
  } catch (error) {
    console.error('[Archive] Failed to load archives:', error);
    archives = [];
    updateStatus(`Failed to load archives: ${error}`, 'error');
  } finally {
    isLoading = false;
  }
}

