/**
 * Load projects with pending chunks
 */
async function loadProjectsWithPending(): Promise<void> {
  try {
    // Get pending chunks
    const pendingResponse = await fetch(`${API_BASE}/api/transcript-archive/pending`);
    if (!pendingResponse.ok) {
      projectsWithPending = [];
      return;
    }
    const pendingData = await pendingResponse.json();

    // Get project configs
    const configsResponse = await fetch(`${API_BASE}/api/transcript-archive/projects`);
    const configsData = configsResponse.ok ? await configsResponse.json() : { projects: [] };
    const configsBySlug = new Map<string, ProjectConfig>();
    for (const config of configsData.projects || []) {
      configsBySlug.set(config.projectSlug, config);
    }

    // Group pending chunks by effective key (includes subdirectory)
    const chunksByEffectiveKey = new Map<string, {
      projectSlug: string;
      subDirectory?: string;
      count: number;
      size: number;
    }>();
    for (const chunk of pendingData.chunks || []) {
      const effectiveKey = getEffectiveProjectKey(chunk.projectSlug, chunk.subDirectory);
      const existing = chunksByEffectiveKey.get(effectiveKey) || {
        projectSlug: chunk.projectSlug,
        subDirectory: chunk.subDirectory,
        count: 0,
        size: 0
      };
      existing.count++;
      existing.size += chunk.compressedSize || 0;
      chunksByEffectiveKey.set(effectiveKey, existing);
    }

    // Build projects with pending data
    projectsWithPending = [];
    for (const [effectiveKey, data] of chunksByEffectiveKey) {
      projectsWithPending.push({
        projectSlug: data.projectSlug,
        subDirectory: data.subDirectory,
        effectiveKey,
        pendingChunks: data.count,
        totalSize: data.size,
        config: configsBySlug.get(effectiveKey) || null,
      });
    }

    // Sort by pending count (most pending first)
    projectsWithPending.sort((a, b) => b.pendingChunks - a.pendingChunks);
  } catch (error) {
    console.error('[Archive] Failed to load projects:', error);
    projectsWithPending = [];
  }
}

/**
 * Render projects list
 */
function renderProjectsList(): string {
  if (projectsWithPending.length === 0) {
    return `
      <div class="archive-empty small">
        <p>No projects with pending archives.</p>
        <p class="hint">Click "Archive Now" to capture conversations, then configure secrets here.</p>
      </div>
    `;
  }

  return projectsWithPending.map(project => {
    const hasSecret = !!project.config?.secretAddress;
    const secretBadge = hasSecret
      ? `<span class="status-badge confirmed" title="Secret: ${project.config!.secretAddress}">✓ Secret configured</span>`
      : `<span class="status-badge pending">⚠️ No secret</span>`;

    // Display subdirectory prominently if present
    const displayName = project.subDirectory
      ? `📁 ${project.subDirectory}`
      : truncateSlug(project.projectSlug);
    const fullPath = project.subDirectory
      ? `${project.projectSlug} / ${project.subDirectory}`
      : project.projectSlug;

    return `
      <div class="project-card" data-slug="${escapeHtml(project.effectiveKey)}">
        <div class="project-header">
          <span class="project-name" title="${escapeHtml(fullPath)}">${escapeHtml(displayName)}</span>
          ${secretBadge}
        </div>
        ${project.subDirectory ? `<div class="project-subdir" style="font-size: 0.75rem; color: #9ca3af; margin-bottom: 0.5rem;">in ${escapeHtml(truncateSlug(project.projectSlug))}</div>` : ''}
        <div class="project-stats">
          <span class="stat">${project.pendingChunks} pending chunk(s)</span>
          <span class="stat">${formatBytes(project.totalSize)}</span>
        </div>
        <div class="project-actions">
          ${hasSecret
            ? `<span class="secret-address" title="${project.config!.secretAddress}">${project.config!.secretAddress.substring(0, 10)}...${project.config!.secretAddress.substring(project.config!.secretAddress.length - 6)}</span>`
            : `<button class="primary small create-secret-btn" data-slug="${escapeHtml(project.effectiveKey)}">Create Secret</button>`
          }
        </div>
      </div>
    `;
  }).join('');
}

/**
 * Truncate project slug for display
 */
function truncateSlug(slug: string): string {
  if (slug.length <= 40) return slug;
  return slug.substring(0, 20) + '...' + slug.substring(slug.length - 15);
}

