/**
 * Setup detail view event handlers
 */
function setupDetailHandlers(archive: LocalArchive): void {
  // Back button
  document.getElementById('archive-back-btn')?.addEventListener('click', () => {
    currentView = 'list';
    selectedArchiveId = null;

    const listView = document.getElementById('archive-list-view');
    const detailView = document.getElementById('archive-detail-view');

    if (listView) listView.style.display = 'block';
    if (detailView) detailView.style.display = 'none';
  });

  // Copy button
  document.getElementById('archive-copy-btn')?.addEventListener('click', () => {
    navigator.clipboard.writeText(archive.content);
    updateStatus('Content copied to clipboard', 'success');
  });

  // Delete button
  document.getElementById('archive-delete-btn')?.addEventListener('click', async () => {
    if (!confirm(`Delete archive "${archive.title}"?\n\nThis cannot be undone.`)) {
      return;
    }

    try {
      const response = await fetch(`${API_BASE}/api/local-archives/${encodeURIComponent(archive.id)}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      updateStatus('Archive deleted', 'success');

      // Go back to list and refresh
      currentView = 'list';
      selectedArchiveId = null;

      const listView = document.getElementById('archive-list-view');
      const detailView = document.getElementById('archive-detail-view');

      if (listView) listView.style.display = 'block';
      if (detailView) detailView.style.display = 'none';

      await loadArchives();
      await loadStats();
      updateListView();
      updateStatsDisplay();
    } catch (error) {
      console.error('[Archive] Failed to delete archive:', error);
      updateStatus(`Failed to delete: ${error}`, 'error');
    }
  });

  // Tab switching
  document.querySelectorAll('.archive-detail-tabs .tab-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      const tabName = target.getAttribute('data-tab');

      // Update active tab button
      document.querySelectorAll('.archive-detail-tabs .tab-btn').forEach(b => b.classList.remove('active'));
      target.classList.add('active');

      // Show correct pane
      document.querySelectorAll('.archive-tab-pane').forEach(pane => {
        (pane as HTMLElement).style.display = 'none';
      });
      const pane = document.getElementById(`archive-tab-${tabName}`);
      if (pane) pane.style.display = 'block';
    });
  });
}

