// Utility functions

function escapeHtml(text: string): string {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

function formatDate(timestamp: number): string {
  const date = new Date(timestamp);
  const now = new Date();
  const diff = now.getTime() - date.getTime();
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (days === 0) {
    const hours = Math.floor(diff / (1000 * 60 * 60));
    if (hours === 0) {
      const minutes = Math.floor(diff / (1000 * 60));
      return minutes <= 1 ? 'Just now' : `${minutes}m ago`;
    }
    return `${hours}h ago`;
  }
  if (days === 1) return 'Yesterday';
  if (days < 7) return `${days}d ago`;

  return date.toLocaleDateString();
}

function formatDateTime(timestamp: number): string {
  return new Date(timestamp).toLocaleString();
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatMarkdown(content: string): string {
  // Basic markdown formatting
  let html = escapeHtml(content);

  // Headers
  html = html.replace(/^### (.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^## (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^# (.+)$/gm, '<h2>$1</h2>');

  // Bold
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

  // Italic
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');

  // Code blocks
  html = html.replace(/```(\w*)\n([\s\S]*?)```/g, '<pre class="code-block"><code>$2</code></pre>');

  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Lists
  html = html.replace(/^- (.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');

  // Line breaks (double newline = paragraph)
  html = html.replace(/\n\n/g, '</p><p>');
  html = `<p>${html}</p>`;

  // Clean up empty paragraphs
  html = html.replace(/<p>\s*<\/p>/g, '');
  html = html.replace(/<p>\s*<(h[234]|ul|pre)/g, '<$1');
  html = html.replace(/<\/(h[234]|ul|pre)>\s*<\/p>/g, '</$1>');

  return html;
}

// =============================================================================
// TRANSCRIPT ARCHIVES (Local + Blockchain)
// =============================================================================

interface TranscriptChunk {
  id: string;
  chunkIndex: number;
  lineRange: [number, number];
  compressedSize: number;
  originalSize: number;
  status: 'pending' | 'uploaded' | 'confirmed';
  contentHash: string;
  createdAt: number;
  archivedAt: number | null;
  txHash?: string;
  blockNumber?: number;
}

interface AllChunksData {
  local: Record<string, TranscriptChunk[]>;
  blockchain: Record<string, TranscriptChunk[]>;
  stats: {
    localSessions: number;
    localChunks: number;
    localBytes: number;
    blockchainSessions: number;
    blockchainChunks: number;
    blockchainBytes: number;
  };
}

let allChunksData: AllChunksData | null = null;

/**
 * Load transcript archives from API (both local and blockchain)
 */
async function loadTranscriptArchives(): Promise<void> {
  try {
    const response = await fetch(`${API_BASE}/api/transcript-archive/all-chunks`);
    if (!response.ok) {
      throw new Error(`API error: ${response.status}`);
    }
    allChunksData = await response.json();
  } catch (error) {
    console.error('[Archive] Failed to load transcript archives:', error);
    allChunksData = null;
  }
}

/**
 * Render transcript archives list (both local and blockchain sections)
 */
function renderTranscriptArchivesList(): string {
  if (!allChunksData) {
    return `
      <div class="archive-empty small">
        <p>Failed to load transcript archives.</p>
      </div>
    `;
  }

  const { local, blockchain, stats } = allChunksData;
  const hasLocal = stats.localSessions > 0;
  const hasBlockchain = stats.blockchainSessions > 0;

  if (!hasLocal && !hasBlockchain) {
    return `
      <div class="archive-empty small">
        <p>No transcript archives yet.</p>
        <p class="hint">Click "Archive Now" below to capture Claude Code conversations.</p>
      </div>
    `;
  }

  // Render local chunks section
  const localSection = hasLocal ? `
    <div class="transcript-group">
      <div class="group-header local">
        <span class="group-icon">💾</span>
        <span class="group-title">Local Archives</span>
        <span class="group-stats">${stats.localSessions} session(s) • ${stats.localChunks} chunk(s) • ${formatBytes(stats.localBytes)}</span>
      </div>
      <div class="transcript-sessions">
        ${Object.entries(local).map(([sessionId, chunks]) => {
          const totalSize = chunks.reduce((sum, c) => sum + c.originalSize, 0);
          const latestChunk = chunks.sort((a, b) => b.createdAt - a.createdAt)[0];
          return `
            <div class="transcript-session-card local" data-session-id="${sessionId}">
              <div class="session-header">
                <span class="session-icon">💾</span>
                <span class="session-id">${sessionId.substring(0, 8)}...</span>
                <span class="session-date">${formatDate(latestChunk.createdAt)}</span>
              </div>
              <div class="session-meta">
                <span>${chunks.length} chunk(s)</span>
                <span>•</span>
                <span>${formatBytes(totalSize)}</span>
                <span class="status-badge pending">Local Only</span>
              </div>
              <div class="session-actions">
                <button class="secondary small view-transcript-btn" data-session-id="${sessionId}">View Details</button>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  ` : '';

  // Render blockchain chunks section
  const blockchainSection = hasBlockchain ? `
    <div class="transcript-group">
      <div class="group-header blockchain">
        <span class="group-icon">⛓️</span>
        <span class="group-title">Blockchain Archives</span>
        <span class="group-stats">${stats.blockchainSessions} session(s) • ${stats.blockchainChunks} chunk(s) • ${formatBytes(stats.blockchainBytes)}</span>
      </div>
      <div class="transcript-sessions">
        ${Object.entries(blockchain).map(([sessionId, chunks]) => {
          const totalSize = chunks.reduce((sum, c) => sum + c.originalSize, 0);
          const latestChunk = chunks.sort((a, b) => (b.archivedAt || 0) - (a.archivedAt || 0))[0];
          return `
            <div class="transcript-session-card blockchain" data-session-id="${sessionId}">
              <div class="session-header">
                <span class="session-icon">⛓️</span>
                <span class="session-id">${sessionId.substring(0, 8)}...</span>
                <span class="session-date">${formatDate(latestChunk.archivedAt || latestChunk.createdAt)}</span>
              </div>
              <div class="session-meta">
                <span>${chunks.length} chunk(s)</span>
                <span>•</span>
                <span>${formatBytes(totalSize)}</span>
                <span class="status-badge confirmed">On Chain</span>
              </div>
              <div class="session-actions">
                <button class="secondary small view-transcript-btn" data-session-id="${sessionId}">View Details</button>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  ` : '';

  // Combined summary at top
  const totalSessions = stats.localSessions + stats.blockchainSessions;
  const totalChunks = stats.localChunks + stats.blockchainChunks;
  const totalBytes = stats.localBytes + stats.blockchainBytes;

  return `
    <div class="transcript-summary">
      <span>${totalSessions} session(s)</span>
      <span>•</span>
      <span>${totalChunks} chunk(s)</span>
      <span>•</span>
      <span>${formatBytes(totalBytes)} total</span>
    </div>
    ${localSection}
    ${blockchainSection}
  `;
}

/**
 * Update transcript archives display
 */
function updateTranscriptArchivesView(): void {
  const listEl = document.getElementById('transcript-archives-list');
  if (listEl) {
    listEl.innerHTML = renderTranscriptArchivesList();
    setupTranscriptArchiveHandlers();
  }
}

/**
 * Setup handlers for transcript archive cards
 */
function setupTranscriptArchiveHandlers(): void {
  document.querySelectorAll('.view-transcript-btn').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const sessionId = (e.target as HTMLElement).getAttribute('data-session-id');
      if (sessionId) {
        await showTranscriptSessionDetail(sessionId);
      }
    });
  });
}

/**
 * Show transcript session detail
 */
async function showTranscriptSessionDetail(sessionId: string): Promise<void> {
  try {
    const response = await fetch(`${API_BASE}/api/transcript-archive/sessions/${encodeURIComponent(sessionId)}/chunks`);
    if (!response.ok) {
      throw new Error(`API error: ${response.status}`);
    }

    const data = await response.json();
    const chunks = data.chunks || [];

    // Get the first chunk's content info
    let contentInfo = null;
    if (chunks.length > 0) {
      try {
        const contentResponse = await fetch(`${API_BASE}/api/transcript-archive/chunks/${encodeURIComponent(chunks[0].id)}/content`);
        if (contentResponse.ok) {
          contentInfo = await contentResponse.json();
        }
      } catch (e) {
        console.error('[Archive] Failed to get content info:', e);
      }
    }

    // Show modal with session details
    showTranscriptModal(sessionId, chunks, contentInfo);
  } catch (error) {
    console.error('[Archive] Failed to load session details:', error);
    updateStatus(`Failed to load session: ${error}`, 'error');
  }
}

/**
 * Show transcript modal with session details
 */
function showTranscriptModal(
  sessionId: string,
  chunks: Array<{
    id: string;
    chunkIndex: number;
    lineCount: number;
    originalSize: number;
    compressedSize: number;
    status: string;
    archivedAt: number;
    txHash: string | null;
  }>,
  contentInfo: {
    source: string;
    content: string | null;
    message?: string;
    secretAddress?: string;
    chainId?: number;
    viewUrl?: string;
  } | null
): void {
  // Remove existing modal if any
  document.getElementById('transcript-modal')?.remove();

  const totalSize = chunks.reduce((sum, c) => sum + c.originalSize, 0);
  const totalCompressed = chunks.reduce((sum, c) => sum + c.compressedSize, 0);

  const modal = document.createElement('div');
  modal.id = 'transcript-modal';
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal-content transcript-session-modal">
      <div class="modal-header">
        <h3>📜 Transcript Session</h3>
        <button class="modal-close" id="transcript-modal-close">✕</button>
      </div>
      <div class="modal-body">
        <div class="session-info">
          <div class="info-row">
            <span class="info-label">Session ID:</span>
            <span class="info-value session-id-full">${sessionId}</span>
            <button class="copy-btn small" data-copy="${sessionId}">Copy</button>
          </div>
          <div class="info-row">
            <span class="info-label">Chunks:</span>
            <span class="info-value">${chunks.length}</span>
          </div>
          <div class="info-row">
            <span class="info-label">Original Size:</span>
            <span class="info-value">${formatBytes(totalSize)}</span>
          </div>
          <div class="info-row">
            <span class="info-label">Compressed:</span>
            <span class="info-value">${formatBytes(totalCompressed)} (${Math.round((1 - totalCompressed / totalSize) * 100)}% reduction)</span>
          </div>
          ${contentInfo?.secretAddress ? `
            <div class="info-row">
              <span class="info-label">Secret Address:</span>
              <span class="info-value">${contentInfo.secretAddress}</span>
              <button class="copy-btn small" data-copy="${contentInfo.secretAddress}">Copy</button>
            </div>
          ` : ''}
        </div>

        <div class="chunks-section">
          <h4>Chunks</h4>
          <div class="chunks-list">
            ${chunks.map(chunk => `
              <div class="chunk-item">
                <div class="chunk-info">
                  <span class="chunk-index">#${chunk.chunkIndex}</span>
                  <span class="chunk-size">${formatBytes(chunk.originalSize)}</span>
                  <span class="chunk-status ${chunk.status}">${chunk.status}</span>
                </div>
                ${chunk.txHash ? `
                  <div class="chunk-tx">
                    <a href="https://polygonscan.com/tx/${chunk.txHash}" target="_blank" class="tx-link">
                      View TX ↗
                    </a>
                  </div>
                ` : ''}
              </div>
            `).join('')}
          </div>
        </div>

        <div class="content-section">
          <h4>Content</h4>
          <div id="transcript-content-area">
            ${(contentInfo?.source === 'local' || contentInfo?.source === 'local-decrypted') && contentInfo.content ? `
              <div class="content-preview">
                <pre class="transcript-content">${escapeHtml(contentInfo.content.substring(0, 10000))}${contentInfo.content.length > 10000 ? '\n\n... (truncated)' : ''}</pre>
              </div>
              <button class="primary" id="copy-transcript-content">Copy Full Content</button>
            ` : contentInfo?.source === 'blockchain' ? `
              <div class="blockchain-notice">
                <p>⛓️ Content is stored encrypted on the blockchain.</p>
                <p>Click "Decrypt & Cache" to fetch and store content locally for easy viewing.</p>
                ${contentInfo.secretAddress ? `
                  <p class="secret-address">Secret: ${contentInfo.secretAddress}</p>
                ` : ''}
              </div>
              <button class="primary" id="decrypt-transcript-btn" data-session-id="${sessionId}">Decrypt & Cache</button>
            ` : `
              <div class="no-content-notice">
                <p>Content information not available.</p>
              </div>
            `}
          </div>
        </div>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  // Close handlers
  document.getElementById('transcript-modal-close')?.addEventListener('click', () => {
    modal.remove();
  });

  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      modal.remove();
    }
  });

  // Copy handlers
  modal.querySelectorAll('.copy-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const text = btn.getAttribute('data-copy');
      if (text) {
        navigator.clipboard.writeText(text);
        updateStatus('Copied to clipboard', 'success');
      }
    });
  });

  // Copy content button
  if (contentInfo?.content) {
    document.getElementById('copy-transcript-content')?.addEventListener('click', () => {
      navigator.clipboard.writeText(contentInfo.content!);
      updateStatus('Transcript content copied to clipboard', 'success');
    });
  }

  // Decrypt button handler
  document.getElementById('decrypt-transcript-btn')?.addEventListener('click', async (e) => {
    const btn = e.target as HTMLButtonElement;
    const sessionIdToDecrypt = btn.getAttribute('data-session-id');
    if (!sessionIdToDecrypt) return;

    btn.textContent = 'Decrypting...';
    btn.disabled = true;

    try {
      const response = await fetch(`${API_BASE}/api/transcript-archive/decrypt/${encodeURIComponent(sessionIdToDecrypt)}`);
      const result = await response.json();

      if (!response.ok || !result.success) {
        throw new Error(result.error || result.message || 'Failed to decrypt');
      }

      updateStatus(`Decrypted ${result.matchedChunks} chunk(s) successfully`, 'success');

      // Refresh the content area with decrypted content
      if (result.chunks && result.chunks.length > 0) {
        const contentArea = document.getElementById('transcript-content-area');
        if (contentArea) {
          // Fetch full content from the first chunk
          const chunkResponse = await fetch(`${API_BASE}/api/transcript-archive/chunks/${encodeURIComponent(result.chunks[0].id)}/content`);
          const chunkData = await chunkResponse.json();

          if (chunkData.content) {
            contentArea.innerHTML = `
              <div class="content-preview">
                <pre class="transcript-content">${escapeHtml(chunkData.content.substring(0, 10000))}${chunkData.content.length > 10000 ? '\n\n... (truncated)' : ''}</pre>
              </div>
              <button class="primary" id="copy-transcript-content-refreshed">Copy Full Content</button>
            `;
            // Re-add copy handler
            document.getElementById('copy-transcript-content-refreshed')?.addEventListener('click', () => {
              navigator.clipboard.writeText(chunkData.content);
              updateStatus('Transcript content copied to clipboard', 'success');
            });
          }
        }
      }
    } catch (error) {
      console.error('[Archive] Decrypt error:', error);
      updateStatus(`Failed to decrypt: ${error instanceof Error ? error.message : String(error)}`, 'error');
      btn.textContent = 'Decrypt & Cache';
      btn.disabled = false;
    }
  });
}

// =============================================================================
// TRANSCRIPT SEARCH (Indexed Content)
// =============================================================================

interface SearchResult {
  id: string;
  sessionId: string;
  turnIndex: number;
  role: 'human' | 'assistant';
  contentPreview: string;
  toolsUsed?: string[];
  filesReferenced?: string[];
  timestamp?: number;
  session?: {
    projectSlug: string;
    totalTurns: number;
    topics: string[];
  };
}

interface SessionResult {
  sessionId: string;
  projectSlug: string;
  summary?: string;
  totalTurns: number;
  filesRead: string[];
  filesWritten: string[];
  toolsUsed: string[];
  topics: string[];
  codeLanguages: string[];
  hasErrors: boolean;
  firstMessageAt?: number;
  lastMessageAt?: number;
}

interface SearchStats {
  totalSessions: number;
  totalMessages: number;
  uniqueFiles: number;
  uniqueTools: number;
  sessionsWithErrors: number;
}

let searchStats: SearchStats | null = null;

/**
 * Load search statistics
 */
async function loadSearchStats(): Promise<void> {
  try {
    const response = await fetch(`${API_BASE}/api/archive-search/stats`);
    if (response.ok) {
      searchStats = await response.json();
      updateSearchStatsDisplay();
    }
  } catch (error) {
    console.error('[Archive] Failed to load search stats:', error);
  }
}

/**
 * Update search stats display
 */
function updateSearchStatsDisplay(): void {
  const statsEl = document.getElementById('search-stats');
  if (!statsEl || !searchStats) return;

  if (searchStats.totalMessages === 0) {
    statsEl.innerHTML = '<span class="stat-empty">No indexed content yet</span>';
  } else {
    statsEl.innerHTML = `
      <span class="stat-item">${searchStats.totalSessions} sessions</span>
      <span class="stat-item">${searchStats.totalMessages} messages</span>
      <span class="stat-item">${searchStats.uniqueFiles} files</span>
    `;
  }
}

/**
 * Setup transcript search event handlers
 */
function setupTranscriptSearchHandlers(): void {
  // Search button
  document.getElementById('transcript-search-btn')?.addEventListener('click', handleTranscriptSearch);

  // Search on Enter key
  document.getElementById('transcript-search-input')?.addEventListener('keypress', (e) => {
    if ((e as KeyboardEvent).key === 'Enter') {
      handleTranscriptSearch();
    }
  });

  // Filter type changes
  document.getElementById('search-filter-type')?.addEventListener('change', () => {
    // Clear results when type changes
    const resultsEl = document.getElementById('transcript-search-results');
    if (resultsEl) {
      resultsEl.innerHTML = '<div class="search-empty">Enter a search term to find past conversations</div>';
    }
  });

  // Reindex button
  document.getElementById('reindex-btn')?.addEventListener('click', handleReindex);
}

/**
 * Handle reindex request - index existing chunks for search
 */
async function handleReindex(): Promise<void> {
  const btn = document.getElementById('reindex-btn') as HTMLButtonElement;
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Indexing...';
  }

  try {
    updateStatus('Reindexing archives for search...', 'info');

    const response = await fetch(`${API_BASE}/api/archive-search/reindex`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ limit: 500 }),
    });

    const result = await response.json();

    if (!response.ok) {
      throw new Error(result.error || 'Reindex failed');
    }

    updateStatus(`Reindex complete: ${result.indexed} chunks indexed, ${result.errors} errors`, 'success');

    // Refresh search stats
    loadSearchStats();
  } catch (error) {
    console.error('[Archive] Reindex error:', error);
    updateStatus(`Reindex failed: ${error instanceof Error ? error.message : String(error)}`, 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Reindex';
    }
  }
}

/**
 * Handle transcript search
 */
async function handleTranscriptSearch(): Promise<void> {
  const input = document.getElementById('transcript-search-input') as HTMLInputElement;
  const filterType = (document.getElementById('search-filter-type') as HTMLSelectElement).value;
  const filterRole = (document.getElementById('search-filter-role') as HTMLSelectElement).value;
  const resultsEl = document.getElementById('transcript-search-results');

  const query = input?.value.trim();
  if (!query) {
    updateStatus('Enter a search term', 'warning');
    return;
  }

  if (!resultsEl) return;

  resultsEl.innerHTML = '<div class="search-loading">Searching...</div>';

  try {
    let url: string;
    let params = new URLSearchParams();
    params.set('q', query);

    switch (filterType) {
      case 'messages':
        url = `${API_BASE}/api/archive-search/messages`;
        if (filterRole) params.set('role', filterRole);
        break;
      case 'sessions':
        url = `${API_BASE}/api/archive-search/sessions`;
        params.set('project', query); // For sessions, query is the project slug
        break;
      case 'files':
        url = `${API_BASE}/api/archive-search/sessions`;
        params = new URLSearchParams({ file: query });
        break;
      case 'tools':
        url = `${API_BASE}/api/archive-search/sessions`;
        params = new URLSearchParams({ tool: query });
        break;
      default:
        url = `${API_BASE}/api/archive-search/messages`;
    }

    const response = await fetch(`${url}?${params.toString()}`);
    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Search failed');
    }

    if (filterType === 'messages') {
      resultsEl.innerHTML = renderMessageResults(data.results || [], query);
    } else {
      resultsEl.innerHTML = renderSessionResults(data.sessions || [], query);
    }

    // Add click handlers for View Transcript buttons
    setupViewTranscriptHandlers();

    updateStatus(`Found ${data.count || 0} result(s)`, 'success');
  } catch (error) {
    console.error('[Archive] Search error:', error);
    resultsEl.innerHTML = `<div class="search-error">Search failed: ${error instanceof Error ? error.message : String(error)}</div>`;
    updateStatus('Search failed', 'error');
  }
}

/**
 * Render message search results
 */
function renderMessageResults(results: SearchResult[], query: string): string {
  if (results.length === 0) {
    return '<div class="search-empty">No messages found matching your search</div>';
  }

  return `
    <div class="search-results-header">
      <span>${results.length} message(s) found</span>
    </div>
    <div class="search-results-list">
      ${results.map(r => `
        <div class="search-result-card message-result">
          <div class="result-header">
            <span class="result-role ${r.role}">${r.role === 'human' ? '👤' : '🤖'} ${r.role}</span>
            <span class="result-session" title="Session: ${r.sessionId}">${r.sessionId.substring(0, 8)}...</span>
            ${r.timestamp ? `<span class="result-time">${formatDate(r.timestamp)}</span>` : ''}
          </div>
          <div class="result-content">${highlightQuery(r.contentPreview, query)}</div>
          ${r.toolsUsed && r.toolsUsed.length > 0 ? `
            <div class="result-tools">
              ${r.toolsUsed.map(t => `<span class="tool-badge">${t}</span>`).join('')}
            </div>
          ` : ''}
          ${r.filesReferenced && r.filesReferenced.length > 0 ? `
            <div class="result-files">
              ${r.filesReferenced.slice(0, 3).map(f => `<span class="file-badge" title="${f}">${getFileName(f)}</span>`).join('')}
              ${r.filesReferenced.length > 3 ? `<span class="file-badge more">+${r.filesReferenced.length - 3}</span>` : ''}
            </div>
          ` : ''}
          ${r.session ? `
            <div class="result-session-meta">
              <span class="session-project">${r.session.projectSlug.substring(0, 30)}...</span>
              <span class="session-turns">${r.session.totalTurns} turns</span>
            </div>
          ` : ''}
          <div class="result-actions">
            <button class="view-transcript-btn" data-session-id="${r.sessionId}" title="View full transcript">
              View Transcript
            </button>
          </div>
        </div>
      `).join('')}
    </div>
  `;
}

/**
 * Render session search results
 */
function renderSessionResults(sessions: SessionResult[], query: string): string {
  if (sessions.length === 0) {
    return '<div class="search-empty">No sessions found matching your search</div>';
  }

  return `
    <div class="search-results-header">
      <span>${sessions.length} session(s) found</span>
    </div>
    <div class="search-results-list">
      ${sessions.map(s => `
        <div class="search-result-card session-result" data-session-id="${s.sessionId}">
          <div class="result-header">
            <span class="result-session-id">${s.sessionId.substring(0, 12)}...</span>
            ${s.hasErrors ? '<span class="error-badge">⚠️ Errors</span>' : ''}
            ${s.lastMessageAt ? `<span class="result-time">${formatDate(s.lastMessageAt)}</span>` : ''}
          </div>
          <div class="result-project">${highlightQuery(s.projectSlug, query)}</div>
          ${s.summary ? `<div class="result-summary">${escapeHtml(s.summary)}</div>` : ''}
          <div class="result-stats">
            <span class="stat">${s.totalTurns} turns</span>
            <span class="stat">${s.filesWritten.length} files written</span>
            <span class="stat">${s.toolsUsed.length} tools</span>
          </div>
          ${s.topics.length > 0 ? `
            <div class="result-topics">
              ${s.topics.slice(0, 5).map(t => `<span class="topic-badge">${t}</span>`).join('')}
            </div>
          ` : ''}
          ${s.codeLanguages.length > 0 ? `
            <div class="result-languages">
              ${s.codeLanguages.map(l => `<span class="lang-badge">${l}</span>`).join('')}
            </div>
          ` : ''}
          <div class="result-files-summary">
            ${s.filesWritten.slice(0, 3).map(f => `<span class="file-written" title="${f}">✏️ ${getFileName(f)}</span>`).join('')}
            ${s.filesWritten.length > 3 ? `<span class="more-files">+${s.filesWritten.length - 3} more</span>` : ''}
          </div>
          <div class="result-actions">
            <button class="view-transcript-btn" data-session-id="${s.sessionId}" title="View full transcript">
              View Transcript
            </button>
          </div>
        </div>
      `).join('')}
    </div>
  `;
}

/**
 * Highlight query in text
 */
function highlightQuery(text: string, query: string): string {
  if (!query) return escapeHtml(text);
  const escaped = escapeHtml(text);
  const pattern = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
  return escaped.replace(pattern, '<mark>$1</mark>');
}

/**
 * Get filename from path
 */
function getFileName(filePath: string): string {
  const parts = filePath.replace(/\\/g, '/').split('/');
  return parts[parts.length - 1] || filePath;
}

/**
 * Setup click handlers for View Transcript buttons
 */
function setupViewTranscriptHandlers(): void {
  const buttons = document.querySelectorAll('.view-transcript-btn');
  buttons.forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const sessionId = (e.target as HTMLElement).dataset.sessionId;
      if (sessionId) {
        await viewTranscript(sessionId);
      }
    });
  });
}

/**
 * View full transcript for a session
 */
async function viewTranscript(sessionId: string): Promise<void> {
  // Create modal if it doesn't exist
  let modal = document.getElementById('transcript-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'transcript-modal';
    modal.className = 'modal transcript-modal';
    modal.innerHTML = `
      <div class="modal-overlay"></div>
      <div class="modal-content transcript-modal-content">
        <div class="modal-header">
          <h3 id="transcript-modal-title">Transcript</h3>
          <button class="modal-close" title="Close">&times;</button>
        </div>
        <div id="transcript-modal-body" class="modal-body transcript-body">
          Loading...
        </div>
      </div>
    `;
    document.body.appendChild(modal);

    // Close handlers
    modal.querySelector('.modal-close')?.addEventListener('click', () => {
      modal!.classList.remove('open');
    });
    modal.querySelector('.modal-overlay')?.addEventListener('click', () => {
      modal!.classList.remove('open');
    });
  }

  // Show modal with loading state
  modal.classList.add('open');
  const titleEl = document.getElementById('transcript-modal-title');
  const bodyEl = document.getElementById('transcript-modal-body');

  if (titleEl) titleEl.textContent = `Session: ${sessionId.substring(0, 16)}...`;
  if (bodyEl) bodyEl.innerHTML = '<div class="loading">Loading transcript...</div>';

  try {
    // First, get the session's chunks
    const chunksResponse = await fetch(`${API_BASE}/api/transcript-archive/all-chunks`);
    if (!chunksResponse.ok) {
      throw new Error('Failed to load chunks');
    }

    const chunksData = await chunksResponse.json();

    // Find chunks for this session
    let sessionChunks = chunksData.local?.sessions?.[sessionId] || [];
    if (sessionChunks.length === 0 && chunksData.blockchain?.sessions?.[sessionId]) {
      sessionChunks = chunksData.blockchain.sessions[sessionId];
    }

    if (sessionChunks.length === 0) {
      if (bodyEl) bodyEl.innerHTML = '<div class="search-empty">No transcript chunks found for this session</div>';
      return;
    }

    // Get content for each chunk
    const transcriptParts: string[] = [];
    for (const chunk of sessionChunks) {
      try {
        const contentResponse = await fetch(`${API_BASE}/api/transcript-archive/chunks/${chunk.id}/content`);
        if (contentResponse.ok) {
          const contentData = await contentResponse.json();
          if (contentData.content) {
            transcriptParts.push(contentData.content);
          }
        }
      } catch (err) {
        console.warn(`Failed to load chunk ${chunk.id}:`, err);
      }
    }

    if (transcriptParts.length === 0) {
      if (bodyEl) bodyEl.innerHTML = '<div class="search-empty">Unable to load transcript content</div>';
      return;
    }

    // Parse and render the JSONL transcript
    const allContent = transcriptParts.join('\n');
    const renderedTranscript = renderTranscriptContent(allContent);

    if (bodyEl) bodyEl.innerHTML = renderedTranscript;
  } catch (error) {
    console.error('[Archive] Error loading transcript:', error);
    if (bodyEl) {
      bodyEl.innerHTML = `<div class="search-error">Failed to load transcript: ${error instanceof Error ? error.message : String(error)}</div>`;
    }
  }
}

/**
 * Render JSONL transcript content as HTML
 */
function renderTranscriptContent(jsonlContent: string): string {
  const lines = jsonlContent.split('\n').filter(line => line.trim());
  const messages: Array<{ role: string; content: string; timestamp?: string }> = [];

  for (const line of lines) {
    try {
      const entry = JSON.parse(line);
      if (entry.type === 'human' || entry.type === 'assistant') {
        let content = '';
        if (typeof entry.message?.content === 'string') {
          content = entry.message.content;
        } else if (Array.isArray(entry.message?.content)) {
          content = entry.message.content
            .filter((c: { type: string }) => c.type === 'text')
            .map((c: { text: string }) => c.text)
            .join('\n');
        }
        messages.push({
          role: entry.type,
          content,
          timestamp: entry.timestamp,
        });
      }
    } catch {
      // Skip invalid JSON lines
    }
  }

  if (messages.length === 0) {
    return '<div class="search-empty">No readable messages in transcript</div>';
  }

  return `
    <div class="transcript-messages">
      ${messages.map(m => `
        <div class="transcript-message ${m.role}">
          <div class="message-header">
            <span class="message-role">${m.role === 'human' ? '👤 Human' : '🤖 Assistant'}</span>
            ${m.timestamp ? `<span class="message-time">${new Date(m.timestamp).toLocaleString()}</span>` : ''}
          </div>
          <div class="message-content">${escapeHtml(m.content).replace(/\n/g, '<br>')}</div>
        </div>
      `).join('')}
    </div>
  `;
}

