/**
 * Network Utilities
 *
 * Provides network-aware currency symbols and chain information.
 */

export interface ChainInfo {
  chainId: number;
  name: string;
  symbol: string;
  explorer: string;
}

/**
 * Known chain configurations
 */
export const CHAIN_INFO: Record<number, ChainInfo> = {
  // Polygon Mainnet
  137: {
    chainId: 137,
    name: 'Polygon',
    symbol: 'POL',
    explorer: 'https://polygonscan.com',
  },
  // Polygon Amoy Testnet
  80002: {
    chainId: 80002,
    name: 'Polygon Amoy',
    symbol: 'POL',
    explorer: 'https://amoy.polygonscan.com',
  },
  // Japan Open Chain
  81: {
    chainId: 81,
    name: 'Japan Open Chain',
    symbol: 'JOC',
    explorer: 'https://explorer.japanopenchain.org',
  },
  // Hardhat/Local
  31337: {
    chainId: 31337,
    name: 'Hardhat',
    symbol: 'ETH',
    explorer: '',
  },
  // Ethereum Mainnet
  1: {
    chainId: 1,
    name: 'Ethereum',
    symbol: 'ETH',
    explorer: 'https://etherscan.io',
  },
};

/**
 * Get the native currency symbol for a given chain ID
 */
export function getCurrencySymbol(chainId: number): string {
  const info = CHAIN_INFO[chainId];
  return info?.symbol ?? 'ETH';
}

/**
 * Get the chain name for a given chain ID
 */
export function getChainName(chainId: number): string {
  const info = CHAIN_INFO[chainId];
  return info?.name ?? `Chain ${chainId}`;
}

/**
 * Get the block explorer URL for a given chain ID
 */
export function getExplorerUrl(chainId: number): string {
  const info = CHAIN_INFO[chainId];
  return info?.explorer ?? '';
}

/**
 * Check if the chain is JOC (Japan Open Chain)
 */
export function isJOC(chainId: number): boolean {
  return chainId === 81;
}

/**
 * Check if the chain is a Polygon network
 */
export function isPolygon(chainId: number): boolean {
  return chainId === 137 || chainId === 80002;
}
