/**
 * Attaches the local API token to dashboard calls to 3020/3021.
 *
 * Those servers now reject browser-origin requests that don't present the token,
 * which is what stops an unrelated local page (another localhost dev server, a local
 * .html file) from invoking wallet-signing. The token is only obtainable through the
 * Electron preload bridge, so this runs in the desktop app and is a no-op elsewhere.
 *
 * Wrapping fetch once here, rather than editing every call site, means a call added
 * later is covered automatically and can't silently regress.
 */
const LOCAL_API_TOKEN_HEADER = 'x-rootz-local-token';
const LOCAL_API_PORTS = new Set(['3020', '3021']);

let tokenPromise: Promise<string | null> | null = null;

function getToken(): Promise<string | null> {
  if (!tokenPromise) {
    const bridge = (window as unknown as { rootzLocalApi?: { getToken: () => Promise<string> } }).rootzLocalApi;
    tokenPromise = bridge
      ? bridge.getToken().catch(() => null)
      : Promise.resolve(null);
  }
  return tokenPromise;
}

function isLocalApiUrl(raw: string): boolean {
  try {
    const u = new URL(raw, window.location.href);
    return (u.hostname === 'localhost' || u.hostname === '127.0.0.1') && LOCAL_API_PORTS.has(u.port);
  } catch {
    return false;
  }
}

export function installLocalApiAuth(): void {
  const bridge = (window as unknown as { rootzLocalApi?: unknown }).rootzLocalApi;
  if (!bridge) return; // not running in the desktop app — nothing to attach

  const original = window.fetch.bind(window);

  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input);
    if (!isLocalApiUrl(url)) return original(input, init);

    const token = await getToken();
    if (!token) return original(input, init);

    // A Request carries its own headers, so rebuild it rather than passing init
    // alongside it (init would be ignored for an already-built Request).
    if (input instanceof Request) {
      const headers = new Headers(input.headers);
      headers.set(LOCAL_API_TOKEN_HEADER, token);
      return original(new Request(input, { headers }), init);
    }

    const headers = new Headers(init?.headers);
    headers.set(LOCAL_API_TOKEN_HEADER, token);
    return original(input, { ...init, headers });
  };
}

// Self-install on import. main.ts imports this module first so the wrapper is in
// place before any other module's top-level code can issue a fetch.
installLocalApiAuth();
