/**
 * Graph Tab — Force-directed visualization of session relationships
 *
 * "Archive Your Thinking" — see how your AI sessions connect
 *
 * Canvas 2D force-directed graph:
 * - Nodes = sessions (sized by totalTurns, colored by project)
 * - Edges = relationships (colored by type, thickness by strength)
 * - Clusters = topic groups (background hulls)
 * - Interactive: drag nodes, hover for details, zoom/pan
 */

// ============================================
// Types
// ============================================

interface GraphSession {
  sessionId: string;
  projectSlug: string;
  summary: string;
  totalTurns: number;
  topics: string[];
  filesWritten: string[];
  codeLanguages: string[];
  hasErrors: boolean;
  firstMessageAt: number;
  lastMessageAt: number;
  createdAt: number;
  updatedAt: number;
}

interface GraphRelationship {
  id: string;
  sourceSessionId: string;
  targetSessionId: string;
  relationshipType: string;
  strength: number;
  reason: string;
  createdAt: number;
  verified: boolean;
}

interface GraphCluster {
  id: string;
  name: string;
  description: string;
  keywords: string[];
  sessionIds: string[];
}

interface GraphData {
  sessions: GraphSession[];
  relationships: GraphRelationship[];
  clusters: GraphCluster[];
  counts: { sessions: number; relationships: number; clusters: number };
}

// Force simulation node
interface SimNode {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  label: string;
  session: GraphSession;
  pinned: boolean;
}

// Force simulation edge
interface SimEdge {
  source: SimNode;
  target: SimNode;
  color: string;
  width: number;
  type: string;
}

// ============================================
// Constants
// ============================================

const API_BASE = 'http://localhost:3020';

const RELATIONSHIP_COLORS: Record<string, string> = {
  continues: '#3b82f6',   // blue
  references: '#22c55e',  // green
  related: '#9ca3af',     // gray
  depends_on: '#ef4444',  // red
  supersedes: '#f97316',  // orange
};

const PROJECT_COLORS = [
  '#6366f1', '#8b5cf6', '#ec4899', '#14b8a6', '#f59e0b',
  '#06b6d4', '#84cc16', '#f43f5e', '#a855f7', '#10b981',
  '#3b82f6', '#eab308', '#ef4444', '#22d3ee', '#d946ef',
];

// ============================================
// State
// ============================================

let canvas: HTMLCanvasElement | null = null;
let ctx: CanvasRenderingContext2D | null = null;
let nodes: SimNode[] = [];
let edges: SimEdge[] = [];
let animationId: number | null = null;
let draggingNode: SimNode | null = null;
let hoveredNode: SimNode | null = null;
let offsetX = 0;
let offsetY = 0;
let scale = 1;
let panStartX = 0;
let panStartY = 0;
let isPanning = false;
let simulationRunning = true;
let simulationAlpha = 1.0; // Cooling factor

// ============================================
// Render
// ============================================

export function renderGraphTab(): string {
  return `
    <div id="graph-tab" style="display: flex; flex-direction: column; height: calc(100vh - 120px); padding: 0;">
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 16px; border-bottom: 1px solid #333; background: #1a1a2e;">
        <div>
          <span style="font-size: 18px; font-weight: bold; color: #e0e0e0;">Session Graph</span>
          <span id="graph-stats" style="margin-left: 12px; color: #888; font-size: 13px;">Loading...</span>
        </div>
        <div style="display: flex; gap: 8px; align-items: center;">
          <button id="graph-detect-btn" style="padding: 4px 12px; background: #2d2d4e; color: #ccc; border: 1px solid #444; border-radius: 4px; cursor: pointer; font-size: 12px;">Detect Links</button>
          <button id="graph-reset-btn" style="padding: 4px 12px; background: #2d2d4e; color: #ccc; border: 1px solid #444; border-radius: 4px; cursor: pointer; font-size: 12px;">Reset View</button>
          <button id="graph-pause-btn" style="padding: 4px 12px; background: #2d2d4e; color: #ccc; border: 1px solid #444; border-radius: 4px; cursor: pointer; font-size: 12px;">Pause</button>
        </div>
      </div>
      <div style="display: flex; flex: 1; overflow: hidden;">
        <canvas id="graph-canvas" style="flex: 1; background: #0d0d1a; cursor: grab;"></canvas>
        <div id="graph-detail" style="width: 280px; background: #1a1a2e; border-left: 1px solid #333; padding: 12px; overflow-y: auto; font-size: 13px; color: #ccc; display: none;">
          <div id="graph-detail-content"></div>
        </div>
      </div>
      <div style="display: flex; gap: 16px; padding: 6px 16px; border-top: 1px solid #333; background: #1a1a2e; font-size: 11px; color: #888;">
        <span><span style="display: inline-block; width: 10px; height: 10px; background: #3b82f6; border-radius: 50%; margin-right: 4px;"></span>continues</span>
        <span><span style="display: inline-block; width: 10px; height: 10px; background: #22c55e; border-radius: 50%; margin-right: 4px;"></span>references</span>
        <span><span style="display: inline-block; width: 10px; height: 10px; background: #9ca3af; border-radius: 50%; margin-right: 4px;"></span>related</span>
        <span><span style="display: inline-block; width: 10px; height: 10px; background: #ef4444; border-radius: 50%; margin-right: 4px;"></span>depends_on</span>
        <span><span style="display: inline-block; width: 10px; height: 10px; background: #f97316; border-radius: 50%; margin-right: 4px;"></span>supersedes</span>
        <span style="margin-left: auto;">Drag nodes | Scroll to zoom | Right-drag to pan</span>
      </div>
    </div>
  `;
}

// ============================================
// Setup
// ============================================

export async function setupGraphTab(): Promise<void> {
  canvas = document.getElementById('graph-canvas') as HTMLCanvasElement;
  if (!canvas) return;

  ctx = canvas.getContext('2d');
  if (!ctx) return;

  // Size canvas to container
  const rect = canvas.parentElement!.getBoundingClientRect();
  canvas.width = rect.width - 280; // Leave room for detail panel
  canvas.height = rect.height;

  // Load data
  try {
    const resp = await fetch(`${API_BASE}/api/graph?limit=500`);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data: GraphData = await resp.json();

    buildGraph(data);

    const statsEl = document.getElementById('graph-stats');
    if (statsEl) {
      statsEl.textContent = `${data.counts.sessions} sessions, ${data.counts.relationships} links, ${data.counts.clusters} clusters`;
    }
  } catch (err) {
    const statsEl = document.getElementById('graph-stats');
    if (statsEl) {
      statsEl.textContent = `Error: ${err instanceof Error ? err.message : 'Failed to load'}. Is Desktop V6 running?`;
      statsEl.style.color = '#ef4444';
    }
    return;
  }

  // Event handlers
  setupInteraction();

  // Buttons
  document.getElementById('graph-reset-btn')?.addEventListener('click', () => {
    offsetX = 0;
    offsetY = 0;
    scale = 1;
    simulationAlpha = 0.5;
    simulationRunning = true;
    const pauseBtn = document.getElementById('graph-pause-btn');
    if (pauseBtn) pauseBtn.textContent = 'Pause';
  });

  document.getElementById('graph-pause-btn')?.addEventListener('click', () => {
    simulationRunning = !simulationRunning;
    const btn = document.getElementById('graph-pause-btn');
    if (btn) btn.textContent = simulationRunning ? 'Pause' : 'Resume';
    if (simulationRunning) simulationAlpha = 0.3;
  });

  document.getElementById('graph-detect-btn')?.addEventListener('click', async () => {
    const btn = document.getElementById('graph-detect-btn') as HTMLButtonElement;
    if (!btn) return;
    btn.textContent = 'Detecting...';
    btn.disabled = true;

    let created = 0;
    for (const node of nodes) {
      try {
        const resp = await fetch(`${API_BASE}/api/relationships/${node.id}/detect`, { method: 'POST' });
        if (resp.ok) {
          const result = await resp.json();
          created += result.relationshipsCreated || 0;
        }
      } catch { /* skip */ }
    }

    btn.textContent = `Detected ${created} links`;
    btn.disabled = false;

    // Reload graph
    if (created > 0) {
      setTimeout(async () => {
        try {
          const resp = await fetch(`${API_BASE}/api/graph?limit=500`);
          const data: GraphData = await resp.json();
          buildGraph(data);
          btn.textContent = 'Detect Links';
        } catch { /* ignore */ }
      }, 500);
    } else {
      setTimeout(() => { btn.textContent = 'Detect Links'; }, 2000);
    }
  });

  // Start animation loop
  animate();
}

export function cleanupGraphTab(): void {
  if (animationId !== null) {
    cancelAnimationFrame(animationId);
    animationId = null;
  }
  canvas = null;
  ctx = null;
  nodes = [];
  edges = [];
  draggingNode = null;
  hoveredNode = null;
}

// ============================================
// Build Graph from Data
// ============================================

function buildGraph(data: GraphData): void {
  const projectColorMap = new Map<string, string>();
  let colorIdx = 0;

  // Create nodes
  const nodeMap = new Map<string, SimNode>();
  const cw = canvas?.width || 800;
  const ch = canvas?.height || 600;

  nodes = data.sessions.map(s => {
    // Assign color by project
    if (!projectColorMap.has(s.projectSlug)) {
      projectColorMap.set(s.projectSlug, PROJECT_COLORS[colorIdx % PROJECT_COLORS.length]);
      colorIdx++;
    }

    const radius = Math.max(6, Math.min(24, 4 + Math.sqrt(s.totalTurns) * 2));
    const label = s.summary
      ? s.summary.slice(0, 40) + (s.summary.length > 40 ? '...' : '')
      : s.topics?.[0] || s.projectSlug || s.sessionId.slice(0, 8);

    const node: SimNode = {
      id: s.sessionId,
      x: cw / 2 + (Math.random() - 0.5) * cw * 0.6,
      y: ch / 2 + (Math.random() - 0.5) * ch * 0.6,
      vx: 0,
      vy: 0,
      radius,
      color: projectColorMap.get(s.projectSlug)!,
      label,
      session: s,
      pinned: false,
    };
    nodeMap.set(s.sessionId, node);
    return node;
  });

  // Create edges
  edges = [];
  for (const rel of data.relationships) {
    const source = nodeMap.get(rel.sourceSessionId);
    const target = nodeMap.get(rel.targetSessionId);
    if (source && target) {
      edges.push({
        source,
        target,
        color: RELATIONSHIP_COLORS[rel.relationshipType] || '#666',
        width: 1 + rel.strength * 3,
        type: rel.relationshipType,
      });
    }
  }

  // Reset simulation
  simulationAlpha = 1.0;
  simulationRunning = true;
}

// ============================================
// Force Simulation
// ============================================

function simulate(): void {
  if (!simulationRunning || simulationAlpha < 0.001) return;

  const alpha = simulationAlpha;
  simulationAlpha *= 0.995; // Cool down

  const cw = canvas?.width || 800;
  const ch = canvas?.height || 600;
  const centerX = cw / 2;
  const centerY = ch / 2;

  // Center gravity
  for (const node of nodes) {
    if (node.pinned) continue;
    node.vx += (centerX - node.x) * 0.0005 * alpha;
    node.vy += (centerY - node.y) * 0.0005 * alpha;
  }

  // Node repulsion (Barnes-Hut would be better for >500 nodes, but this works for now)
  for (let i = 0; i < nodes.length; i++) {
    if (nodes[i].pinned) continue;
    for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i];
      const b = nodes[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const minDist = a.radius + b.radius + 40;

      if (dist < minDist * 3) {
        const force = (alpha * 800) / (dist * dist);
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;
        if (!a.pinned) { a.vx -= fx; a.vy -= fy; }
        if (!b.pinned) { b.vx += fx; b.vy += fy; }
      }
    }
  }

  // Edge spring forces
  for (const edge of edges) {
    const dx = edge.target.x - edge.source.x;
    const dy = edge.target.y - edge.source.y;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const idealDist = 120;
    const force = (dist - idealDist) * 0.005 * alpha;
    const fx = (dx / dist) * force;
    const fy = (dy / dist) * force;

    if (!edge.source.pinned) { edge.source.vx += fx; edge.source.vy += fy; }
    if (!edge.target.pinned) { edge.target.vx -= fx; edge.target.vy -= fy; }
  }

  // Apply velocities with damping
  for (const node of nodes) {
    if (node.pinned) continue;
    node.vx *= 0.85;
    node.vy *= 0.85;
    node.x += node.vx;
    node.y += node.vy;

    // Keep in bounds
    node.x = Math.max(node.radius, Math.min(cw - node.radius, node.x));
    node.y = Math.max(node.radius, Math.min(ch - node.radius, node.y));
  }
}

// ============================================
// Render Loop
// ============================================

function draw(): void {
  if (!ctx || !canvas) return;

  const w = canvas.width;
  const h = canvas.height;

  ctx.save();
  ctx.clearRect(0, 0, w, h);

  // Apply camera transform
  ctx.translate(offsetX, offsetY);
  ctx.scale(scale, scale);

  // Draw edges
  for (const edge of edges) {
    ctx.beginPath();
    ctx.moveTo(edge.source.x, edge.source.y);
    ctx.lineTo(edge.target.x, edge.target.y);
    ctx.strokeStyle = edge.color;
    ctx.globalAlpha = 0.4;
    ctx.lineWidth = edge.width / scale;
    ctx.stroke();
    ctx.globalAlpha = 1.0;
  }

  // Draw nodes
  for (const node of nodes) {
    const isHovered = node === hoveredNode;
    const isDragging = node === draggingNode;

    // Glow for hovered/dragging
    if (isHovered || isDragging) {
      ctx.beginPath();
      ctx.arc(node.x, node.y, node.radius + 6, 0, Math.PI * 2);
      ctx.fillStyle = node.color;
      ctx.globalAlpha = 0.2;
      ctx.fill();
      ctx.globalAlpha = 1.0;
    }

    // Node circle
    ctx.beginPath();
    ctx.arc(node.x, node.y, node.radius, 0, Math.PI * 2);
    ctx.fillStyle = node.color;
    ctx.globalAlpha = isHovered || isDragging ? 1.0 : 0.8;
    ctx.fill();
    ctx.globalAlpha = 1.0;

    // Error indicator
    if (node.session.hasErrors) {
      ctx.beginPath();
      ctx.arc(node.x + node.radius * 0.6, node.y - node.radius * 0.6, 4, 0, Math.PI * 2);
      ctx.fillStyle = '#ef4444';
      ctx.fill();
    }

    // Label (only show if zoomed in enough or node is large or hovered)
    if (scale > 0.6 || node.radius > 12 || isHovered) {
      ctx.font = `${Math.max(9, 11 / scale)}px monospace`;
      ctx.fillStyle = '#e0e0e0';
      ctx.globalAlpha = isHovered ? 1.0 : 0.7;
      ctx.textAlign = 'center';
      ctx.fillText(node.label, node.x, node.y + node.radius + 14 / scale);
      ctx.globalAlpha = 1.0;
    }
  }

  // Highlight edges for hovered node
  if (hoveredNode) {
    for (const edge of edges) {
      if (edge.source === hoveredNode || edge.target === hoveredNode) {
        ctx.beginPath();
        ctx.moveTo(edge.source.x, edge.source.y);
        ctx.lineTo(edge.target.x, edge.target.y);
        ctx.strokeStyle = edge.color;
        ctx.globalAlpha = 0.9;
        ctx.lineWidth = (edge.width + 2) / scale;
        ctx.stroke();
        ctx.globalAlpha = 1.0;
      }
    }
  }

  ctx.restore();

  // Draw "no data" message if empty
  if (nodes.length === 0) {
    ctx.fillStyle = '#888';
    ctx.font = '16px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('No session data yet.', w / 2, h / 2 - 20);
    ctx.font = '13px monospace';
    ctx.fillText('Use Claude Code with Desktop V6 to build your thinking graph.', w / 2, h / 2 + 10);
    ctx.fillText('Click "Detect Links" to find connections between sessions.', w / 2, h / 2 + 35);
  }
}

function animate(): void {
  simulate();
  draw();
  animationId = requestAnimationFrame(animate);
}

// ============================================
// Interaction
// ============================================

function screenToWorld(sx: number, sy: number): { x: number; y: number } {
  return {
    x: (sx - offsetX) / scale,
    y: (sy - offsetY) / scale,
  };
}

function findNodeAt(wx: number, wy: number): SimNode | null {
  // Search in reverse (top-most first)
  for (let i = nodes.length - 1; i >= 0; i--) {
    const n = nodes[i];
    const dx = wx - n.x;
    const dy = wy - n.y;
    if (dx * dx + dy * dy <= (n.radius + 4) * (n.radius + 4)) {
      return n;
    }
  }
  return null;
}

function showDetail(node: SimNode): void {
  const panel = document.getElementById('graph-detail');
  const content = document.getElementById('graph-detail-content');
  if (!panel || !content) return;

  panel.style.display = 'block';

  // Resize canvas
  if (canvas && canvas.parentElement) {
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width - 280;
  }

  const s = node.session;
  const date = s.lastMessageAt ? new Date(s.lastMessageAt).toLocaleDateString() : 'Unknown';
  const connectedEdges = edges.filter(e => e.source === node || e.target === node);
  const relatedNodes = connectedEdges.map(e => e.source === node ? e.target : e.source);

  content.innerHTML = `
    <div style="margin-bottom: 12px;">
      <div style="font-size: 15px; font-weight: bold; color: ${node.color}; margin-bottom: 4px;">
        ${escapeHtml(node.label)}
      </div>
      <div style="font-size: 11px; color: #666;">${s.sessionId.slice(0, 16)}...</div>
    </div>

    <div style="margin-bottom: 12px;">
      <div style="color: #888; font-size: 11px; text-transform: uppercase; margin-bottom: 4px;">Project</div>
      <div>${escapeHtml(s.projectSlug)}</div>
    </div>

    ${s.summary ? `
    <div style="margin-bottom: 12px;">
      <div style="color: #888; font-size: 11px; text-transform: uppercase; margin-bottom: 4px;">Summary</div>
      <div style="font-size: 12px; line-height: 1.4;">${escapeHtml(s.summary)}</div>
    </div>
    ` : ''}

    <div style="margin-bottom: 12px;">
      <div style="color: #888; font-size: 11px; text-transform: uppercase; margin-bottom: 4px;">Stats</div>
      <div style="font-size: 12px;">
        ${s.totalTurns} turns &middot; ${date}
        ${s.hasErrors ? ' &middot; <span style="color: #ef4444;">errors</span>' : ''}
      </div>
    </div>

    ${s.topics?.length ? `
    <div style="margin-bottom: 12px;">
      <div style="color: #888; font-size: 11px; text-transform: uppercase; margin-bottom: 4px;">Topics</div>
      <div style="display: flex; flex-wrap: wrap; gap: 4px;">
        ${s.topics.slice(0, 8).map(t => `<span style="background: #2d2d4e; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${escapeHtml(t)}</span>`).join('')}
      </div>
    </div>
    ` : ''}

    ${connectedEdges.length ? `
    <div style="margin-bottom: 12px;">
      <div style="color: #888; font-size: 11px; text-transform: uppercase; margin-bottom: 4px;">Connections (${connectedEdges.length})</div>
      <div style="font-size: 12px;">
        ${connectedEdges.map((e, i) => {
          const other = relatedNodes[i];
          const dir = e.source === node ? '&rarr;' : '&larr;';
          return `<div style="margin: 3px 0; padding: 4px; background: #0d0d1a; border-radius: 3px;">
            <span style="color: ${e.color};">${e.type}</span> ${dir}
            <span style="color: ${other.color};">${escapeHtml(other.label)}</span>
            <span style="color: #555; font-size: 10px;"> (${(e.width > 1 ? ((e.width - 1) / 3 * 100).toFixed(0) : '0')}%)</span>
          </div>`;
        }).join('')}
      </div>
    </div>
    ` : '<div style="color: #555; font-style: italic;">No connections yet</div>'}
  `;
}

function hideDetail(): void {
  const panel = document.getElementById('graph-detail');
  if (panel) panel.style.display = 'none';

  // Resize canvas back
  if (canvas && canvas.parentElement) {
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width;
  }
}

function setupInteraction(): void {
  if (!canvas) return;

  canvas.addEventListener('mousedown', (e: MouseEvent) => {
    const rect = canvas!.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;
    const { x: wx, y: wy } = screenToWorld(sx, sy);

    const node = findNodeAt(wx, wy);

    if (e.button === 2 || (e.button === 0 && !node)) {
      // Pan
      isPanning = true;
      panStartX = e.clientX - offsetX;
      panStartY = e.clientY - offsetY;
      canvas!.style.cursor = 'grabbing';
    } else if (node) {
      // Drag node
      draggingNode = node;
      node.pinned = true;
      canvas!.style.cursor = 'move';
      showDetail(node);
    }
  });

  canvas.addEventListener('mousemove', (e: MouseEvent) => {
    const rect = canvas!.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;

    if (isPanning) {
      offsetX = e.clientX - panStartX;
      offsetY = e.clientY - panStartY;
      return;
    }

    if (draggingNode) {
      const { x: wx, y: wy } = screenToWorld(sx, sy);
      draggingNode.x = wx;
      draggingNode.y = wy;
      draggingNode.vx = 0;
      draggingNode.vy = 0;
      return;
    }

    // Hover detection
    const { x: wx, y: wy } = screenToWorld(sx, sy);
    const node = findNodeAt(wx, wy);
    if (node !== hoveredNode) {
      hoveredNode = node;
      canvas!.style.cursor = node ? 'pointer' : 'grab';
    }
  });

  canvas.addEventListener('mouseup', () => {
    if (draggingNode) {
      draggingNode.pinned = false;
      draggingNode = null;
    }
    isPanning = false;
    canvas!.style.cursor = hoveredNode ? 'pointer' : 'grab';
  });

  canvas.addEventListener('wheel', (e: WheelEvent) => {
    e.preventDefault();
    const rect = canvas!.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    const newScale = Math.max(0.1, Math.min(5, scale * zoomFactor));

    // Zoom toward cursor position
    offsetX = sx - (sx - offsetX) * (newScale / scale);
    offsetY = sy - (sy - offsetY) * (newScale / scale);
    scale = newScale;
  });

  canvas.addEventListener('dblclick', (e: MouseEvent) => {
    const rect = canvas!.getBoundingClientRect();
    const { x: wx, y: wy } = screenToWorld(e.clientX - rect.left, e.clientY - rect.top);
    const node = findNodeAt(wx, wy);
    if (node) {
      showDetail(node);
    } else {
      hideDetail();
    }
  });

  // Prevent context menu on right-click (used for panning)
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());

  // Resize handler
  const resizeObserver = new ResizeObserver(() => {
    if (canvas && canvas.parentElement) {
      const rect = canvas.parentElement.getBoundingClientRect();
      const detailPanel = document.getElementById('graph-detail');
      const detailWidth = detailPanel?.style.display !== 'none' ? 280 : 0;
      canvas.width = rect.width - detailWidth;
      canvas.height = rect.height;
    }
  });

  if (canvas.parentElement) {
    resizeObserver.observe(canvas.parentElement);
  }
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
